window.CISP_QUESTION_SETS = {"version":1,"sets":[{"id":"wx2026-01","name":"CISE 练习题（A卷）","subtitle":"2026 · 已审+解析","sourceFile":"2026- CISE练习题（A卷）-已审+解析.docx","questionCount":100,"questions":[{"id":"wx2026-01-001","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"1","domain":"信息安全技术","stem":"软件存在漏洞和缺陷是不可避免的,实践中常使用软件缺陷密度(Defectm/KL0C)来衡量软件的安全性,假设某大软件共有296万行源代码,总共被检测出145个缺陷,则可以计算出其软件缺陷密度值是()","options":["0.00049","0.049","0.49","49"],"correctIndex":1,"explanation":"将源代码行数转换为千行（KLOC）:296 万行 = 2960000 行 = 2960000 ÷ 1000 = 2960；计算缺陷密度:缺陷密度 = 145÷2960≈ 0.049","imageNames":[]},{"id":"wx2026-01-002","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"2","domain":"信息安全法规标准","stem":"GB/T 18336《信息技术安全性评估准则》是测评标准类中的重要标准,该标准定义了保护轮期(Protection Profile.PP)和安全目标(Security Target.ST)的评估准则,提出了评估保证级(Evaluation Aanurane Level,EAL),其评估保证级共分为()个递增的评估保证等级。","options":["4","5","6","7"],"correctIndex":3,"explanation":"GB/T 18336《信息技术安全性评估准则》中的评估保证级共分为7个递增的评估保证等级,分别是 EAL1 至 EAL7。","imageNames":[]},{"id":"wx2026-01-003","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"3","domain":"信息安全工程","stem":"Gery McGraw博士及其合作者提出软件安全应由三根支柱来支撑。这三个支柱是（）","options":["源代码审核、风险分析和渗透测试","应用风险管理、软件安全接触点和安全知识","威胁建模、渗透测试和软件安全接触点","威胁建模、源代码审核和模糊测试"],"correctIndex":1,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-01-004","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"4","domain":"信息安全法规标准","stem":"国际标准化组织(International Organization for Standardization.ISO)对信息安全的定义为( )","options":["保护信息和信息系续不被未经授权的访问、使用、泄露、修改和破坏,为信息和信息系统提供保密性、完整性 可用性、可控性和不可否认性","信息安全,有时编写为 InfoSec,是防止未经授权的访网、使用、被露、中断、修改、检查、记录成破坏信息的做法。它是一个可以用于任何形式数据(例如电子、物理)的通用术语","在既定的密级条件下,网络与信息系统抵御意外事件或恶意行为的能力,这些事件和行为将威胁所存储或传输的数据以及经由这些网络和系统所提供的服务的可用性、真实性、完整性和机密性","为数据处理系统建立和采取技术、管理的安全保护,保护计算机硬件、软件、数据不因偶然的或恶意的原因而受到破坏、更改、泄露"],"correctIndex":3,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-01-005","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"5","domain":"信息安全保障","stem":"对信息安全事件的分级参考下列三个要素:信息系统的重要程度、系统损失和社会影响。依据信息系统的重要程度对信息系统进行划分,不属于正确划分级别的是()。","options":["特别重要信息系统","重要信息系统","一般信息系统","关键信息系统"],"correctIndex":3,"explanation":"《信息安全技术 信息安全事件分类分级指南》（GB/Z 20986-2007）“信息系统的重要程度主要考虑信息系统所承载的业务对国家安全、经济建设、社会生活的重要性以及业务对信息系统的依赖程度,划分为特别重要信息系统、重要信息系统和一般信息系统。”","imageNames":[]},{"id":"wx2026-01-006","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"6","domain":"信息安全管理","stem":"恢复时间目标(Recovery Time Objective , RTO)和恢复点目标(Recovery Point Objective, RPO)是业务连续性和灾难恢复工作中的两个重要指标,随着信息系统越来越重要和信息技术越来越先进,这两个指标的数值越来越小。小华准备为其工作的信息系统拟定RTO和RPO指标,则以下描述中。正确的是()。","options":["RTO 可以为0,RPO 也可以为0","RTO 可以为0,RPO 不可以为0","RTO 不可以为 0,RPO 可以为0","RTO 不可以为0,RPO 也不可以为0"],"correctIndex":0,"explanation":"RTO（恢复时间目标）:指从灾难发生到信息系统恢复运行所需的时间,即业务中断的容忍上限。 RPO（恢复点目标）:指灾难发生后,系统能恢复到的时间点,即允许丢失的数据量（以时间为单位）。 RTO=0意味着业务中断时间为零,即系统需在灾难发生时无缝切换至备用环境。 现代技术（如高可用集群、双活数据中心、自动化故障转移）可实现近乎零中断的切换（例如毫秒级）。理论可行性:在技术极限下,RTO可趋近于0。 分析RPO是否可以为0 RPO=0表示数据零丢失,即灾难前后的数据完全一致。 实现方式包括同步数据复制（如存储级同步、数据库实时同步）,确保数据写入主备系统无延迟。理论可行性:在技术极限下,RPO可趋近于0。 题目强调“信息技术越来越先进”,需考虑理想情况下的技术能力。若技术完全支持无中断切换和数据零丢失,则RTO和RPO均可为0。","imageNames":[]},{"id":"wx2026-01-007","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"7","domain":"信息安全工程","stem":"为了保障系统安全,某单位需要对其跨地区大型网络实时应用系统进行渗透测试,以下关于渗透测试过程的说法不正确的是()。","options":["由于在实际渗透测试过程中存在不可预知的风险,所以测试前要提醒用户进行系统和数据备份,以便出现问题时可以及时恢复系统和数据","渗透测试从“逆向”的角度出发,测试软件系统的安全性,其价值在于可以测试软件在实际系统中运行时的安全状况","渗透测试应当经过方案制定、信息收集、漏洞利用、完成渗透测试报告等步骤","为了深入发掘该系统存在的安全威胁,应该在系统正常业务运行高峰期进行渗透测试"],"correctIndex":3,"explanation":"业务高峰期测试的风险:性能影响:渗透测试的流量或攻击行为可能加剧系统负载,导致业务中断或数据丢失。 。","imageNames":[]},{"id":"wx2026-01-008","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"8","domain":"信息安全技术","stem":"小李在检查公司对外服务网站的源代码时,发现程序在发生诸如没有找到资源、数据库连接错误、写临时文件错误等问题时,会将详细的错误原因在结果页面上显示出来。从安全角度考虑,小李决定修改代码,将详细的错误原因都隐藏起来,在页面上仅仅告知用户“抱歉,发生内部错误!”。请问,这种处理方法的主要目的是()。","options":["避免缓冲区溢出","安全处理系统异常","安全使用临时文件","最小化反馈信息"],"correctIndex":3,"explanation":"选项D:“最小化反馈信息”是安全领域的核心原则之一,即仅向用户提供必要的信息,避免泄露系统内部细节。是为了最小化反馈给用户的信息,防止攻击者利用这些详细错误信息进行进一步的攻击。","imageNames":[]},{"id":"wx2026-01-009","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"9","domain":"信息安全管理","stem":"王工是某单位的系统管理员。他在某次参加了单位组织的风险管理工作时。根据任务安排。他依据已有的资产系表,逐个分析可能危害这些资产的主体、动机、途径等多种因素,分析这些因素出现及造成损失的可能性大乐产为其赋值。请问,他这个工作属于下面要一个阶段的工作()","options":["资产识别并赋值","脆弱性识别并赋值","威胁识别并赋值","确认已有的安全措施并赋值"],"correctIndex":2,"explanation":"A选项资产识别并赋值是对资产本身进行；B选项脆弱性识别并赋值是找系统的弱点；D选项确认已有的安全措施并赋值是对安全措施相关,所以选C。","imageNames":[]},{"id":"wx2026-01-010","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"10","domain":"信息安全技术","stem":"2016年10月21日,美国东部地区发生大规模断网事件,此次事件是由于美国主要 DNS 服务商 Dyn 遭遇大规模DDos 攻击所致,影响规模惊人,对人们生产生活造成严重影响。DDoS 攻击的主要目的是破坏系统的()","options":["保密性","可用性","不可否认性","抗抵赖性"],"correctIndex":1,"explanation":"DDoS（分布式拒绝服务）攻击的主要目的是通过大量的请求使目标系统资源耗尽,无法正常为合法用户提供服务,从而破坏系统的可用性。A选项保密性是防止信息泄露；C选项不可否认性和D选项抗抵赖性是防止发送方或接收方否认已经发生的行为,所以选B。","imageNames":[]},{"id":"wx2026-01-011","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"11","domain":"信息安全技术","stem":"某社交网站的用户点击了该网站上的一个广告。该广告含有一个跨站脚本,会将他的浏览器定向到旅游网文旅游网站则了他的社交网络信息。虽然该用户没有主动访问该旅游网站,但旅游网站已经截获了他的社交网信息(还有他的好友们的信息),于是犯罪分子便可以躲藏在社交网站的广告后面,截获用户的个人信息宁。这种向 Web 页面插入恶意html代码的攻击方式称为()","options":["分布式拒绝服务攻击","跨站脚本攻击","SQL 注入攻击","缓冲区溢出攻击"],"correctIndex":1,"explanation":"向Web页面插入恶意html代码的攻击方式称为跨站脚本攻击（XSS）。A选项分布式拒绝服务攻击是通过大量请求使系统瘫痪；C选项SQL注入攻击是向数据库注入恶意SQL语句；D选项缓冲区溢出攻击是利用缓冲区溢出漏洞进行攻击,所以选B。","imageNames":[]},{"id":"wx2026-01-012","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"12","domain":"信息安全工程","stem":"有关能力成熟度模型(CMM),错误的理解是()。","options":["CMM的思想不关注结果,而是强调了过程的控制,过程如果是高质量的,结果通常会是高质量的","CMM 的思想来源于项目管理、质量管理和过程管理","CMM 是一种衡量工程实施能力的方法,是一种面向工程过程的方法","CMM是建立在统计过程控制理论基础上的,它基于这样一个假设,即“生产过程的高质量和在过程中组织实施的成熟性可以低成本地生产出高质量产品”"],"correctIndex":1,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-01-013","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"13","domain":"信息安全管理","stem":"操作系统用于管理计算机资源,控制整个系统运行,是计算机软件的基础。操作系统安全是计算、网络及信息系统安全的基础。一般操作系统都提供了相应的安全配置接口。小王新买了一台计算机,开机后首先对自带的 Windows 操作系统进行配置。他的主要操作有:(1)关团不必要的服务和端口;(2)在“本地安全策略”中配置账号策略、本地策略、公钥策略和 IP安全策略;(3)备份敏感文件,禁止建立空连接,下载最新补丁;(4)关闭审核策略,开启口令策略,开启账户策略。这些操作中错误的是()。","options":["操作(1),应该关闭不必要的服务和所有端口","操作(2),在“本地安全策略”中不应该配置公钥策略,而应该配置私钥策略","操作(3),备份敏感文件会导致这些文件遭到窃取的几率增加","操作(4),应该开启审核策略"],"correctIndex":3,"explanation":"操作（1）中关闭不必要的服务和端口,但不是所有端口,A选项错误；操作（2）在“本地安全策略”中配置公钥策略是合理的,B选项错误；操作（3）备份敏感文件是必要的安全措施,不会导致文件遭到窃取几率增加,C选项错误；操作（4）应该开启审核策略,以便记录系统活动,便于安全审计,所以选D。","imageNames":[]},{"id":"wx2026-01-014","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"14","domain":"信息安全管理","stem":"某集团公司根据业务需要,在各地分支机构部署前置机,为了保证安全,集团总部要求前置机开放日志共享,由总部服务器采集进行集中分析,在运行过程中发现攻击者也可通过共享从前置机中提取日志,从而导致部分敏感信息泄露,根据降低攻击面的原则,应采取以下哪项处理措施()","options":["由于共享导致了安全问题,应直接关闭日志共享,禁止总部提取日志进行分析","为配合总部的安全策略,会带来一定的安全问题,但不影响系统使用,因此接受此风险","日志的存在就是安全风险,最好的办法就是取消日志,通过设置让前置机不记录日志","只允许特定的 IP 地址从前置机提取日志,对日志共享设置访问密码且限定访问的时间"],"correctIndex":3,"explanation":"根据降低攻击面的原则,应采取限制访问的措施。A选项直接关闭日志共享不利于总部分析安全情况；B选项接受风险不是最佳做法；C选项取消日志不利于安全审计和问题排查；D选项只允许特定的IP地址从前置机提取日志,对日志共享设置访问密码且限定访问时间,可以有效降低攻击面,所以选D。","imageNames":[]},{"id":"wx2026-01-015","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"15","domain":"信息安全工程","stem":"北京某公司利用SSE-CMM对其自身工程队伍能力进行自我改善,其理解正确的是()。","options":["系统安全工程能力成熟度模型(SSE-CMM)定义了6个能力级别,当工程队伍不能执行一个过程域中的基本实践时,该过程域的过程能力是0级","达到 SSE-CM 最高级以后,工程队伍执行同一个过程,每次执行的结果质量必须相同","系统安全工程能力成熟度模型(SSE-CMM)定义了3个风险过程:评价威胁,评价脆弱性,评价影响","SSE-QM 强调系统安全工程与其他工程学科的区别性和独立性"],"correctIndex":0,"explanation":"系统安全工程能力成熟度模型（SSE - CMM）定义了6个能力级别,当工程队伍不能执行一个过程域中的基本实践时,该过程域的过程能力是0级,A选项正确。达到SSE - CMM最高级后,工程队伍执行同一个过程,每次执行结果质量会提高,但不是必须相同,B选项错误；SSE - CMM定义了6个基本实践,而不是3个风险过程,C选项错误；SSE - CMM强调系统安全工程与其他工程学科的相似性和相关性,D选项错误。所以选A。","imageNames":[]},{"id":"wx2026-01-016","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"16","domain":"信息安全技术","stem":"由于 Internet 的安全问题日益突出,基于 TCP/IP协议,相关组织和专家在协议的不同层次设计了相应的安全通信协议,用来保障网络各层次的安全。其中,属于或依附于传输层的安全协议是()。","options":["PP2P","L2TP","SSL","IPSec"],"correctIndex":2,"explanation":"PPTP（点对点隧道协议）和L2TP（第二层隧道协议）是数据链路层协议；SSL（安全套接层）是依附于传输层的安全协议,用于保障网络通信的安全；IPSec是网络层的安全协议。","imageNames":[]},{"id":"wx2026-01-017","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"17","domain":"信息安全法规标准","stem":"以下哪项的行为不属于违反国家保密规定的行为()","options":["将涉密计算机、涉密存储设备接入互联网及其他公共信息网络","通过普通邮政等无保密措施的渠道传递国家秘密载体","在私人交往中涉及国家秘密","以不正当手段获取商业秘密"],"correctIndex":3,"explanation":"A选项将涉密计算机、涉密存储设备接入互联网及其他公共信息网络,B选项通过普通邮政等无保密措施的渠道传递国家秘密载体,C选项在私人交往中涉及国家秘密,都属于违反国家保密规定的行为；D选项以不正当手段获取商业秘密属于侵犯商业秘密的行为,不属于违反国家保密规定的行为,所以选D。","imageNames":[]},{"id":"wx2026-01-018","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"18","domain":"信息安全法规标准","stem":"关于计算机取证描述不正确的是()","options":["计算机取证是使用先进的技术和工具,按照标准规程全面地检查计算机系统,以提取和保护有关计算机犯罪的相关证据的活动","取证的目的包括:通过证据查找策事者、通过证据推断犯罪过程、通过证据判断受害者损失程度及收集证据提供法律支持","电子证据是计算机系统运行过程中产生的各种信息记录及存储的电子化资料及物品。对于电子证据,取证工作主要围绕两方面进行:证据的获取和证据的保护","计算机取证的过程可以分为准备、保护、提取、分析和提交5个步骤"],"correctIndex":2,"explanation":"电子证据取证工作不仅包括 “证据的获取和保护”,还包括 “证据的分析（如还原攻击过程）和提交（如形成法律认可的证据报告）”。","imageNames":[]},{"id":"wx2026-01-019","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"19","domain":"信息安全技术","stem":"在某信息系统的设计中,用户登录过程是这样的:(1)用户通过 HTTP 协议访问信息系统:(2)用户在登录页面输入用户名和口令:(3)信息系统在服务器端检查用户名和密码的正确性,如果正确,则鉴别完成。可以出,这个鉴别过程属于()。","options":["单向鉴别","双向鉴别","三向鉴别","第三方鉴别"],"correctIndex":0,"explanation":"用户通过HTTP协议访问信息系统,在服务器端检查用户名和密码正确性完成鉴别,这是单向鉴别,即一方对另一方的身份进行验证。双向鉴别是双方互相验证身份；三向鉴别和第三方鉴别题干未体现,所以选A。","imageNames":[]},{"id":"wx2026-01-020","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"20","domain":"信息安全法规标准","stem":"以下关于检查评估和自评估说法错误的是()。","options":["信息安全风险评估分自评估、检查评估两形式。应以检查评估为主,自评估和检查评估相互结合、互为补充","检查评估可以依据相关标准的要求,实施完整的风险评估,也可以在自评估实施的基础上,对关键环节或重点内容实施抽样评估","信息安全风险评估应贯穿于网络和信息系统建设运行的全过程","自评估只能由组织自身发起并实施,对信息系统及其管理进行风险评估活动"],"correctIndex":0,"explanation":"信息安全风险评估分自评估、检查评估两种形式,应以自评估为主,自评估和检查评估相互结合、互为补充。","imageNames":[]},{"id":"wx2026-01-021","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"21","domain":"信息安全法规标准","stem":"风险,在 GB/T 22081 中定义为事态的概率及其结果的组合。风险的目标可能有很多不同的方面,如财务目标、健康和人身安全目标、信息安全目标和环境目标等;目标也可能有不同的级别,如战略目标、组织目标、项目目标、产品目标和过程目标等。ISO/IEC TR 13335-1中揭示了风险各要素关系模型,如图所示。请结合此图,怎么才能降低风险对组织产生的影响?()","options":["组织应该根据风险建立响应的保护要求,通过构架防护措施降低风险对组织产生的影响","加强防护措施,降低风险","减少威胁和脆弱点,降低风险","减少资产降低风险"],"correctIndex":0,"explanation":"根据ISO/IEC TR 13335 - 1揭示的风险各要素关系模型,降低风险对组织产生的影响,组织应根据风险建立响应的保护要求,通过构架防护措施来达成。B选项“加强防护措施,降低风险”表述过于笼统,没有明确建立保护要求与构架防护措施的逻辑；C选项减少威胁和脆弱点是降低风险的手段,但没有体现出基于风险建立保护要求并构架防护措施这一完整逻辑；D选项减少资产不是降低风险的合理常规方式,还可能影响组织正常运营。所以选A。","imageNames":["wx2026-01-03.png"]},{"id":"wx2026-01-022","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"22","domain":"信息安全技术","stem":"小张新购入了一台安装了Windows操作系统的笔记本电脑。为了提升操作系统的安全性,小张在Windows系统中的-本地安全策略中,配置了四类安全策略,账号策略、本地策略、公份策略和IP安全策略。那么该操作于操作系统安全配置内容中的()。","options":["关闭不必要的服务","关闭不必要的端口","制定安全策略","查看日志记录"],"correctIndex":2,"explanation":"小张在Windows系统中的“本地安全策略”中配置账号策略、本地策略、公钥策略和IP安全策略,这属于制定安全策略的操作。A选项关闭不必要的服务、B选项关闭不必要的端口,题干中均未提及；D选项查看日志记录与配置这些策略无关。所以选C。","imageNames":[]},{"id":"wx2026-01-023","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"23","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型(SSE-CM),错误的理解是()","options":["SSE-CMM 要求实施组织与其他组织相互作用,如开发方、产品供应商、集成商和咨询服务商等","SSE-CMM 可以使安全工程成为一个确定的、成熟的和可度量的科目。","基于SSE-CMM的工程是独立工程,与软件工程、硬件工程、通信工程等分别规划实施","SSE-CMM覆盖整个组织的活动,包括管理、组织和工程活动等,而不仅仅是系统安全的工程活动"],"correctIndex":2,"explanation":"SSE - CMM强调系统安全工程与其他工程学科如软件工程、硬件工程、通信工程等是相互关联和影响的,并非独立工程。","imageNames":[]},{"id":"wx2026-01-024","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"24","domain":"信息安全法规标准","stem":"关于 Wi-Fi联盟提出的安全协议 WPA 和 WPA2 的区别,下面描述正确的是()。","options":["WPA是有线局域安全协议,而WPA2是无线局域网协议","WPA是适用于中国的无线局域安全协议,而WPA2是适用于全世界的无线局域网协议","WPA没有使用密码算法对接入进行认证,而WPA2使用了密码算法对接入进行认证","WPA是依照802.11i标准草案制定的,而WPA2是依照802.11i正式标准制定的"],"correctIndex":3,"explanation":"WPA是依照802.11i标准草案制定的,而WPA2是依照802.11i正式标准制定的。A选项WPA和WPA2都是无线局域网安全协议；B选项WPA并非仅适用于中国；C选项WPA和WPA2都使用了密码算法对接入进行认证。所以选D。","imageNames":[]},{"id":"wx2026-01-025","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"25","domain":"信息安全技术","stem":"二十世纪二十年代,德国发明家亚瑟谢尔比乌斯(Arthur Scherbius)发明了Enigma密码机,按照密码学发展历史阶段划分,这个阶段属于()。","options":["古典密码阶段。这一阶段的密码专家常常靠直觉和技巧来设计密码,而不是凭借推理和证明,常用的密码运算方法包括替代方法和置换方法","近代密码发展阶段。这一阶段开始使用机械代替手工计算,形成了机械式密码设备和更进一步的机电密码设备","现代密码学的早期发展阶段。这一阶段以香农的论文“保密系统的通信理论”(“The Communication Theory of Secret Systems”)为理论基础,开始了对密码学的科学探索","现代密码学的近期发展阶段。这一阶段以公钥密码思想为标志,引发了密码学历史上的革命性的变革,同时,众多的密码算法开始应用于非机密单位和商业场合"],"correctIndex":1,"explanation":"二十世纪二十年代德国发明家亚瑟谢尔比乌斯发明的Enigma密码机,开始使用机械代替手工计算,形成了机械式密码设备,属于近代密码发展阶段。A选项古典密码阶段主要靠直觉和技巧设计密码,常用替代和置换方法,该阶段不符合；C选项现代密码学的早期发展阶段以香农的论文为理论基础；D选项现代密码学的近期发展阶段以公钥密码思想为标志。所以选B。","imageNames":[]},{"id":"wx2026-01-026","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"26","domain":"信息安全保障","stem":"以下关于项目的含义,理解错误的是()。","options":["项目是为达到特定的目的、使用一定资源、在确定的期间内、为特定发起人而提供独特的产品、服务或成果而进行的一次性努力","项目有明确的开始日期,结束日期由项目的领导者根据项目进度来随机确定","项目资源指完成项目所需要的人、财、物等","项目目标要遵守 SMART 原则,即项目的目标要求具体(Specific)、可测量(Measurable)、需相关方的一致同意(Agree to)、现实(Realistic)、有一定的时限(Time-oriented)"],"correctIndex":1,"explanation":"项目有明确的开始日期和结束日期,结束日期不是由项目领导者随机确定的,而是根据项目目标、范围、资源等多种因素预先规划好的。","imageNames":[]},{"id":"wx2026-01-027","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"27","domain":"信息安全技术","stem":"以下关于 Web 传输协议、服务端和客户端软件的安全问题说法不正确的是()。","options":["HTTP 协议主要存在明文传输数据、弱验证和缺乏状态跟踪等方面的安全问题","HTTP 协议缺乏有效的安全机制,易导致拒绝服务、电子欺骗、嗅探等攻击","Cookie 是为了辨别用户身份,进行会话跟踪而存储在用户本地终端上的数据,用户可以随意查看存储在 Cookie中的数据,但其中的内容不能被修改","针对 HTP 协议存在的安全问题,使用 HTTPS 具有较高的安全性,可以通过证书来验证服务器的身份,并为浏览器和服务器之间的通信加密"],"correctIndex":2,"explanation":"Cookie是为了辨别用户身份,进行会话跟踪而存储在用户本地终端上的数据,用户不仅可以随意查看存储在Cookie中的数据,其中的内容也可以被修改。","imageNames":[]},{"id":"wx2026-01-028","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"28","domain":"信息安全法规标准","stem":"小李在某单位是负责信息安全风险管理方面工作的部门领导,主要负责对所在行业的新人进行基本业务素质培训.一次培训的时候,小李主要负责讲解风险评估方法.请问小李的所述论点中错误的是哪项()","options":["风险评估方法包括:定性风险分析、定量风险分析以及半定量风险分析","定性风险分析需要凭借分析者的经验和直觉或者业界的标准和惯例,因此具有随意性","定量风险分析试图在计算风险评估与成本效益分析期间收集的各个组成部分的具体数字值,因此更具客观性","半定量风险分析技术主要指在风险分析过程中综合使用定性和定量风险分析技术对风险要素的赋值方式,实现对风险各要素的度量数值化"],"correctIndex":1,"explanation":"定性风险分析虽然凭借分析者的经验和直觉或者业界的标准和惯例,但并不是具有随意性,而是在一定规则和经验基础上进行的。","imageNames":[]},{"id":"wx2026-01-029","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"29","domain":"信息安全技术","stem":"以下关于网络安全设备说法正确的是()。","options":["防火墙既能实现内外网物理隔离,又能实现内外网逻辑隔离","安全隔离与信息交换系统也称为网闸,需要信息交换时,同一时间可以和两个不同安全级别的网络连接","入侵检测系统的主要作用是发现并报告系统中未授权或违反安全策略的行为","虚拟专用网是在公共网络中。利用隧道技术,建立一个永久、安全的通信网络"],"correctIndex":2,"explanation":"入侵检测系统的主要作用是发现并报告系统中未授权或违反安全策略的行为。A选项防火墙主要实现内外网逻辑隔离,不能实现物理隔离。B选项安全隔离与信息交换系统（网闸）需要信息交换时,同一时间只能和一个不同安全级别的网络连接；D选项虚拟专用网是在公共网络中利用隧道技术建立临时、安全的通信网络,不是永久。","imageNames":[]},{"id":"wx2026-01-030","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"30","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合IS0/IEC 27001或GB/T 22080标准要求,其信息安全控制措施通常需要在资产管理方面实施常规控制,资产管理包含对资产负责和信息分类两个控制目标。信息分类控制的目标是为了确保信息受到适当级别的保护,通常采取以下哪项控制措施()","options":["资产清单","资产责任人","资产的可接受使用","分类指南、信息的标记和处理"],"correctIndex":3,"explanation":"信息分类控制的目标是为了确保信息受到适当级别的保护,通常采取分类指南、信息的标记和处理等控制措施。A选项资产清单是资产管理中对资产进行登记的内容；B选项资产责任人是明确资产管理责任；C选项资产的可接受使用是规定资产的使用规范。","imageNames":[]},{"id":"wx2026-01-031","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"31","domain":"信息安全法规标准","stem":"具有行政法律责任强制力的安全管理规定和安全制度包括() (1)安全事件(事故)制度2)安全等级保护制度(3)信息系统安全监控(4)安全专用产品销许可证制度","options":["1,2,4","2,3","2,3,4","1,2,3"],"correctIndex":0,"explanation":"安全等级保护制度是国家信息安全保障的基本制度、基本策略和基本方法,具有行政法律责任强制力。 安全专用产品销售许可证制度是对销售安全专用产品的企业进行管理,确保产品质量,保障信息安全,具有行政法律责任强制力。 安全事件（事故）制度用于规范安全事件的处理流程、责任追究等,具有行政法律责任强制力。 信息系统安全监控主要是对信息系统运行状态的监测,本身不属于具有行政法律责任强制力的制度。所以选A。","imageNames":[]},{"id":"wx2026-01-032","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"32","domain":"信息安全管理","stem":"老王是一名企业信息化负责人,由于企业员工在浏览网页时总导致病毒感染系统,为了解决这一问题,老王求信息安全员给出解决措施,信息安全员给出了四条措施建议,老王根据多年的信息安全管理经验,认为其中不太适合推广,你认为是哪条措施()","options":["采购防病毒网关并部署在企业互联网出口中,实现对所有浏览网页进行检测,阻止网页中的病毒进入内网","采购并统一部署企业防病毒软件,信息化管理部门统一进行病毒库升级,确保每台计算机都具备有效的病毒检测和查杀能力","制定制度禁止使用微软的 IE 浏览器上网,统一要求使用 Chrome 浏览器","组织对员工进行一次上网行为安全培训,提高企业员工在互联网浏览时的安全意识"],"correctIndex":2,"explanation":"选项C禁止使用微软的IE浏览器而统一要求使用Chrome浏览器,这种做法过于绝对。不同浏览器都有其特点和适用场景,而且不能从根本上解决病毒感染问题,因为其他浏览器也可能存在安全漏洞,不太适合推广。","imageNames":[]},{"id":"wx2026-01-033","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"33","domain":"信息安全法规标准","stem":"关于信息安全管理体系(Information Security Management Systems,ISMS),下面描述错误的是()。","options":["信息安全管理体系是组织在整体或特定范围内建立信息安全方针和目标,以及完成这些目标所用方法的体系,包括组织架构、方针、活动、职责及相关实践要素","管理体系(Management Systems)是为达到组织目标的策略、程序、指南和相关资源的框架,信息安全管理体系是管理体系思想和方法在信息安全领域的应用","概念上,信息安全管理体系有广义和狭义之分,狭义的信息安全管理体系是指按照 IS027001 标准定义的管理体系,它是一个组织整体管理体系的组成部分","同其他管理体系一样,信息安全管理体系也要建立信息安全管理组织机构、健全信息安全管理制度、构建信息安全技术防护体系和加强人员的安全意识等内容"],"correctIndex":3,"explanation":"选项D中,信息安全管理体系主要侧重于信息安全方面的管理,虽然也会涉及组织机构、制度、技术防护和人员意识等内容,但与其他管理体系在目标和重点上有明显区别,不能简单等同。 34.Kerberos 协议是一种集中访问控制协议,它能在复杂的网络环境中,为用户提供安全的单点登录服务。单点登录是指用户在网络中进行一次身份认证,便可以访问其授权的所有网络资源,而不再需要其他的身份认证过程,实质是消息M在多个应用系统之间的传递或共享.其中消息M 是指以下选项中的()。 A.安全凭证 B.用户名 C. 加密密钥 D.会话密钥 答案:A 解析:Kerberos协议中,用户在网络中进行一次身份认证后获得安全凭证,凭借该安全凭证可以访问其授权的所有网络资源,而不再需要其他的身份认证过程,实现单点登录。用户名只是用户身份的标识；加密密钥和会话密钥是用于加密和解密数据的工具,不是实现单点登录时在多个应用系统之间传递或共享的消息。","imageNames":[]},{"id":"wx2026-01-034","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"34","domain":"信息安全技术","stem":"Kerberos 协议是一种集中访问控制协议,它能在复杂的网络环境中,为用户提供安全的单点登录服务。单点登录是指用户在网络中进行一次身份认证,便可以访问其授权的所有网络资源,而不再需要其他的身份认证过程,实质是消息M在多个应用系统之间的传递或共享.其中消息M 是指以下选项中的()。","options":["安全凭证","用户名","加密密钥","会话密钥"],"correctIndex":0,"explanation":"解析:Kerberos协议中,用户在网络中进行一次身份认证后获得安全凭证,凭借该安全凭证可以访问其授权的所有网络资源,而不再需要其他的身份认证过程,实现单点登录。用户名只是用户身份的标识；加密密钥和会话密钥是用于加密和解密数据的工具,不是实现单点登录时在多个应用系统之间传递或共享的消息。","imageNames":[]},{"id":"wx2026-01-035","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"35","domain":"信息安全法规标准","stem":"下列我国哪一个政策性文件明确了我国信息安全保障工作的方针和总体要求以及加强信息安全保障工作的主要原则()","options":["《关于加强政府信息系统安全和保密管理工作的通知》","《中华人民共和国计算机信息系统安全保护条例》","《国家信息化领导小组关于加强信息安全保障工作的意见》","《关于开展信息安全风险评估工作的意见》"],"correctIndex":2,"explanation":"选项A《关于加强政府信息系统安全和保密管理工作的通知》主要针对政府信息系统安全和保密管理提出要求。 选项B《中华人民共和国计算机信息系统安全保护条例》主要是对计算机信息系统的安全保护进行规范。 选项C《国家信息化领导小组关于加强信息安全保障工作的意见》明确了我国信息安全保障工作的方针和总体要求以及加强信息安全保障工作的主要原则。 选项D《关于开展信息安全风险评估工作的意见》重点是开展信息安全风险评估工作。","imageNames":[]},{"id":"wx2026-01-036","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"36","domain":"信息安全工程","stem":"以下关于威胁建模流程步骤说法不正确的是()。","options":["威胁建模主要流程包括四步:确定建模对象、识别威胁、评估威胁和消减威胁","评估威胁是对威胁进行分析,评估被利用和攻击发生的概率,了解被攻击后资产的受损后果,并计算风险","消减威胁是根据威胁的评估结果,确定是否要消除该威胁以及消减的技术措施,可以通过重新设计直接消除威胁,或设计采用技术手段来消减威胁","识别威胁是发现组件或进程存在的威胁,它可能是恶意的,也可能不是恶意的,威胁就是漏洞"],"correctIndex":3,"explanation":"选项D威胁和漏洞是不同的概念,威胁是指可能对系统造成损害的潜在因素,而漏洞是系统中存在的弱点,威胁可能利用漏洞进行攻击,但不能说威胁就是漏洞。","imageNames":[]},{"id":"wx2026-01-037","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"37","domain":"信息安全法规标准","stem":"某商贸公司信息安全管理员考虑到信息系统对业务影响越来越重要,计划编制本单位信息安全应急响应预案在向主管领导写报告时,他列举了编制信息安全应急响应预案的好处和重要性,在他罗列的四条理由中,其中不适合为理由的一条是（）","options":["应急预案是明确关键业务系统信息安全应急响应相挥体系和工作机制的重要方式","应预案是提高应对网络和信息系统突发事件能力,减少突发事件造成的损失和危害,保障信息系统运行平稳、安全、有序、高效的手段","编制应急预案是国家网络安全法对所有单位的强制要求,因此必须建设","应急预案是保障单位业务系统信息安全的重要措施"],"correctIndex":2,"explanation":"选项C虽然国家网络安全法对一些单位有信息安全相关的要求,但并不是对所有单位都强制要求编制信息安全应急响应预案,该说法过于绝对,不适合作为编制预案的理由。","imageNames":[]},{"id":"wx2026-01-038","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"38","domain":"信息安全法规标准","stem":"ISO 9001-2000标准鼓励在制定、实施质量管理体系以及改进其有效性时采用过程方法,通过满足顾客要求增进顾客满意。下图是关于过程方法的示意图,图中括号空白处应填写( )。","options":["策略","管理者","组织","活动"],"correctIndex":3,"explanation":"选项A策略是指导原则,不直接参与过程管控；选项B管理者负责制定方针、监控过程、确保资源,是过程方法的核心管控角色；选项C组织是主体,而非过程中的管控节点；选项D活动是过程的组成部分,在 ISO 9001:2000 标准的过程方法模型中,过程被定义为一组“相互关联或相互作用的活动”,这些活动利用资源将输入转化为输出。题目附图中的蓝色矩形框代表一个“过程”,框内五个小方块表示流程步骤,而括号位于该过程框的上方,通常标注的是过程的组成单位,即“活动”。","imageNames":["wx2026-01-04.png"]},{"id":"wx2026-01-039","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"39","domain":"信息安全管理","stem":"在某次信息安全应急响应过程中,小王正在实施如下措施:消除或阻断攻击源、找到并消除系统的脆弱性/漏洞、修改安全策略、加强防范措施、格式化被感染恶意程序的介质等。请问,按照PDCERF应急响应方法,这些工作应处于以下哪个阶段（ ）","options":["准备阶段","检测阶段","遏制阶段","根除阶段"],"correctIndex":3,"explanation":"准备阶段主要是制定应急响应计划、准备应急资源等前期工作。 检测阶段是发现信息安全事件的发生,确定事件的性质和范围。 遏制阶段是采取措施阻止事件的进一步扩散和恶化,如隔离受感染的系统等。 根除阶段是消除或阻断攻击源、找到并消除系统的脆弱性/漏洞、修改安全策略、加强防范措施、格式化被感染恶意程序的介质等,目的是彻底解决安全问题,防止事件再次发生。所以这些工作处于根除阶段。","imageNames":[]},{"id":"wx2026-01-040","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"40","domain":"信息安全技术","stem":"Kerberos 协议是常用的集中访问控制协议,通过可信第三方的认证服务,减轻应用服务器的负担。Kerberos 的运行环境由密钥分发中心(KDC)、应用服务器和客户端三个部分组成。其中,KDC 分为认证服务器 AS 和票据授权服务器TGS两部分。下图展示了 Kerberos 协议的三个阶段,分别为(1)Kerberos 获得服务许可票据,(2) Kerberos 获得服务,(3)Kerberos 获得票据许可票据。下列选项中,对这三个阶段的排序正确的是()。","options":["(1)-(2)-(3)","(3)-(2)一(1)","(2)-(1)一(3)","(3)一(1)一(2)"],"correctIndex":3,"explanation":"Kerberos协议的三个阶段顺序为:首先Kerberos获得票据许可票据,用户向认证服务器AS申请票据许可票据；然后Kerberos获得服务许可票据,用户凭借票据许可票据向票据授权服务器TGS申请服务许可票据；最后Kerberos获得服务,用户凭借服务许可票据向应用服务器申请服务。所以顺序是(3)-(1)-(2)。","imageNames":["wx2026-01-05.png"]},{"id":"wx2026-01-041","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"41","domain":"信息安全管理","stem":"关于对信息安全事件进行分类分级管理的原因描述不正确的是().","options":["信息安全事件的种类很多,产重程度也不尽相同,其响应和处理方式也应各不相同","对信息安全事件进行分类和分级管理,是有效防范和响应信息安全事件的基础","能够使事前准备、事中应对和事后处理的各项相关工作更具针对性和有效性","我国早期的计算机安全事件的应急响应工作主要包括计算机病毒防范和“千年虫”问题的解决,关于网络安全应急响应的起步最早"],"correctIndex":3,"explanation":"选项D:我国早期计算机安全事件的应急响应工作主要包括计算机病毒防范和“千年虫”问题的解决,但这与对信息安全事件进行分类分级管理的原因无关。","imageNames":[]},{"id":"wx2026-01-042","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"42","domain":"信息安全法规标准","stem":"某集团公司信息安全管理员根据领导安排制定了下一年度的培训工作计划,提出了四大培训任务和目标,关于这四个培训任务和目标,作为主管领导,以下选项中不合理的是()","options":["由于网络安全上升到国家安全的高度,网络安全必须得到足够的重视。因此安排了对集团公司下属单位的总经理(一把手)的网络安全法培训","对下级单位的网络安全管理岗人员实施全面安全培训,建议通过CISP 培训以确保人员能力得到保障","对其他信息化相关人员(网络管理员、软件开发人员)也进行安全基础培训,使相关人员对网络安全有所了解","对全体员工安排信息安全意识及基础安全知识培训,实现全员信息安全意识教育"],"correctIndex":2,"explanation":"选项A:管理层是安全策略的决策者,其法律意识直接影响企业合规性和资源投入。此类培训属于“自上而下”的安全文化推动,优先级最高。 选项B优先级中等:安全专岗是技术防护的核心力量,CISP认证能系统提升其专业能力,直接保障企业安全防护水平。此类培训属于“关键能力建设”。 选项C优先级最低:给懂点技术的人培训安全基础,相对其他几种来说培训效果最低,如:网络管理员本身就具备了安全基础知识。 选项D优先级次之:全员培训提升整体安全意识,覆盖范围广且个体影响差异大,需长期持续推进,也是法律合规的体现。 如果该题变为选出最合理的,则选A,如果变为最不合理的则选C。","imageNames":[]},{"id":"wx2026-01-043","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"43","domain":"信息安全技术","stem":"金女士经常通过计算机在互联网上购物,从安全角度看,下面哪项是不好的操作习惯()","options":["使用专用上网购物用计算机,安装好软件后不要对该计算机上的系统软件、应用软件进行升级","为计算机安装具有良好声誉的安全防护软件,包括病毒查杀、安全检查和安全加固方面的软件","在 IE 的配置中,设置只能下载和安装经过签名的、安全的ActiveX 控件","在使用网络浏览器时,设置不在计算机中保留网络历史记录和表单数据"],"correctIndex":0,"explanation":"选项A:使用专用上网购物用计算机是正确的,但不安装系统软件和应用软件的升级是不好的操作习惯。软件升级通常包含安全补丁,可以修复已知的安全漏洞,提高系统的安全性,不升级会使计算机容易受到攻击。","imageNames":[]},{"id":"wx2026-01-044","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"44","domain":"信息安全法规标准","stem":"在国家标准 GB/T 20274.1-2006《信息安全技术信息系统安全保障评估框架第一部分:简介和一般模型》中,信息系统安全保障模型包含哪几个方面?()","options":["保障要素、生命周期和运行维护","保障要素、生命周期和安全特征","规划组织、生命周期和安全特征","规划组织、生命周期和运行维护"],"correctIndex":1,"explanation":"在国家标准GB/T 20274.1-2006《信息安全技术 信息系统安全保障评估框架 第一部分:简介和一般模型》中,信息系统安全保障模型包含保障要素、生命周期和安全特征三个方面。保障要素是实施安全保障的基础；生命周期涵盖了信息系统从规划、设计、实施、运行到废弃的整个过程；安全特征则描述了信息系统应具备的安全属性。","imageNames":[]},{"id":"wx2026-01-045","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"45","domain":"信息安全技术","stem":"某信息安全公司的团队对某款名为“红包快抢”的外挂进行分析,发现此外挂是一个典型的木马后门,使黑客能够获得受害者电脑的访问权。该后门程序为了达到长期驻留在受害者的计算机中,通过修改注册表启动项来达到后门程序随受害者计算机系统启动而启动。为防范此类木马后门的攻击,以下做法无用的是()。","options":["不下载、不执行、不接收来历不明的软件或文件","修改用户名和口令","不随意打开来历不明的邮件,不浏览不健康不正规的网站","安装反病毒软件和防火墙,安装专门的木马防治软件"],"correctIndex":1,"explanation":"选项B:修改用户名和口令对于防范通过修改注册表启动项来达到长期驻留的木马后门攻击没有作用。此类木马后门主要关注的是系统的启动机制和注册表信息,与用户名和口令无关。","imageNames":[]},{"id":"wx2026-01-046","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"46","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合ISO/IEC27001或GB/T 22080标准要求,其信息安全控制措施通常需要在物理和环境安全方面实施常规控制。物理和环境安全领域包括安全区域和设备安全两个控制目标。安全区域的控制目标是防止对组织场所和信息的未授权物理访问、损坏和干扰,关键或敏感的信息及信息处理设施应放在安全区域内,并受到相应保护,该目标可以通过以下控制措施来实现,不包括哪一项()","options":["物理安全边界、物理入口控制","办公室、房间和设施的安全保护,外部和环境威胁的安全防护","通信安全、合规性","在安全区域工作,公共访问、交接区安全"],"correctIndex":2,"explanation":"选项C:通信安全主要涉及信息在传输过程中的保密性、完整性和可用性等,合规性是指组织遵守相关法律法规和标准的要求,它们不属于物理和环境安全领域中安全区域的控制措施。","imageNames":[]},{"id":"wx2026-01-047","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"47","domain":"信息安全管理","stem":"常见的访问控制模型包括自主访问控制模型、强制访问控制模型和基于角色的访问控制模型等。下面描述中错误的是()。","options":["从安全性等级来看,这三个模型安全性从低到高的排序是自主访问控制模型、强制访问控制模型和基于角色的访问控制模型","自主访问控制是一种广泛应用的方法,资源的所有者(往往也是创建者)可以规定谁有权访问它们的资源,具有较好的易用性和可扩展性","强制访问控制模型要求主体和客体都有一个固定的安全属性,系统用该安全属性来决定一个主体是否可以访问某个客体。该模型具有一定的抗恶意程序攻击能力,适用于专用或安全性要求较高的系统","基于角色的访问控制模型的基本思想是根据用户所担任的角色来决定用户在系统中的访问权限,该模型便于实施授权管理和安全约束,容易实现最小特权、职责分离等各种安全策略"],"correctIndex":0,"explanation":"自主访问控制安全性最低,强制访问控制安全性最高,基于角色的访问控制的灵活性和安全性介于自主访问控制和强制访问控制之间,并非安全性最高。","imageNames":[]},{"id":"wx2026-01-048","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"48","domain":"信息安全法规标准","stem":"PDCA循环又叫戴明环,是管理学常用的一种模型。关于PDCA四个字母,下面理解错误的是（）。","options":["P是Prepare,指准备,包括明确对象、方法,制定活动规划","D是Do,指实施、月体运作,实现计划中的内容","c是Check,指检查、总结执行计划的结果,明确效果,找出问题","A是Act或Adjut.指改进、完善和处理,对总结检查的结果进行处理。对成功的经验加以肯定,并予以标准化,总结失败的教训并加以重视,对没有解决的问题,应该交给下一个 PDCA 环解决"],"correctIndex":0,"explanation":"选项A:P是Plan,指计划,包括明确对象、方法,制定活动规划,而不是Prepare（准备）,该选项理解错误。","imageNames":[]},{"id":"wx2026-01-049","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"49","domain":"信息安全管理","stem":"小华在某电子商务公司工作。某天他在查看信息系统设计文档时,发现其中标注该信息系统的 RPO(恢复点目标)指标为3小时,请同这意味着()。","options":["该信息系统发生重大信息安全事件后,工作人员应在3小时内到位,完成问题定位和应急处理工作","该信息系统发生重大信息安全事件后,工作人员应在3小时内完成应急处理工作,并恢复对外运行","若该信总系统发生重大信息安全事件,工作人员在完成处置和灾难恢复工作后,系统至多能丢失3小时的业务类","若该信息系统发生重大信息安全事件,工作人员在完成处置和灾难恢复工作后,系统运行3小时后能恢复全部数"],"correctIndex":2,"explanation":"RPO（恢复点目标）是指在一个信息系统发生重大信息安全事件后,工作人员在完成处置和灾难恢复工作后,系统能容忍丢失的数据量所对应的时间点。该信息系统的RPO指标为3小时,意味着若该信息系统发生重大信息安全事件,工作人员在完成处置和灾难恢复工作后,系统至多能丢失3小时的业务数据。","imageNames":[]},{"id":"wx2026-01-050","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"50","domain":"信息安全管理","stem":"随机进程名称是恶意代码迷惑管理员和系统安全检查人员的技术手段之一,以下对于随机进程名技术。描述正确的是()。","options":["随机进程名技术虽然每次进程名都是随机的,但是只要找到了进程名称,就找到了恶意代码程序本身","恶意代码生成随机进程名称的目的是使进程名称不固定,因为杀毒软件是按进程名称进行病毒进程查杀,","恶意代码使用随机进程名是通过生成特定格式的进程名称,使进程管理器中看不到恶意代码的进程","随机进程名技术每次启动时随机生成恶意代码进程名称,通过不确定的进程名称使自己不容易被发现真实的恶意代码程序名称。"],"correctIndex":3,"explanation":"选项A:随机进程名技术每次启动时随机生成恶意代码进程名称,即使找到了某一次的进程名称,下次启动时进程名称又会改变,所以不能仅仅通过找到进程名称就找到恶意代码程序本身,该选项描述错误。 选项B:杀毒软件不仅仅是按进程名称进行病毒进程查杀,还会通过病毒特征码、行为分析等多种方式进行查杀,恶意代码生成随机进程名称的主要目的是使自己不容易被发现,而不是因为杀毒软件只按进程名称查杀,该选项描述错误。 选项C:恶意代码使用随机进程名并不是通过生成特定格式的进程名称使进程管理器中看不到恶意代码的进程,而是通过不断变化进程名称来迷惑管理员和安全检查人员,该选项描述错误。","imageNames":[]},{"id":"wx2026-01-051","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"51","domain":"信息安全管理","stem":"小王在学习定量风险评估方法后，决定试着为单位机房计算火灾的风险大小，假设单位机房的总价值为400万元人民币，暴露系数（ExposureFactor，EF）是25%，年度发生率（AnnualixedRateofOccurrence，ARO）为0.2。那么小王计算的年度预算损失（AnnualixedLossExpectancy，ALE）应该是（）","options":["100万元人民币","400万元人民币","20万元人民币","180万元人民币"],"correctIndex":2,"explanation":"年度损失预期值（ALE）=单次损失预期值（SLE）*年度发生率（ARO） - 单次损失预期值（SLE）=暴露因素（EF）*资产总价值（AV） - 暴露因素（EF）=资产总价值（AV）/损失的资产价值*100% - 年度发生率（ARO）=年度发生次数/年限 年度损失预期值=25%\\*400\\*0.2=20","imageNames":[]},{"id":"wx2026-01-052","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"52","domain":"信息安全管理","stem":"应急响应是信息安全事件管理的重要内容、基于应急响应工作的特点和事件的不规则性,事先制定出事件应急响应方法和过程,有助于一个组织在事件发生时院止混乱的发生成是在混配状态中迅速恢复控制,将损失和负面影响降到最低,应急响应方法和过程并不是唯一的,一种被广为按受的应急响应方法是将应急响应管理过程分为6个阶段,为准备>检测>送制>根除>恢复>跟踪>总结,请问下列说法有关于信息安全应急响应管理过程错误的是","options":["确定重要资产和风险,实施针对风险的防护措施是信息安全应想响应规划过程中最关健的步理","在检测阶段,首先要进行监测、报告及信息收集","遏制措施可能会因为事件的类别和级别不同而完全不同。常见的遏制措施有:完全关闭所有系统、拔掉网线等","应按照应急响应计划中事先制定的业务恢复优先顺序和恢复步骤,顺次恢复相关的系统"],"correctIndex":2,"explanation":"遏制措施需根据事件类型和级别动态调整,但“完全关闭所有系统”或“拔掉网线”属于极端手段,可能影响业务连续性。正确的遏制措施应平衡安全与业务需求（如隔离受感染设备、限制访问权限）。 “完全关闭所有系统”过于绝对,未考虑最小化影响原则。","imageNames":[]},{"id":"wx2026-01-053","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"53","domain":"信息安全工程","stem":"某购物网站开发项目经过需求分析进入系统设计阶段,为了保证用户帐户的安全,项目开发人员决定用户登录时除了用户名口令认证方式外,还加入基于数字证书的身份认证功能,同时用户口令使用 SHA-1 算法加密后存放在后台数据库中,请问以上安全设计遵循的是哪项安全设计原则()","options":["最小特权原则","职责分离原则织","深防御原则","最少共享机制原则"],"correctIndex":2,"explanation":"纵深防御原则是指在信息系统中采用多层防护机制,从不同的角度对系统进行保护,以提高系统的安全性。本题中除了用户名口令认证方式外,还加入基于数字证书的身份认证功能,同时对口令进行加密,采用了多种安全防护措施,遵循了纵深防御原则,该选项正确。选项A:最小特权原则是指每个主体（用户或进程）只被授予完成其任务所必需的最小权限集合。选项B:职责分离原则是指将不同的职责分配给不同的人员或角色,以降低欺诈或错误的风险。选项D:最少共享机制原则是指尽量减少系统中共享资源的数量和范围,以降低安全风险。","imageNames":[]},{"id":"wx2026-01-054","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"54","domain":"信息安全法规标准","stem":"在信息安全险管理过程中,背景建立是实施工作的第一步、下面哪项理解是错误的().","options":["背景建立的依据是国家、地区或行业的相关政策、法律、法规和标准,以及机构的使命、信息系统的业务目标和特性","背景建立阶段应识别需要保护的资产、面临的威胁以及存在的脆弱性,并分别赋值,同时确认已有的安全措施,形成需要保护的资产清单","背景建立阶段应调查信息系统的业务目标、业务特性、管理特性和技术特性,形成信息系统的描述报告求报告","背景建立阶段应分析信息系统的体系结构和关健要索,分析信息系统的安全环境和要求,形成信息系统的安全要"],"correctIndex":1,"explanation":"识别需要保护的资产、面临的威胁以及存在的脆弱性,并分别赋值,同时确认已有的安全措施,形成需要保护的资产清单,这些工作是在风险评估阶段完成的,而不是背景建立阶段。","imageNames":[]},{"id":"wx2026-01-055","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"55","domain":"信息安全技术","stem":"超文本传输协议(HyperText Transfer Protocol,HTTP)是互联网上广泛使用的一种网络协议。下面哪种协议基于 HTIP 并结合 SSL 协议,具各用户鉴别和通信数据加密等功能()、","options":["HTTP 1.0 协议","HTTP 1.1协议","HTTPS 协议","HTTPD 协议"],"correctIndex":2,"explanation":"HTTPS协议是基于HTTP协议并结合SSL协议,具备用户鉴别和通信数据加密等功能,能够提供更安全的网络通信。而HTTP 1.0协议和HTTP 1.1协议不具备这些安全功能,HTTPD协议不是基于HTTP并结合SSL协议的协议。","imageNames":[]},{"id":"wx2026-01-056","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"56","domain":"信息安全管理","stem":"“统一威胁管理”是将防病毒、入侵检测和防火墙等安全需求统一管理,目前市场上已经出现了多种此类安全设备,这里“统一威胁管理”常常被简称为()。","options":["UTM","FW","IDS","SOC"],"correctIndex":0,"explanation":"“统一威胁管理”常常被简称为UTM,它将防病毒、入侵检测和防火墙等安全需求统一管理。FW是防火墙的简称,IDS是入侵检测系统的简称,SOC是安全运营中心的简称。","imageNames":[]},{"id":"wx2026-01-057","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"57","domain":"信息安全技术","stem":"以下关于Windows操作系统身份标识与签别,说法不正确的是().","options":["本地安全授权机构(LSA)生成用户账户在该系统内唯一的安全标识符(SID)","用户对鉴别信息的操作,如更改密码等都通过一个以Administrator权限运行的服务“Security Account Manager”来实现","Windows 操作系统远程登录经历了 SMB 签别机制、LM签别机制、NTLM鉴别机制、Kerberos 签别体系等阶段","完整的安全标识符(SID)包括用户和组的安全描述,48比特的身份特权、修订版本和可变的验证值"],"correctIndex":1,"explanation":"SAM服务的权限:安全账户管理器（SAM）是Windows中存储用户账户和密码的数据库,但用户对鉴别信息的操作（如更改密码）并非直接通过SAM服务以Administrator权限运行。实际流程:用户通过LSASS（Local Security Authority Subsystem Service）进程提交密码修改请求,LSASS调用SAM接口更新数据,且LSASS以SYSTEM权限运行（高于Administrator）。SAM是数据库,而非独立服务；密码操作由LSASS代理,而非直接以Administrator权限运行SAM。","imageNames":[]},{"id":"wx2026-01-058","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"58","domain":"信息安全管理","stem":"王工是某单位的系统管理员,他在某次参加了单位组织的风险管理工作时,发现当前案例中共有两个重要资产:资产A1和资产 2:其中资产A1面临两个主要威胁:威胁T1和威胁 T2;而资产 A2 面临一个主要胁:威胁 T3:威胁 T1 可以利用的资产A1存在的两个脆弱性:脆弱性 V1和脆弱性V2:威胁T2可以利用的资产A1存在的三个脆弱性,脆弱性 V3、脆弱性 V4和脆弱性 V5:威胁 T3 可以利用的资产 A2存在的两个脆性:脆弱性V6和脆弱性 V7. 根据上述条件,请问:使用相乘法时,应该为资产 A1 计算几个风险值()","options":["2","3","5","6"],"correctIndex":2,"explanation":"A1风险值是由两个值来决定,一个是安全事件的可能性,一个是安全事件造成的损失,先算第一个安全事件的可能性,就是它的发生的这个频率,它是由这个威胁去乘以这个脆弱性的,A1资产有2个威胁,T1是利用的是2个脆弱性,就是1个威胁*2脆弱性,1*2=2,T2是3个脆弱性,就是1个威胁*3脆弱性,1*3=3,两者比较,取值选大的,最后它发生的这个频率是3,算出安全事件的可能性是3,然后再算第二个安全事件造成的损失。就是资产受到破坏的程度,它是由资产去乘以这个脆弱性,一个资产,正好是5个脆弱性,1*5=5。安全事件可能性是3,安全事件造成的损失是5,两者比较,一个是3,一个是5,取值选大的,得到5,选C。","imageNames":[]},{"id":"wx2026-01-059","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"59","domain":"信息安全工程","stem":"以下有关系统工程说法错误的是()。","options":["系统工程不属于基本理论,也不属于技术基础,它研究的重点是方法论","系统工程的目的是实现总体效果最优化,即从复杂问题的总体入手,认为总体大于各部分之和,各部分虽然存在不足,但总体可以优化","系统工程只需使用定量分析的方法,通过建立实际对象的数学模型,应用合适的优化算法对模型求解,解决实际问题","霍尔三维结构将系统工程整个活动过程分为前后紧密衔接的7个阶段和7个步骤"],"correctIndex":2,"explanation":"系统工程需要使用定量分析和定性分析相结合的方法,通过建立实际对象的数学模型,应用合适的优化算法对模型求解,同时结合定性分析来综合考虑各种因素,解决实际问题,而不是只需使用定量分析的方法。","imageNames":[]},{"id":"wx2026-01-060","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"60","domain":"信息安全工程","stem":"某单位根据业务需要准备立项开发一个业务软件,对于软件开发安全投入经费研讨时开发部门和信息中心就发生了分歧,开发部门认为开发阶段无需投入,软件开发完成后发现问题后再针对性的解决,比前期安全投入要成本更低;信息中心则认为应在软件安全开发阶段投入,后期解决代价太大,双方争执不下,作为信息安全专家,请选择对软件开发安全投入的准确说法()","options":["双方的说法都正确,需要根据具体情况分析是开发阶段投入解决问题还是在上线后再解决问题费用更低","双方的说法都错误,软件安全问题在任何时候投入解决都可以,只要是一样的问题,解决的代价相同","信息中心的考虑是正确的,在软件开发需求分析阶段开始考虑安全问题,总体经费投入比软件运行后的费用要低","软件开发部门的说法是正确的,因为软件出现安全问题后更清楚问题所在,安排人员进行代码修订更简单,因此费用更低"],"correctIndex":2,"explanation":"在软件开发需求分析阶段开始考虑安全问题,进行安全设计和开发,可以避免在后期发现安全问题时进行大规模的代码修改和系统调整,总体经费投入比软件运行后的费用要低。开发阶段不投入安全经费,后期解决安全问题往往代价更大。所以信息中心的考虑是正确的。","imageNames":[]},{"id":"wx2026-01-061","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"61","domain":"信息安全工程","stem":"某单位门户网站开发完成后,测试人员使用模糊测试进行安全性测试,以下关于模糊测试过程的说法正确的是()","options":["模拟正常用户输入行为,生成大量数据包作为测试用例","数据处理点、数据通道的入口点和可信边界点往往不是测试对象","监测和记录输入数据后程序正常运行的情况","深入分析网站测试过程中产生崩溃或异常的原因,必要时需要测试人员手工重现并分析"],"correctIndex":3,"explanation":"选项A:模糊测试是通过向被测系统输入非预期的、随机的或畸形的数据,来检测系统是否存在安全漏洞,而不是模拟正常用户输入行为生成大量数据包作为测试用例。选项B数据处理点、数据通道的入口点和可信边界点往往是模糊测试的重点测试对象,因为这些地方容易出现安全漏洞。选项 C:模糊测试主要是监测和记录输入数据后程序出现崩溃、异常等情况,而不是正常运行的情况。选项D:深入分析网站测试过程中产生崩溃或异常的原因,必要时需要测试人员手工重现并分析,这有助于找出系统的安全漏洞,所以D选项正确。","imageNames":[]},{"id":"wx2026-01-062","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"62","domain":"信息安全法规标准","stem":"我国等级保护政策发展的正确顺序是()。 1等级保护相关政策文件颁布 2计算机系统安全保护等级划分思想提出 3等级保护相关标准发布 4网络安全法将等级保护制度作为基本国策 5等级保护工作试点","options":["12345","23154","25134","12435"],"correctIndex":2,"explanation":"《中华人民共和国计算机信息系统安全保护条例》(国务院147号令)首先计算机系统安全保护等级划分思想提出；《关于信息安全等级保护工作的实施意见》（公通字[2004]66号）接着进行等级保护工作试点；然后等级保护相关政策文件颁布；之后《信息系统安全等级保护基本要求》（GBT 22239-2008）等级保护相关标准发布；最后网络安全法将等级保护制度作为基本国策。2017年《网络安全法》正式将等级保护制度上升为法律层面的基本制度,是政策的最高保障所以正确顺序是25134。","imageNames":[]},{"id":"wx2026-01-063","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"63","domain":"信息安全保障","stem":"《国家信息化领等小组关于加强信息安全保障工作的意见》（中办发[2003]27号）明确了我国信息安全保障工作的()、加强信息安全保障工作的()、需要重点加强的信息安全保障工作。27号文的重大意义是,它标志着我国信息安全保障工作有了、我国最近十余年的信息安全保障工作都是围绕此政策性文件来()的、促进了我国()的各项工作。","options":["方针;主要原则;总体纲领;展开和推进;信息安全保障建设总体要求;","总体要求;主要原则;展开;信息安全保障建设;","方针和总体要求;主要原则;总体纲领;展开和推进;信息安全保障建设;","总体要求;主要原则;总体纲领;展开;信息安全保建设;"],"correctIndex":2,"explanation":"《国家信息化领导小组关于加强信息安全保障工作的意见》（中办发[2003]27号）明确了我国信息安全保障工作的方针和总体要求、加强信息安全保障工作的主要原则、需要重点加强的信息安全保障工作。27号文的重大意义是,它标志着我国信息安全保障工作有了总体纲领,我国最近十余年的信息安全保障工作都是围绕此政策性文件来展开和推进的,促进了我国信息安全保障建设的各项工作。","imageNames":[]},{"id":"wx2026-01-064","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"64","domain":"信息安全管理","stem":"Linux系统的安全设置主要从磁盘分区、账户安全设置、禁用危险服务、远程登录安全、用户鉴别安全、审计策略、保护root 账户、使用网络防火墙和文件权限操作共10个方面来完成。小张在学习了Linux 系统安全的相关知识后,分试为自己计算机上的 Linux 系统进行安全配置。下列选项是他的部分操作,其中不合理的是()。","options":["编辑文件/etc/passwd,检查文件中用户ID,禁用所有用户ID=0的用户","编辑文件/etc/ssh/sshd_config,将PermitRootLogin 设置为 no","编辑文件/ete/pam.d/systemauth,设置auth required pam_tally.so onerrufail deny 6 unlock_time=300","编辑文件/etc /profile,设置TMOUT=600"],"correctIndex":0,"explanation":"选项 A 不合理:/etc/passwd 中用户 ID（UID）=0 的账户是 root 账户（系统超级管理员）,禁用所有 UID=0 的用户会导致系统失去超级管理员,无法进行核心配置、维护操作,破坏系统正常运行。正确做法是加强 root 账户保护（如禁止远程登录）,而非禁用。","imageNames":[]},{"id":"wx2026-01-065","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"65","domain":"信息安全管理","stem":"某单位在一次信息安全风险管理活动中,风险评估报告提出服务器的 FIP 服务存在高风险漏洞。随后该单位在风险处理时选择了安装 FTP 服务洞补丁程序并加固 FTP 服务安全措施,请问该措施属于哪种风险处理方式","options":["风险降低","风险规避","风险转移","风险接受"],"correctIndex":0,"explanation":"选项A:风险降低是指采取措施降低风险发生的可能性或减少风险发生后造成的损失。安装FTP服务漏洞补丁程序并加固FTP服务安全措施,降低了服务器因FTP服务漏洞被攻击的风险,属于风险降低,所以A选项正确。 选项B:风险规避是指通过改变计划,避免风险发生的可能性。选项C:风险转移是指将风险的后果连同应对的责任转移给第三方。选项D:风险接受是指明确风险存在,并主动承担风险后果。","imageNames":[]},{"id":"wx2026-01-066","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"66","domain":"信息安全技术","stem":"某银行有5台交换机连接了大量交易机构的网络(如图所示),在基于以太网的通信中,计算机A需要与计算机B通信,A必须先广播“ARP 请求信息”,获取计算机B的物理地址。每到月底时用户发现该银行网络服务速度极其缓慢、银行经调查后发现为了当其中一台交换机收到ARP 请求后,会转发给接收端口以外的其他所有端口,ARP 请求会被转发到网络中的所有客户机上.为降低网络的带宽消耗,将广播流限制在固定区域内,可以采用的技术是()","options":["配置虚拟专用网络","动态分配地址","为路由交换设备修改默认口令","VLAN 划分"],"correctIndex":3,"explanation":"选项A:配置虚拟专用网络主要是用于在不同网络之间建立安全的通信通道,不能将广播流限制在固定区域内,所以A错误。 选项B:动态分配地址主要是解决IP地址分配和管理的问题,不能降低广播流的带宽消耗,所以B错误。 选项C:为路由交换设备修改默认口令主要是提高设备的安全性,防止设备被非法访问,不能解决广播流的问题,所以C错误。 选项D:VLAN划分可以将一个物理网络划分为多个逻辑子网,将广播流限制在固定区域内,降低网络的带宽消耗,所以D正确。","imageNames":["wx2026-01-06.png"]},{"id":"wx2026-01-067","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"67","domain":"信息安全技术","stem":"关子ARP欺骗原理和防范措施,下面理解错误的是().","options":["ARP欺骗是指攻击者直接向受害者主机发送错误的 ARP 应答报文,使得受害者主机将错误的硬件地址映射关系有入到ARP 缓存中,从而起到冒充主机的目的","单纯利用ARP欺骗攻击时,ARP欺骗通常影响的是内部子网,不能跨越路由实施攻击","解决ARP欺骗的一个有效方法是采用“静态”的ARP缓存,如果发生硬件地址的更改,则需要人工更新缓存","彻底解决ARP欺骗的方法是避免使用ARP协议和ARP缓存,直接采用IP地址和其他主机进行连接"],"correctIndex":3,"explanation":"ARP协议是网络通信中用于解析IP地址和物理地址的重要协议,不能避免使用ARP协议和ARP缓存,否则网络将无法正常通信。","imageNames":[]},{"id":"wx2026-01-068","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"68","domain":"信息安全工程","stem":"由于频繁出现软件运行时被照客远程攻击获取数据的现象,某软件公司准备加强软件安全开发管理,在下面做法中,对于解决问题没有直接帮助的是()。","options":["要求所有的开发人员参加软件安全意识培调","要求规范软件编码,并制定公司的安全编码准则","要求增加软件安全测试环节,尽早发现软件安全问题","要求用windows10系统做开发"],"correctIndex":3,"explanation":"D选项:要求用windows10系统做开发,与软件运行时被黑客远程攻击获取数据的问题没有直接关系,不能直接解决问题。","imageNames":[]},{"id":"wx2026-01-069","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"69","domain":"信息安全工程","stem":"下列关于软件安全开发中的 BSI(Baild Security In)系列模型说法错误的是 O","options":["BSI含义是指将安全内建到软件开发过程中,而不是可有可无,更不是游离于软件开发生命周期之外","软件安全的三根支柱是风险管理、软件安全触点和安全知识","软件安全触点是软件开发生命周期中一套轻量缓最优工程化方法,它提供了从不同角度保障安全的行为方式","BSI系列模型强调安全测试的重要性,要求安全测试贯穿整个开发过程及软件生命周期"],"correctIndex":3,"explanation":"D选项:BSI系列模型强调将安全内建到软件开发过程中,而不是强调安全测试的重要性。","imageNames":[]},{"id":"wx2026-01-070","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"70","domain":"信息安全管理","stem":"关于信息安全应急响应管理过程描述不正确的是()。","options":["基于应急响应工作的特点和事件的不规则性,事先制定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生或是在混乱状态中迅速恢复控制,将损失和负面影响降至最低","应急响应方法和过程并不是唯一的","一种被广为接受的应念响应方法是将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪总结6个阶段","一种被广为接受的应急响应方法是将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪总结6个阶段,这6个阶段的响应方法一定能确保事件处理的成功"],"correctIndex":3,"explanation":"虽然将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪总结6个阶段是一种被广为接受的方法,但不能确保事件处理的成功,因为事件的不确定性和复杂性,所以D选项错误。","imageNames":[]},{"id":"wx2026-01-071","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"71","domain":"信息安全法规标准","stem":"按照我国信息安全等级保护的有关政策和标准，有些信息系统只需要自主定级、自主保护，按照要求向 公安机关备案即可，可以不需要上级或主管都门来测评和检查。此类信息系统应属于：","options":["零级系统","一级系统","二级系统","三级系统"],"correctIndex":2,"explanation":"选二级,按标准和政策来,国家政策66号文,等保分为5个等级,每个级别都叫自主定级,自主保护。明确三级及以上需测评。","imageNames":[]},{"id":"wx2026-01-072","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"72","domain":"信息安全工程","stem":"由于密码技术都依赖于密钥,因此密钥的安全管理是密码技术应用中非常重要的环节,下列关于密钥管理说法错误的是()。","options":["科克霍夫在《军事密码学》中指出系统的保密性不依载于对加密体制或算法的保密,而依赖于密钥","在保密通信过程中,通信双方可以一直使用之前用过的会话密钥,不影响安全性","密钥管理需要在安全策略的指导下处理密钥生命周期的整个过程,包括产生、存储、备份、分配、更新、撤销等","在保密通信过程中,通信双方也可利用 DiffieHellnan 协议协商出会话密钥进行保密通信"],"correctIndex":1,"explanation":"在保密通信过程中,会话密钥不能一直使用。如果长期使用同一个会话密钥,一旦该密钥被破解,之前的所有通信内容都将面临泄露风险,所以需要定期更换会话密钥。","imageNames":[]},{"id":"wx2026-01-073","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"73","domain":"信息安全管理","stem":"一个信息管理系统通常会对用户进行分组并实施访问控制。例如,在一个学校的教务系统中,教师能够录入学生的考试成绩,学生只能查看自己的分数,而学校教务部门的管理人员能够对课程信息、学生的选课信息等内容进行修改,下列选项中,对访问控制的作用的理解错误的是()。","options":["对经过身份鉴别后的合法用户提供所有服务","拒绝非法用户的非授权访问请求","在用户对系统资源提供最大限度共享的基础上,对用户的访问权进行管理","防止对信息的非授权改和滥用"],"correctIndex":0,"explanation":"选项 A:访问控制的作用不是对经过身份鉴别后的合法用户提供所有服务,而是根据用户的身份和权限,为其提供相应的服务,限制其对系统资源的访问。","imageNames":[]},{"id":"wx2026-01-074","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"74","domain":"信息安全技术","stem":"小赵是某大学计算机科学与技术专业的毕业生，在前往一家大型企业应聘时，面试经理要求他给出该企业信息系统访问控制模型的设计思路。如果想要为一个存在大量用户的信息系统实现自主访问控制功能，在以下选项中，从时间和资源消耗的角度，下列选项中他应该采取的最合适的模型或方法是（）","options":["访问控制列表（ACL）","能力表（CL）","BLP模型","Biba模型"],"correctIndex":0,"explanation":"A选项:访问控制列表(ACL)是一种常用的自主访问控制方法,它通过在客体上附加一个主体明细表来表示访问控制矩阵,对于存在大量用户的信息系统,从时间和资源消耗的角度,ACL是一种比较合适的模型,该选项正确。 B选项:能力表(CL)是给主体赋予访问客体的能力,在大量用户的情况下,管理和维护能力表会比较复杂,时间和资源消耗较大,该选项错误。 C选项:BLP模型是一种强制访问控制模型,主要用于军事等对安全要求较高的领域,其实现和管理较为复杂,不适合大量用户的自主访问控制场景,该选项错误。 D选项:Biba模型也是一种强制访问控制模型,主要用于保证数据的完整性,同样不适合大量用户的自主访问控制场景,该选项错误。","imageNames":[]},{"id":"wx2026-01-075","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"75","domain":"信息安全法规标准","stem":"以下关于灾难恢复和数据备份的理解,说法正确的是()","options":["增量备份是备份从上次完全备份后更新的全部数据文件","依据具备的灾难恢复资源程度的不同,灾难恢复能力分为7个等级","数报备份按数据类型划分可以划分为操作系统备份和数据库备份","使用差分备份数据恢复时只需最后一次的标准备份,如果每天都有大量数据变化,差分备份工作非常费时"],"correctIndex":2,"explanation":"选项A:增量备份是备份从上次完全备份或增量备份后更新的数据文件,而不是从上次完全备份后更新的全部数据文件,该说法错误。 选项B:依据国家标准《信息系统灾难恢复规范》（GB/T 20988-2007）,灾难恢复能力分为6 个,而不是7个,该说法错误。 选项C:数据备份按数据类型划分可以划分为操作系统备份和数据库备份等,该说法正确。 选项D:使用差分备份,数据恢复时只需最后一次的完全备份与差分备份。如果每天都有大量数据变化,完全备份工作非常费时,而不是差分备份,该说法错误。","imageNames":[]},{"id":"wx2026-01-076","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"76","domain":"信息安全法规标准","stem":"规范的实施流程和文档管理,是信息安全风险评估能否取得成果的重要基础,某单位在实施风险评估时,按照规范形成了若干文档,其中下面()中的文档应属于风险评估中“风险要素识别”阶段输出的文档。","options":["《风险评估方案》,主要包括本次风险评估的目的、范围、目标、评估步、经费预算和进度安持等内容","《风险评估方法和工具列表》,主要包括拟用的风险评估方法和测试评估工八等内容","《风险评估准则要求》、主要包括现有风险评估参考标准、采用的风险分析方法、资产分类标准等内容","《已有安全措施列表》,主要包括经检查确认后的已有技术和管理各方面安全措施等内容"],"correctIndex":3,"explanation":"选项 A:《风险评估方案》（含目的、范围、进度等）是 “准备阶段” 的核心文档,用于明确评估计划,不属于识别阶段。选项 B:《风险评估方法和工具列表》是 “准备阶段” 确定的评估手段,用于规范评估过程,不属于识别阶段。选项 C:《风险评估准则要求》（含标准、分析方法、资产分类标准）是 “准备阶段” 制定的评估依据,用于统一评估口径,不属于识别阶段。选项D:《已有安全措施列表》记录经检查确认后的已有技术和管理各方面安全措施,是在风险要素识别阶段,对资产面临的风险进行识别时,需要考虑已有的安全措施情况,所以属于该阶段输出的文档。","imageNames":[]},{"id":"wx2026-01-077","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"77","domain":"信息安全管理","stem":"为了能够合理、有序地处理安全事件,应事先制定出事件应救响成方法和过程,有助于一个组织在事件发生时限止淝乱的发生或是在混乱状态中迅速恢复控制,将损失和负面影响降至最低。PDCERP方法论是一种广泛使用的方法,其将应急响应分成六个阶段,如下图所示,请为图中括号空白处选择合适的内容()。","options":["培训阶段","文档阶段","报告阶段","检测阶段"],"correctIndex":3,"explanation":"PDCERF 方法论是应急响应的经典框架,其六个阶段的固定顺序为: Preparation（准备阶段）→ Detection（检测阶段）→ Containment（控制阶段）→ Eradication（根除阶段）→ Recovery（恢复阶段）→ Follow-up（总结阶段）","imageNames":["wx2026-01-08.png"]},{"id":"wx2026-01-078","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"78","domain":"信息安全技术","stem":"以下关于互联网协议安全(Internet Protocol Security,IPsec)协议说法错误的是()。","options":["在传送模式中,保护的是IP负载","验证头协议(Authentication Header,AH)和IP封装安全载荷协议(Encapsulating Security Payload,ESP)都能以传输模式和隧道模式工作。","在随道模式中,保护的是整个互联网协议(Internet Protocol,IP)包,包括IP头","IPsec 仅能保证传输数据的可认证性和保密性。"],"correctIndex":3,"explanation":"选项 D:IPsec 的核心功能包括三方面:① 数据保密性（ESP 加密）、② 数据完整性（AH/ESP认证）、③ 数据源认证（AH/ESP认证）,部分场景还支持 “抗重播攻击”,并非 “仅保证可认证性和保密性”。","imageNames":[]},{"id":"wx2026-01-079","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"79","domain":"信息安全技术","stem":"目前,信息系统面临外部攻击者的恶意攻击威胁,从威胁能力和掌握资源分,这些或胁可以按照个人威胁、组织威胁和国家威胁三个层面划分,则下面选项中属于组织威胁的是 ()。","options":["喜欢恶作剧、实现自我挑战的娱乐型黑客","实施犯罪、获取非法经济利益网络犯罪团伙","搜集政治、军事、经济等情报信息的情报机构","巩固战略优势,执行军事任务、进行目标破坏的信息作战部队"],"correctIndex":1,"explanation":"选项 A:“娱乐型黑客” 以个人兴趣为驱动,无组织协作或资源支持,属于 “个人威胁”。 选项 B:“网络犯罪团伙” 有明确分工（如技术攻击、资金转移）、组织架构和资源支持,以非法经济利益为目标,属于 “组织威胁”。 选项 C:“情报机构” 是国家层面的官方组织,以获取他国战略情报为目标,属于 “国家威胁”。 选项 D:“信息作战部队” 是国家军事力量的组成部分,以破坏敌方信息系统、巩固战略优势为目标,属于 “国家威胁”。","imageNames":[]},{"id":"wx2026-01-080","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"80","domain":"信息安全法规标准","stem":"某电子商务网站在开发设计时,使用了威胁建模方法来分析电子商务网站所面临的威胁。STRIDE 是微软 SDL 中提出的威胁建模方法,将威胁分为六类,为每一类威胁提供了标准的消减措施,Spoofing 是 STRIDE 中欺骗类的威,以下威胁中哪个可以归入此类威胁(()","options":["网站竞争对手可能雇佣攻击者实施 DDoS 攻击,降低网站访问速度","网站使用 http 协议进行浏览等操作,未对数据进行加密,可能导致用户传输信息泄露,例如购买的商品金额等","网站使用http 协议进行浏览等操作,无法确认数据与用户发出的是否一致,可能数据被中途篡改","网站使用用户名、密码进行登录验证,攻击者可能会利用弱口令或其他方式获得用户密码,以该用户身份登录修改用户订单等信息"],"correctIndex":3,"explanation":"选项 A:DDoS 攻击的核心是 “消耗目标资源,导致服务不可用”,对应 STRIDE 中的 “Denial of Service（拒绝服务）”,而非欺骗。 选项 B:HTTP 协议未加密导致数据泄露,核心是 “信息被未授权获取”,对应 STRIDE 中的 “Information Disclosure（信息泄露）”,而非欺骗。。 选项 C:HTTP 协议无法确认数据一致性导致数据被篡改,核心是 “数据完整性被破坏”,对应 STRIDE 中的 “Tampering（篡改）”,而非欺骗。 选项 D:攻击者获取用户密码后 “以该用户身份登录”,本质是 “伪造合法用户身份”,符合 Spoofing（欺骗）的定义。","imageNames":[]},{"id":"wx2026-01-081","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"81","domain":"信息安全技术","stem":"保护-检测-响应(Protection-Detection-Response,PDR)模型是()工作中常用的模型,其思想是承认()中漏洞的存在,正视系统面临的(),通过采取适度防护、加强()、落实对安全事件的响应、建立对威胜的防护来保障系统的安全。","options":["信息系统;信息安全保障:威胁;检测工作","信息安全保障;信息系统;检测工作;威胁","信息安全保障;信息系统;威胁;检测工作","信息安全保障; 威胁; 信息系统; 检测工作"],"correctIndex":2,"explanation":"PDR模型是信息安全保障工作中常用的模型。其思想是承认信息系统中漏洞的存在,正视系统面临的威胁,通过采取适度防护、加强检测工作、落实对安全事件的响应、建立对威胁的防护来保障系统的安全。所以依次应填入信息安全保障、信息系统、威胁、检测工作。","imageNames":[]},{"id":"wx2026-01-082","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"82","domain":"信息安全技术","stem":"数据库的安全很复杂,往往需要考虑多种安全策略,才可以更好地保护数捌库的安全,以下关于数据库常用的安全策略理解不正确的题( )","options":["最小特权数则,是让用户可以合法的存取或能改数据库的前提下,分配最小的特权,使得这些信息恰好能够完成 用户的工作","最大共享策略,在保证数据库的完整性,保密性和可用性的前提下,最大程度地共享数据库中的信息","粒度最小策略,将数据库中的数据项进行划分,粒度越小,安全级别越高,在实际中需要选择最小粒度","按内容存取控制策略,不同权限的用户访问数据库的不同部分"],"correctIndex":2,"explanation":"选项A正确描述了最小特权原则的核心思想,即仅分配用户完成工作所需的最小权限,防止过度授权导致安全风险。选项B准确概括了最大共享策略的目标,即在保证数据库安全属性（完整性、保密性、可用性）的前提下,尽可能实现数据共享,避免过度限制导致数据库失去实用价值。 选项C数据库安全中的粒度划分需根据实际需求权衡安全与效率,并非粒度越小越好。例如,对整表设置权限可能降低管理复杂度,但若过度细化到字段级则可能影响性能。因此,实际应选择合理适当的粒度。 选项D正确描述了按内容存取控制策略,即根据数据内容动态分配用户权限,确保不同权限用户仅能访问其授权范围内的数据。","imageNames":[]},{"id":"wx2026-01-083","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"83","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS 符合IS0/IEC 27001或GB/T 22080标准要求,其信息安全控制措施通常在以下方面实施常规控制,以下哪个选项的内容不属于常规控制措施的范围","options":["信息安全方针、信息安全组织、资产管理","人力资源安全、物理和环境安全、通信安全","安全采购、开发与维护、合规性","安全事件管理、供应商关系、业务安全性审计"],"correctIndex":3,"explanation":"常规控制措施范围包括信息安全方针、信息安全组织、资产管理；人力资源安全、物理和环境安全、通信安全；安全采购、开发与维护、合规性；安全事件管理、供应商关系等。业务安全性审计不属于常规控制措施范围。","imageNames":[]},{"id":"wx2026-01-084","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"84","domain":"信息安全法规标准","stem":"关于《网络安全法》域外适用效力的理解,以下哪项是错误的()","options":["当前对于境外的网络攻击,我国只能通过向来源国采取抗议。","对于来自境外的网络安全威胁我国可以组织技术力量进行监测、防御和处置","对于来自境外的违法信息我国可以加以断传播","对于来自境外的网络攻击我国可以追究其法律责任"],"correctIndex":0,"explanation":"《网络安全法》具有域外适用效力。对于来自境外的网络安全威胁,我国可以组织技术力量进行监测、防御和处置；对于来自境外的违法信息可以加以阻断传播；对于来自境外的网络攻击可以追究其法律责任,并非只能通过向来源国采取抗议。","imageNames":[]},{"id":"wx2026-01-085","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"85","domain":"信息安全工程","stem":"信息系统安全保障评估概念和关系如图所示。信息系统安全保障评估,就是在信息系统所处的运行环境中对信息系统安全保障的具体工作和活动进行客观的评估,通过信息系统安全保障评估所搜集的(),向信息系统的所有相关方提供信息系统的()能够实现其安全保障策略,能够将其所面临的风险降低到其可接受的程度的主观信心。信息系统安全保障评估的评估对象是(),信息系统不仅包含了仅讨论技术的信息技术系统,还包括同信息系统所处的运行环境相关的人和管理等领域,信息系统安全保障是一个动态持续的过程,沙及信息系统整个(),因此信息系统安全保障的评估也应该提供一种()的信心。","options":["安全保障工作;客观证据;信息系统;生命周期;动态持续","客观证据;安全保障工作;信息系统;生命周期;动态持续","客观证据;安全保障工作;生命周期;信息系统;动态持续","客观证据;安全保障工作;动态持续;信息系统;生命周期"],"correctIndex":1,"explanation":"信息系统安全保障评估通过搜集客观证据,向相关方提供信息系统的安全保障工作能够实现其安全保障策略,将风险降低到可接受程度的主观信心。评估对象是信息系统,涉及信息系统整个生命周期,应提供动态持续的信心。所以顺序为客观证据、安全保障工作、信息系统、生命周期、动态持续。","imageNames":["wx2026-01-09.png"]},{"id":"wx2026-01-086","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"86","domain":"信息安全技术","stem":"数据在进行传输前,需要由协议栈自上而下对数据进行封装。TCP/IP 协议中,数据封装的顺序是()","options":["A传输层、网络接口层、互联网络层","传输层、互联网络层、网络接口层","互联网络层、传输层、网络接口层","互联网络层、网络接口层、传输层"],"correctIndex":1,"explanation":"在TCP/IP协议中,数据封装的顺序是传输层添加TCP或UDP头部,互联网络层添加IP头部,网络接口层添加帧头部和尾部,即传输层、互联网络层、网络接口层。","imageNames":[]},{"id":"wx2026-01-087","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"87","domain":"信息安全法规标准","stem":"跟据《信息安全等级保护管理办法》、《关于开展信息安全等级保护测评体系建设试点工作的通知》(公信安(20091812)级保护建设和开展()工作的知(公信安[20101303 号)等文件,由公安部对等级保护测评机构管理,接受测评机构的中请、考核和定期(),对不具备能力的测评机构则()","options":["等级测评;测评体系;等级保护评估中心;能力验证;取消授权","测评体系;等级保护评估中心;等级测评;能力验证;取消授权","测评体系;等级测评;等级保护评估中心;能力验证;取消授权","测评体系;等级保护评估中心;能力验证;等级测评;取消授权"],"correctIndex":2,"explanation":"根据相关文件,由公安部对等级保护测评机构管理,先开展测评体系建设试点工作,然后进行等级保护建设和开展等级测评工作,接受测评机构申请、考核和定期由等级保护评估中心进行能力验证,对不具备能力的测评机构取消授权。所以顺序为测评体系、等级测评、等级保护评估中心、能力验证、取消授权。","imageNames":[]},{"id":"wx2026-01-088","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"88","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS 符合IS0/IEC 27001成GB/T 22080 标准要求,其信息安全控制措施通常需要在符合性方面实施常规控制,符合性常规控制这一领域不包括以下哪项控制目标()","options":["符合法律要求","符合安全策略和标准以及技术符合性","信息系统审核考虑","访问控制的业务要求、用户访问管理"],"correctIndex":3,"explanation":"符合性常规控制领域包括符合法律要求、符合安全策略和标准以及技术符合性、信息系统审核考虑等。访问控制的业务要求、用户访问管理不属于符合性常规控制领域。","imageNames":[]},{"id":"wx2026-01-089","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"89","domain":"信息安全管理","stem":"随着信息技术的不断发展,信息系统的重要性也越来越突出,而与此同时,发生的信息安全事件也越来越多。综合分析信息安全问题产生的根源,下面描述正确的是(),","options":["信息系统自身存在脆弱性是根本原因。信息系统越来越重要,同时自身在开发、部署和使用过程中存在的脆弱性,导致了诸多的信息安全事件发生。因此,杜绝脆弱性的存在是解决信息安全问题的根本所在","信息系统面临诸多黑客的威胁,包括恶意攻击者和恶作剧攻击者。信息系统应用越来越广泛,接触信息系统的人越多,信息系统越可能遭受攻击。因此,避免有恶意攻击可能的人接触信息系统就可以解决信息安全问题","信息安全问题产生的根源要从内因和外因两个方面分析,因为信息系统自身存在脆弱性,同时外部又有威胁源,从而导致信息系统可能发生安全事件。因此,要防范信息安全风险,需从内外因同时着手","信息安全问题的根本原因是内因、外因和人三个因素的综合作用,内因和外因都可能导致安全事件的发生,但最重要的还是人的因素,外部攻击者和内部工作人员通过远程攻击、本地破坏和内外勾结等手段导致安全事件发生。因此,对人这个因素的防范应是安全工作重点"],"correctIndex":2,"explanation":"信息安全问题产生的根源要从内因和外因分析,内因是信息系统自身存在脆弱性,外因是外部有威胁源,二者共同作用导致信息系统可能发生安全事件。因此要防范信息安全风险,需从内外因同时着手,C选项正确。A选项杜绝脆弱性存在不现实；B选项避免有恶意攻击可能的人接触信息系统不能完全解决问题；D选项虽然人的因素重要,但内因和外因同样关键,不能只强调人的因素。","imageNames":[]},{"id":"wx2026-01-090","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"90","domain":"信息安全技术","stem":"即使最好用的安全产品也存在()。结果,在任何的系统中散手最终都能够找出一个被开发出的漏洞。一种有效的对策是在敌手和它的目标之间配备多种()。每一种机制都应包括()两种手段。","options":["安全机制:安全缺陷;保护和检测","安全缺陷;安全机制:保护和检测","安全缺陷;保护和检测:安全机制","安全缺陷;安全机制:外边和内部"],"correctIndex":1,"explanation":"即使最好的安全产品也存在安全缺陷,所以任何系统最终都可能被找出漏洞。有效的对策是在敌手和目标之间配备多种安全机制,每种机制都应包括保护和检测两种手段。","imageNames":[]},{"id":"wx2026-01-091","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"91","domain":"信息安全法规标准","stem":"某贸易公司的 0A 系统由于存在系统漏洞,被攻击者上传了木马病毒并删除了系统中的数据,由于系统备份是每周六进行一次,事件发生时间为周三,因此导致该公司三个工作日的数据丢失并使得0A 系统在随后两天内无法访问,影响到了与公司有业务往来部分公司业务。在事故处理报告中,根据 GB/Z 20986-2007《信息安全事件分级分类指南》,该事件的准确分类和定级应该是()","options":["有害程序事件 特别重大事件( I级)","信息破坏事件 重大事件(II级)","有害程序事件 较大事件(III级)","信息破坏事件 一般事件(IV级)"],"correctIndex":2,"explanation":"该事件是由于系统漏洞被攻击者上传木马病毒并删除数据,属于有害程序事件。事件导致三个工作日数据丢失且OA系统两天无法访问,影响部分公司业务,根据GB/Z 20986 - 2007《信息安全事件分级分类指南》,应定为较大事件（III级）。 选项A（有害程序事件I级）:影响程度不足以达到特别重大级别。 选项B（信息破坏事件II级）:事件分类不准确（应为有害程序事件）,且影响未达重大级别。 选项C（有害程序事件III级）:分类准确,定级影响程度未达到较大事件标准。但也可能因具体损失金额或业务影响程度不同而调整定级。 选项D（信息破坏事件一般事件IV级）:分类需修正为有害程序事件,但定级（IV级）符合实际影响。选项D的分类不够精准,因此优先选择C。","imageNames":[]},{"id":"wx2026-01-092","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"92","domain":"信息安全管理","stem":"从 Linux 内核 2.1 版开始,实现了基于权能的特权管理机制,实现了对超级用户的特权分割,打破了 UNIX/LINUX 操作系统中超级用户/普通用户的概念,提高了操作系统的安全性。下列选项中,对特权管理机制的理解错误的是()","options":["普通用户及其 shell 没有任何权能,而超级用户及其 shell 在系统启动之初拥有全部权能","系统管理员可以剥夺和恢复超级用户的某些权能","进程可以放弃自己的菜的权地","当普通用户的某些操作设计特权操作时,仍然通过setuid实现"],"correctIndex":1,"explanation":"系统管理员对超级用户权能的剥夺与恢复: 传统UNIX/Linux中,root权限是固有的,无法通过用户层工具直接剥夺或恢复其核心权能（如CAP_SYS_ADMIN）。权能机制允许进程主动放弃权能（如通过capset系统调用）,但系统管理员无法强制剥夺root的某些权能,除非修改内核参数或使用安全模块（如SELinux）限制其行为。","imageNames":[]},{"id":"wx2026-01-093","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"93","domain":"信息安全法规标准","stem":"以下哪项制度或标准被作为我国的一项基础制度加以推行,并且有一定强制性,其实施的主要目标是提高我国信息和信息系统安全建设的整体水平,重点保障基础信息网络和重要信息系统的安全。()","options":["信息安全管理体系(ISMS)","信息安全等级保护","NIST SP800","IS0 270000 系列"],"correctIndex":1,"explanation":"信息安全等级保护是我国的一项基础制度,有一定强制性,主要目标是提高我国信息和信息系统安全建设的整体水平,重点保障基础信息网络和重要信息系统的安全。信息安全管理体系（ISMS）、NIST SP800、ISO 27000系列都不是我国特有的基础制度,答案选B。","imageNames":[]},{"id":"wx2026-01-094","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"94","domain":"信息安全管理","stem":"小牛在对某公司的信息系统进行风险评估后,因考虑到该业务系统中部分涉及金融交易的功能模块风险太高,他建议该公司以放弃这个功能模块的方式来处理该风险。请问这种风险处置的方法是()。","options":["降低风险","规避风险","转移风险","放弃风险"],"correctIndex":1,"explanation":"规避风险是指通过改变项目计划,消除风险或产生风险的条件,或者保护项目目标免受风险的影响。小牛建议公司放弃涉及金融交易且风险太高的功能模块,属于规避风险的处置方法,答案选B。降低风险是通过降低风险发生的可能性或减少风险造成的损失来应对风险；转移风险是将风险的后果连同应对的责任转移给第三方；放弃风险表述不准确,一般是规避风险的说法。","imageNames":[]},{"id":"wx2026-01-095","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"95","domain":"信息安全技术","stem":"部署互联网协议安全虚拟专用网(Internet Protocol Security Virtual Private Network, IPsec VPN)时,以下说法正确的是().","options":["配置MD5安全算法可以提供可靠地数据加密","配置 AES 算法可以提供可靠的数据完整性验证","部署IPsec VPN网络时,需要考虑IP地址的规划,尽量在分支节点使用可以聚合的IP地址段,来减少IPsec安全关联(Security Authentication,SA)资源的消耗","报文验证头协议(Authentication Header,AH)可以提供数据机密性"],"correctIndex":2,"explanation":"MD5是一种摘要算法,不能提供可靠的数据加密,A选项错误；AES算法是一种对称加密算法,主要用于数据加密,不能提供可靠的数据完整性验证,B选项错误；部署IPsec VPN网络时,考虑IP地址规划,在分支节点使用可聚合的IP地址段,可减少IPsec安全关联（SA）资源的消耗,C选项正确；报文验证头协议（AH）主要提供数据完整性、数据源认证和抗重放攻击,不能提供数据机密性,D选项错误。","imageNames":[]},{"id":"wx2026-01-096","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"96","domain":"信息安全技术","stem":"私有 IP 地址是一段保留的 IP 地址。只使用在局域网中,无法在 Internet 上使用。关于私有地址,下面描述正确的是()。","options":["A类和B类地址中没有私有地址,C类地址中可以设置私有地址","A类地址中没有私有地址,B类和C类地址中可以设置私有地址","A类、B 类和C类地址中都可以设置私有地址","A类、B类和C类地址中都没有私有地址"],"correctIndex":2,"explanation":"私有IP地址包括A类地址中的10.0.0.0 - 10.255.255.255,B类地址中的172.16.0.0 - 172.31.255.255,C类地址中的192.168.0.0 - 192.168.255.255。所以A类、B类和C类地址中都可以设置私有地址,答案选C。","imageNames":[]},{"id":"wx2026-01-097","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"97","domain":"信息安全技术","stem":"PKI的主要理论基础是()","options":["对称密码算法","公钥密码算法","量子密码","摘要算法"],"correctIndex":1,"explanation":"PKI（公钥基础设施）的主要理论基础是公钥密码算法,通过公钥和私钥的配合实现加密、解密、数字签名等功能,保障信息安全,答案选B。对称密码算法使用相同的密钥进行加密和解密；量子密码是一种新兴的密码技术；摘要算法主要用于生成数据的摘要信息,用于完整性验证等。","imageNames":[]},{"id":"wx2026-01-098","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"98","domain":"信息安全工程","stem":"你是单位安全主管,由于微软刚发布了数个系统漏洞补丁,安全运维人员给出了针对此批漏洞修补的四个建议方案,请选择其中一个最优方案执行()","options":["由于本次发布的数个漏洞都属于高危漏洞,为了避免安全风险,应对单位所有的服务器和客户端尽快安装补丁","本次发布的漏洞目前尚未出现利用工具,因此不会对系统产生实质性危害,所以可以先不做处理","对于重要的服务,应在测试环境中安装并确认补丁兼容性问题后再在正式生产环境中部署","对于服务器等重要设备,立即使用系统更新功能安装这批补丁,用户终端计算机由于没有重要数据,由终端自行升级"],"correctIndex":2,"explanation":"对于微软发布的系统漏洞补丁,不能因为尚未出现利用工具就不处理,B选项错误；也不能立即对所有服务器和客户端安装补丁,可能会因补丁兼容性问题影响系统正常运行,A选项错误；对于服务器等重要设备,应先在测试环境中安装并确认补丁兼容性问题后再在正式生产环境中部署,而不是立即使用系统更新功能安装,D选项错误；C选项的做法合理,能最大程度减少补丁对系统的影响。","imageNames":[]},{"id":"wx2026-01-099","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"99","domain":"信息安全技术","stem":"某网络安全公司基于网络的实时入侵检测技术,动态监测来自于外部网络和内部网络的所有访问行为。当检测到来自内外网络针对或通过防火墙的攻击行为,会及时响应,并通知防火墙实时阻断攻击源,从而进一步提高了系统的抗攻击能力,更有效地保护了网络资源,提高了防御体系级别。但入侵检测技术不能实现以下哪种功能()。","options":["检测并分析用户和系统的活动","核查系统的配置澜洞,评估系统关键资源和数据文件的完整性","防止 IP 地址欺骗","识别违反安全策略的用户活动"],"correctIndex":2,"explanation":"入侵检测技术可以检测并分析用户和系统的活动、核查系统的配置漏洞和评估系统关键资源和数据文件的完整性、识别违反安全策略的用户活动。但防止IP地址欺骗通常需要通过网络地址转换（NAT）、访问控制列表（ACL）等技术实现,入侵检测技术不能直接实现,答案选C。","imageNames":[]},{"id":"wx2026-01-100","setId":"wx2026-01","setName":"CISE 练习题（A卷）","sourceNumber":"100","domain":"信息安全法规标准","stem":"某IT公司针对信息安全事件已经建立了完善的预案,在年度企业信息安全总结会上,信息安全管理员对今应急预案工作做出了四个总结,其中有一项总结工作是错误,作为企业的CSO,请你指出存在问题的是哪个总结","options":[".公司制定的应急演练流程包括应急事件通报、确定应急事件优先级、应急响应启动实施、应急响应时间后期维、更新现有应急预案五个阶段,流程完善可用","公司应急预案包括了基础环境类、业务系统类、安全事件类和其他类,基本覆盖了各类应急事件类型","公司应急预案对事件分类依据 GB/220986-2007《信息安全技术信息安全事件分类分级指南》,分为7个基本类别,预案符合国家相关标准","公司成立了信息安全应急响应组织,该组织由业务和技术人员组成,划分成应急响应领导小组、技术保障小专家小组、实施小组和日常运行小组"],"correctIndex":3,"explanation":"参考《信息安全技术 信息安全应急响应计划规范》GB/T 24363-2009,内容如下,“应急响应的工作机构由管理、业务、技术和行政后勤等人员组成”,不仅是业务和技术。","imageNames":[]}]},{"id":"wx2026-02","name":"CISO 练习题（B卷）","subtitle":"2026 · 已审+解析","sourceFile":"2026- CISO练习题（B卷）-已审+解析.docx","questionCount":100,"questions":[{"id":"wx2026-02-001","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"1","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合ISO/IEC 27001或GB22080标准要求,其信息安全控制措施通常在以下方面实施常规控制,不包括哪一项（）","options":["信息安全方针、信息安全组织、资产管理","人力资源安全、物理和环境安全、通信安全","安全采购、开发与维护、合规性","安全事件管理、供应商关系、业务安全性审计"],"correctIndex":3,"explanation":"常规控制措施范围包括信息安全方针、信息安全组织、资产管理；人力资源安全、物理和环境安全、通信安全；安全采购、开发与维护、合规性；安全事件管理、供应商关系等。业务安全性审计不属于常规控制措施范围。","imageNames":[]},{"id":"wx2026-02-002","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"2","domain":"信息安全管理","stem":"关于信息安全管理体系的作用,下面理解错误的是()。","options":["对内而言,有助于建立起文档化的信息安全管理规范,实现有“法”可依,有章可循,有据可查","对内而言,是一个光花钱不挣钱的事情,需要组织通过其他方面收入来弥补投入","对外而言,有助于使各利益相关方对组织充满信心","对外而言,能起到规范外包工作流程和要求,帮助界定双方各自信息安全责任"],"correctIndex":1,"explanation":"信息安全管理体系虽然需要一定的投入,但从长远来看,它能降低信息安全事件带来的损失,提升组织的运营效率和竞争力,并非光花钱不挣钱。","imageNames":[]},{"id":"wx2026-02-003","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"3","domain":"信息安全技术","stem":"由于Internet的安全问题日益突出,基于TCP/IP协议,相关组织和专家在协议的不同层次设计了相应的安全通信协议,用来保障网络各层次的安全。其中,属于或依附于传输层的安全协议是（）。","options":["L2TP","SSL","PPTP","IPSec"],"correctIndex":1,"explanation":"PPTP（点对点隧道协议）和L2TP（第二层隧道协议）是数据链路层协议；SSL（安全套接层）是依附于传输层的安全协议,用于保障网络通信的安全；IPSec是网络层的安全协议。","imageNames":[]},{"id":"wx2026-02-004","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"4","domain":"信息安全法规标准","stem":"以下关于检查评估和自评估说法错误的是()","options":["信息安全风险评估分自评估、检查评估两形式。应以检查评估为主,自评估和检查评估相互结合、互为补充","检查评估可以依据相关标准的要求,实施完整的风险评估,也可以在自评估实施的基础上,对关键环节或重点内容实施抽样评估","信息安全风险评估应贯穿于网络和信息系统建设运行的全过程","自评估只能由组织自身发起并实施,对信息系统及其管理进行风险评估活动"],"correctIndex":0,"explanation":"信息安全风险评估分自评估和检查评估两种形式,应以自评估为主,检查评估和自评估相互结合、互为补充,而不是以检查评估为主。 5.以下关于 Windows操作系统身份标识与鉴别,说法不正确的是()。 A.本地安全授权机构(LSA)生成用户账户在该系统内唯一的安全标识符(SID) B.用户对鉴别信息的操作,如更改密码等都通过一个以Administrator权限运行的服务“Security Accounts Manager”来实现 C. Windows 操作系统远程登录经历了SMB鉴别机制、LM鉴别机制、NTLM鉴别机制、Kerberos 鉴别体系等阶段 D.完整的安全标识符(SID)包括用户和组的安全描述,48比特的身份特权、修订版本和可变的验证值 答案:B SAM服务的权限:安全账户管理器（SAM）是Windows中存储用户账户和密码的数据库,但用户对鉴别信息的操作（如更改密码）并非直接通过SAM服务以Administrator权限运行。实际流程:用户通过LSASS（Local Security Authority Subsystem Service）进程提交密码修改请求,LSASS调用SAM接口更新数据,且LSASS以SYSTEM权限运行（高于Administrator）。SAM是数据库,而非独立服务；密码操作由LSASS代理,而非直接以Administrator权限运行SAM。","imageNames":[]},{"id":"wx2026-02-005","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"5","domain":"信息安全技术","stem":"以下关于 Windows操作系统身份标识与鉴别,说法不正确的是()。","options":["本地安全授权机构(LSA)生成用户账户在该系统内唯一的安全标识符(SID)","用户对鉴别信息的操作,如更改密码等都通过一个以Administrator权限运行的服务“Security Accounts Manager”来实现","Windows 操作系统远程登录经历了SMB鉴别机制、LM鉴别机制、NTLM鉴别机制、Kerberos 鉴别体系等阶段","完整的安全标识符(SID)包括用户和组的安全描述,48比特的身份特权、修订版本和可变的验证值"],"correctIndex":1,"explanation":"SAM服务的权限:安全账户管理器（SAM）是Windows中存储用户账户和密码的数据库,但用户对鉴别信息的操作（如更改密码）并非直接通过SAM服务以Administrator权限运行。实际流程:用户通过LSASS（Local Security Authority Subsystem Service）进程提交密码修改请求,LSASS调用SAM接口更新数据,且LSASS以SYSTEM权限运行（高于Administrator）。SAM是数据库,而非独立服务；密码操作由LSASS代理,而非直接以Administrator权限运行SAM。","imageNames":[]},{"id":"wx2026-02-006","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"6","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合 ISO/IEC 27001或 GB/T 22080 标准要求,其信息安全控制措施通常需要在物理和环境安全方面实施常规控制。物理和环境安全领域包括安全区域和设备安全两个控制目标。安全区域的控制目标是防止对组织场所和信息的未授权物理访问、损坏和干扰,关键或敏感的信息及信息处理设施应放在安全区域内,并受到相应保护,该目标可以通过以下控制措施来实现,不包括哪一项( )","options":["物理安全边界、物理入口控制","办公室、房间和设施的安全保护,外部和环境威胁的安全防护","通信安全、合规性","在安全区域工作,公共访问、交接区安全"],"correctIndex":2,"explanation":"选项C:通信安全主要涉及信息在传输过程中的保密性、完整性和可用性等,合规性是指组织遵守相关法律法规和标准的要求,它们不属于物理和环境安全领域中安全区域的控制措施。","imageNames":[]},{"id":"wx2026-02-007","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"7","domain":"信息安全工程","stem":"由于频繁出现软件运行时被黑客远程攻击获取数据的现象,某软件公司准备加强软件安全开发管理,在下面做法中,对于解决问题没有直接帮助的是()。","options":["要求所有的开发人员参加软件安全意识培训","要求规范软件编码,并制定公司的安全编码准则","要求增加软件安全测试环节,尽早发现软件安全问题","要求开发人员采用瀑布模型进行开发"],"correctIndex":3,"explanation":"选项A:开发人员参加软件安全意识培训能提高他们对软件安全的重视程度,减少因安全意识不足导致的漏洞,对解决软件被攻击问题有帮助。选项B:规范软件编码并制定安全编码准则可以从源头上减少软件中的安全漏洞,降低被攻击的风险。选项C:增加软件安全测试环节能尽早发现软件中的安全问题并及时修复,提高软件的安全性。选项D:瀑布模型是一种软件开发模型,它强调开发的阶段性和顺序性,但对解决软件安全被攻击问题没有直接帮助,不能直接提升软件的安全性。","imageNames":[]},{"id":"wx2026-02-008","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"8","domain":"信息安全法规标准","stem":"某IT公司针对信息安全事件已经建立了完善的预案,在年度企业信息安全总结会上,信息安全管理员对今年应急预案工作做出了四个工作总结,作为企业的CSO,请你指出存在问题的是哪个总结？（)","options":["公司制定的应急演练流程包括应急事件通报、确定应急事件优先级,应急响应启动实施、应急响应时间后期运维、更新现在应急预案五个阶段,流程完善可用","公司应急预案包括了基础环境类、业务系统类、安全事件类和其他类,基本覆盖了各类应急事件类型","公司应急预案对事件分析依据GB/Z 20986-2007《信息安全技术信息安全事件分类分级指南》,分为7个基本类别,预案符合国家相关标准","公司成立了信息安全应急响应组织,该组织由业务和技术人员组成,划分成应急响应领导小组、技术保障小组、专家小组、实施小组和日常运行小组"],"correctIndex":3,"explanation":"参考《信息安全技术 信息安全应急响应计划规范》GB/T 24363-2009,内容如下,“应急响应的工作机构由管理、业务、技术和行政后勤等人员组成”,不仅是业务和技术。","imageNames":[]},{"id":"wx2026-02-009","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"9","domain":"信息安全技术","stem":"小李在检查公司对外服务网站的源代码时,发现程序在发生诸如没有找到资源、数据库连接错误、写临时文件错误等问题时,会将详细的错误原因在结果页面上显示出来。从安全角度考虑,小李决定修改代码,将详细的错误原因都隐藏起来,在页面上仅仅告知用户“抱歉,发生内部错误！”。请问,这种处理方法的主要目的是（）","options":["避免缓冲区溢出","安全处理系统异常","安全使用临时文件","最小化反馈信息"],"correctIndex":3,"explanation":"选项A:隐藏错误原因与避免缓冲区溢出没有直接关系,缓冲区溢出是由于程序未正确检查缓冲区边界导致的。选项B:安全处理系统异常是一个宽泛的概念,隐藏错误原因主要是为了减少信息泄露,而不是单纯的安全处理异常。选项C:隐藏错误原因与安全使用临时文件无关,临时文件的安全使用主要涉及文件的访问权限、存储位置等方面。选项D:“最小化反馈信息”是安全领域的核心原则之一,即仅向用户提供必要的信息,避免泄露系统内部细节。是为了最小化反馈给用户的信息,防止攻击者利用这些详细错误信息进行进一步的攻击。","imageNames":[]},{"id":"wx2026-02-010","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"10","domain":"信息安全技术","stem":"作为信息安全从业人员,以下哪种行为违反了CISP 职业道德准则()","options":["抵制通过网络系统侵犯公众合法权益","通过公众网络传播非法软件","不在计算机网络系统中进行造谣、欺诈、诽谤等活动","帮助和指导信息安全同行提升信息安全保障知识和能力"],"correctIndex":1,"explanation":"通过公众网络传播非法软件违反了法律法规和职业道德准则,会对网络环境和社会造成危害。","imageNames":[]},{"id":"wx2026-02-011","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"11","domain":"信息安全法规标准","stem":"规范的实施流程和文档管理,是信息安全风险评估能否取得成果的重要基础.某单位在实施风险评估时,按照规范形成了若干文档,其中,下面()中的文档应属于风险评估中“风险要素识别”阶段输出的文档。","options":["《风险评估方案》主要包括本次风险评估的目的、范围、目标、评估步骤、经费预算和进度安排等内容","《风险评估方法和工具列表》,主要包括拟用的风险评估方法和测试评估工具等内容","《风险评估准则要求》,主要包括现有风险评估参考标准、采用的风险分析方法、资产分类标准等内容","《已有安全措施列表》,主要包括经检查确认后的已有技术和管理各方面安全措施等内容"],"correctIndex":3,"explanation":"选项 A:《风险评估方案》（含目的、范围、进度等）是 “准备阶段” 的核心文档,用于明确评估计划,不属于识别阶段。选项 B:《风险评估方法和工具列表》是 “准备阶段” 确定的评估手段,用于规范评估过程,不属于识别阶段。选项 C:《风险评估准则要求》（含标准、分析方法、资产分类标准）是 “准备阶段” 制定的评估依据,用于统一评估口径,不属于识别阶段。选项D:《已有安全措施列表》记录经检查确认后的已有技术和管理各方面安全措施,是在风险要素识别阶段,对资产面临的风险进行识别时,需要考虑已有的安全措施情况,所以属于该阶段输出的文档。","imageNames":[]},{"id":"wx2026-02-012","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"12","domain":"信息安全工程","stem":"以下关于信息安全工程说法正确的是()。","options":["信息化建设中系统功能的实现是最重要的","信息化建设可以先实施系统,而后对系统进行安全加固","信息化建设中在规划阶段合理规划信息安全,在建设阶段要同步实施信息安全建设","信息化建设没有必要涉及信息安全建设"],"correctIndex":2,"explanation":"选项A:信息化建设中,信息安全与系统功能同样重要,不能只强调系统功能的实现,而忽视信息安全,否则可能导致系统面临各种安全威胁,该选项错误。 选项B:信息化建设不能先实施系统再进行安全加固,应该在规划阶段就合理规划信息安全,在建设阶段同步实施信息安全建设,否则后期加固可能会面临诸多困难,且可能无法从根本上保障系统安全,该选项错误。 选项C:在信息化建设规划阶段合理规划信息安全,建设阶段同步实施信息安全建设,能够使信息系统从设计到运行都具备较好的安全保障,该选项正确。 选项D:信息化建设必须涉及信息安全建设,信息安全是信息系统正常运行和业务持续开展的重要保障,该选项错误。","imageNames":[]},{"id":"wx2026-02-013","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"13","domain":"信息安全管理","stem":"关于信息安全事件管理和应急响应,以下说法错误的是:","options":["应急响应是指组织为了应对突发/重大信息安全事件的发生所做的准备,以及在事件发生后所采取的措施","应急响应方法,将应急响应管理过程分为遏制、根除、处置、恢复、报告和跟踪6 个阶段","对信息安全事件的分级主要参考信息系统的重要程度、系统损失和社会影响三方面因素","根据信息安全事件的分级参考要素,可将信息安全事件划分为4个级别:特别重大事件(Ⅰ级)、重大事件(Ⅱ级)、较大事件(Ⅲ级)和一般事件(Ⅳ级)"],"correctIndex":1,"explanation":"选项A:应急响应是组织为应对突发/重大信息安全事件所做的准备以及事件发生后采取的措施,该说法正确。 选项B:应急响应方法将应急响应管理过程分为准备、检测、遏制、根除、恢复、跟踪6个阶段,而不是遏制、根除、处置、恢复、报告和跟踪,该说法错误。 选项C:对信息安全事件的分级主要参考信息系统的重要程度、系统损失和社会影响三方面因素,该说法正确。 选项D:根据信息安全事件的分级参考要素,可将信息安全事件划分为4个级别:特别重大事件(Ⅰ级)、重大事件(Ⅱ级)、较大事件(Ⅲ级)和一般事件(Ⅳ级),该说法正确。","imageNames":[]},{"id":"wx2026-02-014","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"14","domain":"信息安全技术","stem":"关于信息安全保障技术框架(IATF),以下说法不正确的是:","options":["分层策略允许在适当的时候采用低安全级保障解决方案以便降低信息安全保障的成本","IATF从人、技术和操作三个层面提供一个框架实施多层保护,使攻击者即使攻破一层也无法破坏整个信息基础设施","允许在关键区域(例如区域边界)使用高安全级保障解决方案,确保系统安全性","IATF深度防御战略要求在网络体系结构各个可能位置实现所有信息安全保障机制"],"correctIndex":3,"explanation":"选项A:IATF的分层策略允许在适当的时候采用低安全级保障解决方案,以降低信息安全保障的成本,同时通过多层保护来提高整体安全性,该说法正确。 选项B:IATF从人、技术和操作三个层面提供框架,实施多层保护,使攻击者即使攻破一层也无法破坏整个信息基础设施,该说法正确。 选项C:IATF允许在关键区域（如区域边界）使用高安全级保障解决方案,确保系统在这些关键部分的安全性,该说法正确。 选项D:IATF深度防御战略要求在网络体系结构各个可能位置实现多种信息安全保障机制,但不是所有机制,而是根据实际情况选择合适的机制,该说法错误。","imageNames":[]},{"id":"wx2026-02-015","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"15","domain":"信息安全法规标准","stem":"以下关于灾难恢复和数据备份的理解,说法正确的是()。","options":["增量备份是备份从上次完全备份后更新的全部数据文件","依据具备的灾难恢复资源程度的不同,灾难恢复能力分为7个等级","数据备份按数据类型划分可以划分为操作系统备份和数据库备份","使用差分备份,数据恢复时只需最后一次的标准备份与差分备份,如果每天都有大量数据变化,差分备份工作非常费时"],"correctIndex":2,"explanation":"选项A:增量备份是备份从上次完全备份或增量备份后更新的数据文件,而不是从上次完全备份后更新的全部数据文件,该说法错误。 选项B:依据国家标准《信息系统灾难恢复规范》（GB/T 20988-2007）,灾难恢复能力分为6 个,而不是7个,该说法错误。 选项C:数据备份按数据类型划分可以划分为操作系统备份和数据库备份等,该说法正确。 选项D:使用差分备份,数据恢复时只需最后一次的完全备份与差分备份。如果每天都有大量数据变化,完全备份工作非常费时,而不是差分备份,该说法错误。","imageNames":[]},{"id":"wx2026-02-016","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"16","domain":"信息安全技术","stem":"以下关于互联网协议安全(Internet Protocol Security,IPSec)协议说法错误的是:","options":["在传送模式中,保护的是IP负载。","验证头协议(Authentication Header,AH)和IP封装安全载荷协议(Encapsulating Security Payload,ESP)都能以传输模式和隧道模式工作。","在隧道模式中,保护的是整个互联网协议IP包,包括IP 头。","IPSec仅能保证传输数据的可认证性和保密性"],"correctIndex":3,"explanation":"选项 D:IPsec 的核心功能包括三方面:① 数据保密性（ESP 加密）、② 数据完整性（AH/ESP认证）、③ 数据源认证（AH/ESP认证）,部分场景还支持 “抗重播攻击”,并非 “仅保证可认证性和保密性”。","imageNames":[]},{"id":"wx2026-02-017","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"17","domain":"信息安全法规标准","stem":"关于计算机取证描述不正确的是()","options":["计算机取证是使用先进的技术和工具,按照标准规程全面地检查计算机系统,以提取和保护有关计算机犯罪的相关证据的活动","取证的目的包括:通过证据查找肇事者、通过证据推断犯罪过程、通过证据判断受害者损失程度及收集证据提供法律支持","电子证据是计算机系统运行过程中产生的各种信息记录及存储的电子化资料及物品。对于电子证据,取证工作主要围绕两方面进行:证据的获取和证据的保护","计算机取证的过程可以分为准备、保护、提取、分析和提交5个步骤"],"correctIndex":2,"explanation":"电子证据取证工作不仅包括 “证据的获取和保护”,还包括 “证据的分析（如还原攻击过程）和提交（如形成法律认可的证据报告）”。","imageNames":[]},{"id":"wx2026-02-018","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"18","domain":"信息安全技术","stem":"即使最好用的安全产品也存在（）的结果,在任何的系统中敌手最终都能够找出一个被开发出的漏洞。一种有效的对策是在敌手和它的目标之间配备多种( ).每种机制都应包括()两种手段。","options":["安全机制;安全缺陷;保护和检测","安全缺陷;安全机制;保护和检测","安全缺陷;保护和检测;安全机制","安全缺陷;安全机制;外边和内部"],"correctIndex":1,"explanation":"即使最好的安全产品也存在安全缺陷,所以任何系统最终都可能被找出漏洞。有效的对策是在敌手和目标之间配备多种安全机制,每种机制都应包括保护和检测两种手段。","imageNames":[]},{"id":"wx2026-02-019","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"19","domain":"信息安全法规标准","stem":"具有行政法律责任强制力的安全管理规定和安全制度包括() 安全事件(包括安全事故)报告制度(2)安全等级保护制度(3)信息系统安全监控(4)安全专用产品销售许可证制度","options":["1,2,4","2,3","2,3,4","1,2,3"],"correctIndex":0,"explanation":"安全等级保护制度是国家信息安全保障的基本制度、基本策略和基本方法,具有行政法律责任强制力。 安全专用产品销售许可证制度是对销售安全专用产品的企业进行管理,确保产品质量,保障信息安全,具有行政法律责任强制力。 安全事件（事故）制度用于规范安全事件的处理流程、责任追究等,具有行政法律责任强制力。 信息系统安全监控主要是对信息系统运行状态的监测,本身不属于具有行政法律责任强制力的制度。所以选A。","imageNames":[]},{"id":"wx2026-02-020","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"20","domain":"信息安全工程","stem":"北京某公司利用SSE-CMM对其自身工程队伍能力进行自我改善,其理解正确的是:","options":["系统安全工程能力成熟度模型（SSE-CMM）定义了6个能力级别,当工程队不能执行一个过程域中的基本实践时,该过程域的过程能力为0级","达到SSE-CMM最高级以后,工程队伍执行同一个过程,每次执行结果质量必须相同。","系统安全工程能力成熟度模型（SSE-CMM）定义了3个风险过程:评价威胁,评价脆弱性,评价影响。","SSE-CMM强调系统安全工程与其他工程科学的区别和独立性"],"correctIndex":0,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-02-021","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"21","domain":"信息安全管理","stem":"王工是某单位的系统管理员,他在某次参加了单位组织的风险管理工作时,根据任务安排,他依据已有的资产列表,逐个分析可能危害这些资产的主体、动机、途径等多种因素,分析这些因素出现造成损失的可能性大小,并为其赋值。请问他这个工作属于下面哪一个阶段的工作（）。","options":["资产识别并赋值","脆弱性识别并赋值","威胁识别并赋值","确认已有的安全措施并赋值"],"correctIndex":2,"explanation":"A选项资产识别并赋值是对资产本身进行；B选项脆弱性识别并赋值是找系统的弱点；D选项确认已有的安全措施并赋值是对安全措施相关,所以选C。","imageNames":[]},{"id":"wx2026-02-022","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"22","domain":"信息安全法规标准","stem":"某集团公司信息安全管理员根据领导安排制定了一下年度的培训工作计划、提出了四大培训任务目标,关于这四个培训任务和目标,作为主管领导,以下选项中正确的是（）","options":["由于网络安全上升到国家安全的高度,因此网络安全必须得到足够的重视,因此安排了对集团公司下属公司的总经理(一把手)的网络安全法培训","对下级单位的网络安全管理人员实施全面安全培训,计划全员通过CISP持证培训以确保人员能力得到保障","对其他信息化相关人员(网络管理员、软件开发人员)也进行安全基础培训,使相关人员对网络安全有所了解","对全体员工安排信息安全意识及基础安全知识培训,安全全员信息安全意识教育"],"correctIndex":0,"explanation":"选项A:管理层是安全策略的决策者,其法律意识直接影响企业合规性和资源投入。此类培训属于“自上而下”的安全文化推动,优先级最高。 选项B优先级中等:安全专岗是技术防护的核心力量,CISP认证能系统提升其专业能力,直接保障企业安全防护水平。此类培训属于“关键能力建设”。 选项C优先级最低:给懂点技术的人培训安全基础,相对其他几种来说培训效果最低,如:网络管理员本身就具备了安全基础知识。 选项D优先级次之:全员培训提升整体安全意识,覆盖范围广且个体影响差异大,需长期持续推进,也是法律合规的体现。 如果该题变为选出最合理的,选A,如果变为最不合理的则选C。","imageNames":[]},{"id":"wx2026-02-023","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"23","domain":"信息安全法规标准","stem":"某商贸公司信息安全管理员考虑到信息系统对业务影响越来越重要,计划编制本单位信息安全应急响应预案,在向主管领导写报告时,他列举了编制信息安全应急响应预案的好处和重要性,在他罗列的四条理由中,其中不适合作为理由的一条是（）","options":["应急预案是保障单位业务系统信息安全的重要措施","应急预案是提高应对网络和信息系统突发事件能力,减少突发事件造成的损失和危害,保障信息系统运行平稳、安全、有序、高效的手段","编制应急预案是国家网络安全法对所有单位的强制要求,因此必须建设","应急预案是保障单位业务系统信息安全的重要措施"],"correctIndex":2,"explanation":"选项C虽然国家网络安全法对一些单位有信息安全相关的要求,但并不是对所有单位都强制要求编制信息安全应急响应预案,该说法过于绝对,不适合作为编制预案的理由。","imageNames":[]},{"id":"wx2026-02-024","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"24","domain":"信息安全管理","stem":"SABSA模型包括(),它是一个(),它在第一层从安全的角度定义了()。模型的每一层在抽象方面逐层减少,细节逐层增加,因此,它的层级都是建在其他层之上的,从策略逐渐到技术和解决方案的（）。其思路上创新提出了一个包括战略、概念、设计、实施、度量和审计层次的()","options":["五层:业务需求:分层模型:实施实践,安全链条","六层;分层模型;业务需求;实施实践:安全链条","五层;分层模型;业务需求:实施实践;安全链条","六层;分层模型:实施实践;业务需求:安全链条"],"correctIndex":1,"explanation":"SABSA模型包括六层,它是一个分层模型,在第一层从安全的角度定义了业务需求。模型的每一层在抽象方面逐层减少,细节逐层增加,层级建在其他层之上,从策略逐渐到技术和解决方案的实施实践。其思路上创新提出了一个包括战略、概念、设计、实施、度量和审计层次的安全链条。所以选B。","imageNames":[]},{"id":"wx2026-02-025","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"25","domain":"信息安全法规标准","stem":"信息安全管理体系（ISMS）的建设和实施是一个组织的战略性举措。若一个组织声称自己的ISMS符合ISO/IEC 27001或GB/T 22080标准要求,则需实施准要求,则需实施以下ISMS建设的各项工作,哪一项不属于ISMS建设的工作.()","options":["规划与建立 ISMS","实施和运行ISMS","监视和评审 ISMS","保持和审核 ISMS"],"correctIndex":3,"explanation":"ISMS建设的工作包括规划与建立ISMS、实施和运行ISMS、监视和评审ISMS。而保持和审核ISMS不属于ISMS建设的工作,而是后续持续改进和监督的环节。所以选D。","imageNames":[]},{"id":"wx2026-02-026","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"26","domain":"信息安全技术","stem":"Kerberos协议是常用的集中访问控制协议,通过可信第三方的认证服务,减轻应用服务器的负担。Kerberos的运行环境由密钥分发中心（KDC）、应用服务器和客户端三个部分组成。其中,KDC分为认证服务器AS和票据授权服务器TGS两部分。下图展示了Kerberos协议的三个阶段,分别为（1）Kerberos获得服务许可票据,（2）Kerberos获得服务,（3）Kerberos获得票据许可票据。下列选项中,对这三个阶段的排序正确的是（）。","options":["（2）→（1）→（3）","（3）→（1）→（2）","（1）→（2）→（3）","（3）→（2）→（1）"],"correctIndex":1,"explanation":"Kerberos协议的三个阶段顺序为:首先Kerberos获得票据许可票据,然后Kerberos获得服务许可票据,最后Kerberos获得服务。所以排序正确的是（3）→（1）→（2）,答案选B。","imageNames":["wx2026-02-01.png"]},{"id":"wx2026-02-027","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"27","domain":"信息安全法规标准","stem":"为保障信息系统的安全,某经营公众服务系统的公司准备并编制一份针对性的信息安全保障方案,并将编制任务交给了小王,为此,小王决定首先编制出一份信息安全需求描述报告。关于此项工作,下面说法错误的是()。","options":["信息安全需求报告应依据该公众服务信息系统的功能设计方案为主要内容来撰写","信息安全需求描述报告是设计和撰写信息安全保障方案的前提和依据","信息安全需求描述报告应当基于信息安全风险评估结果和有关政策法规和标准的合规性要求得到","信息安全需求描述报告的主体内容可以按照技术、管理和工程等方面需求展开编写"],"correctIndex":0,"explanation":"A选项:信息安全需求报告应依据信息安全风险评估结果和有关政策法规和标准的合规性要求得到,而不是主要依据公众服务信息系统的功能设计方案来撰写,该说法错误。","imageNames":[]},{"id":"wx2026-02-028","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"28","domain":"信息安全工程","stem":"你是单位安全主管,由于微软刚发布了数个系统漏洞补丁,安全运维人员给出了针对此批漏洞修补的四个建议方案,请选择其中一个最优方案执行()","options":["由于本次发布的数个漏洞都属于高危漏洞,为了避免安全风险,应对单位所有的服务器和客户端尽快安装补工","本次发布的漏洞目前尚未出现利用工具,因此不会对系统产生实质性危害,所以可以先不做处理","对于重要的服务,应在测试环境中安装并确认补丁兼容性问题后再在正式生产环境中部署","对于服务器等重要设备,立即使用系统更新功能安装这批补丁,用户终端计算机由于没有重要数据,由终端自行升级"],"correctIndex":2,"explanation":"选项A:虽然漏洞属于高危漏洞,但直接对所有服务器和客户端尽快安装补丁,可能会因补丁兼容性问题导致系统故障,影响业务正常运行。 选项B:虽然目前尚未出现利用工具,但不能忽视漏洞的潜在危害,不进行处理会使系统面临安全风险。 选项C:对于重要的服务,在测试环境中安装并确认补丁兼容性问题后再在正式生产环境中部署,既能保证系统的安全性,又能避免因补丁问题影响业务,是最优方案。 选项D:对于服务器等重要设备立即安装补丁,但用户终端计算机由终端自行升级,可能导致部分终端无法及时升级或升级出现问题,不能全面保障系统安全。","imageNames":[]},{"id":"wx2026-02-029","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"29","domain":"信息安全管理","stem":"GB／T 22080-2008《信息技术安全技术信息安全管理体系要求》指出,建立信息安全管理体系应参照PDCA模型进行,即信息安全管理体系应包括建立ISMS、实施和运行ISMS、监视和评审ISMS、保持和改进ISMS等过程,并在这些过程中应实施若干活动,请选出以下描述错误的选项（）","options":["“制定ISMS方针”是建设ISMS阶段工作内容","“实施培训和意识教育计划“是实施和运行ISMS阶段工作内容","“进行有效性测量”是监视和评审ISMS阶段工作内容","“实施内部审核”是保护和改进ISMS阶段工作内容"],"correctIndex":3,"explanation":"“实施内部审核”是监视和评审ISMS阶段的工作内容,用于检查ISMS是否符合标准要求和实际运行情况,而不是保持和改进ISMS阶段。","imageNames":[]},{"id":"wx2026-02-030","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"30","domain":"信息安全保障","stem":"信息系统建设完成后,（ ）的信息系统的而运营使用单位应当选择符合国家规定的测评机构进行测评合格后方可投入使用","options":["二级以上","三级以上","四级以上","五级以上"],"correctIndex":1,"explanation":"信息系统建设完成后,三级以上的信息系统的运营使用单位应当选择符合国家规定的测评机构进行测评合格后方可投入使用。","imageNames":[]},{"id":"wx2026-02-031","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"31","domain":"信息安全法规标准","stem":"小李在某单位是负责信息安全风险管理方面工作的部门领导,主要负责对所在行业的新人进行基本业务素质培训,一次培训的时候,小李主要负责讲解风险评估方法。请问小李的所述论点中错误的是哪项:","options":["风险评估方法包括:定性风险分析、定量风险分析以及半定量风险分析","定性风险分析需要凭借分析者的经验和直觉或者业界的标准和惯例,因此具有随意性","定量风险分析试图在计算风险评估与成本效益分析期间收集的各个组成部分的具体数字值,因此更具客观性","半定量风险分析技术主要指在风险分析过程中综合使用定性和定量风险分析技术对风险要素的赋值方式,实现对风险各要素的度量数值化"],"correctIndex":1,"explanation":"定性风险分析虽然凭借分析者的经验和直觉或者业界的标准和惯例,但并不是具有随意性,而是在一定规则和经验基础上进行的。","imageNames":[]},{"id":"wx2026-02-032","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"32","domain":"信息安全管理","stem":"小王在学习定量风险评估方法后,决定试着为单位机房计算火灾的风险大小。假设单位机房的总价值为400万元人民币,暴露系数（ExposureFactor,EF）是25%,年度发生率（Annualized Rate of Occurrence,ARO）为0.2,那么小王计算的年度预期损失（Annualized Loss Expectancy,ALE）应该是（）","options":["100 万元人民币","400 万元人民币","20 万元人民币","180 万元人民币"],"correctIndex":2,"explanation":"年度预期损失（ALE）的计算公式为:ALE = 单次预期损失额（SLE）× 年度发生率（ARO）。其中单次预期损失额（SLE）= 资产价值×暴露系数（EF）,已知资产价值为400万元人民币,暴露系数（EF）是25%,则SLE = 400×25% = 100万元人民币,年度发生率（ARO）为0.2,所以ALE = 100×0.2 = 20万元人民币。","imageNames":[]},{"id":"wx2026-02-033","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"33","domain":"信息安全工程","stem":"以下关于威胁建模流程步骤说法不正确的是()。","options":["威胁建模主要流程包括四步:确定建模对象、识别威胁、评估威胁和消减威胁","评估威胁是对威胁进行分析,评估被利用和攻击发生的概率,了解被攻击后资产的受损后果,并计算风险","消减威胁是根据威胁的评估结果,确定是否要消除该威胁以及消减的技术措施,可以通过重新设计直接消除威胁,或设计采用技术手段来消减威胁。","识别威胁是发现组件或进程存在的威胁,它可能是恶意的,威胁就是漏洞"],"correctIndex":3,"explanation":"选项D威胁和漏洞是不同的概念,威胁是指可能对系统造成损害的潜在因素,而漏洞是系统中存在的弱点,威胁可能利用漏洞进行攻击,但不能说威胁就是漏洞。","imageNames":[]},{"id":"wx2026-02-034","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"34","domain":"信息安全保障","stem":"以下关于项目的含义,理解错误的是()。","options":["项目是为达到特定的目的、使用一定资源、在确定的期间内、为特定发起人而提供独特的产品、服务或成果而进行的一次性努力","项目有明确的开始日期,结束日期由项目的领导者根据项目进度来随机确定","项目资源指完成项目所需要的人、财、物等","项目目标要遵守SMART原则,即项目的目标要求具体（Specific）、可测量（Measurable）、需相关方的一致同意(Agree to)、现实 (Realistic)、有一定的时限 (Time-oriented)"],"correctIndex":1,"explanation":"项目有明确的开始日期和结束日期,结束日期不是由项目领导者随机确定的,而是根据项目目标、范围、资源等多种因素预先规划好的。","imageNames":[]},{"id":"wx2026-02-035","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"35","domain":"信息安全工程","stem":"有关能力成熟度模型（CMM）错误的理解是","options":["CMM的基本思想是,因为问题是由技术落后引起的,所以新技术的运用会在一定程度上提高质量、生产率和利润率","CMM的思想来源于项目管理和质量管理","CMM是一种衡量工程实施能力的方法,是一种面向工程过程的方法","CMM是建立在统计过程控制理论基础上的,它基于这样一个假设,即“生产过程的高质量和在过程中组织实施的成熟性可以低成本地生产出高质量产品”"],"correctIndex":0,"explanation":"选项A:CMM的基本思想是把软件开发的努力集中呈现为一个有序的、有纪律的且能自我管理的软件过程,从而生产出高质量的软件,而不是认为问题是由技术落后引起且单纯靠新技术运用提高质量等。","imageNames":[]},{"id":"wx2026-02-036","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"36","domain":"信息安全技术","stem":"保护-检测-响应（Protection-Detection-Response,PDR）模型是（）工作中常用的模型,其思想是承认（）中漏洞的存在,正视系统面临的（）。通过采取适度防护、加强（）、落实对安全事件的响应、建立对威胁的防护来保障系统的安全","options":["信息系统；信息安全保障；威胁；检测工作","信息安全保障；信息系统；检测工作；威胁","信息安全保障；信息系统；威胁；检测工作","信息安全保障；威胁；信息系统；检测工作"],"correctIndex":2,"explanation":"PDR模型是信息安全保障工作中常用的模型。其思想是承认信息系统中漏洞的存在,正视系统面临的威胁,通过采取适度防护、加强检测工作、落实对安全事件的响应、建立对威胁的防护来保障系统的安全。所以依次应填入信息安全保障、信息系统、威胁、检测工作。","imageNames":[]},{"id":"wx2026-02-037","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"37","domain":"信息安全管理","stem":"王工是某单位的系统管理员,他在某次参加了单位组织的风险管理工作时,发现当前案例中共有两个重要资产；资产A1和资产A2；其中资产A1面临两个主要威胁；威胁T1和威胁T2；面资产A2面临一个主要威胁；威胁T3；威胁T1可以利用的资产A1存在的两个脆弱性；脆弱性V1和脆弱性V2；威胁T2利用资产A1存在的三个脆弱性,脆弱性V3、V4和V5。资产A2面临一个威胁T3,威胁T3利用A2的两个脆弱性V6和V7。根据上述条件,请问；使用相乘法时,应该为资产A1计算几个风险值（）","options":["2","3","5","6"],"correctIndex":2,"explanation":"A1风险值是由两个值来决定,一个是安全事件的可能性,一个是安全事件造成的损失,先算第一个安全事件的可能性,就是它的发生的这个频率,它是由这个威胁去乘以这个脆弱性的,A1资产有2个威胁,T1是利用的是2个脆弱性,就是1个威胁*2脆弱性,1*2=2,T2是3个脆弱性,就是1个威胁*3脆弱性,1*3=3,两者比较,取值选大的,最后它发生的这个频率是3,算出安全事件的可能性是3,然后再算第二个安全事件造成的损失。就是资产受到破坏的程度,它是由资产去乘以这个脆弱性,一个资产,正好是5个脆弱性,1*5=5。安全事件可能性是3,安全事件造成的损失是5,两者比较,一个是3,一个是5,取值选大的,得到5,选C。","imageNames":[]},{"id":"wx2026-02-038","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"38","domain":"信息安全管理","stem":"信息安全组织的管理涉及内部组织和外部各方两个控制目标。为了实现对组织内部信息安全的有效管理,应该实施常规的控制措施,不包括哪些选项()","options":["信息安全的管理承诺、信息安全协调、信息安全职责的分配","信息处理设施的授权过程、保密性协议、与政府部门的联系","与特定利益集团的联系、信息安全的独立评审","与外部各方相关风险的识别、处理外部各方协议中的安全问题"],"correctIndex":3,"explanation":"D选项:与外部各方相关风险的识别、处理外部各方协议中的安全问题属于对外部各方风险管理的控制目标,不是组织内部信息安全管理的常规控制措施。","imageNames":[]},{"id":"wx2026-02-039","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"39","domain":"信息安全法规标准","stem":"在国家标准GB/T 20274.1-2006《信息安全技术信息系统安全保障评估框架第一部分:简介和一般模型》中,信息系统安全保障模型包含哪几个方面？（）","options":["保障要素、生命周期和运行维护","保障要素、生命周期和安全特征","规划组织、生命周期和安全特征","规划组织、生命周期和运行维护"],"correctIndex":1,"explanation":"在国家标准GB/T 20274.1-2006《信息安全技术 信息系统安全保障评估框架 第一部分:简介和一般模型》中,信息系统安全保障模型包含保障要素、生命周期和安全特征三个方面。保障要素是实施安全保障的基础；生命周期涵盖了信息系统从规划、设计、实施、运行到废弃的整个过程；安全特征则描述了信息系统应具备的安全属性。","imageNames":[]},{"id":"wx2026-02-040","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"40","domain":"信息安全技术","stem":"某银行有5台交换机连接了大量交易机构的网络（如图所示）。在基于以太网的通信中,计算机A需要与计算机B通信,A必须先广播“ARP请求信息”。获取计算机B的物理地址,每到月底时用户发现该银行网络服务速度极其缓慢,银行经调查后发现为了当其中一台交换机收到ARP请求后,会转发给接收端口以外的其他所有端口,ARP请求会被发到网络中的所有客户上,为降低网络的带宽消耗,将广播流限制在固定区域内,可以采用的技术是","options":["VLAN划分","动态分配地址","为路由交换设备修改默认令","设立入侵防御系统"],"correctIndex":0,"explanation":"公开题库未附解析。","imageNames":["wx2026-02-02.png"]},{"id":"wx2026-02-041","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"41","domain":"信息安全工程","stem":"Gary McGraw博士及其合作者提出软件安全应由三根支柱来支撑,这三个支柱是()。","options":["源代码审核、风险分析和渗透测试","应用风险管理、软件安全接触点和安全知识","威胁建模、渗透测试和软件安全接触点","威胁建模、源代码审核和模糊测试"],"correctIndex":1,"explanation":"Gary McGraw博士及其合作者提出软件安全应由三根支柱来支撑,这三个支柱是应用风险管理、软件安全接触点和安全知识。A选项中源代码审核、风险分析和渗透测试是软件安全测试和评估的常见方法；C选项中威胁建模、渗透测试是软件安全的部分技术和方法,软件安全接触点是重要支柱之一；D选项中威胁建模、源代码审核和模糊测试也是软件安全的相关技术和方法。","imageNames":[]},{"id":"wx2026-02-042","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"42","domain":"信息安全技术","stem":"小赵是某大学计算机科学与技术专业的毕业生,在前往一家大型企业应聘时,面试经理要求他给出该企业信息系统访问控制模型的设计思路。如果想要为一个存在大量用户的信息系统实现自主访问控制功能,在以下选项中,从时间和资源消耗的角度,下列选项中他应该采取的最合适的模型或方法是()","options":["访问控制列表(ACL)","能力表(CL)","BLP 模型","Biba 模型"],"correctIndex":0,"explanation":"A选项:访问控制列表(ACL)是一种常用的自主访问控制方法,它通过在客体上附加一个主体明细表来表示访问控制矩阵,对于存在大量用户的信息系统,从时间和资源消耗的角度,ACL是一种比较合适的模型,该选项正确。 B选项:能力表(CL)是给主体赋予访问客体的能力,在大量用户的情况下,管理和维护能力表会比较复杂,时间和资源消耗较大,该选项错误。 C选项:BLP模型是一种强制访问控制模型,主要用于军事等对安全要求较高的领域,其实现和管理较为复杂,不适合大量用户的自主访问控制场景,该选项错误。 D选项:Biba模型也是一种强制访问控制模型,主要用于保证数据的完整性,同样不适合大量用户的自主访问控制场景,该选项错误。","imageNames":[]},{"id":"wx2026-02-043","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"43","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型(SSE-CMM),错误的理解是:","options":["SSE-CMM要求实施组织与其他组织相互作用,如开发方、产品供应商、集成商和咨询服务商等","SSE-CMM可以使安全工程成为一个确定的、成熟的和可度量的科目","基于SSE-CMM的工程是独立工程,与软件工程、硬件工程、通信工程等分别规划实施","SSE-CMM覆盖整个组织的活动,包括管理、组织和工程活动等,而不仅仅是系统安全的工程活动"],"correctIndex":2,"explanation":"C选项:基于SSE - CMM的工程不是独立工程,它与软件工程、硬件工程、通信工程等相互关联,需要在整个系统工程的背景下进行规划和实施。","imageNames":[]},{"id":"wx2026-02-044","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"44","domain":"信息安全法规标准","stem":"有关危害国家秘密安全的行为的法律责任,正确的是:","options":["严重违反保密规定行为只要发生,无论产生泄密实际后果,都要依法追究责任","非法获取国家秘密,不会构成刑事犯罪,不需承担刑事责任","过失泄露国家秘密,不会构成刑事犯罪,不需承担刑事责任","承担了刑事责任,无需再承担行政责任和／或其他处分"],"correctIndex":0,"explanation":"A选项:严重违反保密规定行为只要发生,无论是否产生泄密实际后果,都要依法追究责任,这体现了对国家秘密安全的严格保护,该说法正确。 选项B:非法获取国家秘密,情节严重的会构成刑事犯罪,需承担刑事责任,该说法错误。 选项C:过失泄露国家秘密,情节严重的也会构成刑事犯罪,需承担刑事责任,该说法错误。 选项D:承担了刑事责任后,还可能需要根据具体情况承担行政责任和／或其他处分,该说法错误。","imageNames":[]},{"id":"wx2026-02-045","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"45","domain":"信息安全管理","stem":"应急响应是信息安全事件管理的重要内容。基于应急响应工作的特点和事件的不规则性,事先创定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生成是在混乱状态中迅速恢复控制,将损失和负面影响降到最低。应急响应方法和过程并不是唯一的。一种被广为接受的应急响应方法是将应急响应管理过程分为6个阶段,为准备→检测→遏制→根除→恢复→跟踪总结。请问下列说法有关于信息安全应急响应管理过程错误的是( ):","options":["确定重要资产和风险,实施针对风险的防护措施是信息安全应急响应规划过程中最关键的步骤","在检测阶段,首先要进行监测、报告及信息收集","遏制措施可能会因为事件的类别和级别不同而完全不同。常见的遏制措施有完全关闭所有系统、拔掉网线等","应按照应急响应计划中事先制定的业务恢复优先顺序和恢复步骤,顺次恢复相关的系统"],"correctIndex":2,"explanation":"遏制措施需根据事件类型和级别动态调整,但“完全关闭所有系统”或“拔掉网线”属于极端手段,可能影响业务连续性。正确的遏制措施应平衡安全与业务需求（如隔离受感染设备、限制访问权限）。 “完全关闭所有系统”过于绝对,未考虑最小化影响原则。","imageNames":[]},{"id":"wx2026-02-046","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"46","domain":"信息安全工程","stem":"信息系统安全保障评估概念和关系如图所示,信息系统安全保障评估,就是在信息系统所处运行环境中对信息系统安全保障的具体工作和活动进行客观的评估,通过信息系统安全保障评估所搜集的（）,向信息系统的所有相关方提供信息系统的（）能够实现其安全保障策略,能够将其所面临的风险降低到其可接受的程度的主观信心,信息系统安全保障评估的评估对象是（）,信息系统不仅包含仅讨论术的信息技术系统,还包括同信息系统所处的运行环境相关的人和管理等领域,信息系统安全保障是一个动态持续的过程,涉及信息系统整个（）,因此信息系统安全保障的评估也应该提供一种（）的信心。","options":["安全保障工作；客观证据；信息系统；生命周期；动态持续","客观证据; 安全保障工作; 信息系统；生命周期；动态持续","客观证据；安全保障工作；生命周期；信息系统；动态持续","客观证据:安全保障工作:动态持续:信息系统:生命周期"],"correctIndex":1,"explanation":"信息系统安全保障评估通过搜集的客观证据,向信息系统的所有相关方提供信息系统的安全保障工作能够实现其安全保障策略,能够将其所面临的风险降低到其可接受的程度的主观信心,评估对象是信息系统,涉及信息系统整个生命周期,评估应该提供一种动态持续的信心。所以选B。","imageNames":["wx2026-02-03.png"]},{"id":"wx2026-02-047","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"47","domain":"信息安全法规标准","stem":"根据相关标准,信息安全风险管理可分为背景建立、风险评估、风险处理、批准监督、监控审查和沟通咨询等阶段。按照该框架,文档《风险分析报告》应属于哪个阶段的输出成果()","options":["风险评估","风险处理","批准监督","监控审查"],"correctIndex":0,"explanation":"《风险分析报告》是在风险评估阶段对信息系统的资产、威胁、脆弱性等进行评估和分析后形成的文档,用于确定信息系统面临的风险状况,属于风险评估阶段的输出成果。风险处理阶段是根据风险评估的结果采取相应的风险处理措施；批准监督阶段是对风险处理措施的批准和监督；监控审查阶段是对风险处理效果的监控和审查。所以选A。","imageNames":[]},{"id":"wx2026-02-048","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"48","domain":"信息安全技术","stem":"软件存在漏洞和缺陷是不可避免的,实践中常用软件缺陷密度（Defects/KLOC）来衡量软件的安全性,假设某个软件共有29.6万行源代码,总共被检测出145个缺陷,则可以计算出其软件缺陷密度值是（）","options":["０.０００４９","０.０４９","０.４９","４９"],"correctIndex":2,"explanation":"软件缺陷密度的计算公式为:软件缺陷密度 = 缺陷数/千行代码数（KLOC）。已知软件共有29.6万行源代码,即296KLOC,总共被检测出145个缺陷,则软件缺陷密度值=145 / 296 ≈ 0.49（Defects/KLOC）。所以选C。","imageNames":[]},{"id":"wx2026-02-049","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"49","domain":"信息安全法规标准","stem":"我国标准《信息安全风险管理指南》（GB/Z24364）给出了信息安全风险管理的内容和过程,可以用下图来表示。图中空白处应该填写（）","options":["风险计算","风险评价","风险预测","风险处理"],"correctIndex":3,"explanation":"我国标准《信息安全风险管理指南》（GB/Z 24364）给出“信息安全风险管理包括背景建立、风险评估、风险处理、批准监督、监控审查和沟通咨询6个方面的内容。背景建立、风险评估、风险处理和批准监督是信息安全风险管理的4个基本步骤,监控审查和沟通咨询则贯穿于这4个步骤中”。","imageNames":["wx2026-02-04.png"]},{"id":"wx2026-02-050","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"50","domain":"信息安全技术","stem":"自主访问控制模型（DAC）的访问控制关系可以用访问控制表（ACL）来表示,该ACL利用在客体上附加一个主体明细表的方法来表示访问控制矩阵,通常使用由客体指向的链表来存储相关数据。下面选项中说法正确的是（）。","options":["ACL在增加客体时,增加相关的访问控制权限较为简单","ACL对于统计某个主体能访问哪些客体比较方便","ACL在删除用户时,去除该用户所有的访问权限比较方便","ACL是Bell-LaPadula模型的一种具体实现"],"correctIndex":0,"explanation":"A选项:ACL在增加客体时,只需在客体的访问控制列表中增加相关主体的访问控制权限,操作较为简单,该说法正确。 B选项:ACL对于统计某个客体能被哪些主体访问比较方便,而不是统计某个主体能访问哪些客体,该说法错误。 C选项:ACL在删除用户时,需要遍历所有客体的访问控制列表,去除该用户所有的访问权限,操作比较繁琐,该说法错误。 D选项:ACL是一种自主访问控制模型,Bell-LaPadula模型是一种强制访问控制模型,二者不同,该说法错误。","imageNames":[]},{"id":"wx2026-02-051","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"51","domain":"信息安全技术","stem":"以下关于Web传输协议、服务端和客户端软件的安全问题说法不正确的是()","options":["HTTP协议主要存在明文传输数据、弱验证和缺乏状态跟踪等方面的安全问题","HTTP协议缺乏有效的安全机制,易导致拒绝服务、电子欺骗、嗅探等攻击","Cookie是为了辨别用户身份,进行会话跟踪而存储在用户本地终端上的数据,用户可以随意查看存储在Cookie中的数据,但其中的内容不能被修改","针对HTTP协议存在的安全问题,使用HTTPS 具有较高的安全性,可以通过证书来验证服务器的身份,并为浏览器和服务器之间的通信加密"],"correctIndex":2,"explanation":"Cookie是为了辨别用户身份,进行会话跟踪而存储在用户本地终端上的数据,用户不仅可以随意查看存储在Cookie中的数据,其中的内容也可以被修改。","imageNames":[]},{"id":"wx2026-02-052","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"52","domain":"信息安全管理","stem":"不同的信息安全风险评估方法可能得到不同的风险评估结果,所以组织机构应当根据各自的实际情况,选择适当的风险评估方法。下面的描述中,错误的是()","options":["定量风险分析试图从财务数字上对安全风险进行评估,得出可以量化的风险分析结果,以度量风险的可能性和损失量","定量风险分析相比定性风险分析能得到准确的数值,所以在实际工作中应使用定量风险分析,而不应选择定性风险分析","定性风险分析过程中,往往需要凭借分析者的经验直接进行,所以分析结果和风险评估团队的素质、经验和知识技能密切相关","定性风险分析更具主观性,而定量风险分析更具客观性"],"correctIndex":1,"explanation":"选项B:定量风险分析和定性风险分析各有优缺点,在实际工作中应根据具体情况选择合适的方法,有时还需要将两者结合使用,而不是只使用定量风险分析。","imageNames":[]},{"id":"wx2026-02-053","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"53","domain":"信息安全管理","stem":"应急响应是信息安全事件管理的重要内容之一。关于应急响应工作,下面描述错误的是()","options":["信息安全应急响应,通常是指一个组织为了应对各种安全意外事件的发生所采取的防范措施,既包括预防性措施,也包括事件发生后的应对措施","应急响应工作有其鲜明的特点:具有高技术复杂性与专业性、强突发性、对知识经验的高依赖性,以及需要广泛的协调与合作","应急响应是组织在处置应对突发/重大信息安全事件时的工作,其主要包括两部分工作:安全事件发生时正确指挥、事件发生后全面总结","应急响应工作的起源和相关机构的成立和1988年11月发生的莫里斯蠕虫病毒事件有关,基于该事件,人们更加重视安全事件的应急处置和整体协调的重要性"],"correctIndex":2,"explanation":"选项C:应急响应是组织在处置应对突发/重大信息安全事件时的工作,其主要包括事件发生前的预防和准备、事件发生时的正确指挥和处置、事件发生后的全面总结和改进等工作,而不只是正确指挥和全面总结,该说法错误。","imageNames":[]},{"id":"wx2026-02-054","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"54","domain":"信息安全管理","stem":"随着信息安全涉及的范围越来越广,各个组织对信息安全管理的需求越来越迫切,越来越多的组织开始尝试使用参考IS0 27001介绍的ISMS 来实施信息安全管理体系,提高组织的信息安全管理能力。关于ISMS,下面描述错误的是()。","options":["在组织中,应由信息技术责任部门(如信息中心)制定并颁布信息安全方针,为组织的ISMS建设指明方向并提供总体纲领,明确总体要求","组织的管理层应确保ISMS 目标和相应的计划得以制定,信息安全管理目标应明确、可度量,风险管理计划应具体,具备可行性","组织的信息安全目标、信息安全方针和要求应传达到全组织范围内,应包括全体员工,同时,也应传达到客户、合作伙伴和供应商等外部各方","组织的管理层应全面了解组织所面临的信息安全风险,决定风险可接受级别和风险可接受准则,并确认接受相关残余风险"],"correctIndex":0,"explanation":"A选项:在组织中,应由管理层制定并颁布信息安全方针,为组织的ISMS建设指明方向并提供总体纲领,明确总体要求,而不是由信息技术责任部门制定。","imageNames":[]},{"id":"wx2026-02-055","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"55","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS 符合ISO/IEC 27001或GB/T 22080标准要求,其信息安全控制措施通常需要在资产管理方面实施常规控制,资产管理包含对资产负责和信息分类两个控制目标。信息分类控制的目标是为了确保信息受到适当级别的保护,通常采取以下哪项控制措施()","options":["资产清单","资产责任人","资产的可接受使用","分类指南、信息的标记和处理"],"correctIndex":3,"explanation":"信息分类控制的目标是为了确保信息受到适当级别的保护,通常采取分类指南、信息的标记和处理等控制措施。资产清单是对资产进行登记和管理的文档；资产责任人主要是明确资产的负责人；资产的可接受使用是对资产使用方式的规范,所以选D。","imageNames":[]},{"id":"wx2026-02-056","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"56","domain":"信息安全管理","stem":"在某次信息安全应急响应过程中,小王正在实施如下措施:消除或阻断攻击源、找到并消除系统的脆弱性/漏洞、修改安全策略、加强防范措施、格式化被感染恶意程序的介质等。请问,按照 PDCERF 应急响应方法,这些工作应处于以下哪个阶段()","options":["准备阶段","检测阶段","遏制阶段","根除阶段"],"correctIndex":3,"explanation":"按照PDCERF应急响应方法,消除或阻断攻击源、找到并消除系统的脆弱性/漏洞、修改安全策略、加强防范措施、格式化被感染恶意程序的介质等工作处于根除阶段,目的是彻底消除安全事件的影响和根源。准备阶段主要是进行应急响应的准备工作；检测阶段是发现安全事件的发生；遏制阶段是采取措施防止事件的进一步扩大。所以选D。","imageNames":[]},{"id":"wx2026-02-057","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"57","domain":"信息安全法规标准","stem":"关于《网络安全法》域外适用效力的理解,以下哪项是错误的()","options":["当前对于境外的网络攻击,我国只能通过向来源国采取抗议","对于来自境外的网络安全威胁我国可以组织技术力量进行监测、防御和处置","对于来自境外的违法信息我国可以加以阻断传播","对于来自境外的网络攻击我国可以追究其法律责任"],"correctIndex":0,"explanation":"选项A:当前对于境外的网络攻击,我国不仅可以通过向来源国采取抗议,还可以采取多种措施,如组织技术力量进行监测、防御和处置,阻断违法信息传播,追究法律责任等,该说法错误。","imageNames":[]},{"id":"wx2026-02-058","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"58","domain":"信息安全法规标准","stem":"关于信息安全管理体系(Information Security Management Systems, ISMS)下面描述错误的是( ).","options":["信息安全管理体系是组织在整体或特定范围内建立信息安全方针和目标,以及完成这些目标所用方法的体系,包括组织架构、方针、活动、职责及相关实践要素","管理体系（Management Systems）是为达到组织目标的策略、程序、指南和相关资源的框架,信息安全管理体系是管理体系思想和方法在信息安全领域的应用","概念上,信息安全管理体系有广义和狭义之分,狭义的信息安全管理体系是指按照ISO27001标准定义的管理体系,它是一个组织整体管理体系的组成部分","同其他管理体系一样,信息安全管理体系也要建立信息安全管理组织机构,健全信息安全管理制度、构建信息安全技术防护体系和加强人员的安全意识等内容"],"correctIndex":3,"explanation":"选项D:信息安全管理体系同其他管理体系不一样。","imageNames":[]},{"id":"wx2026-02-059","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"59","domain":"信息安全保障","stem":"公钥基础设施（Public Key Infrastructure,PKI）引入数字证书的概念,用来表示用户的身份。下图简要地描述了终端实体（用户）从认证权威机构CA申请、撤销和更新数字证书的流程。请为中间框空白处选择合适的选项（）。","options":["证书库","RA","OCSP","CRL库"],"correctIndex":1,"explanation":"终端实体（用户）从认证权威机构CA申请、撤销和更新数字证书的流程中,中间框空白处应为RA（注册机构）,RA负责接收用户的证书申请、审核用户身份等信息,并将申请转发给CA。证书库是存储证书和CRL（证书撤销列表）的地方；OCSP（在线证书状态协议）用于实时查询证书的状态；CRL库是存储证书撤销列表的数据库。所以选B。","imageNames":["wx2026-02-05.png"]},{"id":"wx2026-02-060","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"60","domain":"信息安全技术","stem":"数据在进行传输前,需要由协议栈自上而下对数据进行封装。TCP/IP 协议中,数据封装的顺序是()。","options":["传输层、网络接口层、互联网络层","传输层、互联网络层、网络接口层","互联网络层、传输层、网络接口层","互联网络层、网络接口层、传输层"],"correctIndex":1,"explanation":"在TCP/IP协议中,数据封装的顺序是传输层、互联网络层、网络接口层。传输层将数据封装成段（Segment）,添加传输层头部；互联网络层将段封装成包（Packet）,添加IP头部；网络接口层将包封装成帧（Frame）,添加帧头部和帧尾部。所以选B。","imageNames":[]},{"id":"wx2026-02-061","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"61","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型（SSE-CMM）中的通用实施（Generic Practices,GP）错误理解是().","options":["GP 是涉及过程的管理、测量和制度化方面的活动","GP 适用于域维中部分过程区域(Process Areas,PA)的活动而非所有 PA 的活动","在工程实施时,GP 应该作为基本实施(Base Practices,BP)的一部分加以执行","在评估时,GP 用于判定工程组织执行某个PA 的能力"],"correctIndex":1,"explanation":"选项B:GP适用于域维中所有过程区域(PA)的活动,而不仅仅是部分PA的活动,该说法错误。","imageNames":[]},{"id":"wx2026-02-062","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"62","domain":"信息安全法规标准","stem":"在信息安全风险管理过程中,背景建立是实施工作的第一步。下面哪项理解是错误的()。","options":["背景建立的依据是国家、地区或行业的相关政策、法律、法规和标准,以及机构的使命、信息系统的业务目标和特性","背景建立阶段应识别需要保护的资产、面临的威胁以及存在的脆弱性,并分别赋值,同时确认已有的安全措施,形成需要保护的资产清单","背景建立阶段应调查信息系统的业务目标.业务特性.管理特性和技术特性,形成信息系统的描述报告","背景建立阶段应分析信息系统的体系结构和关键要素,分析信息系统的安全环境和要求,形成信息系统的安全要求报告"],"correctIndex":1,"explanation":"选项B:识别需要保护的资产、面临的威胁以及存在的脆弱性,并分别赋值,同时确认已有的安全措施,形成需要保护的资产清单是风险评估阶段的工作,而不是背景建立阶段的工作。","imageNames":[]},{"id":"wx2026-02-063","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"63","domain":"信息安全法规标准","stem":"王先生是某政府信息中心主任。以下哪项项目是符合《保守国家秘密法》要求的()","options":["王先生安排下属小李将损害的涉密计算机的某国外品牌硬盘送到该品牌中国区维修中心修理","王先生要求下属小张把中心所有计算机贴上密级标志","王先生每天晚上 12 点将涉密计算机连接上互联网更新杀毒软件病毒库","王先生提出对加密机和红黑电源插座应该与涉密信息系统同步投入使用"],"correctIndex":3,"explanation":"选项A:将损害的涉密计算机的国外品牌硬盘送到该品牌中国区维修中心修理,可能会导致涉密信息泄露,不符合《保守国家秘密法》要求。 选项B:把中心所有计算机贴上密级标志,应根据计算机存储和处理信息的密级进行准确标识,而不是所有计算机都贴同样的密级标志。 选项C:每天晚上12点将涉密计算机连接上互联网更新杀毒软件病毒库,会使涉密计算机暴露在互联网环境中,增加泄密风险,不符合要求。 选项D:对加密机和红黑电源插座应该与涉密信息系统同步投入使用,符合涉密信息系统的安全保密要求,该选项正确。","imageNames":[]},{"id":"wx2026-02-064","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"64","domain":"信息安全技术","stem":"以下关于网络安全设备说法正确的是() .","options":["防火墙既能实现内外网物理隔离,又能实现内外网逻辑隔离","安全隔离与信息交换系统也称为网闸,需要信息交换时,同一时间可以和两个不同安全级别的网络连接","入侵检测系统的主要作用是发现并报告系统中未授权或违反安全策略的行为","虚拟专用网是在公共网络中,利用隧道技术,建立一个永久.安全的通信网络"],"correctIndex":2,"explanation":"选项 A:防火墙实现 “逻辑隔离”（通过规则控制访问）,无法实现 “物理隔离”（物理上断开连接）,表述错误。 选项 B:网闸（安全隔离与信息交换系统）的核心是 “物理隔离 + 数据摆渡”,同一时间不能同时连接两个不同安全级别的网络（需通过摆渡机制单向传输数据）,表述错误。 选项 C:入侵检测系统（IDS）通过监测网络 / 系统行为,发现并报告未授权或违反安全策略的行为（如异常访问、攻击尝试）,表述正确。 选项 D:VPN（虚拟专用网）是在公共网络中建立 “临时、安全” 的通信隧道,而非 “永久” 连接,表述错误。","imageNames":[]},{"id":"wx2026-02-065","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"65","domain":"信息安全管理","stem":"Linux系统的安全设置主要从磁盘分区、账户安全设置、禁用危险服务、远程登录安全、用户鉴别安全、审计策略、保护root账户、使用网络防火墙和文件权限操作共10个方面来完成。小张在学习了Linux系统安全的相关知识后,尝试为自己计算机上的Linux系统进行安全配置。下列选项是他的部分操作,其中不合理的是（）。","options":["编辑文件/etc/ssh/sshd_config,将PermitRootLogin设置为no","编辑文件/etc/profile,设置TMOUT=600","编辑文件/etc/pam.d/system-auth,设置auth required pam_tally.so onerr=fail deny=6 unlock_time=300","编辑文件/etc/passwd,检查文件中用户ID,禁用所有用户ID=0的用户"],"correctIndex":3,"explanation":"选项 D不合理:/etc/passwd 中用户 ID（UID）=0 的账户是 root 账户（系统超级管理员）,禁用所有 UID=0 的用户会导致系统失去超级管理员,无法进行核心配置、维护操作,破坏系统正常运行。正确做法是加强 root 账户保护（如禁止远程登录）,而非禁用。","imageNames":[]},{"id":"wx2026-02-066","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"66","domain":"信息安全保障","stem":"《国家信息化领导小组关于加强信息安全保障工作的意见》中办发[2003]27号明确了我国信息安全保障工作的（）、加强信息安全保障工作的（）、需要重点加强的信息安全保障工作。27号文的重大意义是,它标志着我国信息安全保障工作有了（）、我国最近十余年的信息安全保障工作都是围绕此政策性文件来（）的、促进了我国（）的各项工作。","options":["方针；主要原则；总体纲领；展开和推进；信息安全保障建设","总体要求；总体纲领:主要原则；展开；信息安全保障建设","总体要求；主要原则；总体纲领；展开；信息安全保障建设","方针和总体要求；主要原则；总体纲领；展开和推进；信息安全保障建设"],"correctIndex":3,"explanation":"《国家信息化领导小组关于加强信息安全保障工作的意见》中办发[2003]27号明确了我国信息安全保障工作的方针和总体要求、加强信息安全保障工作的主要原则、需要重点加强的信息安全保障工作。27号文的重大意义是,它标志着我国信息安全保障工作有了总体纲领、我国最近十余年的信息安全保障工作都是围绕此政策性文件来展开和推进的、促进了我国信息安全保障建设的各项工作。所以选D。","imageNames":[]},{"id":"wx2026-02-067","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"67","domain":"信息安全管理","stem":"恢复时间目标（Recovery Time Objective ,RTO）和恢复点目标（Recovery Point Objective,RPO）是业务连续性和灾难恢复工作中的两个重要指标,随着信息系统越来越重要和信息技术越来越先进,这两个指标的数值越来越小。小华准备为其工作的信息系统拟定RTO和RPO指标,则以下描述中,正确的是（ ）。","options":["RTO可以为0,RPO也可以为0","RTO可以为0,RPO不可以为0","RTO不可以为0,RPO也不可以为0","RTO不可以为0,RPO可以为0"],"correctIndex":0,"explanation":"RTO（恢复时间目标）是指灾难发生后,信息系统从停机到恢复正常服务所需的最短时间,理论上可以为0,即立即恢复。 RPO（恢复点目标）是指灾难发生后,系统和数据能够恢复到的时间点,理论上也可以为0,即实时备份,不丢失任何数据。所以选A。","imageNames":[]},{"id":"wx2026-02-068","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"68","domain":"信息安全技术","stem":"2016年10月21日,美国东部地区发生大规模断网事件,此次事件是由于美国主要DNS服务商Dyn遭遇大规模攻击所致,影响规模惊人,对人们生产生活造成严重影响。DDoS攻击的主要目的是破坏系统的()。","options":["保密性","可用性","不可否认性","抗抵赖性"],"correctIndex":1,"explanation":"DDoS攻击是通过大量合法的请求占用大量系统资源,从而使合法用户无法得到服务响应,破坏了系统的可用性。保密性是指信息不被泄露给非授权用户；不可否认性和抗抵赖性类似,是指防止发送方或接收方否认自己发送或接收过信息。所以选B。","imageNames":[]},{"id":"wx2026-02-069","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"69","domain":"信息安全管理","stem":"随机进程名称是恶意代码迷惑管理员和系统安全检查人员的技术手段之一以下对于随机进程名技术,描述正确的是()。","options":["随机进程名技术虽然每次进程名都是随机的,但是只要找到了进程名称,就找到了恶意代码程序本身","恶意代码生成随机进程名称的目的是使进程名称不固定,因为杀毒软件是按照进程名称进行病毒进程查杀","恶意代码使用随机进程名是通过生成特定格式的进程名称,使进程管理器中看不到恶意代码的进程","随机进程名技术每次启动时随机生成恶意代码进程名称,通过不固定的进程名称使自己不容易被发现真实的恶意"],"correctIndex":3,"explanation":"选项A:随机进程名技术每次进程名随机,找到进程名也不一定能找到恶意代码程序本身,因为恶意代码可能隐藏或伪装,A错误。 选项B:杀毒软件不只是按照进程名称查杀病毒,还会根据行为、特征码等多种方式,B错误。 选项C:恶意代码使用随机进程名不是使进程管理器中看不到进程,而是让进程名不固定难以被发现,C错误。 选项D:随机进程名技术每次启动随机生成进程名称,通过不固定的进程名称使自己不容易被发现真实的恶意,D正确。","imageNames":[]},{"id":"wx2026-02-070","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"70","domain":"信息安全管理","stem":"从Linux内核2.1版开始,实现了基于权能的特权管理机制,实现了对超级用户的特权分割,打破了UNIX/LINUX操作系统中超级用户/普通用户的概念,提高了操作系统的安全性。下列选项中,对特权管理机制的理解错误的是（）。","options":["普通用户及其shell没有任何权能,而超级用户及其shell在系统启动之初拥有全部权能","当普通用户的某些操作设计特权操作时,仍然通过setuid实现","系统管理员可以剥夺和恢复超级用户的某些权能","进程可以放弃自己的某些权能"],"correctIndex":2,"explanation":"选项A:普通用户及其shell没有任何权能,超级用户及其shell在系统启动之初拥有全部权能,这是基于权能的特权管理机制的特点,A正确。 选项B:当普通用户涉及特权操作时,通过setuid实现,即临时获得特权,B正确。 选项C:传统UNIX/Linux中,root权限是固有的,无法通过用户层工具直接剥夺或恢复其核心权能（如CAP_SYS_ADMIN）。权能机制允许进程主动放弃权能（如通过capset系统调用）,但系统管理员无法强制剥夺root的某些权能,除非修改内核参数或使用安全模块（如SELinux）限制其行为。C错误。 选项D:进程可以放弃自己的某些权能,以提高安全性,D正确。","imageNames":[]},{"id":"wx2026-02-071","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"71","domain":"信息安全工程","stem":"由于密码技术都依赖于密钥,因此密钥的安全管理是密码技术应用中非常重要的环节,下列关于密钥管理说法错误的是()。","options":["科克霍夫在《军事密码学》中指出系统的保密性不依赖于对加密体制或算法的保密,而依赖于密钥","在保密通信过程中,通信双方可以一直使用之前用过的会话密钥,不影响安全性","密钥管理需要在安全策略的指导下处理密钥生命周期的整个过程,包括产生、存储、备份、分配、更新、撤销等","在保密通信过程中,通信双方也可利用Diffie-Hellman协议协商出会话密钥进行保密通信"],"correctIndex":1,"explanation":"在保密通信过程中,会话密钥不能一直使用。如果长期使用同一个会话密钥,一旦该密钥被破解,之前的所有通信内容都将面临泄露风险,所以需要定期更换会话密钥。","imageNames":[]},{"id":"wx2026-02-072","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"72","domain":"信息安全管理","stem":"一个信息管理系统通常会对用户进行分组并实施访问控制。例如,在一个学校的教务系统中,教师能够录入学生的考试成绩,学生只能查看自己的分数,而学校教务部门的管理人员能够对课程信息、学生的选课信息等内容进行修改。下列选项中,对访问控制的作用的理解错误的是()。","options":["对经过身份鉴别后的合法用户提供所有服务","拒绝非法用户的非授权访问请求","在用户对系统资源提供最大限度共享的基础上,对用户的访问权进行管理","防止对信息的非授权篡改和滥用"],"correctIndex":0,"explanation":"访问控制的作用是对经过身份鉴别后的合法用户根据其权限提供相应的服务,而不是提供所有服务,A错误。","imageNames":[]},{"id":"wx2026-02-073","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"73","domain":"信息安全技术","stem":"在某信息系统的设计中,用户登录过程是这样的:(1)用户通过HTTP 协议访问信息系统:(2)用户在登录页面输入用户名和口令;(3)信息系统在服务器端检查用户名和密码的正确性,如果正确,则鉴别完成。可以看。出,这个鉴别过程属于()。","options":["单向鉴别","双向鉴别","三向鉴别","第三方鉴别"],"correctIndex":0,"explanation":"用户通过HTTP协议访问信息系统,在服务器端检查用户名和密码正确性完成鉴别,这是单向鉴别,即一方对另一方的身份进行验证。双向鉴别是双方互相验证身份；三向鉴别和第三方鉴别题干未体现,所以选A。","imageNames":[]},{"id":"wx2026-02-074","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"74","domain":"信息安全管理","stem":"以下哪种风险被认为是合理的风险()。","options":["最小的风险","残余风险","未识别的风险","可接受的风险"],"correctIndex":3,"explanation":"可接受的风险是指在综合考虑了风险的成本、收益等因素后,组织愿意承担的风险。最小的风险表述不准确；残余风险是在采取了风险处理措施后仍然存在的风险；未识别的风险是尚未被发现的风险。所以选D。","imageNames":[]},{"id":"wx2026-02-075","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"75","domain":"信息安全保障","stem":"对信息安全事件的分级参考下列三个要素:信息系统的重要程度、系统损失和社会影响,依据信息系统的重要程度对信息进行划分,不属于正确划分级别的是()。","options":["特别重要信息系统","重要信息系统","一般信息系统","关键信息系统"],"correctIndex":3,"explanation":"《信息安全技术 信息安全事件分类分级指南》（GB/Z 20986-2007）“信息系统的重要程度主要考虑信息系统所承载的业务对国家安全、经济建设、社会生活的重要性以及业务对信息系统的依赖程度,划分为特别重要信息系统、重要信息系统和一般信息系统。”","imageNames":[]},{"id":"wx2026-02-076","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"76","domain":"信息安全法规标准","stem":"以下哪个说法最符合《网络安全法》中关于网络的定义()","options":["计算机局域网","包含服务器、交换机等设备的系统","涵盖处理各种信息的设备的网络空间","人与人交往联系的社会网络"],"correctIndex":2,"explanation":"《网络安全法》中网络的定义是指由计算机或者其他信息终端及相关设备组成的按照一定的规则和程序对信息进行收集、存储、传输、交换、处理的系统,涵盖处理各种信息的设备的网络空间。计算机局域网只是网络的一种形式；包含服务器、交换机等设备的系统表述不准确；人与人交往联系的社会网络不是《网络安全法》中网络的定义。所以选C。","imageNames":[]},{"id":"wx2026-02-077","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"77","domain":"信息安全法规标准","stem":"规范的实施流程和文档管理,是信息安全风险评估能否取得成果的重要基础。某单位在实施风险评估时,按照规范形成了若干文档,其中,下面()中的文档应属于风险评估中“风险要素识别”阶段输出的文档。","options":["《风险评估方案,主要包括本次风险评估的目的、范围、目标、评估步、经费预算和进度安排等内容","《风险评估方法和工具列表》主要包括拟用的风险评估方法和测试评估工具等内容","《风险评估准则要求》,主要包括现有风险评估参考标准、采用的风险分析方法、资产分类标准等内容","《已有安全措施列表》,主要包括经检查确认后的已有技术和管理各方面安全措施等内容"],"correctIndex":3,"explanation":"选项 A:《风险评估方案》（含目的、范围、进度等）是 “准备阶段” 的核心文档,用于明确评估计划,不属于识别阶段。选项 B:《风险评估方法和工具列表》是 “准备阶段” 确定的评估手段,用于规范评估过程,不属于识别阶段。选项 C:《风险评估准则要求》（含标准、分析方法、资产分类标准）是 “准备阶段” 制定的评估依据,用于统一评估口径,不属于识别阶段。选项D:《已有安全措施列表》记录经检查确认后的已有技术和管理各方面安全措施,是在风险要素识别阶段,对资产面临的风险进行识别时,需要考虑已有的安全措施情况,所以属于该阶段输出的文档。","imageNames":[]},{"id":"wx2026-02-078","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"78","domain":"信息安全管理","stem":"某集团公司根据业务需要,在各地分支机构部署前置机为了保证安全,集团总部要求前置机开放日志共享,由总部服务器采集进行集中分析,在运行过程中发现攻击者也可通过共享从前置机中提取日志,从而导致部分敏感信息泄露,根据降低攻击面的原则,应采取以下哪项处理措施()","options":["由于共享导致了安全问题,应直接关闭日志共享,禁止总部提取日志进行分析","为配合总部的安全策略,会带来一定的安全问题,但不影响系统使用,因此接受此风险","日志的存在就是安全风险,最好的办法就是取消日志,通过设置让前置机不记录日志","只允许特定的IP地址从前置机提取日志,对日志共享设置访问密码且限定访间的时间"],"correctIndex":3,"explanation":"选项A错误:直接关闭日志共享,禁止总部提取日志进行分析,会影响总部对安全事件的分析和处理,不是合理的措施。选项B错误:接受此风险会带来敏感信息泄露的安全问题,不是降低攻击面的做法。选项C错误:取消日志不利于对系统安全事件的监测和分析,不是合理的措施。选项D正确:只允许特定的IP地址从前置机提取日志,对日志共享设置访问密码且限定访问时间,可以降低攻击面,减少安全风险。","imageNames":[]},{"id":"wx2026-02-079","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"79","domain":"信息安全管理","stem":"为了能够合理、有序地处理安全事件,应事先制定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生或是在混乱状态中迅速恢复控制,将损失和负面影响降至最低。PDCERF方法论是一种防范使用的方法,其将应急响应分成六个阶段,如下图所示,请为图中括号空白处选择合适的内容（）","options":["培训阶段","文档阶段","报告阶段","检测阶段"],"correctIndex":3,"explanation":"PDCERF方法论将应急响应分成六个阶段:准备（Preparation）、检测（Detection）、遏制（Containment）、根除（Eradication）、恢复（Recovery）和跟踪总结（Follow - up）,所以括号空白处应为检测阶段,选D。","imageNames":["wx2026-02-06.png"]},{"id":"wx2026-02-080","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"80","domain":"信息安全技术","stem":"关于ARP欺骗原理和防范措施,下面理解错误的是()。","options":["ARP欺骗是指攻击者直接向受害者主机发送错误的ARP应答报文,使得受害者主机将错误的硬件地址映射关系存入到ARP缓存中,从而起到冒充主机的目的","单纯利用ARP欺骗攻击时,ARP 欺骗通常影响的是内部子网,不能跨越路由实施攻击","解决ARP欺骗的一个有效方法是采用“静态”的ARP缓存,如果发生硬件地址的更改,则需要人工更新缓存","彻底解决ARP欺骗的方法是避免使用ARP协议和ARP缓存,直接采用IP地址和其他主机进行连接"],"correctIndex":3,"explanation":"ARP协议是网络通信中用于解析IP地址和物理地址的重要协议,不能避免使用ARP协议和ARP缓存,否则网络将无法正常通信。","imageNames":[]},{"id":"wx2026-02-081","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"81","domain":"信息安全技术","stem":"某信息安全公司的团队对某款名为“红包快抢”的外挂进行分析,发现此外挂是一个典型的木马后门,使黑客能够获得受害者电脑的访问权。该后门程序为了达到长期驻留在受害者的计算机中,通过修改注册表启动项来达到后门程序随受害者计算机系统启动而启动。为防范此类木马后门的攻击,以下做法无用的是（）。","options":["不下载、不执行,不接收来历不明的软件或文件","修改用户名和口令","不随意打开来历不明的邮件,不浏览不健康不正规的网站","安装反病毒软件和防火墙,安装专门的木马防治软件"],"correctIndex":1,"explanation":"选项B:修改用户名和口令对于防范通过修改注册表启动项来达到长期驻留的木马后门攻击没有作用。此类木马后门主要关注的是系统的启动机制和注册表信息,与用户名和口令无关。","imageNames":[]},{"id":"wx2026-02-082","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"82","domain":"信息安全管理","stem":"风险在GB／T 22081 中定义为事态的概率及其结果的组合,风险的目标可能有很多不同的方面,如财务目标、健康和人身安全目标、信息安全目标和环境目标等；目标也可能有不同的级别,如战略目标、组织目标、项目目标、产品目标和过程目标等。ISO／IBC 13335-1 中揭示了风险各要素关系模型,如图所示,请结合此图,怎么才能降低风险对组织产生的影响？（）","options":["组织应该根据风险建立响应的保护要求,通过构架防护措施降低风险对组织产生的影响","加强防护措施,降低风险","减少威胁和脆弱点,降低风险","减少资产降低风险"],"correctIndex":0,"explanation":"根据ISO/IEC TR 13335 - 1揭示的风险各要素关系模型,降低风险对组织产生的影响,组织应根据风险建立响应的保护要求,通过构架防护措施来达成。B选项“加强防护措施,降低风险”表述过于笼统,没有明确建立保护要求与构架防护措施的逻辑；C选项减少威胁和脆弱点是降低风险的手段,但没有体现出基于风险建立保护要求并构架防护措施这一完整逻辑；D选项减少资产不是降低风险的合理常规方式,还可能影响组织正常运营。所以选A。","imageNames":["wx2026-02-07.png"]},{"id":"wx2026-02-083","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"83","domain":"信息安全技术","stem":"密码学是网络安全的基础,但网络安全不能单纯依靠安全的密码算法、密码协议也是网络安全的一个重要组成部分。下面描述中,错误的是（）","options":["在实际应用中,密码协议应按照灵活性好、可扩展性高的方式制定,不要限制和框住的执行步骤,有些复杂的步骤可以不明确处理方式。","密码协议定义了两方或多方之间为完成某项任务而指定的一系列步骤,协议中的每个参与方都必须了解协议,且按步骤执行。","根据密码协议应用目的的不同,参与该协议的双方可能是朋友和完全信息的人,也可能是敌人和互相完全不信任的人。","密码协议(Crypto graphic protocol) ,有时也称安全协议(security protocol), 是使用密码学完成某项特定的任务并满足安全需求的协议,其末的是提供安全服务"],"correctIndex":0,"explanation":"选项A:在实际应用中,密码协议应按照明确的步骤制定,不能过于灵活和模糊,否则会导致协议执行的不一致和安全问题。","imageNames":[]},{"id":"wx2026-02-084","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"84","domain":"信息安全保障","stem":"信息安全保障技术框架.（Information Assurance Technical Framework, IATF) ,目的是为保障政府和工业的()提供了()。信息安全保障技术框架的一个核心思想是()。深度防御战略的三个核心要素:()、技术和运行(亦称为操作)","options":["信息基础设施;技术指南;深度防御:人员","技术指南;信息基础设施;深度防御;人员","信息基础设施;深度防御:技术指南,人员","信息基础设施:技术指南;人员深度防御"],"correctIndex":0,"explanation":"信息安全保障技术框架（IATF）的目的是为保障政府和工业的信息基础设施提供了技术指南。其核心思想是深度防御。深度防御战略的三个核心要素是人员、技术和运行（亦称为操作）。所以选A。","imageNames":[]},{"id":"wx2026-02-085","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"85","domain":"信息安全技术","stem":"金女士经常通过计算机在互联网上购物,从安全角度看,下面哪项是不好的操作习惯()","options":["使用专用上网购物用计算机,安装好软件后不要对该计算机上的系统软件、应用软件进行升级","为计算机安装具有良好芦誉的安全防护软件,包括病毒查杀、 安全检查和安全加固方面的软件","在IE的配置中,设置只能下载和安装经过签名的、安全的ActiveX控件","在使用网络浏览器时,设置不在计算机中保留网络历史记录和表单数据"],"correctIndex":0,"explanation":"选项A:使用专用上网购物用计算机,但安装好软件后不进行系统软件、应用软件的升级是不好的操作习惯,因为软件升级可以修复安全漏洞,提高安全性。","imageNames":[]},{"id":"wx2026-02-086","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"86","domain":"信息安全法规标准","stem":"某贸易公司的OA系统由于存在系统漏洞,被攻击者传上了木马病毒并删除了系统中的数据,由于系统备份是每周六进行一次,事件发生时间为周三,因此导致该公司三个工作日的数据丢失并使得OA系统在随后两天内无法访问,影响到了与公司有业务往来部分公司业务。在事故处理报告中,根据GB/Z 20986-2007《信息安全事件分级分类指南》,该事件的准确分类和定级应该是（）","options":["有害程序事件 特别重大事件(I级)","信息破坏事件 重大事件(Ⅱ级)","有害程序事件 较大事件(II级)","信息破坏事件 一般事件(V级)"],"correctIndex":2,"explanation":"该事件是由于系统漏洞被攻击者上传木马病毒并删除数据,属于有害程序事件。事件导致三个工作日数据丢失且OA系统两天无法访问,影响部分公司业务,根据GB/Z 20986 - 2007《信息安全事件分级分类指南》,应定为较大事件（III级）。 选项A（有害程序事件I级）:影响程度不足以达到特别重大级别。 选项B（信息破坏事件II级）:事件分类不准确（应为有害程序事件）,且影响未达重大级别。 选项C（有害程序事件III级）:分类准确,定级影响程度未达到较大事件标准。但也可能因具体损失金额或业务影响程度不同而调整定级。 选项D（信息破坏事件一般事件IV级）:分类需修正为有害程序事件,但定级（IV级）符合实际影响。选项D的分类不够精准,因此优先选择C。","imageNames":[]},{"id":"wx2026-02-087","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"87","domain":"信息安全管理","stem":"某单位在一次信息安全风险管理活动中,风险评估报告提出服务器A的FIP 服务存在高风险漏洞。随后该单位在风险处理时选择了安装FIP 服务漏洞补丁程序并加固FTP服务安全措施,请问该措施属于哪种风险处理方式","options":["风险降低","风险规避","风险转移","风险接受"],"correctIndex":0,"explanation":"安装FTP服务漏洞补丁程序并加固FTP服务安全措施,降低了服务器A的FTP服务存在高风险漏洞带来的风险,属于风险降低的处理方式。风险规避是采取措施避免风险的发生；风险转移是将风险转移给其他方；风险接受是接受风险的存在。所以选A。","imageNames":[]},{"id":"wx2026-02-088","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"88","domain":"信息安全法规标准","stem":"（）第二十三条规定存储、处理国家秘密的计算机信息系统（以下简称涉密信息系统）按照（）实行分级保护。（）应当按照国家保密标准配备保密设施、设备。（）、设备应当与涉密信息系统同步规划、同步建设、同步运行。（三同步）涉密信息系统应当按照规定,经（）后,方可投入使用。","options":["《保密法》;涉密程度;涉密信息系统;保密设施;检查合格","《国家保密法》;涉密程度;涉密系统;保密设施;检查合格","《网络保密法》;涉密程度;涉密系统;保密设施;检查合格","《安全保密法》;涉密程度;涉密信息系统;保密设施;检查合格"],"correctIndex":0,"explanation":"《保密法》第二十三条规定存储、处理国家秘密的计算机信息系统（以下简称涉密信息系统）按照涉密程度实行分级保护。涉密信息系统应当按照国家保密标准配备保密设施、设备。保密设施、设备应当与涉密信息系统同步规划、同步建设、同步运行（三同步）。涉密信息系统应当按照规定,经检查合格后,方可投入使用。所以选A。","imageNames":[]},{"id":"wx2026-02-089","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"89","domain":"信息安全管理","stem":"关于信息安全应急响应管理过程描述不正确的是()。","options":["基于应急响应工作的特点和事件的不规则性,事先制定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生或是在混乱状态中迅速恢复控制,将损失和负面影响降至最低","应急响应方法和过程并不是唯一的","一种被广为接受的应急响应方法是将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪总结6个阶段","一种被广为接受的应急响应方法是将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪总结6个阶段,这6个阶段的响应方法一定能确保事件处理的成功"],"correctIndex":3,"explanation":"虽然将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪总结6个阶段是一种被广为接受的方法,但不能确保事件处理的成功,因为事件的不确定性和复杂性,所以D选项错误。","imageNames":[]},{"id":"wx2026-02-090","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"90","domain":"信息安全工程","stem":"以下有关系统工程说法错误的是()。","options":["系统工程不属于基本理论,也不属于技术基础,它研究的重点是方法论。","系统工程的目的是实现总体效果最优化,常即从复杂问题的总体入手,认为总体大于各部分之和,各部分虽然存在不足,但总体可以优化","系统工程只需使用定量分析的方法,通过建立实际对象的数学模型,应用合适的优化算法对模型求解,解决实际的问题","霍尔三维结构将系统工程整个活动过程分为前后紧密衔接的7个阶段和7个步骤"],"correctIndex":2,"explanation":"系统工程需要使用定量分析和定性分析相结合的方法,通过建立实际对象的数学模型,应用合适的优化算法对模型求解,同时结合定性分析来综合考虑各种因素,解决实际问题,而不是只需使用定量分析的方法。","imageNames":[]},{"id":"wx2026-02-091","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"91","domain":"信息安全法规标准","stem":"CC标准是目前系统安全认证方面最权威的标准,以下哪一项没有体现CC标准的先进性()","options":["结构的开放性,即功能和保证要求都可以在具体的“保护轮廓”和“安全目标”中进一步细化和扩展","表达方式的通用性,即给出通用的表达方式","独立性,它强调将安全的功能和保证分离","实用性,将CC的安全性要求具体应用到IT产品的开发、生产、测试和评估过程中"],"correctIndex":2,"explanation":"C选项:CC标准并没有强调将安全的功能和保证分离","imageNames":[]},{"id":"wx2026-02-092","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"92","domain":"信息安全管理","stem":"老王是一名企业信息化负责人,由于企业员工在浏览网页时总导致病毒感染系统,为了解决这一问题,老王要求信息安全员给出解决措施,信息安全员给出了四条措施建议,老王根据多年的信息安全管理经验,认为不太适合推广你认为是哪条措施()","options":["采购防病毒网关并部署在企业互联网出口中,实现对所有浏览网页进行检测,阻止网页中的病毒进入内网","采购并统一部署企业防病毒软件,信息化管理部门统一进行病毒库升级,确保每台计算机都具备有效的病毒检测和查杀能力","制定制度禁止使用微软的 IE 浏览器上网,统一要求使用Chrome 浏览器","组织对员工进行一次上网行为要全培训,提高企业员工在互联网浏览时的安全意识"],"correctIndex":2,"explanation":"选项C禁止使用微软的IE浏览器而统一要求使用Chrome浏览器,这种做法过于绝对。不同浏览器都有其特点和适用场景,而且不能从根本上解决病毒感染问题,因为其他浏览器也可能存在安全漏洞,不太适合推广。","imageNames":[]},{"id":"wx2026-02-093","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"93","domain":"信息安全技术","stem":"某社交网站的用户点击了该网站上的一个广告。该广告含有一个跨站脚本,会将他的浏览器定向到旅游网站,旅游网站则获得了他的社交网络信息。虽然该用户没有主动访问该旅游网站,但旅游网站已经截获了他的社交网络信息（还有他的好友们的信息）,于是犯罪分子便可以躲藏在社交网站的广告后面,截获用户的个人信息了。这种向Web页面插入恶意html代码的攻击方式称为（）","options":["分布式拒绝服务攻击","跨站脚本攻击","SQL 注入攻击","缓冲区溢出攻击"],"correctIndex":1,"explanation":"向Web页面插入恶意html代码的攻击方式称为跨站脚本攻击（XSS）。分布式拒绝服务攻击（DDoS）是通过大量合法的请求占用大量系统资源,使合法用户无法得到服务响应；SQL注入攻击是通过在应用程序中注入恶意的SQL代码,窃取或篡改数据库中的数据；缓冲区溢出攻击是通过向程序的缓冲区写入超过其容量的数据,导致程序崩溃或执行恶意代码。所以选B。","imageNames":[]},{"id":"wx2026-02-094","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"94","domain":"信息安全法规标准","stem":"以下哪项制度或标准被作为我国的一项基础制度加以推行,并且有一定强制性,其实施的主要目标是有效地提高我国信息和信息系统安全建设的整体水平,重点保障基础信息网络和重要信息系统的安全（）","options":["信息安全管理体系(ISMS)","信息安全等级保护","NIST SP800","ISO 270000 系列"],"correctIndex":1,"explanation":"信息安全等级保护是我国的一项基础制度,有一定强制性,主要目标是提高我国信息和信息系统安全建设的整体水平,重点保障基础信息网络和重要信息系统的安全。信息安全管理体系（ISMS）、NIST SP800、ISO 27000系列都不是我国特有的基础制度,答案选B。","imageNames":[]},{"id":"wx2026-02-095","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"95","domain":"信息安全管理","stem":"小华在某电子商务公司工作,某天他在查看信息系统设计文档时,发现其中标注该信息系统的RPO（恢复点目标）指标为3小时。请问这意味着（）","options":["该信息系统发生重大信息安全事件后,工作人员应在3小时内到位,完成问题定位和应急处理工作","该信息系统发生重大信息安全事件后,工作人员应在3小时内完成应急处理工作,并恢复对外运行","若该信息系统发生重大信息安全事件,工作人员在完成处置和灾难恢复工作后,系统至多能丢失3小时的业务数据","若该信息系统发生重大信息安全事件,工作人员在完成处置和灾难恢复工作后,系统运行3小时后能恢复全部数据"],"correctIndex":2,"explanation":"RPO（恢复点目标）是指在一个信息系统发生重大信息安全事件后,工作人员在完成处置和灾难恢复工作后,系统能容忍丢失的数据量所对应的时间点。该信息系统的RPO指标为3小时,意味着若该信息系统发生重大信息安全事件,工作人员在完成处置和灾难恢复工作后,系统至多能丢失3小时的业务数据。","imageNames":[]},{"id":"wx2026-02-096","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"96","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合IS0/IEC 27001或GB/T 22080 标准要求,其信息安全控制措施通常需要在人力资源安全方面实施常规控制,人力资源安全划分为3个控制阶段,不包括哪一项()","options":["任用之前","任用中","任用终止或变化","任用公示"],"correctIndex":3,"explanation":"人力资源安全划分为3个控制阶段,分别是任用之前、任用中、任用终止或变化。任用之前主要是对人员的背景调查、资质审查等；任用中包括对人员的安全意识培训、权限管理等；任用终止或变化时涉及权限回收、信息交接等。而任用公示不属于人力资源安全的控制阶段内容,所以答案选D。","imageNames":[]},{"id":"wx2026-02-097","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"97","domain":"信息安全管理","stem":"根据信息安全风险要素之间的关系,下图中空白处应该填写()","options":["资产","安全事件","脆弱性","安全措施"],"correctIndex":2,"explanation":"根据信息安全风险要素关系:“威胁利用脆弱性,作用于资产,产生安全事件,导致资产损失”。","imageNames":["wx2026-02-08.png"]},{"id":"wx2026-02-098","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"98","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合IS0/IEC 27001 或 GB/T 22080 标准要求,其信息安全控制措施通常需要在符合性方面实施常规控制。符合性常规控制这一领域不包括以下哪项控制目标()","options":["符合法律要求","符合安全策略和标准以及技术符合性","信息系统审核考虑","访问控制的业务要求、用户访问管理"],"correctIndex":3,"explanation":"符合性常规控制这一领域的控制目标主要包括符合法律要求、符合安全策略和标准以及技术符合性、信息系统审核考虑等。访问控制的业务要求、用户访问管理属于访问控制领域的控制目标,并非符合性常规控制领域的目标,所以答案选D。","imageNames":[]},{"id":"wx2026-02-099","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"99","domain":"信息安全法规标准","stem":"小王在学习信息安全管理体系相关知识之后,对于建立信息安全管理体系,自己总结了下面四条要求,其中理解不正确的是（ ）。","options":["信息安全管理体系的建立应基于最新的信息安全技术,因为这是国家有关信息安全的法律和法规方面的要求,这体现以预防控制为主的思想正确答案","信息安全管理体系的建立应参照国际国内有关标准实施,因为这些标准是标准化组织在总结研究了很多实际的或潜在的问题后,制定的能共同的和重复使用的规则","信息安全管理体系应强调全过程和动态控制的思想,因为安全问题是动态的,系统所处的安全环境也不会一成不变的,不可能建设永远安全的系统","信息安全管理体系应体现科学性和全面性的特点,因为要对信息安全管理涉及的方方面面实施较为均衡的管理,避免遗漏某些方面而导致组织的整体信息安全水平过低"],"correctIndex":0,"explanation":"选项A:信息安全管理体系的建立应基于组织自身的业务需求、风险状况等因素,而不是单纯基于最新的信息安全技术。虽然要遵循国家有关信息安全的法律和法规,但这不是基于最新技术,且信息安全管理体系强调的是管理,而非仅仅依靠技术预防控制。","imageNames":[]},{"id":"wx2026-02-100","setId":"wx2026-02","setName":"CISO 练习题（B卷）","sourceNumber":"100","domain":"信息安全法规标准","stem":"ISO 9001-2000标准在制定、实施质量管理体系以及改进其有效性时采用过程方法,通过满足顾客要求增进顾客满意。下图是关于过程方法的示意图,图中括号空白处应填写（）","options":["策略","管理者","组织","活动"],"correctIndex":3,"explanation":"选项A策略是指导原则,不直接参与过程管控；选项B管理者负责制定方针、监控过程、确保资源,是过程方法的核心管控角色；选项C组织是主体,而非过程中的管控节点；选项D活动是过程的组成部分,在 ISO 9001:2000 标准的过程方法模型中,过程被定义为一组“相互关联或相互作用的活动”,这些活动利用资源将输入转化为输出。","imageNames":["wx2026-02-09.png"]}]},{"id":"wx2026-03","name":"CISP 复习题（1）","subtitle":"100题 · 有答案+解析","sourceFile":"CISP复习题（1）100题（有答案）-已审+解析.docx","questionCount":100,"questions":[{"id":"wx2026-03-001","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"1","domain":"信息安全法规标准","stem":"依据国家标准/T20274《信息系统安全保障评估框架》,信息系统安全目标(ISST)中,安全保障目的指的是:","options":["信息系统安全保障目的","环境安全保障目的","信息系统安全保障目的和环境安全保障目的","信息系统整体安全保障目的、管理安全保障目的、技术安全保障目的和工程安全保障目的"],"correctIndex":3,"explanation":"依据国家标准GB/T 20274《信息系统安全保障评估框架》,信息系统安全目标(ISST)中,安全保障目的包含信息系统整体安全保障目的、管理安全保障目的、技术安全保障目的和工程安全保障目的。","imageNames":[]},{"id":"wx2026-03-002","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"2","domain":"信息安全管理","stem":"以下哪一项是数据完整性得到保护的例子?","options":["某网站在访问量突然增加时对用户连接数量进行了限制,保证已登录的用户可以完成操作","在提款过程中ATM终端发生故障,银行业务系统及时对该用户的账户余额进行了冲正操作","某网管系统具有严格的审计功能,可以确定哪个管理员在何时对核心交换机进行了什么操作","李先生在每天下班前将重要文件锁在档案室的保密柜中,使伪装成清洁工的商业间谍无法查看"],"correctIndex":1,"explanation":"A为可用性,B为完整性,C是抗抵赖,D是保密性。冲正是完整性纠正措施,是Clark-Wilson模型的应用,解决数据变化过程的完整性。","imageNames":[]},{"id":"wx2026-03-003","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"3","domain":"信息安全管理","stem":"进入21世纪以来,信息安全成为世界各国安全战略关注的重点,纷纷制定并颁布网络空间安全战略,但各国历史、国情和文化不同,网络空间安全战略的内容也各不相同,以下说法不正确的是:","options":["与国家安全、社会稳定和民生密切相关的关键基础设施是各国安全保障的重点","美国尚未设立中央政府级的专门机构处理网络信息安全问题,信息安全管理职能由不同政府部门的多个机构共同承担","各国普遍重视信息安全事件的应急响应和处理","在网络安全战略中,各国均强调加强政府管理力度,充分利用社会资源,发挥政府与企业之间的合作关系"],"correctIndex":1,"explanation":"美国已经设立中央政府级的专门机构。","imageNames":[]},{"id":"wx2026-03-004","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"4","domain":"信息安全保障","stem":"与PDR模型相比,P2DR模型多了哪一个环节?","options":["防护","检测","反应","策略"],"correctIndex":3,"explanation":"PPDR是指策略、保护、检测和反应（或响应）。PPDR比PDR多策略。","imageNames":[]},{"id":"wx2026-03-005","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"5","domain":"信息安全保障","stem":"以下关于项目的含义,理解错误的是:","options":["项目是为达到特定的目的、使用一定资源、在确定的期间内、为特定发起人而提供独特的产品、服务或成果而进行的一次性努力。","项目有明确的开始日期,结束日期由项目的领导者根据项目进度来随机确定。","项目资源指完成项目所需要的人、财、物等。","项目目标要遵守SMART原则,即项目的目标要求具体(Specific)、可测量（Measurable)、需相关方的一致同意(Agreeto)、现实(Realistic)、有一定的时限(Timeoriented)"],"correctIndex":1,"explanation":"据项目进度不能随机确定,需要根据项目预算、特性、质量等要求进行确定。","imageNames":[]},{"id":"wx2026-03-006","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"6","domain":"信息安全管理","stem":"2008年1月2日,美目发布第54号总统令,建立国家网络安全综合计划（Comprehensive National Cyber security Initiative,CNCI)。CNCI计划建立三道防线:第一道防线,减少漏洞和隐患,预防入侵；第二道防线,全面应对各类威胁；第三道防线,强化未来安全环境.从以上内容,我们可以看出以下哪种分析是正确的:","options":["CNCI是以风险为核心,三道防线首要的任务是降低其网络所面临的风险","从CNCI可以看出,威胁主要是来自外部的,而漏洞和隐患主要是存在于内部的","CNCI的目的是尽快研发并部署新技术彻底改变其糟糕的网络安全现状,而不是在现在的网络基础上修修补补","CNCI彻底改变了以往的美国信息安全战略,不再把关键基础设施视为信息安全保障重点,而是追求所有网络和系统的全面安全保障"],"correctIndex":0,"explanation":"CNCI第一个防线针对漏洞进行风险控制,第二个防线针对威胁进行风险控制,总体的目标是降低网络风险。B、C、D答案均无法从题干反应。","imageNames":[]},{"id":"wx2026-03-007","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"7","domain":"信息安全法规标准","stem":"下列对于信息安全保障深度防御模型的说法错误的是:","options":["信息安全外部环境:信息安全保障是组织机构安全、国家安全的一个重要组成部分,因此对信息安全的讨论必须放在国家政策、法律法规和标准的外部环境制约下。","信息安全管理和工程:信息安全保障需要在整个组织机构内建立和完善信息安全管理体系,将信息安全管理综合至信息系统的整个生命周期,在这个过程中,我们需要采用信息系统工程的方法来建设信息系统。","信息安全人才体系:在组织机构中应建立完善的安全意识,培训体系也是信息安全保障的重要组成部分。","信息安全技术方案:“从外而内、自下而上、形成边界到端的防护能力”。"],"correctIndex":3,"explanation":"D的正确描述是从内而外,自上而下,从端到边界的防护能力。","imageNames":[]},{"id":"wx2026-03-008","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"8","domain":"信息安全技术","stem":"某用户通过账号、密码和验证码成功登录某银行的个人网银系统,此过程属于以下哪一类:","options":["个人网银系统和用户之间的双向鉴别","由可信第三方完成的用户身份鉴别","个人网银系统对用户身份的单向鉴别","用户对个人网银系统合法性的单向鉴别"],"correctIndex":2,"explanation":"题干为网银系统对用户的鉴别。","imageNames":[]},{"id":"wx2026-03-009","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"9","domain":"信息安全技术","stem":"Alice 用Bob的密钥加密明文,将密文发送给Bob。Bob再用自己的私钥解密,恢复出明文。以下说法正确的是:","options":["此密码体制为对称密码体制","此密码体制为私钥密码体制","此密码体制为单钥密码体制","此密码体制为公钥密码体制"],"correctIndex":3,"explanation":"题干中使用到了私钥解密,私钥是公钥密码体制中用户持有的密钥,相对于公钥而言,则为非对称密码体制,非对称密码体制又称为公钥密码体制。","imageNames":[]},{"id":"wx2026-03-010","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"10","domain":"信息安全保障","stem":"下列哪一种方法属于基于实体“所有”鉴别方法:","options":["用户通过自己设置的口令登录系统,完成身份鉴别","用户使用个人指纹,通过指纹识别系统的身份鉴别","用户利用和系统协商的秘密函数,对系统发送挑战进行正确应答,通过身份鉴别","用户使用集成电路卡(如智能卡)完成身份鉴别"],"correctIndex":3,"explanation":"实体所有鉴别包括身份证、IC卡、钥匙、USB-Key等。","imageNames":[]},{"id":"wx2026-03-011","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"11","domain":"信息安全技术","stem":"为防范网络欺诈确保交易安全,网银系统首先要求用户安全登录,然后使用“智能卡+短信认证”模式进行网上转账等交易,在此场景中用到下列哪些鉴别方法?","options":["实体“所知”以及实体“所有”的鉴别方法","实体“所有”以及实体“特征”的鉴别方法","实体“所知”以及实体“特征”的鉴别方法","实体“所有”以及实体“行为”的鉴别方法"],"correctIndex":0,"explanation":"题目中安全登录会涉及到账号密码为实体所知,智能卡和短信是实体所有。","imageNames":[]},{"id":"wx2026-03-012","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"12","domain":"信息安全工程","stem":"某单位开发了一个面向互联网提供服务的应用网站,该单位委托软件测评机构对软件进行了源代码分析、模糊测试等软件安全性测试,在应用上线前,项目经理提出了还需要对应用网站进行一次渗透性测试,作为安全主管,你需要提出渗透性测试相比源代码测试、模糊测试的优势给领导做决策,以下哪条是渗透性测试的优势?","options":["渗透测试以攻击者的思维模拟真实攻击,能发现如配置错误等运行维护期产生的漏洞","渗透测试是用软件代替人工的一种测试方法,因此测试效率更高","渗透测试使用人工进行测试,不依赖软件,因此测试更准确","渗透测试中必须要查看软件源代码,因此测试中发现的漏洞更多"],"correctIndex":0,"explanation":"渗透测试是模拟攻击的黑盒测试,有利于发现系统明显的问题。","imageNames":[]},{"id":"wx2026-03-013","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"13","domain":"信息安全法规标准","stem":"软件安全设计和开发中应考虑用户稳私包,以下关于用户隐私保护的说法哪个是错误的?","options":["告诉用户需要收集什么数据及搜集到的数据会如何披使用","当用户的数据由于某种原因要被使用时,给用户选择是否允许","用户提交的用户名和密码属于稳私数据,其它都不是","确保数据的使用符合国家、地方、行业的相关法律法规"],"correctIndex":2,"explanation":"个人隐私包括但不限于用户名密码、位置、行为习惯等信息。","imageNames":[]},{"id":"wx2026-03-014","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"14","domain":"信息安全工程","stem":"软件安全保障的思想是在软件的全生命周期中贯彻风险管理的思想,在有限资源前提下实现软件安全最优防护,避免防范不足带来的直接损失,也需要关注过度防范造成的间接损失。在以下软件安全开发策略中,不符合软件安全保障思想的是:","options":["在软件立项时考虑到软件安全相关费用,经费中预留了安全测试、安全评审相关费用,确保安全经费得到落实","在软件安全设计时,邀请软件安全开发专家对软件架构设计进行评审,及时发现架构设计中存在的安全不足","确保对软编码人员进行安全培训,使开发人员了解安全编码基本原则和方法,确保开发人员编写出安全的代码","在软件上线前对软件进行全面安全性测试,包括源代码分析、模糊测试、渗透测试,未经以上测试的软件不允许上线运行"],"correctIndex":3,"explanation":"软件的安全测试根据实际情况进行测试措施的选择和组合。","imageNames":[]},{"id":"wx2026-03-015","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"15","domain":"信息安全技术","stem":"以下哪一项不是工作在网络第二层的隧道协议:","options":["VTP","L2F","PPTP","L2TP"],"correctIndex":0,"explanation":"L2F、PPTP、L2TP均为二层隧道协议。","imageNames":[]},{"id":"wx2026-03-016","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"16","domain":"信息安全技术","stem":"主体S对客体01有读(R)权限,对客体02有读(R)、写(W)、拥有(Own)权限,该访问控制实现方法是:","options":["访问控制表(ACL)","访问控制矩阵","能力表(CL)","前缀表(Profiles)"],"correctIndex":2,"explanation":"定义主体访问客体的权限叫作CL。定义客体被主体访问的权限叫ACL。","imageNames":[]},{"id":"wx2026-03-017","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"17","domain":"信息安全管理","stem":"以下场景描述了基于角色的访问控制模型(Role-based Access Control.RBAC):根据组织的业务要求或管理要求,在业务系统中设置若干岗位、职位或分工,管理员负责将权限(不同类别和级别的)分别赋予承担不同工作职责的用户。关于RBAC模型,下列说法错误的是:","options":["当用户请求访问某资源时,如果其操作权限不在用户当前被激活角色的授权范围内,访问请求将被拒绝","业务系统中的岗位、职位或者分工,可对应RBAC模型中的角色","通过角色,可实现对信息资源访问的控制","RBAC模型不能实现多级安全中的访问控制"],"correctIndex":3,"explanation":"RBAC模型能实现多级安全中的访问控制。","imageNames":[]},{"id":"wx2026-03-018","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"18","domain":"信息安全法规标准","stem":"下面哪一项不是虚拟专用网络(VPN)协议标准:","options":["第二层隧道协议(L2TP)","Internet安全性(IPSEC)","终端访问控制器访问控制系统(TACACS+)","点对点隧道协议(PPTP)"],"correctIndex":2,"explanation":"TACACS+是AAA权限控制系统,不属于VPN。","imageNames":[]},{"id":"wx2026-03-019","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"19","domain":"信息安全技术","stem":"下列对网络认证协议Kerberos描述正确的是:","options":["该协议使用非对称密钥加密机制","密钥分发中心由认证服务器、票据授权服务器和客户机三个部分组成","该协议完成身份鉴别后将获取用户票据许可票据","使用该协议不需要时钟基本同步的环境"],"correctIndex":2,"explanation":"A错误,因为使用对称密码；B错误,因为密钥分发中心不包括客户机；D错误,因为协议需要时钟同步。三个步骤: 身份认证后获得票据许可票据； 获得服务许可票据； 获得服务。","imageNames":[]},{"id":"wx2026-03-020","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"20","domain":"信息安全技术","stem":"鉴别的基本途径有三种:所知、所有和个人特征,以下哪一项不是基于你所知道的:","options":["口令","令牌","知识","密码"],"correctIndex":1,"explanation":"令牌是基于实体所有的鉴别方式。","imageNames":[]},{"id":"wx2026-03-021","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"21","domain":"信息安全技术","stem":"在ISO 的OSI安全体系结构中,以下哪一个安全机制可以提供抗抵赖安全服务?","options":["加密","数字签名","访问控制","路由控制"],"correctIndex":1,"explanation":"数字签名可以提供抗抵赖、鉴别和完整性。","imageNames":[]},{"id":"wx2026-03-022","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"22","domain":"信息安全技术","stem":"某公司已有漏洞扫描和入侵检测系统(Intrusion Detection System,IDS)产品,需要购买防火墙,以下做法应当优先考虑的是:","options":["选购当前技术最先进的防火墙即可","选购任意一款品牌防火墙","任意选购一款价格合适的防火墙产品","选购一款同已有安全产品联动的防火墙"],"correctIndex":3,"explanation":"在技术条件允许情况下,可以实现IDS和FW的联动。","imageNames":[]},{"id":"wx2026-03-023","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"23","domain":"信息安全技术","stem":"在OSI参考模型中有7个层次,提供了相应的安全服务来加强信息系统的安全性,以下哪一层提供了保密性、身份鉴别、数据完整性服务?","options":["网络层","表示层","会话层","物理层"],"correctIndex":0,"explanation":"网络层和应用层可以提供保密性、身份鉴别、完整性、抗抵赖、访问控制服务。","imageNames":[]},{"id":"wx2026-03-024","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"24","domain":"信息安全管理","stem":"某单位人员管理系统在人员离职时进行账号删除,需要离职员工所在部门主管经理和人事部门人员同时进行确认才能在系统上执行,该设计是遵循了软件安全哪项原则","options":["最小权限","权限分离","不信任","纵深防御"],"correctIndex":1,"explanation":"权限分离是将一个较大的权限分离为多个子权限组合操作来实现。","imageNames":[]},{"id":"wx2026-03-025","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"25","domain":"信息安全技术","stem":"以下关于互联网协议安全(Internet Protocol Security,IPSec)协议说法错误的是:","options":["在传送模式中,保护的是IP负载。","验证头协议(Authentication Header,AH)和IP封装安全载荷协议(Encapsulating Security Payload,ESP)都能以传输模式和隧道模式工作。","在隧道模式中,保护的是整个互联网协议IP包,包括IP 头。","IPSec仅能保证传输数据的可认证性和保密性。"],"correctIndex":3,"explanation":"IPSEC可以提供身份鉴别、保密性、完整性、抗抵赖、访问控制服务。","imageNames":[]},{"id":"wx2026-03-026","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"26","domain":"信息安全法规标准","stem":"某电子商务网站在开发设计时,使用了威胁建模方法来分折电子商务网站所面临的威胁,STRIDE 是微软SDL中提出的威胁建模方法,将威胁分为六类,为每一类威胁提供了标准的消减措施,Spoofing是STRIDE中欺骗类的威胁,以下威胁中哪个可以归入此类威胁?","options":["网站竞争对手可能雇佣攻击者实施DDoS攻击,降低网站访问速度","网站使用http协议进行浏览等操作,未对数据进行加密,可能导致用户传输信息泄露,例如购买的商品金额等","网站使用http协议进行浏览等操作,无法确认数据与用户发出的是否一致,可能数据被中途篡改","网站使用用户名、密码进行登录验证,攻击者可能会利用弱口令或其他方式获得用户密码,以该用户身份登录修改用户订单等信息"],"correctIndex":3,"explanation":"A属于可用性；B保密性；C属于完整性。","imageNames":[]},{"id":"wx2026-03-027","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"27","domain":"信息安全技术","stem":"以下关于PGP(Pretty Good Privacy)软件叙述错误的是:","options":["PGP可以实现对邮件的加密、签名和认证","PGP可以实现数据压缩","PGP可以对邮件进行分段和重组","PGP采用SHA算法加密邮件"],"correctIndex":3,"explanation":"SHA不提供加密,SHA是摘要算法提供数据完整性校验。","imageNames":[]},{"id":"wx2026-03-028","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"28","domain":"信息安全技术","stem":"入侵防御系统(IPS)是继入侵检测系统(IDS)后发展期出来的一项新的安全技术,它与IDS有着许多不同点,请指出下列哪一项描述不符合IPS 的特点?","options":["串接到网络线路中","对异常的进出流量可以直接进行阻断","有可能造成单点故障","不会影响网络性能"],"correctIndex":3,"explanation":"IPS在串联情况下,会影响网络性能。","imageNames":[]},{"id":"wx2026-03-029","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"29","domain":"信息安全技术","stem":"相比文件配置表(FAT)文件系统,以下哪个不是新技术文件系统(NTFS)所具有的优势?","options":["NTFS使用事务日志自动记录所有文件夹和文件更新,当出现系统损坏和电源故障等问题,而引起操作失败后,系统能利用日志文件重做或恢复未成功的操作","NTFS的分区上,可以为每个文件或文件夹设置单独的许可权限","对于大磁盘,NTFS文件系统比FAT有更高的磁盘利用率","相比FAT文件系统,NTFS文件系统能有效的兼容linux下EXT2文件格式"],"correctIndex":3,"explanation":"NTFS不能兼容EXT文件系统。","imageNames":[]},{"id":"wx2026-03-030","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"30","domain":"信息安全管理","stem":"某公司系统管理员最近正在部署一台Web服务器,使用的操作系统是windows,在进行日志安全管理设置时,系统管理员拟定四条日志安全策略给领导进行参考,其中能有效应对攻击者获得系统权限后对日志进行修改的策略是:","options":["网络中单独部署syslog服务器,将Web服务器的日志自动发送并存储到该syslog日志服务器中","严格设置Web日志权限,只有系统权限才能进行读和写等操作","对日志属性进行调整,加大日志文件大小、延长覆盖时间、设置记录更多信息等","使用独立的分区用于存储日志,并且保留足够大的日志空间"],"correctIndex":0,"explanation":"在多重备份存储情况下,可以防护日志被篡改的攻击（前提非实时同步）。","imageNames":[]},{"id":"wx2026-03-031","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"31","domain":"信息安全技术","stem":"关于linux下的用户和组,以下描述不正确的是 。","options":["在linux中,每一个文件和程序都归属于一个特定的“用户”","系统中的每一个用户都必须至少属于一个用户组","用户和组的关系可是多对一,一个组可以有多个用户,一个用户不能属于多个组","root是系统的超级用户,无论是否文件和程序的所有者都具有访问权限"],"correctIndex":2,"explanation":"一个用户可以属于多个组。","imageNames":[]},{"id":"wx2026-03-032","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"32","domain":"信息安全管理","stem":"安全的运行环境是软件安全的基础,操作系统安全配置是确保运行环境安全必不可少的工作,某管理员对即将上线的Windows操作系统进行了以下四项安全部署工作,其中哪项设置不利于提高运行环境安全?","options":["操作系统安装完成后安装最新的安全补丁,确保操作系统不存在可被利用的安全漏洞","为了方便进行数据备份,安装Windows操作系统时只使用一个分区C,所有数据和操作系统都存放在C盘","操作系统上部署防病毒软件,以对抗病毒的威胁","将默认的管理员账号Administrator改名,降低口令暴力破解攻击的发生可能"],"correctIndex":1,"explanation":"操作系统和应用安全装应分开不同磁盘部署。","imageNames":[]},{"id":"wx2026-03-033","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"33","domain":"信息安全技术","stem":"在数据库安全性控制中,授权的数据对象,授权子系统就越灵活?","options":["粒度越小","约束越细致","范围越大","约束范围大"],"correctIndex":0,"explanation":"数据粒度越细则授权策略越灵活便利。","imageNames":[]},{"id":"wx2026-03-034","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"34","domain":"信息安全技术","stem":"下列哪一些对信息安全漏洞的描述是错误的?","options":["漏洞是存在于信息系统的某种缺陷。","漏洞存在于一定的环境中,寄生在一定的客体上(如TOE中、过程中等)。","具有可利用性和违规性,它本身的存在虽不会造成破坏,但是可以被攻击者利用,从而给信息系统安全带来威胁和损失。","漏洞都是人为故意引入的一种信息系统的弱点"],"correctIndex":3,"explanation":"漏洞是人为故意或非故意引入的弱点。","imageNames":[]},{"id":"wx2026-03-035","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"35","domain":"信息安全技术","stem":"账号锁定策略中对超过一定次数的错误登录账号进行锁定是为了对抗以下哪种攻击?","options":["分布式拒绝服务攻击(DDoS)","病毒传染","口令暴力破解","缓冲区溢出攻击"],"correctIndex":2,"explanation":"账号锁定是为了解决暴力破解攻击的。","imageNames":[]},{"id":"wx2026-03-036","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"36","domain":"信息安全保障","stem":"以下哪个不是导致地址解析协议(ARP)欺骗的根源之一?","options":["ARP协议是一个无状态的协议","为提高效率,ARP信息在系统中会缓存","ARP缓存是动态的,可被改写","ARP协议是用于寻址的一个重要协议"],"correctIndex":3,"explanation":"D不是导致欺骗的根源。","imageNames":[]},{"id":"wx2026-03-037","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"37","domain":"信息安全工程","stem":"张三将微信个人头像换成微信群中某好友头像,并将昵称改为该好友的昵称,然后向该好友的其他好友发送一些欺骗消息。该攻击行为属于以下哪类攻击?","options":["口令攻击","暴力破解","拒绝服务攻击","社会工程学攻击"],"correctIndex":3,"explanation":"D属于社会工程学攻击。","imageNames":[]},{"id":"wx2026-03-038","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"38","domain":"信息安全工程","stem":"关于软件安全开发生命周期(SDL),下面说法错误的是:","options":["在软件开发的各个周期都要考虑安全因素","软件安全开发生命周期要综合采用技术、管理和工程等手段","测试阶段是发现并改正软件安全漏洞的最佳环节,过早或过晚检测修改漏洞都将增大软件开发成本","在设计阶段就尽可能发现并改正安全隐患,将极大减少整个软件开发成本"],"correctIndex":2,"explanation":"设计阶段是发现和改正问题的最佳阶段。","imageNames":[]},{"id":"wx2026-03-039","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"39","domain":"信息安全工程","stem":"在软件保障成熟度模型(Software Assurance Maturity Mode,SAMM)中,规定了软件开发过程中的核心业务功能,下列哪个选项不属于核心业务功能:","options":["治理,主要是管理软件开发的过程和活动","构造,主要是在开发项目中确定目标并开发软件的过程与活动","验证,主要是测试和验证软件的过程与活动","购置,主要是购买第三方商业软件或者采用开源组件的相关管理过程与活动"],"correctIndex":3,"explanation":"SAMM模型四个部分是治理、构造、验证和部署。","imageNames":[]},{"id":"wx2026-03-040","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"40","domain":"信息安全工程","stem":"从系统工程的角度来处理信息安全问题,以下说法错误的是:","options":["系统安全工程旨在了解企业存在的安全风险,建立一组平衡的安全需求,融合各种工程学科的努力将此安全需求转换为贯穿系统整个生存期的工程实施指南。","系统安全工程需对安全机制的正确性和有效性做出诠释,证明安全系统的信任度能够达到企业的要求,或系统遗留的安全薄弱性在可容许范围之内。","系统安全工程能力成熟度模型(SSE-CMM)是一种衡量安全工程实践能力的方法,是一种使用面向开发的方法。","系统安全工程能力成熟度模型(SSE-CMM)是在原有能力成熟度模型(CMM)的基础上,通过对安全工作过程进行管理的途径,将系统安全工程转变为一个完好定义的、成熟的、可测量的先进学科。"],"correctIndex":2,"explanation":"SSE-CMM是面向工程过程质量控制的一套方法。","imageNames":[]},{"id":"wx2026-03-041","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"41","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型(SSE-CMM)中的基本实施(Base Practices,BP),正确的理解是:","options":["BP是基于最新技术而制定的安全参数基本配置","大部分BP是没有经过测试的","一项BP适用于组织的生存周期而非仅适用于工程的某一特定阶段","一项BP可以和其他BP有重叠"],"correctIndex":2,"explanation":"A错误,BP是基于最佳的工程过程实践；B错误,BP是经过测试的；D错误,一项BP和其他的BP是不重复。","imageNames":[]},{"id":"wx2026-03-042","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"42","domain":"信息安全管理","stem":"以下哪一种判断信息系统是否安全的方式是最合理的?","options":["是否己经通过部署安全控制措施消灭了风险","是否可以抵抗大部分风险","是否建立了具有自适应能力的信息安全模型","是否已经将风险控制在可接受的范围内"],"correctIndex":3,"explanation":"判断风险控制的标准是风险是否控制在接受范围内。","imageNames":[]},{"id":"wx2026-03-043","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"43","domain":"信息安全法规标准","stem":"以下关于信息安全法治建设的意义,说法错误的是:","options":["信息安全法律环境是信息安全保障体系中的必要环节","明确违反信息安全的行为,并对行为进行相应的处罚,以打击信息安全犯罪活动","信息安全主要是技术问题,技术漏洞是信息犯罪的根源","信息安全产业的逐渐形成,需要成熟的技术标准和完善的技术体系"],"correctIndex":2,"explanation":"信息安全问题是多方面存在的,不能认为主要为技术问题,同时技术漏洞不是犯罪的根源所在。","imageNames":[]},{"id":"wx2026-03-044","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"44","domain":"信息安全管理","stem":"小张是信息安全风险管理方面的专家,被某单位邀请过去对其核心机房经受某种灾害的风险进行评估,已知:核心机房的总价价值一百万,灾害将导致资产总价值损失二成四(24%),历史数据统计告知该灾害发生的可能性为八年发生三次,请问小张最后得到的年度预期损失为多少:","options":["24万","0.09 万","37.5 万","9 万"],"correctIndex":3,"explanation":"年度预期损失（ALE）=资产价值×损失比例×年发生率。资产价值100万,损失比例24%,年发生率3÷8 = 0.375次/年,ALE = 100×24%×0.375 = 9万。","imageNames":[]},{"id":"wx2026-03-045","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"45","domain":"信息安全法规标准","stem":"2005 年4 月1日正式施行的《电子签名法》,被称为“中国首部真正意义上的信息化法律”,自此电子签名与传统手写签名和盖章具有同等的法律效力。以下关于电子签名说法错误的是:","options":["电子签名——是指数据电文中以电子形式所含、所附用于识别签名人身份并表明签名人认可其中内容的数据","电子签名适用于民事活动中的合同或者其他文件、单证等文书","电子签名需要第三方认证的,由依法设立的电子认证服务提供者提供认证服务","电子签名制作数据用于电子签名时,属于电子签名人和电子认证服务提供者共有"],"correctIndex":3,"explanation":"电子签名不可以与认证服务提供者共有。","imageNames":[]},{"id":"wx2026-03-046","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"46","domain":"信息安全管理","stem":"风险管理的监控与审查不包含:","options":["过程质量管理","成本效益管理","跟踪系统自身或所处环境的变化","协调内外部组织机构风险管理活动"],"correctIndex":3,"explanation":"D答案属于沟通咨询工作,ABC属于风险管理的监控审查工作。风险管理过程包括背景建立、风险评估、风险处理、批准监督,以及沟通咨询和监控审查。","imageNames":[]},{"id":"wx2026-03-047","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"47","domain":"信息安全法规标准","stem":"信息安全等级保护要求中,第三级适用的正确的是:","options":["适用于一般的信息和信息系统,其受到破坏后,会对公民、法人和其他组织的权益有一定影响,但不危害国家安全、社会秩序、经济建设和公共利益","适用于一定程度上涉及国家安全、社会秩序、经济建设和公共利益的一般信息和信息系统,其受到破坏后,会对国家安全、社会秩序、经济建设和公共利益造成一般损害","适用于涉及国家安全、社会秩序、经济建设和公共利益的信息和信息系统,其受到破坏后,会对国家安全、社会秩序、经济建设和公共利益造成严重损害","适用于涉及国家安全、社会秩序、经济建设和公共利益的重要信息和信息系统的核心子系统。其受到破坏后,会对国家安全、社会秩序,经济建设和公共利益造成特别严重损害"],"correctIndex":1,"explanation":"题目中B为等级保护三级,该考点为等级保护定级指南。","imageNames":[]},{"id":"wx2026-03-048","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"48","domain":"信息安全管理","stem":"下面哪一项安全控制措施不是用来检测未经授权的信息处理活动的:","options":["设置网络连接时限","记录并分析系统错误日志","记录并分析用户和管理员操作日志","启用时钟同步"],"correctIndex":0,"explanation":"A属于防护措施；BCD属于检测措施,可以用来检测未经授权的信息处理活动。","imageNames":[]},{"id":"wx2026-03-049","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"49","domain":"信息安全法规标准","stem":"有关危害国家秘密安全的行为的法律责任,正确的是:","options":["严重违反保密规定行为只要发生,无论产生泄密实际后果,都要依法追究责任","非法获取国家秘密,不会构成刑事犯罪,不需承担刑事责任","过失泄露国家秘密,不会构成刑事犯罪,不需承担刑事责任","承担了刑事责任,无需再承担行政责任和／或其他处分"],"correctIndex":0,"explanation":"严重违反保密规定行为只要发生,无论是否产生泄密实际后果,都要依法追究责任。非法获取国家秘密和过失泄露国家秘密,情节严重会构成刑事犯罪；承担了刑事责任,还可能需承担行政责任和／或其他处分。","imageNames":[]},{"id":"wx2026-03-050","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"50","domain":"信息安全管理","stem":"以下对于信息安全事件理解错误的是:","options":["信息安全事件,是指由于自然或者人为以及软硬件本身缺陷或故障的原因,对信息系统造成危害,或在信息系统内发生对社会造成负面影响的事件","对信息安全事件进行有效管理和响应,最小化事件所造成的损失和负面影响,是组织信息安全战略的一部分","应急响应是信息安全事件管理的重要内容","通过部署信息安全策略并配合部署防护措施,能够对信息及信息系统提供保护,杜绝信息安全事件的发生"],"correctIndex":3,"explanation":"通过部署信息安全策略并配合部署防护措施,不能杜绝信息安全事件的发生,只能降低发生的可能性和减少损失。A选项信息安全事件定义正确；B选项事件管理重要性正确；C选项应急响应重要性正确","imageNames":[]},{"id":"wx2026-03-051","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"51","domain":"信息安全保障","stem":"假设一个系统已经包含了充分的预防控制措施,那么安装监测控制设备:","options":["是多余的,因为它们完成了同样的功能,但要求更多的开销","是必须的,可以为预防控制的功效提供检测","是可选的,可以实现深度防御","在一个人工系统中是需要的,但在一个计算机系统中则是不需要的,因为预防控制功能已经足够"],"correctIndex":2,"explanation":"即使系统有充分预防控制措施,安装监测控制设备也是可选的,它能实现深度防御,进一步增强系统安全性。监测控制可检测预防控制是否有效,但不是多余的,也不是必须的,且在计算机系统中同样有安装监测控制设备的意义,所以选C。","imageNames":[]},{"id":"wx2026-03-052","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"52","domain":"信息安全管理","stem":"关于我国加强信息安全保障工作的主要原则,以下说法错误的是:","options":["立足国情,以我为主,坚持技术与管理并重","正确处理安全和发展的关系,以安全保发展,在发展中求安全","统筹规划,突出重点,强化基础工作","全面提高信息安全防护能力,保护公众利益,维护国家安全"],"correctIndex":3,"explanation":"D描述的是信息安全保障工作目标,而非主要原则。ABC描述的是信息安全保障的原则。","imageNames":[]},{"id":"wx2026-03-053","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"53","domain":"信息安全工程","stem":"以下哪一项不是信息安全管理工作必须遵循的原则?","options":["风险管理在系统开发之初就应该予以充分考虑,并要贯穿于整个系统开发过程之中","风险管理活动应成为系统开发、运行、维护、直至废弃的整个生命周期内的持续性工作","由于在系统投入使用后部署和应用风险控制措施针对性会更强,实施成本会相对较低","在系统正式运行后,应注重残余风险的管理,以提高快速反应能力"],"correctIndex":2,"explanation":"安全措施投入应越早则成本越低,C答案则成本会上升。","imageNames":[]},{"id":"wx2026-03-054","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"54","domain":"信息安全法规标准","stem":"《信息安全技术 信息安全风险评估规范》（GB/T 20984-2007）中关于信息系统生命周期各阶段的风险评估描述不正确的是:","options":["规划阶段风险评估的目的是识别系统的业务战略,以支撑系统安全需求及安全战略等","设计阶段的风险评估需要根据规划阶段所明确的系统运行环境、资产重要性,提出安全功能需求","实施阶段风险评估的目的是根据系统安全需求和运行环境对系统开发、实施过程进行风险识别,并对系统建成后的安全功能进行验证","运行维护阶段风险评估的目的是了解和控制运行过程中的安全风险,是一种全面的风险评估。评估内容包括对真实运行的信息系统、资产、脆弱性等各方面"],"correctIndex":3,"explanation":"该题目来源于《信息安全技术 信息安全风险评估规范》（GB/T 20984-2007）,其原文描述D为“是一种较全面的风险评估”。","imageNames":[]},{"id":"wx2026-03-055","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"55","domain":"信息安全管理","stem":"对信息安全风险评估要素理解正确的是:","options":["资产识别的粒度随着评估范围、评估目的的不同而不同,既可以是硬件设备,也可以是业务系统,也可以是组织机构","应针对构成信息系统的每个资产做风险评价","脆弱性识别是将信息系统安全现状与国家或行业的安全要求做符合性比对而找出的差距项","信息系统面临的安全威胁仅包括人为故意威胁、人为非故意威胁"],"correctIndex":0,"explanation":"B错误,应该是抽样评估；C错误,应该其描述的是差距分析；D错误,应该是威胁包括人为威胁和环境威胁。","imageNames":[]},{"id":"wx2026-03-056","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"56","domain":"信息安全保障","stem":"以下哪些是需要在信息安全策略中进行描述的:","options":["组织信息系统安全架构","信息安全工作的基本原则","组织信息安全技术参数","组织信息安全实施手段"],"correctIndex":1,"explanation":"安全策略是宏观的原则性要求,不包括具体的架构、参数和实施手段。","imageNames":[]},{"id":"wx2026-03-057","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"57","domain":"信息安全管理","stem":"根据《关于开展信息安全风险评估工作的意见》的规定,错误的是:","options":["信息安全风险评估分自评估、检查评估两形式。应以检查评估为主,自评估和检查评估相互结合、互为补充","信息安全风险评估工作要按照“严密组织、规范操作、讲求科学、注重实效”的原则开展","信息安全风险评估应贯穿于网络和信息系统建设运行的全过程","开展信息安全风险评估工作应加强信息安全风险评估工作的组织领导"],"correctIndex":0,"explanation":"信息安全风险评估应以自评估（自查）为主。","imageNames":[]},{"id":"wx2026-03-058","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"58","domain":"信息安全管理","stem":"下面的角色对应的信息安全职责不合理的是:","options":["高级管理层——最终责任","信息安全部门主管——提供各种信息安全工作必须的资源","系统的普通使用者——遵守日常操作规范","审计人员——检查安全策略是否被遵从"],"correctIndex":1,"explanation":"通常由管理层提供各种信息安全工作必须的资源。","imageNames":[]},{"id":"wx2026-03-059","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"59","domain":"信息安全法规标准","stem":"自2004年1月起,国内各有关部门在申报信息安全国家标准计划项目时,必须经由以下哪个组织提出工作意见,协调一致后由该组织申报。","options":["全国通信标准化技术委员会(TC485)","全国信息安全标准化技术委员会(TC260)","中国通信标准化协会(CCSA)","网络与信息安全技术工作委员会"],"correctIndex":1,"explanation":"自2004年1月起,国内各有关部门在申报信息安全国家标准计划项目时,必须经由全国信息安全标准化技术委员会(TC260)提出工作意见,协调一致后由该组织申报,所以选B。","imageNames":[]},{"id":"wx2026-03-060","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"60","domain":"信息安全管理","stem":"风险计算原理可以用下面的范式形式化地加以说明:风险值=R（A,T,V)=R(L(T,V),F(Ia,Va))以下关于上式各项说明错误的是:","options":["R表示安全风险计算函数,A表示资产,T表示威胁,V表示脆弱性","L表示威胁利资产脆弱性导致安全事件的可能性","F表示安全事件发生后造成的损失","Ia,Va分别表示安全事件作用全部资产的价值与其对应资产的严重程度"],"correctIndex":3,"explanation":"Ia表示安全事件作用资产的价值,Va表示安全事件发生后该资产对应的脆弱性严重程度。","imageNames":[]},{"id":"wx2026-03-061","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"61","domain":"信息安全保障","stem":"以下哪一项在防止数据介质被滥用时是不推荐使用的方法:","options":["禁用主机的CD驱动、USB接口等I／O设备","对不再使用的硬盘进行严格的数据清除","将不再使用的纸质文件用碎纸机粉碎","用快速格式化删除存储介质中的保密文件"],"correctIndex":3,"explanation":"快速格式化删除存储介质中的保密文件不能防止信息泄露。","imageNames":[]},{"id":"wx2026-03-062","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"62","domain":"信息安全工程","stem":"在进行应用系统的测试时,应尽可能避免使用包含个人稳私和其它敏感信息的实际生产系统中的数据,如果需要使用时,以下哪一项不是必须做的:","options":["测试系统应使用不低于生产系统的访问控制措施","为测试系统中的数据部署完善的备份与恢复措施","在测试完成后立即清除测试系统中的所有敏感数据","部署审计措施,记录生产数据的拷贝和使用"],"correctIndex":1,"explanation":"由于备份会造成个人稳私和其它敏感信息的扩散。","imageNames":[]},{"id":"wx2026-03-063","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"63","domain":"信息安全管理","stem":"为了保证系统日志可靠有效,以下哪一项不是日志必需具备的特征。","options":["统一而精确地的时间","全面覆盖系统资产","包括访问源、访问目标和访问活动等重要信息","可以让系统的所有用户方便的读取"],"correctIndex":3,"explanation":"日志只有授权用户可以读取。","imageNames":[]},{"id":"wx2026-03-064","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"64","domain":"信息安全管理","stem":"关于信息安全事件管理和应急响应,以下说法错误的是:","options":["应急响应是指组织为了应对突发／重大信息安全事件的发生所做的准备,以及在事件发生后所采取的措施","应急响应方法,将应急响应管理过程分为遏制、根除、处置、恢复、报告和跟踪6 个阶段","对信息安全事件的分级主要参考信息系统的重要程度、系统损失和社会影响三方面因素","根据信息安全事件的分级参考要素,可将信息安全事件划分为4个级别:特别重大事件(Ⅰ级)、重大事件(Ⅱ级)、较大事件(Ⅲ级)和一般事件(Ⅳ级)"],"correctIndex":1,"explanation":"应急响应的六个阶段是准备、检测、遏制、根除、恢复、跟踪总结。","imageNames":[]},{"id":"wx2026-03-065","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"65","domain":"信息安全工程","stem":"以下哪一项不属于信息安全工程监理模型的组成部分:","options":["监理咨询支撑要素","控制和管理手段","监理咨询阶段过程","监理组织安全实施"],"correctIndex":3,"explanation":"监理模型组成包括监理咨询支撑要素、监理咨询阶段过程、控制和管理手段。","imageNames":[]},{"id":"wx2026-03-066","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"66","domain":"信息安全管理","stem":"以下关于灾难恢复和数据备份的理解,说法正确的是:","options":["增量备份是备份从上次完全备份后更新的全部数据文件","依据具备的灾难恢复资源程度的不同,灾难恢复能力分为7个等级","数据备份按数据类型划分可以划分为系统数据备份和用户数据备份","如果系统在一段时间内没有出现问题,就可以不用再进行容灾演练了"],"correctIndex":2,"explanation":"A错误,因为差分备份是上次全备后的更新数据；增量备份是任何上一次备份后的更新数据。全备份周期最长、次之差分备份,更新周期最短是增量备份。B错误,我国灾备能力级别一共分为6级。D是明显的错误。","imageNames":[]},{"id":"wx2026-03-067","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"67","domain":"信息安全保障","stem":"某公司拟建设面向内部员工的办公自动化系统和面向外部客户的营销系统,通过公开招标选择M公司为承建单位,并选择了H监理公司承担该项目的全程监理工作,目前,各个应用系统均已完成开发,M公司已经提交了验收申请,监理公司需要对A公司提交的软件配置文件进行审查,在以下所提交的文档中,哪一项属于开发类文档:","options":["项目计划书","质量控制计划","评审报告","需求说明书"],"correctIndex":3,"explanation":"ABC其均属于项目管理文档。需求说明书、设计说明书、测试方案、测试用例等属于开发类文档。","imageNames":[]},{"id":"wx2026-03-068","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"68","domain":"信息安全工程","stem":"在某网络机房建设项目中,在施工前,以下哪一项不属于监理需要审核的内容:","options":["审核实施投资计划","审核实施进度计划","审核工程实施人员","企业资质"],"correctIndex":0,"explanation":"监理从项目招标开始到项目的验收结束,在投资计划阶段没有监理。","imageNames":[]},{"id":"wx2026-03-069","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"69","domain":"信息安全管理","stem":"以下关于直接附加存储(Direct Attached Storage,DAS)说法错误的是:","options":["DAS能够在服务器物理位置比较分散的情况下实现大容量存储.是一种常用的数据存储方法","DAS实现了操作系统与数据的分离,存取性能较高并且实施简单","DAS的缺点在于对服务器依赖性强,当服务器发生故障时,连接在服务器上的存储设备中的数据不能被存取","较网络附加存储(Network Attached Storage,NAS),DAS节省硬盘空间,数据非常集中,便于对数据进行管理和备份"],"correctIndex":3,"explanation":"NAS优点数据集中、节约空间,缺点是占用网络带宽、存储中心存在单点故障。 DAS优点数据分散、风险分散,缺点是存储空间利用率低、不便于统一管理。SAN基于NAS的进一步实现,基于高速网络、多备份中心来进行实现。","imageNames":[]},{"id":"wx2026-03-070","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"70","domain":"信息安全工程","stem":"某公司在执行灾难恢复测试时.信息安全专业人员注意到灾难恢复站点的服务器的运行速度缓慢,为了找到根本愿因,他应该首先检查:","options":["灾难恢复站点的错误事件报告","灾难恢复测试计划","灾难恢复计划(DRP)","主站点和灾难恢复站点的配置文件"],"correctIndex":0,"explanation":"首先应检查灾难恢复站点的错误事件报告,以找到服务器运行速度缓慢的根本原因,再检查测试计划、灾难恢复计划、配置文件等,所以选A。","imageNames":[]},{"id":"wx2026-03-071","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"71","domain":"信息安全管理","stem":"以下对异地备份中心的理解最准确的是:","options":["与生产中心不在同一城市","与生产中心距离100公里以上","与生产中心距离200公里以上","与生产中心面临相同区域性风险的机率很小"],"correctIndex":3,"explanation":"异地备份中心与生产中心面临相同区域性风险的机率很小。","imageNames":[]},{"id":"wx2026-03-072","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"72","domain":"信息安全保障","stem":"作为业务持续性计划的一部分,在进行业务影响分析(BIA)时的步骤是: 1.标识关键的业务过程; 2.开发恢复优先级; 3.标识关键的IT资源; 4.表示中断影响和允许的中断时间","options":["１-3-4-2","１-3-2-4","1-2-3-4","１-4-3-2"],"correctIndex":0,"explanation":"业务影响分析(BIA)的步骤是标识关键业务过程、标识关键IT资源、表示中断影响和允许中断时间、开发恢复优先级,所以选A。","imageNames":[]},{"id":"wx2026-03-073","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"73","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型(SSE-CMM),错误的理解是:","options":["SSE-CMM要求实施组织与其他组织相互作用,如开发方、产品供应商、集成商和咨询服务商等","SSE-CMM可以使安全工程成为一个确定的、成熟的和可度量的科目","基手SSE-CMM的工程是独立工程,与软件工程、硬件工程、通信工程等分别规划实施","SSE-CMM覆盖整个组织的活动,包括管理、组织和工程活动等,而不仅仅是系统安全的工程活动"],"correctIndex":2,"explanation":"SSE-CMM是系统工程,不可以独立实施。","imageNames":[]},{"id":"wx2026-03-074","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"74","domain":"信息安全工程","stem":"下面关于信息系统安全保障的说法不正确的是:","options":["信息系统安全保障与信息系统的规划组织、开发采购、实施交付、运行维护和废弃等生命周期密切相关","信息系统安全保障要素包括信息的完整性、可用性和保密性","信息系统安全需要从技术、工程、管理和人员四个领域进行综合保障","信息系统安全保障需要将信息系统面临的风险降低到可接受的程度,从而实现其业务使命"],"correctIndex":1,"explanation":"信息系统安全保障要素为技术、工程、管理和人员四个领域。信息系统安全保障的安全特征是完整、保密和可用性。","imageNames":[]},{"id":"wx2026-03-075","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"75","domain":"信息安全工程","stem":"在使用系统安全工程-能力成熟度模型(SSECMM)对一个组织的安全工程能力成熟度进行测量时,正确的理解是:","options":["测量单位是基本实施(Base Practices,BP)","测量单位是通用实践(Generic Practices,GP)","测量单位是过程区域(Process Areas,PA)","测量单位是公共特征(Common Features,CF)"],"correctIndex":3,"explanation":"基本实施（BP）:是具体的活动或任务,是安全工程实践的基础单元。但它们本身并不直接作为能力成熟度的测量单位。 通用实施（GP）:提供了对基本实施的管理、监督和改进的框架。但同样不是直接用于测量能力成熟度的单位。 过程区域（PA）:过程区域是相关基本实施的集合,共同支持一个特定的安全工程目标或活动。但更多地是描述性的,而非测量性的。 公共特征（CF）:描述在实现某个过程区域时,组织需要满足的一系列共同属性或条件。在SSE-CMM模型中,公共特征是用于测量和评估组织安全工程能力成熟度的关键单位。","imageNames":[]},{"id":"wx2026-03-076","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"76","domain":"信息安全法规标准","stem":"下面关于信息系统安全保障模型的说法不正确的是:","options":["国家标准《信息系统安全保障评估框架第一部分:简介和一般模型》(GB／T20274.1-2006)中的信息系统安全保障模型将风险和策略作为基础和核心","模型中的信息系统生命周期模型是抽象的概念性说明模型,在信息系统安全保障具体操作时,可根据具体环境和要求进行改动和细化","信息系统安全保障强调的是动态持续性的长效安全,而不仅是某时间点下的安全","信息系统安全保障主要是确保信息系统的保密性、完整性和可用性,单位对信息系统运行维护和使用的人员在能力和培训方面不需要投入"],"correctIndex":3,"explanation":"单位对信息系统运行维护和使用的人员在能力和培训方面需要投入。","imageNames":[]},{"id":"wx2026-03-077","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"77","domain":"信息安全法规标准","stem":"信息系统安全工程(ISSE)的一个重要目标就是在IT项目的各个阶段充分考虑安全因素,在IT项目的立项阶段,以下哪一项不是必须进行的工作:","options":["明确业务对信息安全的要求","识别来自法律法规的安全要求","论证安全要求是否正确完整","通过测试证明系统的功能和性能可以满足安全要求"],"correctIndex":3,"explanation":"D属于项目的验收阶段,不属于IT项目的立项阶段,题干属于立项阶段。","imageNames":[]},{"id":"wx2026-03-078","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"78","domain":"信息安全技术","stem":"关于信息安全保障技术框架(IATF),以下说法不正确的是:","options":["分层策略允许在适当的时候采用低安全级保障解决方案以便降低信息安全保障的成本","IATF从人、技术和操作三个层面提供一个框架实施多层保护,使攻击者即使攻破一层也无法破坏整个信息基础设施","允许在关键区域(例如区域边界)使用高安全级保障解决方案,确保系统安全性","IATF深度防御战略要求在网络体系结构各个可能位置实现所有信息安全保障机制"],"correctIndex":3,"explanation":"IATF是在网络的各位置实现所需的安全机制。","imageNames":[]},{"id":"wx2026-03-079","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"79","domain":"信息安全工程","stem":"某单位开发一个面向互联网提供服务的应用网站,该单位委托软件测评机构对软件进行了源代码分析,模糊测试等软件测试,在应用上线前,项目经理提出了还需要对应用网站进行一次渗透性测试,作为安全主管,你需要提出渗透性测试相比源代码测试,模糊测试的优势给领导做决策,以下哪条是渗透性的优势？","options":["渗透测试使用人工进行测试,不依赖软件,因此测试更准确","渗透测试是用软件代替人工的一种测试方法。因此测试效率更高","渗透测试以攻击者思维模拟真实攻击,能发现如配置错误等运行维护期产生的漏洞","渗透测试中必须要查看软件源代码,因此测试中发现的漏洞更多"],"correctIndex":2,"explanation":"渗透测试以攻击者思维模拟真实攻击,能发现如配置错误等运行维护期产生的漏洞。","imageNames":[]},{"id":"wx2026-03-080","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"80","domain":"信息安全工程","stem":"以下关于软件安全测试说法正确的是（）","options":["软件安全测试就是黑盒测试","FUZZ测试是经常采用的安全测试方法之一","软件安全测试关注的是软件的功能","软件安全测试可以发现软件中产生的所有安全问题"],"correctIndex":1,"explanation":"软件安全测试不只是黑盒测试,A选项错误；FUZZ测试是常用的安全测试方法之一,B选项正确；软件安全测试关注软件安全,不是功能,C选项错误；软件安全测试不能发现所有安全问题,D选项错误,所以选B。","imageNames":[]},{"id":"wx2026-03-081","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"81","domain":"信息安全工程","stem":"信息安全工程作为信息安全保障的重要组成部门,主要是为了解决:","options":["信息系统的技术架构安全问题","信息系统组成部门的组件安全问题","信息系统生命周期的过程安全问题","信息系统运行维护的安全管理问题"],"correctIndex":2,"explanation":"信息安全工程主要解决信息系统生命周期的过程安全问题。","imageNames":[]},{"id":"wx2026-03-082","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"82","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型（SSE-CMM)中基本实施（Base Practice）正确的理解是:","options":["BP不限定于特定的方法工具,不同业务背景中可以使用不同的方法","BP不是根据广泛的现有资料,实施和专家意见综合得出的","BP不代表信息安全工程领域的最佳实践","BP不是过程区域（Process Areas,PA )的强制项"],"correctIndex":0,"explanation":"BP属于安全工程的最小单元,其不限定于特定的方法工具,不同业务背景中可以使用不同的方法；是根据广泛的现有资料,实施和专家意见综合得出的；代表着信息安全工程领域的最佳实践；并且是过程区域（Process Areas,PA )的强制项。","imageNames":[]},{"id":"wx2026-03-083","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"83","domain":"信息安全管理","stem":"层次化的文档是信息安全管理体系《Information Security Management System.ISMS》建设的直接体系,也ISMS建设的成果之一,通常将ISMS的文档结构规划为4层金字塔结构,那么,以下选项（）应放入到一级文件中.","options":["《风险评估报告》","《人力资源安全管理规定》","《ISMS内部审核计划》","《单位信息安全方针》"],"correctIndex":3,"explanation":"正确答案为D。一级文件中一般为安全方针、策略文件；二级文件中一般为管理规范制度；三级文件一般为操作手册和流程；四级文件一般表单和管理记录。","imageNames":[]},{"id":"wx2026-03-084","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"84","domain":"信息安全管理","stem":"信息安全管理体系（information Security Management System.简称ISMS）的实施和运行ISMS 阶段,是ISMS过程模型的实施阶段（Do）,下面给出了一些备①制定风险处理计划②实施风险处理计划③开发有效性测量程序④实施培训和意识教育计划⑤管理ISMS的运行⑥管理ISMS的资源⑦执行检测事态和响应事件的程序⑧实施内部审核⑨实施风险再评估选的活动,选项（）描述了在此阶段组织应进行的活动。","options":["①②③④⑤⑥","①②③④⑤⑥⑦","①②③④⑤⑥⑦⑧","①②③④⑤⑥⑦⑧⑨"],"correctIndex":1,"explanation":"管理体系包括PDCA（Plan-Do-Check-Act）四个阶段,题干中1-7的工作都属于管理体系的实施阶段（D-Do）,而8和9属于检查阶段（C-Check）。","imageNames":[]},{"id":"wx2026-03-085","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"85","domain":"信息安全管理","stem":"在实施信息安全风险评估时,需要对资产的价值进行识别、分类和赋值,关于资产价值的评估,以下选项中正确的是（）","options":["资产的价值指采购费用","资产的价值指维护费用","资产的价值与其重要性密切相关","资产的价值无法估计"],"correctIndex":2,"explanation":"资产价值与其重要性密切相关,不是指采购费用或维护费用,且可以估计。","imageNames":[]},{"id":"wx2026-03-086","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"86","domain":"信息安全工程","stem":"某软件公司准备提高其开发软件的安全性,在公司内部发起了有关软件开发生命周期的讨论,在下面的发言观点中,正确的是（）","options":["软件安全开发生命周期较长,而其中最重要的是要在软件的编码安全措施,就可以解决90%以上的安全问题。","应当尽早在软件开发的需求和设计阶段增加一定的安全措施,这样可以比在软件发布以后进行漏洞修复所花的代价少得多。","和传统的软件开发阶段相比,微软提出的安全开发生命周期（SDL)最大特点是增加了一个专门的安全编码阶段。","软件的安全测试也很重要,考试到程序员的专业性,如果该开发人员已经对软件进行了安全性测试,就没有必要再组织第三方进行安全性测试。"],"correctIndex":1,"explanation":"答案为B。A-现代软件工程体系中软件最重要的阶段为设计阶段。C-SDL最大的特点是增加了安全培训和应急响应。D-第三方测试是必要的软件安全测试类型。","imageNames":[]},{"id":"wx2026-03-087","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"87","domain":"信息安全工程","stem":"某网站在设计对经过了威胁建模和攻击面分析,在开发时要求程序员编写安全的代码,但是在部署时由于管理员将备份存放在WEB目录下导致了攻击者可直接下载备份,为了发现系统中是否存在其他类拟问题,一下那种测试方式是最佳的测试方法。","options":["模糊测试","源代码测试","渗透测试","软件功能测试"],"correctIndex":2,"explanation":"渗透测试可以发现系统中类似管理员将备份存放在WEB目录下导致可直接下载备份的问题,模糊测试、源代码测试、软件功能测试不能很好地发现此类问题。","imageNames":[]},{"id":"wx2026-03-088","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"88","domain":"信息安全工程","stem":"下面哪项属于软件开发安全方面的问题（）","options":["软件部署时所需选用服务性能不高,导致软件执行效率低。","应用软件来考虑多线程技术,在对用户服务时按序排队提供服务","应用软件存在SQL注入漏洞,若被黑客利用能窃取数据库所用数据","软件受许可证（license）限制,不能在多台电脑上安装。"],"correctIndex":2,"explanation":"ABD与软件安全开发无关。","imageNames":[]},{"id":"wx2026-03-089","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"89","domain":"信息安全工程","stem":"为增强Web应用程序的安全性,某软件开发经理决定加强Web软件安全开发培训,下面哪项内容不在考虑范围内（）","options":["关于网站身份签别技术方面安全知识的培训","针对OpenSSL心脏出血漏洞方面安全知识的培训","针对SQL注入漏洞的安全编程培训","关于ARM系统漏洞挖掘方面安全知识的培训"],"correctIndex":3,"explanation":"D属于ARM系统,不属于WEB安全领域。","imageNames":[]},{"id":"wx2026-03-090","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"90","domain":"信息安全技术","stem":"以下关于https协议http协议相比的优势说明,那个是正确的:","options":["Https协议对传输的数据进行加密,可以避免嗅探等攻击行为","Https使用的端口http不同,让攻击者不容易找到端口,具有较高的安全性","Https协议是http协议的补充,不能独立运行,因此需要更高的系统性能","Https协议使用了挑战机制,在会话过程中不传输用户名和密码,因此具有较高的"],"correctIndex":0,"explanation":"HTTPS具有数据加密机制。","imageNames":[]},{"id":"wx2026-03-091","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"91","domain":"信息安全管理","stem":"不同的信息安全风险评估方法可能得到不同的风险评估结果,所以组织机构应当根据各自的实际情况选择适当的风险评估方法。下面的描述中错误的是（）。","options":["定量风险分析试图从财务数字上对安全风险进行评估,得出可以量化的风险分析结果,以度量风险的可能性和缺失量","定量风险分析相比定性风险分析能得到准确的数值,所以在实际工作中应使用定量风险分析,而不应选择定性风险分析","定性风险分析过程中,往往需要凭借分析者的经验和直接进行,所以分析结果和风险评估团队的素质、经验和知识技能密切相关","定性风险分析更具主观性,而定量风险分析更具客观性"],"correctIndex":1,"explanation":"实际工作中根据情况选择定量、定性或定量与定性相结合。","imageNames":[]},{"id":"wx2026-03-092","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"92","domain":"信息安全管理","stem":"小李去参加单位组织的信息安全管理体系（Information Security Management System.ISMS）的理解画了一下一张图(图中包括了规划建立、实施运行、保持和改进),但是他还存在一个空白处未填写,请帮他选择一个最合适的选项（）。","options":["监控和反馈ISMS","批准和监督ISMS","监视和评审ISMS","沟通和咨询ISMS"],"correctIndex":2,"explanation":"管理体系PDCA分别指的阶段是:P-规划建立、D-实施运行、C-监视和评审、A-保持和改进。","imageNames":[]},{"id":"wx2026-03-093","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"93","domain":"信息安全法规标准","stem":"为推动和规范我国信息安全等级保护工作,我国制定和发布了信息安全等级保护工作所需要的一系列标准,这些标准可以按照等级保护工作的工作阶段大致分类。下面四个标准中,（）规定了等级保护定级阶段的依据、对象、流程、方法及等级变更等内容。","options":["GB／T 20271-2006《信息系统通用安全技术要求》","GB／T 22240-2008《信息系统安全保护等级定级指南》","GB／T 25070-2010《信息系统等级保护安全设计技术要求》","GB／T 20269-2006《信息系统安全管理要求》"],"correctIndex":1,"explanation":"GB／T 22240 - 2008《信息系统安全保护等级定级指南》规定了等级保护定级阶段的依据等内容。","imageNames":[]},{"id":"wx2026-03-094","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"94","domain":"信息安全保障","stem":"某移动智能终端支持通过指纹识别解锁系统的功能,与传统的基于口令的鉴别技术相比,关于此种鉴别技术说法不正确的是:","options":["所选择的特征（指纹）便于收集、测量和比较","每个人所拥有的指纹都是独一无二的","指纹信息是每个人独有的,指纹识别系统不存在安全威胁问题","此类系统一般由用户指纹信息采集和指纹信息识别两部分组成"],"correctIndex":2,"explanation":"指纹识别系统存在安全威胁问题,同时存在着错误拒绝率和错误接受率的问题。","imageNames":[]},{"id":"wx2026-03-095","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"95","domain":"信息安全法规标准","stem":"下列我国哪一个政策性文件明确了我国信息安全保障工作的方针和总体要求以及加强信息安全工作的主要原则？","options":["《关于加强政府信息系统安全和保密管理工作的通知》","《中华人民共和国计算机信息系统安全保护条例》","《国家信息化领导小组关于加强信息安全保障工作的意见》","《关于开展信息安全风险评估工作的意见》"],"correctIndex":2,"explanation":"《国家信息化领导小组关于加强信息安全保障工作的意见》（中办2003年27号文件）规定了信息安全工作的原则,例如立足国情、以我为主、坚持技管并重等。","imageNames":[]},{"id":"wx2026-03-096","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"96","domain":"信息安全法规标准","stem":"在以下标准中,属于推荐性国家标准的是？","options":["GB/T XXXX.X-200X","GB XXXX-200X","DBXX/T XXX-200X","GB/Z XXX-XXX-200X"],"correctIndex":0,"explanation":"A为国标推荐标准；B为国标强制标准；C为地方标准；D为国标指导标准。","imageNames":[]},{"id":"wx2026-03-097","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"97","domain":"信息安全工程","stem":"微软SDL将软件开发生命周期制分为七个阶段,并列出了十七项重要的安全活动。其中“弃用不安全的函数”属于（）的安全活动","options":["要求阶段","设计阶段","实施阶段","验证阶段"],"correctIndex":2,"explanation":"弃用不安全的函数为编码实施阶段。","imageNames":[]},{"id":"wx2026-03-098","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"98","domain":"信息安全工程","stem":"由于频繁出现计算机运行时被黑客远程攻击获取数据的现象,某软件公司准备加强软件安全开发管理,在下面做法中,对于解决问题没有直接帮助的是（）","options":["要求所有的开发人员参加软件安全开发知识培训","要求增加软件源代码审核环节,加强对软件代码的安全性审查","要求统一采用Windows8系统进行开发,不能采用之前的Windows 版本","要求邀请专业队伍进行第三方安全性测试,尽量从多角度发现软件安全问题"],"correctIndex":2,"explanation":"统一采用Windows8系统对软件安全无帮助。","imageNames":[]},{"id":"wx2026-03-099","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"99","domain":"信息安全工程","stem":"关于源代码审核,描述正确的是（）","options":["源代码审核过程遵循信息安全保障技术框架模型(IATF),在执行时应一步一步严格执行","源代码审核有利于发现软件编码中存在的安全问题,相关的审核工具既有商业开源工具","源代码审核如果想要有效率高,则主要依赖人工审核而不是工具审核,因为人工智能的,需要人的脑袋来判断","源代码审核能起到很好的安全保证作用,如果执行了源代码审核,则不需要安全测试"],"correctIndex":1,"explanation":"A错误,因为IATF不用于代码审核；C错误,因为人工和攻击相结合；D错误,安全测试由需求确定。","imageNames":[]},{"id":"wx2026-03-100","setId":"wx2026-03","setName":"CISP 复习题（1）","sourceNumber":"100","domain":"信息安全管理","stem":"微软提出了STRIDE模型,其中R是Repudiation(抵赖)的缩写,此项错误的是（）","options":["某用户在登录系统并下载数据后,却声称“我没有下载过数据\"软件R 威胁","某用户在网络通信中传输完数据后,却声称“这些数据不是我传输的”威胁也属于R威胁。","对于R威胁,可以选择使用如强认证、数字签名、安全审计等技术","对于R威胁,可以选择使用如隐私保护、过滤、流量控制等技术"],"correctIndex":3,"explanation":"R-抵赖是无法通过过滤、流控和隐私保护实现的,R-抵赖的实现方式包括数字签名、安全审计、第三方公证。","imageNames":[]}]},{"id":"wx2026-04","name":"CISP 复习题（2）","subtitle":"原卷顺序 · 有答案+解析","sourceFile":"CISP复习题（2）100题（有答案）-已审+解析.docx","questionCount":99,"questions":[{"id":"wx2026-04-001","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"1","domain":"信息安全法规标准","stem":"我国信息安全保障工作先后经历启动、逐步展开和积极推进,以及深化落实三个阶段,以下关于我国信息安全保障各阶段说法不正确的是:","options":["2001国家信息化领导小组重组,网络与信息安全协调小组成立,我国信息安全保障工作正式启动","2003年7月,国家信息化领导小组制定出台了《关于加强信息安全保障工作的意见》（中办发27号文）,明确了“积极防御、综合防范“的国家信息安全保障方针","2003年中办发27号文件的发布标志着我国信息安全保障进入深化落实阶段","在深化落实阶段,信息安全法律法规、标准化,信息安全基础设施建设,以及信息安全等级保护和风险评估取得了新进展。"],"correctIndex":2,"explanation":"2006年进入到深化落实阶段。选项A,2001年国家信息化领导小组重组及网络与信息安全协调小组成立,确实标志着我国信息安全保障工作正式启动；选项B,2003年7月国家信息化领导小组制定出台的《关于加强信息安全保障工作的意见》（中办发27号文）,明确提出“积极防御、综合防范”的国家信息安全保障方针；选项D,在深化落实阶段,信息安全法律法规、标准化、信息安全基础设施建设以及信息安全等级保护和风险评估确实取得了新进展。","imageNames":[]},{"id":"wx2026-04-002","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"2","domain":"信息安全技术","stem":"金女士经常通过计算机在互联网上购物,从安全角度看,下面哪项是不好的习惯:","options":["使用专用上网购物用计算机,安装好软件后不要对该计算机上的系统软件,应用软件进行升级","为计算机安装具有良好声誉的安全防护软件,包括病毒查杀,安全检查和安全加固方面的软件","在IE的配置中,设置只能下载和安装经过签名的,安全的ActiveX控件","在使用网络浏览器时,设置不在计算机中保留网络历史纪录和表单数据"],"correctIndex":0,"explanation":"使用专用上网购物计算机是好的习惯,但安装好软件后不进行系统软件和应用软件的升级是错误的。软件升级通常包含安全补丁,能修复已知漏洞,提高系统安全性。B选项,为计算机安装具有良好声誉的安全防护软件,包括病毒查杀、安全检查和安全加固方面的软件,能有效防范安全威胁；C选项,在IE的配置中设置只能下载和安装经过签名的、安全的ActiveX控件,可防止恶意控件的安装；D选项,在使用网络浏览器时设置不在计算机中保留网络历史纪录和表单数据,能减少个人信息泄露的风险。","imageNames":[]},{"id":"wx2026-04-003","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"3","domain":"信息安全管理","stem":"我国信息安全保障建设包括信息安全组织与管理体制、基础设施、技术体系等方面,以下关于安全保障建设主要工作内容说法不正确的是:","options":["建全国家信息安全组织与管理体制机制,加强信息安全工作的组织保障","建设信息安全基础设施,提供国家信息安全保障能力支撑","建立信息安全技术体系,实现国家信息化发展的自主创新","建立信息安全人才培养体系,加快信息安全学科建设和信息安全人才培养"],"correctIndex":2,"explanation":"建立信息安全技术体系的目的是保障国家信息化的安全,而非实现自主创新。","imageNames":[]},{"id":"wx2026-04-004","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"4","domain":"信息安全法规标准","stem":"某银行信息系统为了满足业务的需要准备进行升级改造,以下哪一项不是此次改造中信息系统安全需求分析过程需要考虑的主要因素","options":["信息系统安全必须遵循的相关法律法规,国家以及金融行业安全标准","信息系统所承载该银行业务正常运行的安全需求","消除或降低该银行信息系统面临的所有安全风险","该银行整体安全策略"],"correctIndex":2,"explanation":"无法消除或降低该银行信息系统面临的所有安全风险。","imageNames":[]},{"id":"wx2026-04-005","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"5","domain":"信息安全法规标准","stem":"信息安全测评是指依据相关标准,从安全功能等角度对信息技术产品、信息系统、服务提供商以及人员进行测试和评估,以下关于信息安全测评说法不正确的是:","options":["信息产品安全评估是测评机构的产品的安全性做出的独立评价,增强用户对已评估产品安全的信任","目前我国常见的信息系统安全测评包括信息系统风险评估和信息系统安全保障测评两种类型","信息安全工程能力评估是对信息安全服务提供者的资格状况、技术实力和实施服务过程质量保证能力的具体衡量和评价。","信息系统风险评估是系统地分析网络与信息系统所面临的威胁及其存在的脆弱性,评估安全事件可能造成的危害程度,提出游针对性的安全防护策略和整改措施"],"correctIndex":1,"explanation":"测评包括信息系统风险评估和信息系统等级保护测评。","imageNames":[]},{"id":"wx2026-04-006","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"6","domain":"信息安全保障","stem":"美国的关键信息基础设施（Critical Information Infrastructure,CII）包括商用核设施、政策设施、交通系统、饮用水和废水处理系统、公共健康和医疗、能源、银行和金融、国防工业基地等等,美国政府强调重点保障这些基础设施信息安全,其主要原因不包括:","options":["这些行业都关系到国计民生,对经济运行和国家安全影响深远","这些行业都是信息化应用广泛的领域","这些行业信息系统普遍存在安全隐患,而且信息安全专业人才缺乏的现象比其他行业更突出","这些行业发生信息安全事件,会造成广泛而严重的损失。"],"correctIndex":2,"explanation":"美国政府强调重点保障关键信息基础设施信息安全的主要原因并非这些行业信息系统普遍存在安全隐患且信息安全专业人才缺乏的现象比其他行业更突出。虽然这些行业可能存在安全隐患和人才问题,但这不是美国政府强调保障其信息安全的主要原因。","imageNames":[]},{"id":"wx2026-04-007","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"7","domain":"信息安全法规标准","stem":"在设计信息系统安全保障方案时,以下哪个做法是错误的:","options":["要充分切合信息安全需求并且实际可行","要充分考虑成本效益,在满足合规性要求和风险处置要求的前提下,尽量控制成本","要充分采取新技术,使用过程中不断完善成熟,精益求精,实现技术投入保值要求","要充分考虑用户管理和文化的可接受性,减少系统方案障碍"],"correctIndex":2,"explanation":"设计信息系统安全保障方案应采用合适的技术。","imageNames":[]},{"id":"wx2026-04-008","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"8","domain":"信息安全技术","stem":"分组密码算法是一类十分重要的密码算法,下面描述中,错误的是（）","options":["分组密码算法要求输入明文按组分成固定长度的块","分组密码的算法每次计算得到固定长度的密文输出块","分组密码算法也称作序列密码算法","常见的DES、IDEA算法都属于分组密码算法"],"correctIndex":2,"explanation":"分组密码算法和序列密码算法是两类不同的密码算法。","imageNames":[]},{"id":"wx2026-04-009","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"9","domain":"信息安全技术","stem":"密码学是网络安全的基础,但网络安全不能单纯依靠安全的密码算法、密码协议也是网络安全的一个重要组成部分。下面描述中,错误的是（）","options":["在实际应用中,密码协议应按照灵活性好、可扩展性高的方式制定,不要限制和框住的执行步骤,有些复杂的步骤可以不明确处理方式。","密码协议定义了两方或多方之间为完成某项任务而指定的一系列步骤,协议中的每个参与方都必须了解协议,且按步骤执行。","根据密码协议应用目的的不同,参与该协议的双方可能是朋友和完全信息的人,也可能是敌人和互相完全不信任的人。","密码协议(Crypto graphic protocol) ,有时也称安全协议(security protocol), 是使用密码学完成某项特定的任务并满足安全需求的协议,其末的是提供安全服务。"],"correctIndex":0,"explanation":"密码协议应限制和框住的执行步骤,有些复杂的步骤必须要明确处理方式。","imageNames":[]},{"id":"wx2026-04-010","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"10","domain":"信息安全技术","stem":"部署互联网协议安全虚拟专用网（Internet protocol Security Virtual Private Network,IPsec VPN）时,以下说法正确的是:","options":["配置MD5安全算法可以提供可靠的数据加密","配置AES算法可以提供可靠的数据完整性验证","部署IPsec VPN 网络时,需要考虑IP 地址的规划,尽量在分支节点使用可以聚合的IP地址段,来减少IPsec安全关联（Security Authentication,SA ）资源的消耗","报文验证头协议（Authentication Header,AH）可以提供数据机密性"],"correctIndex":2,"explanation":"A错误,MD5提供完整性；B错误,AES提供的保密性；D错误,AH协议提供完整性、验证及抗重放攻击。","imageNames":[]},{"id":"wx2026-04-011","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"11","domain":"信息安全管理","stem":"虚拟专用网络（VPN）通常是指在公共网路中利用隧道技术,建立一个临时的,安全的网络。这里的字母P的正确解释是（）","options":["Special-purpose. 特定、专用用途的","Proprietary 专有的、专卖的","Private 私有的、专有的","Specific 特种的、具体的"],"correctIndex":2,"explanation":"虚拟专用网络（VPN）中的“P”代表“Private”,即私有的、专有的。VPN通过隧道技术在公共网络中建立一个临时的、安全的网络,为用户提供私有的网络连接。","imageNames":[]},{"id":"wx2026-04-012","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"12","domain":"信息安全管理","stem":"以下Windows系统的账号存储管理机制SAM（Security Accounts Manager）的说法哪个是正确的:","options":["存储在注册表中的账号数据是管理员组用户都可以访问,具有较高的安全性","存储在注册表中的账号数据administrator账户才有权访问,具有较高的安全性","存储在注册表中的账号数据任何用户都可以直接访问,灵活方便","存储在注册表中的账号数据只有System账号才能访问,具有较高的安全性"],"correctIndex":3,"explanation":"存储在注册表中的账号数据只有System账号才能访问,具有较高的安全性。这样可以防止其他用户随意访问和修改账号数据,保障账号信息的安全。","imageNames":[]},{"id":"wx2026-04-013","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"13","domain":"信息安全管理","stem":"某公司的对外公开网站主页经常被黑客攻击后修改主页内容,该公司应当购买并部署下面哪个设备（）","options":["安全路由器","网络审计系统","网页防篡改系统","虚拟专用网（Virtual Private Network,VPN）系统"],"correctIndex":2,"explanation":"网页防篡改系统可以实时监测和恢复被篡改的网页内容,有效防止黑客对网站主页的修改。","imageNames":[]},{"id":"wx2026-04-014","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"14","domain":"信息安全技术","stem":"关于恶意代码,以下说法错误的是:","options":["从传播范围来看,恶意代码呈现多平台传播的特征。","按照运行平台,恶意代码可以分为网络传播型病毒、文件传播型病毒。","不感染的依附性恶意代码无法单独执行","为了对目标系统实施攻击和破坏,传播途径是恶意代码赖以生存和繁殖的基本条件"],"correctIndex":1,"explanation":"按照运行平台,恶意代码可以分为Windows平台、Linux平台、工业控制系统等。","imageNames":[]},{"id":"wx2026-04-015","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"15","domain":"信息安全技术","stem":"某单位对其主网站的一天访问流量监测图,图显示该网站在当天17:00到20:00间受到了攻击,则从数据分析,这种攻击类型最可能属于下面什么攻击（）。","options":["跨站脚本（Cross Site Scripting,XSS）攻击","TCP会话劫持（TCP Hijack）攻击","IP 欺骗攻击","拒绝服务（Denial of Service,DoS）攻击"],"correctIndex":3,"explanation":"从流量监测图显示该网站在当天17:00到20:00间受到攻击,这种在特定时间段内对网站进行大量访问,导致网站无法正常响应的攻击最可能是拒绝服务（DoS）攻击。","imageNames":[]},{"id":"wx2026-04-016","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"16","domain":"信息安全工程","stem":"当前,应用软件安全已经日益引起人们的重视,每年新发现的应用软件漏洞已经占新发现漏洞总数一半以上。下列选项中,哪个与应用软件漏洞成因无关:","options":["传统的软件开发工程未能充分考虑安全因素","开发人员对信息安全知识掌握不足","相比操作系统而言,应用软件编码所采用的高级语言更容易出现漏洞","应用软件的功能越来越多,软件越来越复杂,更容易出现漏洞"],"correctIndex":2,"explanation":"应用软件编码所采用的高级语言与漏洞的产生没有直接关系。漏洞的产生主要是由于传统的软件开发工程未能充分考虑安全因素、开发人员对信息安全知识掌握不足以及应用软件功能越来越多、软件越来越复杂等原因。","imageNames":[]},{"id":"wx2026-04-017","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"17","domain":"信息安全工程","stem":"下面哪个模型和软件安全开发无关（）？","options":["微软提出的“安全开发生命周期（Security Development Lifecycle,SDL）”","Gray McGraw等提出的“使安全成为软件开发必须的部分（Building Security IN,BSI） ”","OWASP维护的“软件保证成熟度模型（Software Assurance Maturity Mode,SAMM）”","“信息安全保障技术框架（Information Assurance Technical Framework,IATF）”"],"correctIndex":3,"explanation":"“信息安全保障技术框架（IATF）”主要侧重于信息安全保障的整体技术框架,与软件安全开发过程关联不大。而微软提出的“安全开发生命周期（SDL）”、Gray McGraw等提出的“使安全成为软件开发必须的部分（BSI）”和OWASP维护的“软件保证成熟度模型（SAMM）”都与软件安全开发密切相关。A选项,SDL是微软提出的软件安全开发模型；B选项,BSI强调将安全融入软件开发过程；C选项,SAMM用于评估和改进软件安全开发能力。","imageNames":[]},{"id":"wx2026-04-018","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"18","domain":"信息安全工程","stem":"某单位门户网站开发完成后,测试人员使用模糊测试进行安全性测试,以下关于模糊测试过程的说法正确的是:","options":["模拟正常用户输入行为,生成大量数据包作为测试用例","数据处理点、数据通道的入口点和可信边界点往往不是测试对象","监测和记录输入数据后程序正常运行的情况","深入分析测试过程中产生崩溃或异常的原因,必要时需要测试人员手工重现并分析"],"correctIndex":3,"explanation":"在模糊测试过程中,深入分析测试过程中产生崩溃或异常的原因非常重要,必要时需要测试人员手工重现并分析,以确定是否存在安全漏洞。A错误,模糊测试是模拟异常输入；B错误,入口与边界点是测试对象；C模糊测试记录和检测异常运行情况。","imageNames":[]},{"id":"wx2026-04-019","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"19","domain":"信息安全工程","stem":"以下关于模糊测试过程的说法正确的是:","options":["模糊测试的效果与覆盖能力,与输入样本选择不相关","为保障安全测试的效果和自动化过程,关键是将发现的异常进行现场保护记录,系统可能无法恢复异常状态进行后续的测试","通过异常样本重现异常,人工分析异常原因,判断是否为潜在的安全漏洞,如果是安全漏洞,就需要进一步分析其危害性、影响范围和修复建议","对于可能产生的大量异常报告,需要人工全部分析异常报告"],"correctIndex":2,"explanation":"模糊测试的效果与覆盖能力与输入样本选择密切相关,需要通过合理选择输入样本来提高测试的覆盖率和效果；为保障安全测试的效果和自动化过程,需要现场保护记录发现的异常,并在系统恢复异常状态后进行后续测试；对于可能产生的大量异常报告,不需要人工全部分析,可以通过自动化的工具和方法对异常报告进行筛选和分类,优先处理可能存在安全漏洞的报告。A选项,输入样本选择对模糊测试效果影响很大；B选项,系统应能在恢复异常状态后进行后续测试；D选项,不需要人工全部分析异常报告。","imageNames":[]},{"id":"wx2026-04-020","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"20","domain":"信息安全法规标准","stem":"关于WI-FI 联盟提出的安全协议WPA和WPA2的区别。下面描述正确的是（）","options":["WPA是有线局域安全协议,而WPA2 是无线局域网协议","WPA是适用于中国的无线局域安全协议,WPA2是使用于全世界的无线局域网协议","WPA没有使用密码算法对接入进行认证,而WPA2使用了密码算法对接入进行认证","WPA是依照802.11i 标准草案制定的,而WPA2是按照802.11i 正式标准制定的"],"correctIndex":3,"explanation":"WPA是依照802.11i标准草案制定的,而WPA2是按照802.11i正式标准制定的。A选项,WPA和WPA2都是无线局域网安全协议；B选项,WPA和WPA2都是全球通用的无线局域网安全协议；C选项,WPA和WPA2都使用了密码算法对接入进行认证。","imageNames":[]},{"id":"wx2026-04-021","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"21","domain":"信息安全技术","stem":"防火墙是网络信息系统建设中常常采用的一类产品,它在内外网隔离方面的作用是","options":["既能物理隔离,又能逻辑隔离","能物理隔离,但不能逻辑隔离","不能物理隔离,但是能逻辑隔离","不能物理隔离,也不能逻辑隔离"],"correctIndex":2,"explanation":"防火墙不能进行物理隔离,但可以通过逻辑隔离的方式,根据预设的规则对网络流量进行过滤和控制,实现内外网的隔离。A选项,防火墙不能进行物理隔离；B选项,防火墙能进行逻辑隔离；D选项,防火墙能进行逻辑隔离。","imageNames":[]},{"id":"wx2026-04-022","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"22","domain":"信息安全管理","stem":"异常入侵检测是入侵检测系统常用的一种技术,它是识别系统或用户的非正常行为或者对于计算机资源的非正常使用,从而检测出入侵行为。下面说法错误的是","options":["在异常入侵检测中,观察的不是已知的入侵行为,而是系统运行过程中的异常现象","实施异常入侵检测,是将当前获取行为数据和已知入侵攻击行为特征相比较,若匹配则认为有攻击发生","异常入侵检测可以通过获得的网络运行状态数据,判断其中是否含有攻击的企图,并通过多种手段向管理员报警","异常入侵检测不但可以发现从外部的攻击,也可以发现内部的恶意行为"],"correctIndex":1,"explanation":"实施误用入侵检测（或特征检测）,是将当前获取行为数据和已知入侵攻击行为特征相比较,若匹配则认为有攻击发生。","imageNames":[]},{"id":"wx2026-04-023","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"23","domain":"信息安全技术","stem":"S公司在全国有20个分支机构,总部由10台服务器、200个用户终端,每个分支机构都有一台服务器、100个左右用户终端,通过专网进行互联互通。公司招标的网络设计方案中,四家集成商给出了各自的IP地址规划和分配的方法,作为评标专家,请给5公司选出设计最合理的一个:","options":["总部使用服务器、用户终端统一使用10.0.1.x、各分支机构服务器和用户终端使用192.168.2.x---192.168.20.x","总部服务器使用10.0.1.1—11、用户终端使用10.0.1.12—212 ,分支机构IP地址随意确定即可","总部服务器使用10.0.1.x 、用户端根据部门划分使用10.0.2.x ,每个分支机构分配两个A类地址段,一个用做服务器地址段、另外一个做用户终端地址段","因为通过互联网连接,访问的是互联网地址,内部地址经NAT映射,因此IP地址无需特别规划,各机构自行决定即可。"],"correctIndex":2,"explanation":"选项A:总部服务器和用户终端未分开地址段,管理混乱；分支机构使用私有C类地址（192.168.x.x）,但未明确子网划分,20个分支机构需20个独立子网,但选项未说明是否合理分配子网掩码（如/24）,可能导致地址浪费或不足。选项B:总部地址分配紧凑,但分支机构地址随意分配会导致冲突风险；缺乏统一规划,专网环境下路由难以管理。选项C:服务器和用户终端分开地址段,便于管理；按部门划分用户终端（10.0.2.x）支持进一步子网细分。分支机构:分配两个A类地址段（如10.1.x.x和10.2.x.x）,每个段可容纳大量主机,虽浪费但满足100个终端需求,且专网环境下地址空间充足；独立地址段便于路由和访问控制。选项D:专网互联需直接使用内部IP通信,NAT用于互联网访问,不能替代内部地址规划；随意分配会导致地址冲突和路由混乱。","imageNames":[]},{"id":"wx2026-04-024","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"24","domain":"信息安全技术","stem":"私有IP地址是一段保留的IP地址。只适用在局域网中,无法在Internet上使用。关于私有地址,下面描述正确的是（）。","options":["A类和B类地址中没有私有地址,C类地址中可以设置私有地址","A类地址中没有私有地址,B类 和C 类地址中可以设置私有地址","A类、B类和C类地址中都可以设置私有地址","A类、B类和C类地址中都没有私有地址"],"correctIndex":2,"explanation":"A类、B类和C类地址中都可以设置私有地址。A类私有地址范围是10.0.0.0 - 10.255.255.255；B类私有地址范围是172.16.0.0 - 172.31.255.255；C类私有地址范围是192.168.0.0 - 192.168.255.255。","imageNames":[]},{"id":"wx2026-04-025","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"25","domain":"信息安全管理","stem":"口令破解是针对系统进行攻击的常用方法,windows系统安全策略中应对口令破解的策略主要是帐户策略中的帐户锁定策略和密码策略,关于这两个策略说明错误的是","options":["密码策略主要作用是通过策略避免拥护生成弱口令及对用户的口令使用进行管控","密码策略对系统中所有的用户都有效","账户锁定策略的主要作用是应对口令暴力破解攻击,能有效地保护所有系统用户应对口令暴力破解攻击","账户锁定策略只适用于普通用户,无法保护管理员administrator 账户应对口令暴力破解攻击"],"correctIndex":2,"explanation":"不是所有用户。账户锁定策略只适用于普通用户,但是对于administrator它是不生效的,所以暴力破解很多的时候,administrator很容易被爆破。","imageNames":[]},{"id":"wx2026-04-026","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"26","domain":"信息安全管理","stem":"windows文件系统权限管理使用访问控制列表（Access Control List.ACL）机制,以下哪个说法是错误的:","options":["安装Windows系统时要确保文件格式适用的是NTFS. 因为Windows的ACL机制需要NTFS文件格式的支持","由于Windows 操作系统自身有大量文件和目录,因此很难对每个文件和目录设置严格的访问权限,为了使用上的便利,Windows上的ACL存在默认设置安全性不高的问题","Windows的ACL机制中,文件和文件夹的权限是主体进行关联的,即文件夹和文件的访问权限信息是写在用户数据库中的","由于ACL 具有很好灵活性,在实际使用中可以为每一个文件设定独立拥护的权限"],"correctIndex":2,"explanation":"Windows的ACL机制中,文件和文件夹的权限是客体关联的,即文件夹和文件的访问权限信息是写在客体文件和文件夹属性数据库中。","imageNames":[]},{"id":"wx2026-04-027","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"27","domain":"信息安全管理","stem":"由于发生了一起针对服务器的口令暴力破解攻击,管理员决定对设置帐户锁定策略以对抗口令暴力破解。他设置了以下账户锁定策略如下: 账户锁定阀值3次无效登陆； 账户锁定时间10分钟； 复位账户锁定计数器5分钟； 以下关于以上策略设置后的说法哪个是正确的","options":["设置账户锁定策略后,攻击者无法再进行口令暴力破解,所有输错的密码的拥护就会被锁住","如果正常用户部小心输错了3次密码,那么该账户就会被锁定10分钟,10分钟内即使输入正确的密码,也无法登录系统","如果正常用户不小心连续输入错误密码3次,那么该拥护帐号被锁定5分钟,5分钟内即使交了正确的密码,也无法登录系统","攻击者在进行口令破解时,只要连续输错3次密码,该账户就被锁定10分钟,而正常拥护登陆不受影响"],"correctIndex":1,"explanation":"答案为B,全部解释为5分钟计数器时间内错误3次则锁定10分钟。","imageNames":[]},{"id":"wx2026-04-028","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"28","domain":"信息安全技术","stem":"加密文件系统（Encrypting File System, EFS）是Windows操作系统的一个组件,以下说法错误的是（）","options":["EFS采用加密算法实现透明的文件加密和解密,任何不拥有合适密钥的个人或者程序都不能解密数据","EFS 以公钥加密为基础,并利用了widows系统中的CryptoAPI 体系结构","EFS加密系统适用于NTFS文件系统合FAT32文件系统（Windows环境下）","EFS加密过程对用户透明,EFS加密的用户验证过程是在登陆windows 时进行的"],"correctIndex":2,"explanation":"答案为C,FAT32不支持EFS加密。","imageNames":[]},{"id":"wx2026-04-029","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"29","domain":"信息安全管理","stem":"关于数据库恢复技术,下列说法不正确的是:","options":["数据库恢复技术的实现主要依靠各种数据的冗余和恢复机制技术来解决,当数据库中数据被破坏时,可以利用冗余数据来进行修复","数据库管理员定期地将整个数据库或部分数据库文件备份到磁带或另一个磁盘上保存起来,是数据库恢复中采用的基本技术","日志文件在数据库恢复中起着非常重要的作用,可以用来进行事务故障恢复和系统故障恢复,并协助后备副本进行介质故障恢复","计算机系统发生故障导致数据未存储到固定存储器上,利用日志文件中故障发生前数据的循环,将数据库恢复到故障发生前的完整状态,这一对事务的操作称为提交"],"correctIndex":3,"explanation":"利用日志文件中故障发生前数据的循环,将数据库恢复到故障发生前的完整状态,这一对事务的操作称为回滚。","imageNames":[]},{"id":"wx2026-04-030","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"30","domain":"信息安全技术","stem":"数据库的安全很复杂,往往需要考虑多种安全策略,才可以更好地保护数据库的安全。以下关于数据库常用的安全策略理解不正确的是:","options":["最小特权原则,是让用户可以合法的存取或修改数据库的前提下,分配最小的特权,使得这些信息恰好能够完成用户的工作","最大共享策略,在保证数据库的完整性、保密性和可用性的前提下,最大程度地共享数据库中的信息","粒度最小的策略,将数据库中数据项进行划分,粒度越小,安全级别越高,在实际中需要选择最小粒度","按内容存取控制策略,不同权限的用户访问数据库的不同部分"],"correctIndex":2,"explanation":"选项A正确描述了最小特权原则的核心思想,即仅分配用户完成工作所需的最小权限,防止过度授权导致安全风险。选项B准确概括了最大共享策略的目标,即在保证数据库安全属性（完整性、保密性、可用性）的前提下,尽可能实现数据共享,避免过度限制导致数据库失去实用价值。选项C数据库安全中的粒度划分需根据实际需求权衡安全与效率,并非粒度越小越好。例如,对整表设置权限可能降低管理复杂度,但若过度细化到字段级则可能影响性能。因此,实际应选择合理适当的粒度。选项D正确描述了按内容存取控制策略,即根据数据内容动态分配用户权限,确保不同权限用户仅能访问其授权范围内的数据。","imageNames":[]},{"id":"wx2026-04-031","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"31","domain":"信息安全技术","stem":"数据在进行传输前,需要由协议自上而下对数据进行封装。TCP/IP协议中,数据封装的顺序是:","options":["传输层、网络接口层、互联网络层","传输层、互联网络层、网络接口层","互联网络层、传输层、网络接口层","互联网络层、网络接口层、传输层"],"correctIndex":1,"explanation":"TCP/IP协议中,数据封装的顺序是传输层、互联网络层、网络接口层。传输层将数据封装成段,互联网络层将段封装成包,网络接口层将包封装成帧进行传输。","imageNames":[]},{"id":"wx2026-04-032","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"32","domain":"信息安全管理","stem":"以下关于SMTP和POP3 协议的说法哪个是错误的","options":["SMTP和POP3协议是一种基于ASCII编码的请求/响应模式的协议","SMTP和POP3协议明文传输数据,因此存在数据泄露的可能","SMTP和POP3协议缺乏严格的用户认证,因此导致了垃圾邮件问题","SMTP和POP3协议由于协议简单,易用性更高,更容易实现远程管理邮件"],"correctIndex":3,"explanation":"选项D:协议简单性并非直接提升远程管理能力。POP3设计初衷是下载邮件到本地后删除服务器副本,不支持多设备同步或远程文件夹管理；远程管理邮件更依赖IMAP协议（支持服务器端邮件操作和同步）。因此,协议简单性与远程管理能力无直接因果关系。","imageNames":[]},{"id":"wx2026-04-033","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"33","domain":"信息安全管理","stem":"安全多用途互联网邮件扩展(Secure Multipurpose Internet Mail Extension, S/MIME )是指一种保障邮件安全的技术,下面描述错误的是（）","options":["S/MIME 采用了非对称密码学机制","S/MIME支持数字证书","S/MIME采用了邮件防火墙技术","S/MIME支持用户身份认证和邮件加密"],"correctIndex":2,"explanation":"S/MIME是邮件安全协议,不是防火墙技术。","imageNames":[]},{"id":"wx2026-04-034","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"34","domain":"信息安全保障","stem":"应用安全,一般是指保障应用程序使用过程和结果的安全。以下内容中不属于应用安全防护考虑的是（）","options":["身份鉴别,应用系统应对登陆的用户进行身份鉴别,只有通过验证的用户才能访问应用系统资源","安全标记,在应用系统层面对主体和客体进行标记,主体不能随意更改权限,增加访问","剩余信息保护,应用系统应加强硬盘、内存或缓冲区中剩余信息的保护,防止存储在硬盘、内存或缓冲区的信息被非授权的访问","机房与设施安全,保证应用系统处于有一个安全的环境条件,包括机房环境、机房安全等级、机房的建造和机房的装修等"],"correctIndex":3,"explanation":"机房与设施安全属于物理安全,不属于应用安全。","imageNames":[]},{"id":"wx2026-04-035","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"35","domain":"信息安全技术","stem":"Apache Http Server（简称Apache）是一个开放源码的web服务运行平台,在使用过程中,该软件默认会将自己的软件名和版本号发送给客户端。从安全角度出发,为隐藏这些信息,应当采取以下那种措施（）","options":["安装后,修改访问控制配置文件","安装后,修改配置文件Httpd.Conf中的有关参数","安装后,删除Apache Http Server源码","从正确的官方网站下载Apache Http Server,并安装使用"],"correctIndex":1,"explanation":"安装Apache Http Server后,修改配置文件Httpd.conf中的有关参数可以隐藏软件名和版本号等信息。A选项,修改访问控制配置文件不能隐藏软件信息；C选项,删除源码不现实且可能影响软件正常运行；D选项,从官方网站下载软件不能解决信息泄露问题。","imageNames":[]},{"id":"wx2026-04-036","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"36","domain":"信息安全工程","stem":"下面信息安全漏洞理解错误的是:","options":["讨论漏洞应该从生命周期的角度出发,信息产品和信息系统在需求、设计、实现、配置、维护和使用等阶段中均有可能产生漏洞","信息安全漏洞是由于信息产品和信息系统在需求、设计、开发、部署或维护阶段,由于设计、开发等相关人员无意中产生的缺陷所造成的","信息安全漏洞如果被恶意攻击者成功利用,可能会给信息产品和信息系统带来安全损害,甚至带来很大的经济损失","由于人类思维能力、计算机计算能力的局限性等因素,所以在信息产品和信息系统中产生新的漏洞是不可避免的"],"correctIndex":1,"explanation":"信息安全漏洞不仅可能是由于相关人员无意中产生的缺陷造成的,也可能是恶意攻击者故意留下的后门等。","imageNames":[]},{"id":"wx2026-04-037","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"37","domain":"信息安全技术","stem":"下面对“零日（ｚｅｒｏ－ｄａｙ）漏洞”的理解中,正确的是（）","options":["指一个特定的漏洞,该漏洞每年１月１日零点发作,可以被攻击者用来远程攻击,获取主机权限","指一个特定的漏洞,特指在2010年被发现出来的一种漏洞,该漏洞被“震网”病毒所利用,用来攻击伊朗布什尔核电站基础设施","指一类漏洞,即特别好被利用,一旦成功利用该类漏洞,可以在１天内文完成攻击,且成功达到攻击目标","指一类漏洞,即刚被发现后立即被恶意利用的安全漏洞,一般来说,那些已经被小部分人发现,但是还未公开、还不存在安全补丁的漏洞都是零日漏洞"],"correctIndex":3,"explanation":"D是零日漏洞的解释。","imageNames":[]},{"id":"wx2026-04-038","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"38","domain":"信息安全管理","stem":"某单位发生的管理员小张在繁忙的工作中接到了一个电话,来电者:小张吗？我是科技处的李强,我的邮箱密码忘记了,现在打不开邮件,我着急收割邮件,麻烦腻先帮我把密码改成１２３,我收完邮件自己修改掉密码。热心的小张很快的满足了来电者的要求,随后,李强发现邮箱系统登陆异常,请问下泪说法哪个是正确的","options":["小张服务态度不好,如果把李强的邮件收下来亲自交给李强就不会发生这个问题","事件属于服务器故障,是偶然事件,应向单位领导申请购买新的服务器","单位缺乏良好的密码修改操作流程或小张没按照操作流程工作","事件属于邮件系统故障,是偶然事件,应向单位领导申请邮件服务软件"],"correctIndex":2,"explanation":"该题目考点为信息安全措施的操作安全,要求一切操作均有流程。","imageNames":[]},{"id":"wx2026-04-039","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"39","domain":"信息安全管理","stem":"某网站管理员小邓在流量监测中发现近期网站的入站ＩCＭＰ流量上升了２５０％,尽管网站没有发现任何的性能下降或其他问题。但为了安全起见,他仍然向主管领导提出了应对策略,作为主管负责人,请选择有效的针对此问题的应对措施:","options":["在防火墙上设置策略,阻止所有的ＩCＭＰ流量进入","删除服务器上的ｐｉｎｇ.ｅｘｅ程序","增加带宽以应对可能的拒绝服务攻击","增加网站服务器以应对即将来临的拒绝服务攻击"],"correctIndex":0,"explanation":"A是应对措施。","imageNames":[]},{"id":"wx2026-04-040","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"40","domain":"信息安全工程","stem":"下面四款安全测试软件中,主要用于ＷＥB安全扫描的是（）","options":["Cisco Auditing Tools","Acunetix Web Vulnerability Scanner","NMAP","ISS Database Scanner"],"correctIndex":1,"explanation":"Acunetix Web Vulnerability Scanner主要用于WEB安全扫描,可以检测网站的安全漏洞。A选项,Cisco Auditing Tools主要用于网络设备审计；C选项,NMAP主要用于网络探测和安全扫描；D选项,ISS Database Scanner主要用于数据库安全扫描。","imageNames":[]},{"id":"wx2026-04-041","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"41","domain":"信息安全工程","stem":"某单位计划在今年开发一套办公自动化（ＯA）系统,将集团公司各地的机构通过互联网进行协同办公,在ＯA系统的设计方案评审会上,提出了不少安全开发的建设,作为安全专家,请指出大家提的建议中不太合适的一条:","options":["对软件开发商提出安全相关要求,确保软件开发商对安全足够的重视,投入资源解决软件安全问题","要求软件开发人员进行安全开发培训,使开发人员掌握基本软件安全开发知识","要求软件开发商使用Ｊａｖａ而不是AＳＰ作为开发语言,避免ＳＱＬ注入漏洞","要求软件开发商对软件进行模块化设计,各模块明确输入和输出数据格式,并在使用前对数据进行校验"],"correctIndex":2,"explanation":"SQL注入与编码SQL语法应用和过滤有关,与开发语言不是必然关系。","imageNames":[]},{"id":"wx2026-04-042","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"42","domain":"信息安全工程","stem":"在软件保障成熟度模型（ＳAＭＭ）中,规定了软件开发过程中的核心业务功能,下列哪个选项不属于核心业务功能","options":["治理,主要是管理软件开发的过程和活动","构造,主要是在开发项目中确定目标并开发软件的过程与活动","验证,主要是测试和验证软件的过程和活动","购置,主要是购买第三方商业软件或者采用开源组件的相关管理过程与活动"],"correctIndex":3,"explanation":"ＳAＭＭ包括治理、构造、验证、部署。","imageNames":[]},{"id":"wx2026-04-043","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"43","domain":"信息安全工程","stem":"某软件公司准备提高其开发软件的安全性,在公司内部发起了有关软件开发生命周期的讨论,在下面的发言观点中,正确的是（）","options":["软件安全开发生命周期较长,阶段较多,而其中最重要的是要在软件的编码阶段做好安全措施,就可以解决９０％以上的安全问题","应当尽早在软件开发的需求和设计阶段就增加一定的安全措施,这样可以比在软件发布以后进行漏洞修复所花的代价少的多。","和传统的软件开发阶段相比,微软提出的安全开发生命周期的最大特点是增加了一个抓们的安全编码阶段","软件的安全测试也很重要,考虑到程序员的专业性,如果该开发人员已经对软件进行了安全性测试,就没有必要再组织第三方进行安全性测试"],"correctIndex":1,"explanation":"正确答案为B。","imageNames":[]},{"id":"wx2026-04-044","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"44","domain":"信息安全技术","stem":"下面有关软件安全问题的描述中,哪项是由于软件设计缺陷引起的（）","options":["设计了三层Ｗｅｂ架构,但是软件存在ＳＱＬ注入漏洞,导致被黑客攻击后能直接访问数据库","使用C语言开发时,采用了一些存在安全问题的字符串处理函数,导致存在缓冲区溢出漏洞","设计了缓存用户隐私数据机制以加快系统处理性能,导致软件在发布运行后,被黑客攻击获取到用户隐私数据","使用了符合要求的密码算法,但在使用算法接口时,没有按照要求生成密钥,导致黑客攻击后能破解并得到明文数据"],"correctIndex":2,"explanation":"设计了缓存用户隐私数据机制以加快系统处理性能,但未充分考虑安全因素,导致软件在发布运行后被黑客攻击获取到用户隐私数据,这是由于软件设计缺陷引起的。A选项,SQL注入漏洞可能是由于编码问题导致的；B选项,缓冲区溢出漏洞可能是由于使用不安全的字符串处理函数导致的；D选项,密钥生成问题可能是由于使用算法接口不当导致的。","imageNames":[]},{"id":"wx2026-04-045","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"45","domain":"信息安全技术","stem":"软件存在漏洞和缺陷是不可避免的,实践中常使用软件缺陷密度（Defects/KLOC）来衡量软件的安全性,假设某个软件共有29.6万行源代码,总共被检测出145个缺陷,则可以计算出其软件缺陷密度值是","options":["0.00049","0.049","0.49","49"],"correctIndex":2,"explanation":"软件缺陷密度（Defects/KLOC）的计算公式为:缺陷数/代码行数（千行）。本题中,软件共有29.6万行源代码,即296KLOC,总共被检测出145个缺陷,则软件缺陷密度值为145/296 ≈ 0.49。","imageNames":[]},{"id":"wx2026-04-046","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"46","domain":"信息安全管理","stem":"某集团公司根据业务需求,在各地分支机构部属前置机,为了保证安全,集团总部要求前置机开放日志共享,由总部服务器采集进行集中分析,在运行过程中发现攻击者也可通过共享从前置机种提取日志,从而导致部分敏感信息泄露,根据降低攻击面的原则,应采取以下哪项处理措施？","options":["由于共享导致了安全问题,应直接关闭日志共享,禁止总部提取日志进行分析","为配合总部的安全策略,会带来一定安全问题,但不影响系统使用,因此接受此风险","日志的存在就是安全风险,最好的办法就是取消日志,通过设置前置机不记录日志","只允许特定ＩＰ地址从前置机提取日志,对日志共享设置访问密码且限定访问的时间"],"correctIndex":3,"explanation":"D的特定ＩＰ地址从前置机提取降低了开放日志共享的攻击面。","imageNames":[]},{"id":"wx2026-04-047","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"47","domain":"信息安全工程","stem":"针对软件的拒绝服务攻击是通过消耗系统资源使软件无法响应正常请求的一种攻击方式,在软件开发时分析拒绝服务攻击的威胁,以下哪个不是需求考虑的攻击方式","options":["攻击者利用软件存在的逻辑错误,通过发送某种类型数据导致运算进入死循环,CＰＵ资源占用始终１００％","攻击者利用软件脚本使用多重嵌套咨询,在数据量大时会导致查询效率低,通过发送大量的查询导致数据库响应缓慢","攻击者利用软件不自动释放连接的问题,通过发送大量连接消耗软件并发连接数,导致并发连接数耗尽而无法访问","攻击者买通ＩDC人员,将某软件运行服务器的网线拔掉导致无法访问"],"correctIndex":3,"explanation":"D为社会工程学攻击。","imageNames":[]},{"id":"wx2026-04-048","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"48","domain":"信息安全技术","stem":"某网站为了开发的便利,使用SA链接数据库,由于网站脚本中被发现存在SQL注入漏洞,导致攻击者利用内置存储过程XP.cmctstell删除了系统中的一个重要文件,在进行问题分析时,作为安全专家,你应该指出该网站设计违反了以下哪项原则:","options":["权限分离原则","最小特权原则","保护最薄弱环节的原则","纵深防御的原则"],"correctIndex":1,"explanation":"SA是数据库最大用户权限,违反了最小特权原则。","imageNames":[]},{"id":"wx2026-04-049","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"49","domain":"信息安全管理","stem":"微软提出了STRIDE模型,其中Repudation（抵赖）的缩写,关于此项安全要求,下面描述错误的是（）","options":["某用户在登陆系统并下载数据后,却声称“我没有下载过数据”,软件系统中的这种威胁就属于R威胁","解决R威胁,可以选择使用抗抵赖性服务技术来解决,如强认证、数字签名、安全审计等技术措施","R威胁是STRIDE六种威胁中第三严重的威胁,比D威胁和E威胁的严重程度更高","解决R威胁,也应按照确定建模对象、识别威胁、评估威胁以及消减威胁等四个步骤来进行"],"correctIndex":2,"explanation":"STRIDE代表6种威胁的简称,无严重程度之分。S-欺骗,T-篡改,R-抵赖,I-信息泄露,D-拒绝服务,E-权限提升（攻击）。","imageNames":[]},{"id":"wx2026-04-050","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"50","domain":"信息安全管理","stem":"关于信息安全管理,下面理解片面的是（）","options":["信息安全管理是组织整体管理的重要、固有组成部分,它是组织实现其业务目标的重要保障","信息安全管理是一个不断演进、循环发展的动态过程,不是一成不变的","信息安全建设中,技术是基础,管理是拔高,既有效的管理依赖于良好的技术基础","坚持管理与技术并重的原则,是我国加强信息安全保障工作的主要原则之一"],"correctIndex":2,"explanation":"C是片面的,应为技管并重。","imageNames":[]},{"id":"wx2026-04-051","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"51","domain":"信息安全法规标准","stem":"以下哪项制度或标准被作为我国的一项基础制度加以推行,并且有一定强制性,其实施的主要目标是有效地提高我国信息和信息系统安全建设的整体水平,重点保障基础信息网络和重要信息系统的安全（）","options":["信息安全管理体系（ISMS）","信息安全等级保护","NIST SP 800","ISO 270000 系统"],"correctIndex":1,"explanation":"信息安全等级保护制度重点保障基础信息网络和重要信息系统的安全。","imageNames":[]},{"id":"wx2026-04-052","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"52","domain":"信息安全管理","stem":"小明是某大学计算科学与技术专业的毕业生,大四上学期开始找工作,期望谋求一份技术管理的职位,一次面试中,某公司的技术经理让小王谈一谈信息安全风险管理中的背景建立的几本概念与认识,小明的主要观点包括:（1）背景建立的目的是为了明确信息安全风险管理的范围和对象,以及对象的特性和安全要求,完成信息安全风险管理项目的规划和准备；（2）背景建立根据组织机构相关的行业经验执行,雄厚的经验有助于达到事半功倍的效果(3)背景建立包括:风险管理准备、信息系统调查、信息系统分析和信息安全分析（4.）背景建立的阶段性成果包括:风险管理计划书、信息系统的描述报告、信息系统的分析报告、信息系统的安全要求报告、请问小明的论点中错误的是哪项:","options":["第一个观点","第二个观点","第三个观点","第四个观点"],"correctIndex":1,"explanation":"背景建立是根据政策、法律、标准、业务、系统、组织等现状来开展。","imageNames":[]},{"id":"wx2026-04-053","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"53","domain":"信息安全法规标准","stem":"降低风险（或减低风险）指通过对面的风险的资产采取保护措施的方式来降低风险,下面那个措施不属于降低风险的措施（）","options":["减少威胁源,采用法律的手段制裁计算机的犯罪,发挥法律的威慑作用,从而有效遏制威胁源的动机","签订外包服务合同,将有计算难点,存在实现风险的任务通过签订外部合同的方式交予第三方公司完成,通过合同责任条款来应对风险","减低威胁能力,采取身份认证措施,从而抵制身份假冒这种威胁行为的能力","减少脆弱性,及时给系统打补丁,关闭无用的网络服务端口,从而减少系统的脆弱性,降低被利用的可能性"],"correctIndex":1,"explanation":"B属于转移风险。","imageNames":[]},{"id":"wx2026-04-054","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"54","domain":"信息安全管理","stem":"关于风险要素识别阶段工作内容叙述错误的是:","options":["资产识别是指对需求保护的资产和系统等进行识别和分类","威胁识别是指识别与每项资产相关的可能威胁和漏洞及其发生的可能性","脆弱性识别以资产为核心,针对每一项需求保护的资产,识别可能被威胁利用的弱点,并对脆弱性的严重程度进行评估","确认已有的安全措施仅属于技术层面的工作,牵涉到具体方面包括:物理平台、系统平台、网络平台和应用平台"],"correctIndex":3,"explanation":"安全措施既包括技术层面,也包括管理层面。","imageNames":[]},{"id":"wx2026-04-055","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"55","domain":"信息安全法规标准","stem":"某单位的信息安全主管部门在学习我国有关信息安全的政策和文件后,认识到信息安全风险评估分为自评估和检查评估两种形式,该部门将有检查评估的特点和要求整理成如下四条报告给单位领导,其中描述错误的是","options":["检查评估可依据相关标准的要求,实施完整的风险评估过程；也可在自评估的基础上,对关键环节或重点内容实施抽样评估","检查评估可以由上级管理部门组织,也可以由本级单位发起,其重点是针对存在的问题进行检查和评测","检查评估可以由上级管理部门组织,并委托有资质的第三方技术机构实施","检查评估是通过行政手段加强信息安全管理的重要措施,具有强制性的特点"],"correctIndex":1,"explanation":"检查评估由上级管理部门组织发起；本级单位发起的为自评估。","imageNames":[]},{"id":"wx2026-04-056","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"56","domain":"信息安全管理","stem":"规范的实施流程和文档管理,是信息安全风险评估结能否取得成果的重要基础,按照规范的风险评估实施流程,下面哪个文档应当是风险要素识别阶段的输出成果（）","options":["《风险评估方案》","《需要保护的资产清单》","《风险计算报告》","《风险程度等级列表》"],"correctIndex":1,"explanation":"风险要素包括资产、威胁、脆弱性、安全措施。","imageNames":[]},{"id":"wx2026-04-057","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"57","domain":"信息安全法规标准","stem":"在信息安全管理的实施过程中,管理者的作用于信息安全管理体系能否成功实施非常重要,但是一下选项中不属于管理者应有职责的是（）","options":["制定并颁发信息安全方针,为组织的信息安全管理体系建设指明方向并提供总体纲领,明确总体要求","确保组织的信息安全管理体系目标和相应的计划得以制定,目标应明确、可度量,计划应具体、可事实","向组织传达满足信息安全的重要性,传达满足信息安全要求、达成信息安全目标、符合信息安全方针、履行法律责任和持续改进的重要性","建立健全信息安全制度,明确安全风险管理作用,实施信息安全风险评估过程、确保信息安全风险评估技术选择合理、计算正确"],"correctIndex":3,"explanation":"D不属于管理者的职责。","imageNames":[]},{"id":"wx2026-04-058","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"58","domain":"信息安全法规标准","stem":"信息安全管理体系（Information Security Management System ,ISMS）的内部审核和管理审核是两项重要的管理活动,关于这两者,下面描述的错误是","options":["内部审核和管理评审都很重要,都是促进ISMS持续改进的重要动力,也都应当按照一定的周期实施","内部审核的实施方式多采用文件审核和现场审核的形式,而管理评审的实施方式多采用召开管理评审会议形式进行","内部审核的实施主体组织内部的ISMS内审小组,而管理评审的实施主体是由国家政策指定的第三方技术服务机构","组织的信息安全方针、信息安全目标和有关ISMS文件等,在内部审核中作为审核标准使用,但在管理评审总,这些文件时被审对象"],"correctIndex":2,"explanation":"管理评审的实施主体由用户的管理者来进行选择。","imageNames":[]},{"id":"wx2026-04-059","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"59","domain":"信息安全管理","stem":"在风险管理中,残余风险是指实施了新的或增强的安全措施后还剩下的风险,关于残余风险,下面描述错误的是（）","options":["风险处理措施确定以后,应编制详细的残余风险清单,并获得管理层对残余风险的书面批准,这也是风险管理中的一个重要过程","管理层确认接收残余风险,是对风险评估工作的一种肯定,表示管理层已经全面了解了组织所面临的风险,并理解在风险一旦变为现实后,组织能够且承担引发的后果","接收残余风险,则表明没有必要防范和加固所有的安全漏洞,也没有必要无限制的提高安全保护措施的强度,对安全保护措施的选择要考虑到成本和技术等因素的限制","如果残余风险没有降低到可接受的级别,则只能被动的选择接受风险,即对风险不进行下一步的处理措施,接受风险可能带来的结果。"],"correctIndex":3,"explanation":"如果残余风险没有降低到可接受的级别,则会被动的选择接受残余风险,但需要对残余风险进行进一步的关注、监测和跟踪。","imageNames":[]},{"id":"wx2026-04-060","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"60","domain":"信息安全管理","stem":"关于业务连续性计划（BCP）以下说法最恰当的是:","options":["组织为避免所有业务功能因重大事件而中断,减少业务风此案而建立的一个控制过程。","组织为避免关键业务功能因重大事件而中断,减少业务风险而建立的一个控制过程。","组织为避免所有业务功能因各种事件而中断,减少业务风此案而建立的一个控制过程","组织为避免信息系统功能因各种事件而中断,减少信息系统风险建立的一个控制过程"],"correctIndex":1,"explanation":"业务连续性计划（BCP）是解决关键业务不中断。","imageNames":[]},{"id":"wx2026-04-061","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"61","domain":"信息安全管理","stem":"在某次信息安全应急响应过程中,小王正在实施如下措施:消除或阻断攻击源,找到并消除系统的脆弱性/漏洞、修改安全策略,加强防范措施、格式化被感染而已程序的介质等,请问,按照应急响应方法,这些工作应处于以下哪个阶段（）","options":["准备阶段","检测阶段","遏制阶段","根除阶段"],"correctIndex":3,"explanation":"消除或阻断攻击源等措施为根除阶段。","imageNames":[]},{"id":"wx2026-04-062","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"62","domain":"信息安全管理","stem":"关于信息安全事件管理和应急响应,以下说法错误的是:","options":["应急响应是指组织为了应急突发/重大信息安全事件的发生所做的准备,以及在事件发生后所采取的措施","应急响应方法,将应急响应管理过程分为遏制、根除、处置、恢复、报告和跟踪6个阶段","对信息安全事件的分级主要参考信息系统的重要过程、系统损失和社会影响三方面。","根据信息安全事件的分级参考要素,可将信息安全事件划分为4个级别,特别重大事件（I级）、重大事件（II级）、较大事件（III级）和一般事件（IV级）"],"correctIndex":1,"explanation":"应急响应包括六个阶段,为准备、检测、遏制、根除、恢复、跟踪总结。","imageNames":[]},{"id":"wx2026-04-063","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"63","domain":"信息安全保障","stem":"对信息安全事件的分级参考下列三个要素:信息系统的重要程度、系统损失和社会影响,依据信息系统的重要程度对信息进行划分,不属于正确划分级别的是:","options":["特别重要信息系统","重要信息系统","一般信息系统","关键信息系统"],"correctIndex":3,"explanation":"我国标准中未定义关键信息系统。","imageNames":[]},{"id":"wx2026-04-064","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"64","domain":"信息安全管理","stem":"恢复时间目标（RTO）和恢复点目标（RPO）是信息系统灾难恢复中的重要概念,关于这两个值能否为零,正确的选项是（）","options":["RTO可以为0,RPO也可以为0","RTO可以为0,RPO不可以为0","RTO不可以为0,但RPO可以为0","RTO不可以为0,RPO也不可以为0"],"correctIndex":0,"explanation":"RTO可以为0,RPO也可以为0。","imageNames":[]},{"id":"wx2026-04-065","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"65","domain":"信息安全工程","stem":"某政府机构拟建设一机房,在工程安全监理单位参与下制定了招标文件,项目分二期,一期目标为年内实现系统上线运营,二期目标为次年上半年完成运行系统风险的处理:招标文件经营管理层审批后发布,就此工程项目而言,以下正确的是:","options":["此项目将项目目标分解为系统上线运营和运行系统风险处理分期实施,具有合理性和可行性","在工程安全监理的参与下,确保了此招标文件的合理性","工程规划不符合信息安全工程的基本原则","招标文件经营管理层审批,表明工程目标符合业务发展规划"],"correctIndex":2,"explanation":"题目描述不符合信息安全工程的“同步规划、同步实施”的基本原则。","imageNames":[]},{"id":"wx2026-04-066","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"66","domain":"信息安全工程","stem":"对系统工程（Systems Engineering ,SE ）的理解,以下错误的是:","options":["系统工程偏重于对工程的组织与经营管理进行研究","系统工程不属于技术实现,而是一种方法论","系统工程不是一种对所有系统都具有普遍意义的科学方法","系统工程是组织管理系统规划、研究、制造、实验、使用的科学方法"],"correctIndex":2,"explanation":"系统工程是一种对所有系统都具有普遍意义的科学方法","imageNames":[]},{"id":"wx2026-04-067","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"67","domain":"信息安全法规标准","stem":"系统工程的模型之一霍尔三维结构模型由时间维、逻辑维和知识维组成。 有关此模型,错误的是:","options":["霍尔三维机构体系形成地描述了系统工程研究的框架","时间维表示系统工程活动从开始到结束按照时间顺序排列的全过程","逻辑维的七个步骤与时间维的七个阶段严格对应,即时间维第一阶段应执行逻辑维第一步骤的活动,时间维第二阶段应执行逻辑维第二步骤的活动","知识维列举可能需要运用的工程、医学、建筑、商业、法律、管理、社会科学和艺术等各种知识和技能"],"correctIndex":2,"explanation":"霍尔三维模型是一种系统思想,无法实现严格的对应。","imageNames":[]},{"id":"wx2026-04-068","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"68","domain":"信息安全工程","stem":"北京某公司利用SSE-CMM对其自身工程队伍能力进行自我改善,其理解正确的是:","options":["系统安全工程能力成熟度模型（SSE-CMM）定义了6个能力级别,当工程队不能执行一个过程域中的基本实践时,该过程域的过程能力为0级","达到SSE-CMM最高级以后,工程队伍执行同一个过程,每次执行结果质量必须相同。","系统安全工程能力成熟度模型（SSE-CMM）定义了3个风险过程:评价威胁,评价脆弱性,评价影响。","SSE-CMM强调系统安全工程与其他工程科学的区别和独立性。"],"correctIndex":0,"explanation":"A当工程队不能执行一个过程域中的基本实践时,该过程域的过程能力为0级。B错误,每次质量结果难以相同。C错误,SSE-CMM定义了一个风险过程,包括四个部分,评估影响、评估威胁、评估脆弱性、评估安全风险。D错误,SSE-CMM强调的是关联性而非独立性。","imageNames":[]},{"id":"wx2026-04-069","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"69","domain":"信息安全工程","stem":"以下哪一项不是信息系统集成项目的特点:","options":["信息系统集成项目要以满足客户和用户的需求为根本出发点。","系统集成就是选择最好的产品和技术,开发响应的软件和硬件,将其集成到信息系统的过程。","信息系统集成项目的指导方法是“总体规划、分步实施”。","信息系统集成包含技术,管理和商务等方面,是一项综合性的系统工程"],"correctIndex":1,"explanation":"系统集成就是选择最适合的产品和技术。","imageNames":[]},{"id":"wx2026-04-070","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"70","domain":"信息安全工程","stem":"以下关于信息安全工程说法正确的是:","options":["信息化建设中系统功能的实现是最重要的","信息化建设可以实施系统,而后对系统进行安全加固","信息化建设中在规划阶段合理规划信息安全,在建设阶段要同步实施信息安全建设","信息化建设没有必要涉及信息安全建设"],"correctIndex":2,"explanation":"C为安全工程的同步规划、同步实施原则。","imageNames":[]},{"id":"wx2026-04-071","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"71","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型（sse-cmm）中的基本实施（Base Practices ,BP）,正确的理解是:","options":["BP是基于最新技术而制定的安全参数基本配置","大部分BP是没有进过测试的","一项BP适用于组织的生存周期而非仅适用于工程的某一特定阶段","一项BP可以和其他BP有重叠"],"correctIndex":2,"explanation":"A答案中BP是基于工程实践总结的工程单元。B答案中BP是经过测试和实践验证的。C答案中一项BP适用于组织的生存周期是正确的。D一项BP不能和其他BP重叠。","imageNames":[]},{"id":"wx2026-04-072","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"72","domain":"信息安全工程","stem":"有关系统安全工程-能力成熟度模型（SSE-CMM）中的通用实施（Generic Practices ,GP）错误理解是:","options":["GP是涉及过程的管理、测量和制度化方面的活动","GP适用于域维中部分过程区域（Process Aractices ,PA）活动而非所有PA的活动","在工程实施时,GP应该作为基本实施（ Base Practices,BP）的一部分加以执行","在评估时,GP用于判定工程组织执行某个PA的能力"],"correctIndex":1,"explanation":"GP适用于域维中所有PA活动。","imageNames":[]},{"id":"wx2026-04-073","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"73","domain":"信息安全法规标准","stem":"在使用系统安全工程-能力成熟度模型（SSE-CCM）对一个组织的安全工程能力成熟度进行测量时,有关测量结果,错误的理解是:","options":["如果该组织在执行某个特定的过程区域时具备了一个特定级别的部分公共特征时,则这个组织在这个过程区域的能力成熟度未达到此级","如果该组织某个过程区域（Process Areas,PA）具备了“定义标准过程”、“执行已定义的过程”两个公共特征,则此过程区域的能力成熟度级别达到3级“充分定义级”","如果某个过程区域（Process Areas,PA)包含4个基本实施（Base Practices,BP）,执行此PA时执行了3个BP,则此过程区域的能力成熟度级别为0","组织在不同的过程区域的能力成熟度可能处于不同的级别上"],"correctIndex":1,"explanation":"SSE-CMM充分定义级包括三个特征,为“定义标准过程”、“执行已定义的过程”、“安全协调实施”。B答案中只描述了两个公共特征。","imageNames":[]},{"id":"wx2026-04-074","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"74","domain":"信息安全工程","stem":"系统安全工程-能力成熟度模型(SSE-CMM）定义的包含评估威胁、评估脆弱性、评估影响和评估安全风险的基本过程领域是:","options":["风险过程","工程过程","保证过程","评估过程"],"correctIndex":0,"explanation":"风险过程包括评估影响、评估威胁、评估脆弱性和评估安全风险。","imageNames":[]},{"id":"wx2026-04-075","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"75","domain":"信息安全法规标准","stem":".以下行为不属于违反国家涉密规定的行为:","options":["将涉密计算机、涉密存储设备接入互联网及其他公共信息网络","通过普通邮政等无保密及措施的渠道传递国家秘密载体","在私人交往中涉及国家秘密","以不正当手段获取商业秘密"],"correctIndex":3,"explanation":"D为商业秘密,不属于涉密规定的行为。","imageNames":[]},{"id":"wx2026-04-076","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"76","domain":"信息安全法规标准","stem":"具有行政法律责任强制的安全管理规定和安全制度包括 1>安全事件（包括安全事故）报告制度 2>安全等级保护制度 3>信息系统安全监控 4>安全专用产品销售许可证制度","options":["1,2,4","2,3","2,3, 4","1,2, 3"],"correctIndex":0,"explanation":"1\\2\\4均为管理规定和安全制度。","imageNames":[]},{"id":"wx2026-04-077","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"77","domain":"信息安全保障","stem":"信息系统建设完成后,（ ）的信息系统的而运营使用单位应当选择符合国家规定的测评机构进行测评合格后方可投入使用","options":["二级以上","三级以上","四级以上","五级以上"],"correctIndex":1,"explanation":"答案为B,三级以上默认包括本级。","imageNames":[]},{"id":"wx2026-04-078","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"78","domain":"信息安全法规标准","stem":"为了保障网络安全,维护网络安全空间主权和国家安全、社会公共利益,保护公民、法人和其他组织的合法权益,促进经济社会信息化健康发展,加强在中华人民共和国境内建设、运营、维护和使用网络,以及网络安全的监督管理,2015年6月,第十二届全国人大常委会第十五次会议初次审议了一部法律草案,并与7月6日起在网上全文公布,向社会公开征求意见,这部法律草案是（）","options":["《中华人民共和国保守国家秘密法（草案）》","《中华人民共和国网络安全法（草案）》","《中华人民共和国国家安全法（草案）》","《中华人民共和国互联网安全法（草案）》"],"correctIndex":1,"explanation":"答案为B。","imageNames":[]},{"id":"wx2026-04-079","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"79","domain":"信息安全法规标准","stem":"为了进一步提高信息安全的保障能力和防护水平,保障和促进信息化建设的健康发展,公安部等4 部分联合发布《关于信息安全等级保护工作的实施意见》(公通字[2004]66号),对等级保护工作的开展提供宏观指导和约束,明确了等级保护工作的基本内容、工作要求和实施计划,以及各部门工作职责分工等,关于该文件,下面理解正确的是","options":["该文件时一个由部委发布的政策性文件,不属于法律文件","该文件适用于2004年的等级保护工作,其内容不能越苏到2005年及之后的工作","该文件时一个总体性知道文件,规定了所有信息系统都要纳入等级保护定级范围","该文件使用范围为发文的这四个部门,不适用于其他部门和企业等单位"],"correctIndex":0,"explanation":"答案为A。","imageNames":[]},{"id":"wx2026-04-080","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"80","domain":"信息安全法规标准","stem":"CC标准是目前系统安全认证方面最权威的而标准,那一项不是体现CC标准的先进性？","options":["结构开放性,即功能和保证要求可以“保护轮廓”和“安全目标”中进行一步细化和扩展","表达方式的通用性,即给出通用的表达方式","独立性,它强调将安全的功能和保证分离","实用性,将CC的安全性要求具体应用到IT产品的开发、生产、测试和评估过程中"],"correctIndex":2,"explanation":"ITSEC最早强调功能和保证的分离,不是CC的先进性。","imageNames":[]},{"id":"wx2026-04-081","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"81","domain":"信息安全法规标准","stem":"对于数字证书而言,一般采用的是哪个标准？","options":["ISO/IEC 1540B","802.11","GB/T 20984","X.509"],"correctIndex":3,"explanation":"数字证书采用X.509标准。","imageNames":[]},{"id":"wx2026-04-082","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"82","domain":"信息安全保障","stem":"在可信计算机系统评估准则（TCSEC）中,下列哪一项是满足强制保护要求的最低级别？","options":["C2","C1","B2","B1"],"correctIndex":3,"explanation":"TCSEC中B1级满足强制保护要求。A选项C2级为自主保护；B选项C1级为随意保护；C选项B2级为结构化保护。","imageNames":[]},{"id":"wx2026-04-083","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"83","domain":"信息安全法规标准","stem":"关于标准,下面哪项理解是错误的（）","options":["标准是在一定范围内为了获得最佳秩序,经协协商一致制定并由公认机构批准,共同重复使用的一种规范性文件,标准是标准化活动的重要成果","国际标准是由国际标准化组织通过并公布的标准,同样是强制性标准,当国家标准和国际标准的条款发生冲突,应以国际标准条款为准。","行业标准是针对没有国家标准而又才需要在全国某个行业范围统一的技术要求而制定的标准,同样是强制性标准,当行业标准和国家标准的条款发生冲突时,应以国家标准条款为准。","地方标准由省、自治区、直辖市标准化行政主管部门制度,冰报国务院标准化行政主管部门和国务院有关行政主管培训部门备案,在公布国家标准后,该地方标准即应废止。"],"correctIndex":1,"explanation":"当国家标准和国际标准的条款发生冲突,应以国家标准条款为准。","imageNames":[]},{"id":"wx2026-04-084","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"84","domain":"信息安全法规标准","stem":"2005年,RFC4301（Request for Comments 4301:Security Architecture for the Intermet Protocol）发布,用以取代原先的RFC2401,该标准建议规定了IPsec系统基础架构,描述如何在IP层（IPv4/IPv6）为流量提供安全业务,请问此类RFC系列标准建设是由哪个组织发布的（）","options":["国际标准化组织","国际电工委员会","国际电信联盟远程通信标准化组织","Internet工程任务组"],"correctIndex":3,"explanation":"RFC系列标准由Internet工程任务组发布。A选项国际标准化组织发布ISO标准；B选项国际电工委员会发布IEC标准；C选项国际电信联盟发布ITU标准。","imageNames":[]},{"id":"wx2026-04-085","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"85","domain":"信息安全法规标准","stem":"关于信息安全管理体系,国际上有标准（ISO/IEC 27001:2013）而我国发布了《信息技术安全技术信息安全管理体系要求》(GB/T 22080-2008）请问,这两个标准的关系是:","options":["IDT (等同采用),此国家标准等同于该国际标准,仅有或没有编辑性修改","EQV(等效采用),此国家标准不等效于该国际标准","NEQ（非等效采用）,此国家标准不等效于该国际标准","没有采用与否的关系,两者之间版本不同,不应该直接比较"],"correctIndex":3,"explanation":"选项A（IDT）:等同采用要求国家标准与国际标准内容完全一致,仅允许编辑性修改（如格式、术语排序）。但GB/T 22080-2008对应的是ISO/IEC 27001:2005,与2013版内容存在差异,不符合IDT条件。 选项B（EQV）:等效采用允许技术性差异,但需保证核心要求一致。GB/T 22080-2008与ISO/IEC 27001:2013版本不同,技术内容已更新,无法直接判定为等效。 选项C（NEQ）:非等效采用表示国家标准与国际标准存在显著差异。但题目中未提供足够信息证明两者技术内容完全不等效。 选项D: GB/T 22080-2008对应的是ISO/IEC 27001:2005,我国后续发布GB/T 22080-2016以对应ISO/IEC 27001:2013,版本不同,直接比较无意义。","imageNames":[]},{"id":"wx2026-04-086","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"86","domain":"信息安全法规标准","stem":"GB/T18336<<信息技术安全性评估准则>>（CC）是测评标准类中的重要标准,该标准定义了保护轮廓（Protection Profile ,PP ）和安全目标（Security Target ,ST）的评估准则,提出了评估保证级（Evaluation Assurance Level,EAL）,其评估保证级共分为（）个递增的评估保证等级","options":["4","5","6","7"],"correctIndex":3,"explanation":"CC标准EAL1-EAL7级。","imageNames":[]},{"id":"wx2026-04-087","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"87","domain":"信息安全工程","stem":"信息安全工程监理的职责包括:","options":["质量控制、进度控制、成本控制、合同管理、信息管理和协调","质量控制、进度控制、成本控制、合同管理和协调","确定安全要求、认可设计方案、监视安全态势、建立保障证据和协调","确定安全要求、认可设计方案、监视安全态势和协调"],"correctIndex":0,"explanation":"A为监理的内容。","imageNames":[]},{"id":"wx2026-04-088","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"88","domain":"信息安全工程","stem":"关于信息安全保障的概念,下面说法错误的是:","options":["信息系统面临的风险和威胁是动态变化的,信息安全保障强调动态的安全理念","信息安全保障已从单纯保护和防御阶段发展为集保护、检测和响应为一体的综合阶段","在全球互联互通的网络空间环境下,可单纯依靠技术措施来保障信息安全","信息安全保障把信息安全从技术扩展到管理,通过技术、管理和工程等措施的综合融合,形成对信息、信息系统及业务使命的保障"],"correctIndex":2,"explanation":"网络空间安全不能单纯依靠技术措施来保障。","imageNames":[]},{"id":"wx2026-04-089","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"89","domain":"信息安全保障","stem":"关于监理过程中成本控制,下列说法中正确的是?","options":["成本只要不超过预计的收益即可","成本应控制得越低越好","成本控制由承建单位实现,监理单位只能记录实际开销","成本控制的主要目的是在批准的预算条件下确保项目保质按期完成"],"correctIndex":3,"explanation":"成本控制旨在确保项目在预算内保质按期完成。A选项错误,成本需控制在预算内；B选项错误,成本需合理；C选项错误,监理单位也需参与成本控制。","imageNames":[]},{"id":"wx2026-04-090","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"90","domain":"信息安全工程","stem":"下列关于ISO15408信息技术安全评估准则(简称CC)通用性的特点,即给出通用的表达方式,描述不正确的是______。","options":["如果用户、开发者、评估者和认可者都使用CC语言,互相就容易理解沟通","通用性的特点对规范实用方案的编写和安全测试评估都具有重要意义","通用性的特点是在经济全球化发展、全球信息化发展的趋势下,进行合格评定和评估结果国际互认的需要","通用性的特点使得CC也适用于对信息安全建设工程实施的成熟度进行评估"],"correctIndex":3,"explanation":"SSE-CMM用于对安全建设工程的成熟度进行评估。CC是信息技术产品或系统的规划、设计、研发、测试、EAL级别评估进行使用。","imageNames":[]},{"id":"wx2026-04-091","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"91","domain":"信息安全法规标准","stem":"对涉密系统进行安全保密测评应当依据以下哪个标准?","options":["BMB20-2007《涉及国家秘密的计算机信息系统分级保护管理规范》","BMB22-2007《涉及国家秘密的计算机信息系统分级保护测评指南》","GB17859-1999《计算机信息系统安全保护等级划分准则》","GB／T20271-2006《信息安全技术信息系统统用安全技术要求》"],"correctIndex":1,"explanation":"涉密系统测评依据BMB22-2007。A选项为管理规范；C、D选项非涉密标准。","imageNames":[]},{"id":"wx2026-04-092","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"92","domain":"信息安全法规标准","stem":"ISO／IEC27001《信息技术 安全技术 信息安全管理体系要求》的内容是基于（）","options":["BS7799-1《信息安全实施细则》","BS7799-2《信息安全管理体系规范》","信息技术安全评估准则(简称ITSEC)","信息技术安全评估通用标准(简称CC)"],"correctIndex":1,"explanation":"BS7799-1发展为ISO27002；BS7799-2发展为ISO27001；TCSEC发展为ITSEC；ITSEC发展为CC。","imageNames":[]},{"id":"wx2026-04-093","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"93","domain":"信息安全法规标准","stem":"在GB／T18336《信息技术安全性评估准则》（CC标准）中,有关保护轮廓(Protection Profile,PP)和安全目标(Security Target,ST),错误的是:","options":["PP是描述一类产品或系统的安全要求","PP描述的安全要求与具体实现无关","两份不同的ST不可能满足同一份PP 的要求","ST与具体的实现有关"],"correctIndex":2,"explanation":"两份不同的ST可以同时满足同一份PP 的要求。","imageNames":[]},{"id":"wx2026-04-094","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"94","domain":"信息安全保障","stem":"以下哪一项不是我国国务院信息化办公室为加强信息安全保障明确提出的九项重点工作内容之一?","options":["提高信息技术产品的国产化率","保证信息安全资金投入","加快信息安全人才培养","重视信息安全应急处理工作"],"correctIndex":0,"explanation":"提高信息技术产品的国产化率不属于九项重点工作内容之一。","imageNames":[]},{"id":"wx2026-04-095","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"95","domain":"信息安全法规标准","stem":"以下哪项是对系统工程过程中“概念与需求定义”阶段的信息安全工作的正确描述?","options":["应基于法律法规和用户需求,进行需求分析和风险评估,从信息系统建设的开始就综合信息系统安全保障的考虑","应充分调研信息安全技术发展情况和信息安全产品市场,选择最先进的安全解决方案和技术产品","应在将信息安全作为实施和开发人员的一项重要工作内容,提出安全开发的规范并切实落实","应详细规定系统验收测试中有关系统安全性测试的内容"],"correctIndex":0,"explanation":"A为概念与需求定义的工作内容。B是安全规划设计阶段内容。C是实施阶段。D是验收测试阶段的内容。","imageNames":[]},{"id":"wx2026-04-096","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"96","domain":"信息安全法规标准","stem":"以下关于法律的说法错误的是（）","options":["法律是国家意志的统一体现,有严密的逻辑体系和效力","法律可以是公开的,也可以是“内部”的","一旦制定,就比较稳定,长期有效,不允许经常更改","法律对违法犯罪的后果由明确规定,是一种“硬约束”"],"correctIndex":1,"explanation":"法律是公开的,内部的规定不能作为法律。","imageNames":[]},{"id":"wx2026-04-097","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"97","domain":"信息安全工程","stem":"由于频繁出现软件运行时被黑客远程攻击获取数据的现象,某软件公司准备加强软件安全开发管理,在下面做法中,对于解决问题没有直接帮助的是（）","options":["要求开发人员采用敏捷开发模型进行开发","要求所有的开发人员参加软件安全意识培训","要求规范软件编码,并制定公司的安全编码准则","要求增加软件安全测试环节,今早发现软件安全问题"],"correctIndex":0,"explanation":"开发人员采用敏捷开发模型进行软件开发,但未包括安全的开发方法和措施。","imageNames":[]},{"id":"wx2026-04-098","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"98","domain":"信息安全管理","stem":"根据信息安全风险要素之间的关系,下图中空白处应该填写（）","options":["资产","安全事件","脆弱性","安全措施"],"correctIndex":2,"explanation":"风险的原理是威胁利用脆弱性,造成对资产的风险。","imageNames":["wx2026-04-01.png"]},{"id":"wx2026-04-099","setId":"wx2026-04","setName":"CISP 复习题（2）","sourceNumber":"99","domain":"信息安全法规标准","stem":"信息安全标准化工作是我国信息安全保障工作的重要组成部分之一,也是政府进行宏观管理的重要依据,同时也是保护国家利益,促进产业发展的重要手段之一,关于我国标准化工作,下面选项中描述错误的是（）","options":["我国是在国家质量监督检验疫总局管理下,由国家标准化管理委员会统一管理全国标准化工作,下设专业技术委员会","事关国家安全利益,信息安全因此不能和国际标准相同,而是要通过本国组织和专家制定标准,切实有效地保护国家利益和安全","我国归口信息安全方面标准是“全国信息安全标准化技术委员会”,为加强有关工作,2016在其下设立“大数据安全特别工作组”","信息安全标准化工作是解决信息安全问题的重要技术支撑,其主要作业突出体现在能够确保有关产品、设施的技术先进性、可靠性和一致性"],"correctIndex":1,"explanation":"信息安全的标准可以和国际标准相同,也可以不相同。包括同等采用方式和等效采用方式等。","imageNames":[]}]},{"id":"wx2026-05","name":"CISP 复习题（3）","subtitle":"100题 · 有答案+解析","sourceFile":"CISP复习题（3）100题（有答案）-已审+解析.docx","questionCount":100,"questions":[{"id":"wx2026-05-001","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"1","domain":"信息安全技术","stem":"最小特权是软件安全设计的基本原则,某应用程序在设计时,设计人员给出了以下四种策略,其中有一个违反了最小特权的原则,作为评审专家,请指出是哪一个?","options":["软件在Linux下按照时,设定运行时使用nobody用户运行实例","软件的日志备份模块由于需要备份所有数据库数据,在备份模块运行时,以数据库备份操作员账号连接数据库","软件的日志模块由于要向数据库中的日志表中写入日志信息,使用了一个日志用户账号连接数据库,该账号仅对日志表拥有权限","为了保证软件在Windows下能稳定的运行,设定运行权限为system,确保系统运行正常,不会因为权限不足产生运行错误"],"correctIndex":3,"explanation":"SYSTEM权限是最大权限,答案为D。","imageNames":[]},{"id":"wx2026-05-002","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"2","domain":"信息安全技术","stem":"主机A 向主机B发出的数据采用AH或ESP的传输模式对经过互联网的数据流量进行保护时,主机A和主机B 的IP地址在应该在下列哪个范围?","options":["10.0.0.0～10.255.255.255","172.16.0.0～172.31.255.255","192.168.0.0～192.168.255.255","不在上述范围内"],"correctIndex":3,"explanation":"采用传输模式则没有地址转换,那么A、B主机应为公有地址。","imageNames":[]},{"id":"wx2026-05-003","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"3","domain":"信息安全工程","stem":"某电子商务网站最近发生了一起安全事件,出现了一个价值1000 元的商品用1元被买走的情况,经分析是由于设计时出于性能考虑,在浏览时使用Http协议,攻击者通过伪造数据包使得向购物车添加商品的价格被修改.利用此漏洞,攻击者将价值1000 元的商品以1元添加到购物车中,而付款时又没有验证的环节,导致以上问题,对于网站的这个问题原因分析及解决措施。最正确的说法应该是?","options":["该问题的产生是由于使用了不安全的协议导致的,为了避免再发生类似的闯题,应对全网站进行安全改造,所有的访问都强制要求使用https","该问题的产生是由于网站开发前没有进行如威胁建模等相关工作或工作不到位,没有找到该威胁并采取相应的消减措施","该问题的产生是由于编码缺陷,通过对网站进行修改,在进行订单付款时进行商品价格验证就可以解决","该问题的产生不是网站的问题,应报警要求寻求警察介入,严惩攻击者即可"],"correctIndex":0,"explanation":"根据题干是采用HTTP的协议导致的,则答案为A。","imageNames":[]},{"id":"wx2026-05-004","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"4","domain":"信息安全技术","stem":"以下哪个选项不是防火墙提供的安全功能?","options":["IP地址欺骗防护","NAT","访问控制","SQL注入攻击防护"],"correctIndex":3,"explanation":"题干中针对的是传统防火墙,而SQL注入防护是WAF的主要功能。","imageNames":[]},{"id":"wx2026-05-005","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"5","domain":"信息安全法规标准","stem":"以下关于可信计算说法错误的是:","options":["可信的主要目的是要建立起主动防御的信息安全保障体系","可信计算机安全评价标准(TCSEC)中第一次提出了可信计算机和可信计算基的概念","可信的整体框架包含终端可信、终端应用可信、操作系统可信、网络互联可信、互联网交易等应用系统可信","可信计算平台出现后会取代传统的安全防护体系和方法"],"correctIndex":3,"explanation":"可信计算平台出现后不会取代传统的安全防护体系和方法。","imageNames":[]},{"id":"wx2026-05-006","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"6","domain":"信息安全技术","stem":"Linux系统对文件的权限是以模式位的形式来表示,对于文件名为test的一个文件,属于admin 组中user用户,以下哪个是该文件正确的模式表示?","options":["- rwx r-x r-x 3 user admin 1024 Sep 13 11:58 test","d rwx r-x r-x 3 user admin 1024 Sep 13 11:58 test","- rwx r-x r-x 3 admin user 1024 Sep 13 11:58 test","rwx r-x r-x 3 admin user1024 Sep 13 11:58 test"],"correctIndex":0,"explanation":"根据题干本题选A。","imageNames":[]},{"id":"wx2026-05-007","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"7","domain":"信息安全技术","stem":"Apache Web服务器的配置文件一般位于/usr／local／apache／conf目录,其中用来控制用户访问Apache目录的配置文件是:","options":["httpd.conf","srL conf","access.conf","Inet.conf"],"correctIndex":0,"explanation":"根据题干本题选择A。","imageNames":[]},{"id":"wx2026-05-008","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"8","domain":"信息安全管理","stem":"应用软件的数据存储在数据库中,为了保证数据安全,应设置良好的数据库防护策略,以下不属于数据库防护策略的是?","options":["安装最新的数据库软件安全补丁","对存储的敏感数据进行安全加密","不使用管理员权限直接连接数据库系统","定期对数据库服务器进行重启以确保数据库运行良好"],"correctIndex":3,"explanation":"D属于运行安全操作,不属于安全防护策略。","imageNames":[]},{"id":"wx2026-05-009","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"9","domain":"信息安全技术","stem":"下列哪项内容描述的是缓冲区溢出漏洞?","options":["通过把SQL命令插入到web表单递交或输入域名或页面请求的查询字符串,最终达到欺骗服务器执行恶意的SQL命令","攻击者在远程WEB页面的HTML代码中插入具有恶意目的的数据,用户认为该页面是可信赖的,但是当浏览器下载该页面,嵌入其中的脚本将被解释执行。","当计算机向缓冲区内填充数据位数时超过了缓冲区本身的容量溢出的数据覆盖在合法数据上","信息技术、信息产品、信息系统在设计、实现、配置、运行等过程中,有意或无意产生的缺陷"],"correctIndex":2,"explanation":"C为缓冲区溢出的正确解释。","imageNames":[]},{"id":"wx2026-05-010","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"10","domain":"信息安全管理","stem":"对恶意代码的预防,需要采取增强安全防范策略与意识等措施,关于以下预防措施或意识,说法错误的是:","options":["在使用来自外部的移动介质前,需要进行安全扫描","限制用户对管理员权限的使用","开放所有端口和服务,充分使用系统资源","不要从不可信来源下载或执行应用程序"],"correctIndex":2,"explanation":"C是错误的,应该是最小化端口和服务。","imageNames":[]},{"id":"wx2026-05-011","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"11","domain":"信息安全技术","stem":"安全专家在对某网站进行安全部署时,调整了Apache的运行权限,从root权限降低为nobody用户,以下操作的主要目的是:","options":["为了提高Apache软件运行效率","为了提高Apache软件的可靠性","为了避免攻击者通过Apache获得root 权限","为了减少Apache上存在的漏洞"],"correctIndex":2,"explanation":"将Apache的运行权限从root权限降低为nobody用户,主要是为了避免攻击者通过Apache获得root权限,从而降低系统的安全风险。A选项运行权限的降低与运行效率无关；B选项与可靠性关系不大；D选项降低运行权限不能直接减少Apache上存在的漏洞。","imageNames":[]},{"id":"wx2026-05-012","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"12","domain":"信息安全保障","stem":"下列关于计算机病毒感染能力的说法不正确的是:","options":["能将自身代码注入到引导区","能将自身代码注入到扇区中的文件镜像","能将自身代码注入文本文件中并执行","能将自身代码注入到文档或模板的宏中代码"],"correctIndex":2,"explanation":"计算机病毒通常是将自身代码注入到可执行文件、引导区、扇区中的文件镜像、文档或模板的宏中代码等,而文本文件本身不能直接执行病毒代码,所以不能将自身代码注入文本文件中并执行。","imageNames":[]},{"id":"wx2026-05-013","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"13","domain":"信息安全技术","stem":"以下哪个是恶意代码采用的隐藏技术:","options":["文件隐藏","进程隐藏","网络连接隐藏","以上都是"],"correctIndex":3,"explanation":"恶意代码采用的隐藏技术包括文件隐藏、进程隐藏、网络连接隐藏等,目的是逃避检测和清除。","imageNames":[]},{"id":"wx2026-05-014","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"14","domain":"信息安全技术","stem":"通过向被攻击者发送大量的ICMP回应请求,消耗被攻击者的资源来进行响应,直至被攻击者再也无法处理有效的网络信息流时,这种攻击称之为:","options":["Land攻击","Smurf 攻击","Ping of Death 攻击","ICMP Flood"],"correctIndex":3,"explanation":"发送大量的ICMP回应请求为ICMP Flood。","imageNames":[]},{"id":"wx2026-05-015","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"15","domain":"信息安全技术","stem":"以下哪个拒绝服务攻击方式不是流量型拒绝服务攻击","options":["Land","UDP Flood","Smurf","Teardrop"],"correctIndex":3,"explanation":"Teardrop属于碎片攻击,不属于流量型拒绝服务攻击。","imageNames":[]},{"id":"wx2026-05-016","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"16","domain":"信息安全技术","stem":"传输控制协议(TCP)是传输层协议,以下关于TCP协议的说法,哪个是正确的?","options":["相比传输层的另外一个协议UDP,TCP既提供传输可靠性,还同时具有更高的效率,因此具有广泛的用途","TCP协议包头中包含了源IP地址和目的IP地址,因此TCP协议负责将数据传送到正确的主机","TCP协议具有流量控制、数据校验、超时重发、接收确认等机制,因此TCP协议能完全替代IP 协议","TCP协议虽然高可靠,但是相比UDP协议机制过于复杂,传输效率要比UDP低"],"correctIndex":3,"explanation":"TCP协议虽然高可靠,但相比UDP协议机制过于复杂,传输效率要比UDP低。A选项TCP相比UDP传输可靠性高,但效率较低；B选项TCP协议包头中不包含源IP地址和目的IP地址,IP地址在IP协议包头中；C选项TCP协议不能完全替代IP协议,IP协议负责数据包的路由和传输,TCP协议负责数据的可靠传输。","imageNames":[]},{"id":"wx2026-05-017","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"17","domain":"信息安全技术","stem":"以下关于UDP协议的说法,哪个是错误的?","options":["UDP具有简单高效的特点,常被攻击者用来实施流量型拒绝服务攻击","UDP协议包头中包含了源端口号和目的端口号,因此UDP可通过端口号将数据包送达正确的程序","相比TCP协议,UDP协议的系统开销更小,因此常用来传送如视频这一类高流量需求的应用数据","UDP协议不仅具有流量控制,超时重发等机制,还能提供加密等服务,因此常用来传输如视频会话这类需要隐私保护的数据"],"correctIndex":3,"explanation":"UDP协议无流量控制,超时重发等机制。","imageNames":[]},{"id":"wx2026-05-018","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"18","domain":"信息安全工程","stem":"有关项目管理,错误的理解是:","options":["项目管理是一门关于项目资金、时间、人力等资源控制的管理科学","项目管理是运用系统的观点、方法和理论,对项目涉及的全部工作进行有效地管理,不受项目资源的约束","项目管理包括对项目范围、时间、成本、质量、人力资源、沟通、风险、采购、集成的管理","项目管理是系统工程思想针对具体项目的实践应用"],"correctIndex":1,"explanation":"项目管理受项目资源的约束。","imageNames":[]},{"id":"wx2026-05-019","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"19","domain":"信息安全技术","stem":"近年来利用DNS劫持攻击大型网站恶性攻击事件时有发生,防范这种攻击比较有效的方法是?","options":["加强网站源代码的安全性","对网络客户端进行安全评估","协调运营商对域名解析服务器进行加固","在网站的网络出口部署应用级防火墙"],"correctIndex":2,"explanation":"协调运营商对域名解析服务器进行加固是DNS防护的主要手段。","imageNames":[]},{"id":"wx2026-05-020","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"20","domain":"信息安全工程","stem":"关于源代码审核,下列说法正确的是:","options":["人工审核源代码审校的效率低,但采用多人并行分析可以完全弥补这个缺点","源代码审核通过提供非预期的输入并监视异常结果来发现软件故障,从而定位可能导致安全弱点的薄弱之处","使用工具进行源代码审核,速度快,准确率高,已经取代了传统的人工审核","源代码审核是对源代码检查分析,检测并报告源代码中可能导致安全弱点的薄弱之处"],"correctIndex":3,"explanation":"D为源代码审核工作内容描述。","imageNames":[]},{"id":"wx2026-05-021","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"21","domain":"信息安全管理","stem":"在戴明环(PDCA)模型中,处置(ACT)环节的信息安全管理活动是:","options":["建立环境","实施风险处理计划","持续的监视与评审风险","持续改进信息安全管理过程"],"correctIndex":3,"explanation":"持续改进信息安全管理过程属于处置(ACT)阶段。","imageNames":[]},{"id":"wx2026-05-022","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"22","domain":"信息安全管理","stem":"信息系统的业务特性应该从哪里获取?","options":["机构的使命","机构的战略背景和战略目标","机构的业务内容和业务流程","机构的组织结构和管理制度"],"correctIndex":2,"explanation":"业务特性从机构的业务内容和业务流程获取。","imageNames":[]},{"id":"wx2026-05-023","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"23","domain":"信息安全管理","stem":"在信息系统设计阶段,“安全产品选择”处于风险管理过程的哪个阶段?","options":["背景建立","风险评估","风险处理","批准监督"],"correctIndex":2,"explanation":"“安全产品选择”是为了进行风险处理。","imageNames":[]},{"id":"wx2026-05-024","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"24","domain":"信息安全管理","stem":"以下关于“最小特权”安全管理原则理解正确的是:","options":["组织机构内的敏感岗位不能由一个人长期负责","对重要的工作进行分解,分配给不同人员完成","一个人有且仅有其执行岗位所足够的许可和权限","防止员工由一个岗位变动到另一个岗位,累积越来越多的权限"],"correctIndex":2,"explanation":"C是“最小特权”的解释；A描述的是轮岗；B描述的是权限分离；D描述的是防止权限蔓延。","imageNames":[]},{"id":"wx2026-05-025","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"25","domain":"信息安全法规标准","stem":"以下哪一项不属于常见的风险评估与管理工具:","options":["基于信息安全标准的风险评估与管理工具","基于知识的风险评估与管理工具","基于模型的风险评估与管理工具","基于经验的风险评估与管理工具"],"correctIndex":3,"explanation":"D基于经验的风险评估工具不存在。","imageNames":[]},{"id":"wx2026-05-026","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"26","domain":"信息安全法规标准","stem":"以下说法正确的是:","options":["验收测试是由承建方和用户按照用户使用手册执行软件验收","软件测试的目的是为了验证软件功能是否正确","监理工程师应按照有关标准审查提交的测试计划,并提出审查意见","软件测试计划开始于软件设计阶段,完成于软件开发阶段"],"correctIndex":2,"explanation":"C是监理工程师的职责。","imageNames":[]},{"id":"wx2026-05-027","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"27","domain":"信息安全保障","stem":"信息系统安全保护等级为3级的系统,应当()年进行一次等级测评?","options":["0.5","1","2","3"],"correctIndex":1,"explanation":"等级保护三级系统一年测评一次,四级系统每半年测评一次。","imageNames":[]},{"id":"wx2026-05-028","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"28","domain":"信息安全保障","stem":"国家科学技术秘密的密级分为绝密级、机密级、秘密级,以下哪项属于绝密级的描述?","options":["处于国际先进水平,并且有军事用途或者对经济建设具有重要影响的","能够局部反应国家防御和治安实力的","我国独有、不受自然条件因素制约、能体现民族特色的精华,并且社会效益或者经济效益显著的传统工艺","国际领先,并且对国防建设或者经济建设具有特别重大影响的"],"correctIndex":3,"explanation":"D为绝密级。","imageNames":[]},{"id":"wx2026-05-029","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"29","domain":"信息安全技术","stem":"关于我国加强信息安全保障工作的总体要求,以下说法错误的是:","options":["坚持积极防御、综合防范的方针","重点保障基础信息网络和重要信息系统安全","创建安全健康的网络环境","提高个人隐私保护意识"],"correctIndex":3,"explanation":"提高个人隐私保护意识不属于（2003年）我国加强信息安全保障工作的总体要求。","imageNames":[]},{"id":"wx2026-05-030","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"30","domain":"信息安全法规标准","stem":"根据《关于加强国家电子政务工程建设项目信息安全风险评估工作的通知》的规定,以下正确的是:","options":["涉密信息系统的风险评估应按照《信息安全等级保护管理办法》等国家有关保密规定和标准进行","非涉密信息系统的风险评估应按照《非涉及国家秘密的信息系统分级保护管理办法》等要求进行","可委托同一专业测评机构完成等级测评和风险评估工作,并形成等级测评报告和风险评估报告","此通知不要求将“信息安全风险评估”作为电子政务项目验收的重要内容"],"correctIndex":2,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-05-031","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"31","domain":"信息安全技术","stem":"某单位信息安全岗位员工,利用个人业余时间,在社交网络平台上向业内同不定期发布信息安全相关知识和前沿动态资讯,这一行为主要符合以下哪一条注册信息安全专业人员（CISP）职业道德准则:","options":["避免任何损害CISP声誉形象的行为","自觉维护公众信息安全,拒绝并抵制通过计算机网络系统泄露个人隐私的行为","帮助和指导信息安全同行提升信息安全保障知识和能力","不在公众网络传播反动、暴力、黄色、低俗信息及非法软件"],"correctIndex":2,"explanation":"该员工利用个人业余时间,在社交网络平台上向业内同行不定期发布信息安全相关知识和前沿动态资讯,这一行为主要符合帮助和指导信息安全同行提升信息安全保障知识和能力的注册信息安全专业人员（CISP）职业道德准则。","imageNames":[]},{"id":"wx2026-05-032","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"32","domain":"信息安全保障","stem":"以下哪一项不是我国信息安全保障的原则:","options":["立足国情,以我为主,坚持以技术为主","正确处理安全与发展的关系,以安全保发展,在发展中求安全","统筹规划,突出重点,强化基础性工作","明确国家、企业、个人的责任和义务,充分发挥各方面的积极性,共同构筑国家信息安全保障体系"],"correctIndex":0,"explanation":"A的正确描述为立足国情,以我为主,坚持以技术和管理并重。","imageNames":[]},{"id":"wx2026-05-033","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"33","domain":"信息安全法规标准","stem":"下列选项中,哪个不是我国信息安全保障工作的主要内容:","options":["加强信息安全标准化工作,积极采用“等同采用、修改采用、制定”等多种方式,尽快建立和完善我国信息安全标准体系","建立国家信息安全研究中心,加快建立国家急需的信息安全技术体系,实现国家信息安全自主可控目标","建设和完善信息安全基础设施,提供国家信息安全保障能力支撑","加快信息安全学科建设和信息安全人才培养"],"correctIndex":1,"explanation":"建立国家信息安全研究中心不是我国信息安全保障工作的主要内容。","imageNames":[]},{"id":"wx2026-05-034","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"34","domain":"信息安全法规标准","stem":"关于信息安全管理,说法错误的是:","options":["信息安全管理是管理者为实现信息安全目标(信息资产的CIA等特性,以及业务运作的持续)而进行的计划、组织、指挥、协调和控制的一系列活动。","信息安全管理是一个多层面、多因素的过程,依赖于建立信息安全组织、明确信息安全角色及职责、制定信息安全方针策略标准规范、建立有效的监督审计机制等多方面非技术性的努力。","实现信息安全,技术和产品是基础,管理是关键。","信息安全管理是人员、技术、操作三者紧密结合的系统工程,是一个静态过程。"],"correctIndex":3,"explanation":"信息安全管理是人员、技术、操作三者紧密结合的系统工程,是一个动态过程。","imageNames":[]},{"id":"wx2026-05-035","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"35","domain":"信息安全法规标准","stem":"以下哪个选项不是信息安全需求的来源?","options":["法律法规与合同条约的要求","组织的原则、目标和规定","风险评估的结果","安全架构和安全厂商发布的病毒、漏洞预警"],"correctIndex":3,"explanation":"安全需求来源于内部驱动,D是外部参考要素,不属于信息安全需求的主要来源。","imageNames":[]},{"id":"wx2026-05-036","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"36","domain":"信息安全工程","stem":"下列关于信息系统生命周期中实施阶段所涉及主要安全需求描述错误的是:","options":["确保采购定制的设备、软件和其他系统组件满足已定义的安全要求","确保整个系统已按照领导要求进行了部署和配置","确保系统使用人员已具备使用系统安全功能和安全特性的能力","确保信息系统的使用已得到授权"],"correctIndex":1,"explanation":"B是错误的,不是按照领导要求进行了部署和配置。","imageNames":[]},{"id":"wx2026-05-037","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"37","domain":"信息安全工程","stem":"下列关于信息系统生命周期中安全需求说法不准确的是:","options":["明确安全总体方针,确保安全总体方针源自业务期望","描述所涉及系统的安全现状,提交明确的安全需求文档","向相关组织和领导人宣贯风险评估准则","对系统规划中安全实现的可能性进行充分分析和论证"],"correctIndex":2,"explanation":"C属于风险评估阶段,不属于题干中的安全需求阶段。","imageNames":[]},{"id":"wx2026-05-038","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"38","domain":"信息安全管理","stem":"小张在某单位是负责事信息安全风险管理方面工作的部门领导,主要负责对所在行业的新人进行基本业务素质培训。一次培训的时候,小张主要负责讲解风险评估工作形式,小张认为: 1.风险评估工作形式包括:自评估和检查评估； 2.自评估是指信息系统拥有、运营或使用单位发起的对本单位信息系统进行风险评估； 3.检查评估是信息系统上级管理部门组织或者国家有关职能部门依法开展的风险评估； 4.对信息系统的风险评估方式只能是“自评估”和“检查评估”中的一个,非此即彼. 请问小张的所述论点中错误的是哪项:","options":["第一个观点","第二个观点","第三个观点","第四个观点"],"correctIndex":3,"explanation":"正确的做法为“自评估”和“检查评估”相互结合和互为补充。","imageNames":[]},{"id":"wx2026-05-039","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"39","domain":"信息安全法规标准","stem":"小李在某单位是负责信息安全风险管理方面工作的部门领导,主要负责对所在行业的新人进行基本业务素质培训,一次培训的时候,小李主要负责讲解风险评估方法。请问小李的所述论点中错误的是哪项:","options":["风险评估方法包括:定性风险分析、定量风险分析以及半定量风险分析","定性风险分析需要凭借分析者的经验和直觉或者业界的标准和惯例,因此具有随意性","定量风险分析试图在计算风险评估与成本效益分析期间收集的各个组成部分的具体数字值,因此更具客观性","半定量风险分析技术主要指在风险分析过程中综合使用定性和定量风险分析技术对风险要素的赋值方式,实现对风险各要素的度量数值化"],"correctIndex":1,"explanation":"定性分析不能靠直觉、不能随意。","imageNames":[]},{"id":"wx2026-05-040","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"40","domain":"信息安全管理","stem":"风险评估工具的使用在一定程度上解决了手动评佑的局限性,最主要的是它能够将专家知识进行集中,使专家的经验知识被广泛使用,根据在风险评估过程中的主要任务和作用愿理,风险评估工具可以为以下几类,其中错误的是:","options":["风险评估与管理工具","系统基础平台风险评估工具","风险评估辅助工具","环境风险评估工具"],"correctIndex":3,"explanation":"通常情况下信息安全风险评估工具不包括环境评估工具。","imageNames":[]},{"id":"wx2026-05-041","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"41","domain":"信息安全法规标准","stem":"为了解风险和控制风险,应当及时进行风险评估活动,我国有关文件指出:风险评估的工作形式可分为自评估和检查评估两种,关于自评估,下面选项中描述错误的是()。","options":["自评估是由信息系统拥有、运营或使用单位发起的对本单位信息系统进行的风险评估","自评估应参照相应标准、依据制定的评估方案和准则,结合系统特定的安全要求实施","自评估应当是由发起单位自行组织力量完成,而不应委托社会风险评估服务机构来实施","周期性的自评估可以在评估流程上适当简化,如重点针对上次评估后系统变化部分进行"],"correctIndex":2,"explanation":"自评估可以委托社会风险评估服务机构来实施。","imageNames":[]},{"id":"wx2026-05-042","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"42","domain":"信息安全管理","stem":"信息安全风险评估是信息安全风险管理工作中的重要环节,在国家网络与信息安全协调小组发布的《关于开展信息安全风险评估工作的意见》(国信办(2006)5号)中,风险评估分为自评估和检查评估两种形式,并对两种工作形式提出了有关工作原则和要求,下面选项中描述正确的是( )。","options":["信息安全风险评估应以自评估为主,自评估和检查评估相互结合、互为补充","信息安全风险评估应以检查评估为主,自评估和检查评估相互结合、互为补充","自评估和检查评估是相互排斥的,单位应慎重地从两种工作形式选择一个,并长期使用","自评估和检查评估是相互排斥的,无特殊理由单位均应选择检查评估,以保证安全效果"],"correctIndex":0,"explanation":"信息安全风险评估应以自评估为主,自评估和检查评估相互结合、互为补充。B选项应以自评估为主,而不是检查评估为主；C选项自评估和检查评估不是相互排斥的,单位可以根据实际情况选择合适的方式；D选项自评估和检查评估不是相互排斥的,单位应根据实际情况选择合适的方式,而不是无特殊理由均应选择检查评估。","imageNames":[]},{"id":"wx2026-05-043","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"43","domain":"信息安全管理","stem":"小王在学习定量风险评估方法后,决定试着为单位机房计算火灾的风险大小,假设单位机房的总价值为200万元人民币,暴露系数(Exposure Factor,EF)是25％,年度发生率(Annualized Rate of Occurrence,ARO)为0.1,那么小王计算的年度预期损失(Annualized Loss Expectancy,ALE)应该是()。","options":["5万元人民币","50万元人民币","2.5万元人民币","25万元人民币"],"correctIndex":0,"explanation":"年度预期损失(ALE) = 单位机房的总价值 × 暴露系数(EF) × 年度发生率(ARO),即ALE = 200万元 × 25％ × 0.1 = 5万元人民币。","imageNames":[]},{"id":"wx2026-05-044","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"44","domain":"信息安全管理","stem":"规范的实施流程和文档管理,是信息安全风险评估结能否取得成果的重要基础,某单位在实施风险评估时,形成了《风险评估方案》并得到了管理决策层的认可,在风险评估实施的各个阶段中,该《风险评估方案》应是如下( )中的输出结果。","options":["风险评估准备阶段","风险要素识别阶段","风险分析阶段","风险结果判定阶段"],"correctIndex":0,"explanation":"《风险评估方案》属于风险评估准备阶段的结果。","imageNames":[]},{"id":"wx2026-05-045","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"45","domain":"信息安全管理","stem":"规范的实施流程和文档管理,是信息安全风险评估能否取得成功的重要基础。某单41位在实施风险评估时,形成了《待评估信息系统相关设备及资产清单》。在风险评估实施的各个阶段中,该《待评估信息系统相关设备及资产清单》应是如下()","options":["风险评估准备","风险要素识别","风险分析","风险结果判定"],"correctIndex":1,"explanation":"风险要素包括资产、威胁、脆弱性、安全措施。","imageNames":[]},{"id":"wx2026-05-046","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"46","domain":"信息安全管理","stem":"风险要素识别是风险评估实施过程中的一个重要步骤,有关安全要素,请选择一个最合适的选项()。","options":["识别面临的风险并赋值","识别存在的脆弱性并赋值","制定安全措施实施计划","检查安全措施有效性"],"correctIndex":1,"explanation":"风险要素包括资产、威胁、脆弱性、安全措施。","imageNames":[]},{"id":"wx2026-05-047","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"47","domain":"信息安全法规标准","stem":"某单位在实施信息安全风险评估后,形成了若干文挡,下面( )中的文挡不应属于风险评估中“风险评估准备”阶段输出的文档。","options":["《风险评估工作计划》,主要包括本次风险评估的目的、意义、范围、目标、组织结构、角色及职责、经费预算和进度安排等内容","《风险评估方法和工具列表》。主要包括拟用的风险评估方法和测试评估工具等内容","《已有安全措施列表》,主要包括经检查确认后的已有技术和管理各方面安全措施等内容","《风险评估准则要求》,主要包括风险评估参考标准、采用的风险分析方法、风险计算方法、资产分类标准、资产分类准则等内容"],"correctIndex":2,"explanation":"风险要素包括资产、威胁、脆弱性、安全措施。","imageNames":[]},{"id":"wx2026-05-048","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"48","domain":"信息安全法规标准","stem":"文档体系建设是信息安全管理体系(ISMS)建设的直接体现,下列说法不正确的是:","options":["组织内的信息安全方针文件、信息安全规章制度文件、信息安全相关操作规范文件等文 档是组织的工作标准,也是ISMS审核的依据","组织内的业务系统日志文件、风险评估报告等文档是对上一级文件的执行和记录,对这些记录不需要保护和控制","组织在每份文件的首页,加上文件修订跟踪表,以显示每一版本的版本号、发布日期、编写人、审批人、主要修订等内容","层次化的文档是ISMS建设的直接体现,文档体系应当依据风险评估的结果建立"],"correctIndex":1,"explanation":"信息安全管理体系运行记录需要保护和控制。","imageNames":[]},{"id":"wx2026-05-049","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"49","domain":"信息安全保障","stem":"某项目的主要内容为建造A类机房,监理单位需要根据《电子信息系统机房设计规范》(GB 50174-2008)的相关要求,对承建单位的施工设计方案进行审核,以下关于监理单位给出的审核意见错误的是:","options":["在异地建立备份机房时,设计时应与主用机房等级相同","由于高端小型机发热量大,因此采用活动地板上送风,下回风的方式","因机房属于A级主机房,因此设计方案中应考虑配备柴油发电机,当市电发生故障时,所配备的柴油发电机应能承担全部负荷的需要","A级主机房应设置洁净气体灭火系统"],"correctIndex":1,"explanation":"散热为下送风、上回风；侧送风、侧回风。","imageNames":[]},{"id":"wx2026-05-050","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"50","domain":"信息安全法规标准","stem":"在工程实施阶段,监理机构依据承建合同、安全设计方案、实施方案、实施记录、国家或地方相关标准和技术指导文件,对信息化工程进行安全____检查,以验证项目是否实现了项目设计目标和安全等级要求。","options":["功能性","可用性","保障性","符合"],"correctIndex":3,"explanation":"题干描述为符合性检查。","imageNames":[]},{"id":"wx2026-05-051","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"51","domain":"信息安全工程","stem":"下系统工程说法错误的是:","options":["系统工程是基本理论的技术实现","系统工程是一种对所有系统都具有普遍意义的科学方法","系统工程是组织管理系统规划、研究、制造、试验、使用的科学方法","系统工程是一种方法论"],"correctIndex":0,"explanation":"系统工程是方法论,不是技术实现。","imageNames":[]},{"id":"wx2026-05-052","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"52","domain":"信息安全管理","stem":"组织建立业务连续性计划（BCP)的作用包括:","options":["在遭遇灾难事件时,能够最大限度地保护组织数据的实时性,完整性和一致性；","提供各种恢复策略选择,尽量减小数据损失和恢复时间,快速恢复操作系统、应用和数据；","保证发生各种不可预料的故障、破坏性事故或灾难情况时,能够持续服务,确保业务系统的不间断运行,降低损失；","以上都是。"],"correctIndex":3,"explanation":"业务连续性计划（BCP）的作用包括在遭遇灾难时保护组织数据的实时性、完整性和一致性；提供恢复策略,减小数据损失和恢复时间,快速恢复系统；保证业务持续服务,降低损失等。","imageNames":[]},{"id":"wx2026-05-053","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"53","domain":"信息安全保障","stem":"业务系统运行中异常错误处理合理的方法是:","options":["让系统自己处理异常","调试方便,应该让更多的错误更详细的显示出来","捕获错误,并抛出前台显示","捕获错误,只显示简单的提示信息,或不显示任何信息"],"correctIndex":3,"explanation":"D为正确的处理方法。","imageNames":[]},{"id":"wx2026-05-054","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"54","domain":"信息安全管理","stem":"以下哪项不是应急响应准备阶段应该做的？","options":["确定重要资产和风险,实施针对风险的防护措施","编制和管理应急响应计划","建立和训练应急响应组织和准备相关的资源","评估事件的影响范围,增强审计功能、备份完整系统"],"correctIndex":3,"explanation":"D描述的是安全事件发生以后,不是应急响应的准备。","imageNames":[]},{"id":"wx2026-05-055","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"55","domain":"信息安全工程","stem":"关于秘钥管理,下列说法错误的是:","options":["科克霍夫原则指出算法的安全性不应基于算法的保密,而应基于秘钥的安全性","保密通信过程中,通信方使用之前用过的会话秘钥建立会话,不影响通信安全","秘钥管理需要考虑秘钥产生、存储、备份、分配、更新、撤销等生命周期过程每一个环节","在网络通信中。通信双方可利用Diffie-He11man协议协商出会话秘钥"],"correctIndex":1,"explanation":"通信方使用之前用过的会话秘钥建立会话,会影响通信安全。","imageNames":[]},{"id":"wx2026-05-056","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"56","domain":"信息安全保障","stem":"以下属于哪一种认证实现方式:用户登录时,认证服务器（Authentication Server,AS)产生一个随机数发送给用户,用户用某种单向算法将自己的口令、种子秘钥和随机数混合计算后作为一次性口令,并发送给AS,AS用同样的方法计算后,验证比较两个口令即可验证用户身份。","options":["口令序列","时间同步","挑战/应答","静态口令"],"correctIndex":2,"explanation":"题干描述的是C的解释。A选项口令序列是按顺序使用预先生成的口令；B选项时间同步是根据时间生成口令；D选项静态口令是固定口令。","imageNames":[]},{"id":"wx2026-05-057","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"57","domain":"信息安全保障","stem":"在对某面向互联网提供服务的某应用服务器的安全检测中发现,服务器上开放了以下几个应用,除了一个应用外其他应用都存在明文传输信息的安全问题,作为一名检测人员,你需要告诉用户对应用进行安全整改以外解决明文传输数据的问题,以下哪个应用已经解决了明文传输数据问题:","options":["SSH","HTTP","FTP","SMTP"],"correctIndex":0,"explanation":"SSH具备数据加密保护的功能。","imageNames":[]},{"id":"wx2026-05-058","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"58","domain":"信息安全技术","stem":"以下哪个属性不会出现在防火墙的访问控制策略配置中？","options":["本局域网内地址","百度服务器地址","HTTP 协议","病毒类型"],"correctIndex":3,"explanation":"病毒类型不会出现在防火墙的访问控制策略中。","imageNames":[]},{"id":"wx2026-05-059","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"59","domain":"信息安全管理","stem":"某linux系统由于root口令过于简单,被攻击者猜解后获得了root口令,发现被攻击后,管理员更改了root口令,并请安全专家对系统进行检测,在系统中发现有一个文件的权限如下 -r-s--x--x 1 test tdst 10704 apr 15 2002/home/test/sh请问以下描述哪个是正确的:","options":["该文件是一个正常文件,test用户使用的shell,test不能读该文件,只能执行","该文件是一个正常文件,是test用户使用的shell,但test用户无权执行该文件","该文件是一个后门程序,该文件被执行时,运行身份root ,test用户间接获得了root 权限","该文件是一个后门程序,由于所有者是test,因此运行这个文件时文件执行权限为test"],"correctIndex":3,"explanation":"Suid位:任何用户执行文件运行权限都为文件所有者的权限","imageNames":[]},{"id":"wx2026-05-060","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"60","domain":"信息安全技术","stem":"某网站为了更好向用户提供服务,在新版本设计时提供了用户快捷登录功能,用户如果使用上次的IP地址进行访问,就可以无需验证直接登录,该功能推出后,导致大量用户账号被盗用,关于以上问题的说法正确的是:","options":["网站问题是由于开发人员不熟悉安全编码,编写了不安全的代码,导致攻击面增大,产生此安全问题","网站问题是由于用户缺乏安全意识导致,使用了不安全的功能,导致网站攻击面增大,产生此问题","网站问题是由于使用便利性提高,带来网站用户数增加,导致网站攻击面增大,产生此安全问题","网站问题是设计人员不了解安全设计关键要素,设计了不安全的功能,导致网站攻击面增大,产生此问题"],"correctIndex":3,"explanation":"设计时提供了用户快捷登录功能,导致大量用户账号被盗用。则答案为D。","imageNames":[]},{"id":"wx2026-05-061","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"61","domain":"信息安全工程","stem":"某购物网站开发项目经过需求分析进入系统设计阶段,为了保证用户账户的安全,项目开发人员决定用户登陆时除了用户名口令认证方式外,还加入基于数字证书的身份认证功能,同时用户口令使用SHA-1算法加密后存放在后台数据库中,请问以上安全设计遵循的是哪项安全设计原则:","options":["最小特权原则","职责分离原则","纵深防御原则","最少共享机制原则"],"correctIndex":2,"explanation":"题目描述的是软件开发的深度防御思想应用。","imageNames":[]},{"id":"wx2026-05-062","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"62","domain":"信息安全工程","stem":"以下关于威胁建模流程步骤说法不正确的是","options":["威胁建模主要流程包括四步:确定建模对象、识别威胁、评估威胁和消减威胁","评估威胁是对威胁进行分析,评估被利用和攻击发生的概率,了解被攻击后资产的受损后果,并计算风险","消减威胁是根据威胁的评估结果,确定是否要消除该威胁以及消减的技术措施,可以通过重新设计直接消除威胁,或设计采用技术手段来消减威胁。","识别威胁是发现组件或进程存在的威胁,它可能是恶意的,威胁就是漏洞。"],"correctIndex":3,"explanation":"威胁就是漏洞是错误的。","imageNames":[]},{"id":"wx2026-05-063","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"63","domain":"信息安全工程","stem":"为了保障系统安全,某单位需要对其跨地区大型网络实时应用系统进行渗透测试,以下关于渗透测试过程的说法不正确的是","options":["由于在实际渗透测试过程中存在不可预知的风险,所以测试前要提醒用户进行系统和数据备份,以便出现问题时可以及时恢复系统和数据","渗透测试从“逆向”的角度出发,测试软件系统的安全性,其价值在于可以测试软件在实际系统中运行时的安全状况","渗透测试应当经过方案制定、信息收集、漏洞利用、完成渗透测试报告等步骤","为了深入发掘该系统存在的安全威胁,应该在系统正常业务运行高峰期进行渗透测试"],"correctIndex":3,"explanation":"工作中不应该在系统正常业务运行高峰期进行渗透测试。","imageNames":[]},{"id":"wx2026-05-064","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"64","domain":"信息安全工程","stem":"有关能力成熟度模型（CMM）错误的理解是","options":["CMM的基本思想是,因为问题是由技术落后引起的,所以新技术的运用会在一定程度上提高质量、生产率和利润率","CMM的思想来源于项目管理和质量管理","CMM是一种衡量工程实施能力的方法,是一种面向工程过程的方法","CMM是建立在统计过程控制理论基础上的,它基于这样一个假设,即“生产过程的高质量和在过程中组织实施的成熟性可以低成本地生产出高质量产品”"],"correctIndex":0,"explanation":"CMM的产生是因为过程控制和管理落后引起的。","imageNames":[]},{"id":"wx2026-05-065","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"65","domain":"信息安全管理","stem":"提高阿帕奇系统(Apache HTTP Server)系统安全性时,下面哪项措施不属于安全配置()?","options":["不在Windows下安装Apache,只在Linux和Unix下安装","安装Apache时,只安装需要的组件模块","不使用操作系统管理员用户身份运行Apache,而是采用权限受限的专用用户账号来运行","积极了解Apache的安全通告,并及时下载和更新"],"correctIndex":0,"explanation":"A不属于安全配置,而属于部署环境选择。","imageNames":[]},{"id":"wx2026-05-066","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"66","domain":"信息安全技术","stem":"某公司开发了一个游戏网站,但是由于网站软件存在漏洞,在网络中传输大数据包时总是会丢失一些数据,如一次性传输大于2000个字节数据时,总是会有3 到5个字节不能传送到对方,关于此案例,可以推断的是（）","options":["该网站软件存在保密性方面安全问题","该网站软件存在完整性方面安全问题","该网站软件存在可用性方面安全问题","该网站软件存在不可否认性方面安全问题"],"correctIndex":1,"explanation":"题干描述的是完整性。","imageNames":[]},{"id":"wx2026-05-067","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"67","domain":"信息安全技术","stem":"信息安全保障是网络时代各国维护国家安全和利益的首要任务,以下哪个国家最早将网络安全上长升为国家安全战略,并制定相关战略计划。","options":["中国","俄罗斯","美国","英国"],"correctIndex":2,"explanation":"美国最早将网络安全上升为国家安全战略,并制定相关战略计划,在网络安全方面起步较早。","imageNames":[]},{"id":"wx2026-05-068","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"68","domain":"信息安全法规标准","stem":"我国党和政府一直重视信息安全工作,我国信息安全保障工作也取得了明显成效,关于我国信息安全实践工作,下面说法错误的是（）","options":["加强信息安全标准化建设,成立了“全国信息安全标准化技术委员会”制订和发布了大批信息安全技术,管理等方面的标准。","重视信息安全应急处理工作,确定由国家密码管理局牵头成立“国家网络应急中心”推动了应急处理和信息通报技术合作工作进展","推进信息安全等级保护工作,研究制定了多个有关信息安全等级保护的规范和标准,重点保障了关系国定安全,经济命脉和社会稳定等方面重要信息系统的安全性","实施了信息安全风险评估工作,探索了风险评估工作的基本规律和方法,检验并修改完善了有关标准,培养和锻炼了人才队伍"],"correctIndex":1,"explanation":"工业和信息化部牵头成立“国家网络应急中心”。","imageNames":[]},{"id":"wx2026-05-069","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"69","domain":"信息安全法规标准","stem":"为保障信息系统的安全,某经营公众服务系统的公司准备并编制一份针对性的信息安全保障方案,并严格编制任务交给了小王,为此,小王决定首先编制出一份信息安全需求描述报告,关于此项工作,下面说法错误的是（）","options":["信息安全需求是安全方案设计和安全措施实施的依据","信息安全需求应当是从信息系统所有者（用户）的角度出发,使用规范化,结构化的语言来描述信息系统安全保障需求","信息安全需求应当基于信息安全风险评估结果,业务需求和有关政策法规和标准的合规性要求得到","信息安全需求来自于该公众服务信息系统的功能设计方案"],"correctIndex":3,"explanation":"信息安全需求来自于法律法规标准符合性要求、业务发展要求、风险评估结果。","imageNames":[]},{"id":"wx2026-05-070","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"70","domain":"信息安全工程","stem":"对系统工程（Systems Engineering,SE）的理解,以下错误的是:","options":["系统工程偏重于对工程的组织与经营管理进行研究","系统工程不属于技术实现,而是一种方法论","系统工程不是一种对所有系统都具有普遍意义的科学方法","系统工程是组织管理系统规划、研究、制造、试验、使用的科学方法"],"correctIndex":2,"explanation":"系统工程是一种对所有系统都具有普遍意义的科学方法。","imageNames":[]},{"id":"wx2026-05-071","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"71","domain":"信息安全法规标准","stem":"关于我国信息安全保障的基本原则,下列说法中不正确的是:","options":["要与国际接轨,积极吸收国外先进经验并加强合作,遵循国际标准和通行做法,坚持管理与技术并重","信息化发展和信息安全不是矛盾的关系,不能牺牲一方以保证另一方","在信息安全保障建设的各项工作中,既要统筹规划,又要突出重点","在国家信息安全保障工作中,要充分发挥国家、企业和个人的积极性,不能忽视任何一方的作用。"],"correctIndex":0,"explanation":"我国信息安全保障首先要遵循国家标准。","imageNames":[]},{"id":"wx2026-05-072","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"72","domain":"信息安全法规标准","stem":"2005年,RFC4301（Request for Comments 4301:Security Architecture for the Internet Protocol）发布,用以取代原先的RFC2401,该标准建议规定了IPsec系统基础架构,描述如何在IP层（IPv4/IPv6）位流量提供安全业务。请问此类RFC系列标准建议是由下面哪个组织发布的（）。","options":["国际标准化组织（International Organization for Standardization,ISO）","国际电工委员会（International Electrotechnical Commission,IEC）","国际电信联盟远程通信标准化组织（ITU Telecommunication Standardization Secctor,ITU-T）","Internet工程任务组（Internet Engineering Task Force,IETF）"],"correctIndex":3,"explanation":"RFC系列标准建议由Internet工程任务组（IETF）发布,国际标准化组织（ISO）发布ISO标准,国际电工委员会（IEC）发布IEC标准,国际电信联盟远程通信标准化组织（ITU - T）发布ITU - T标准。","imageNames":[]},{"id":"wx2026-05-073","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"73","domain":"信息安全法规标准","stem":"GB/T 18336《信息技术安全性评估准则》是测评标准类中的重要标准,该标准定义了保护轮廊（Protection Profile,PP）和安全目标（Security Target,ST）的评估准则,提出了评估保证级（Evaluation Assurance Level,EAL）,其评估保证级共分为（）个递增的评估保证等级。","options":["4","5","6","7"],"correctIndex":3,"explanation":"GB/T 18336《信息技术安全性评估准则》提出的评估保证级（EAL）共分为7个递增的评估保证等级。","imageNames":[]},{"id":"wx2026-05-074","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"74","domain":"信息安全管理","stem":"应急响应是信息安全事件管理的重要内容之一。关于应急响应工作,下面描述错误的是（ ）。","options":["信息安全应急响应,通常是指一个组织为了应对各种安全意外事件的发生所采取的防范措施。即包括预防性措施,也包括事件发生后的应对措施","应急响应工作有其鲜明的特点:具有高技术复杂性与专业性、强突发性、对知识经验的高依赖性,以及需要广泛的协调与合作","应急响应是组织在处置应对突发/重大信息安全事件时的工作,其主要包括两部分工作:安全事件发生时的正确指挥、事件发生后全面总结","应急响应工作的起源和相关机构的成立和1988年11月发生的莫里斯蠕虫病毒事件有关,基于该事件,人们更加重视安全事件的应急处置和整体协调的重要性"],"correctIndex":2,"explanation":"应急响应是安全事件发生前的充分准备和事件发生后的响应处理。","imageNames":[]},{"id":"wx2026-05-075","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"75","domain":"信息安全管理","stem":"PDCERF方法是信息安全应急响应工作中常用的一种方法,它将应急响应分成六个阶段。其中,主要执行如下工作应在哪一个阶段:关闭信息系统、和/或修改防火墙和路由器的过滤规则,拒绝来自发起攻击的嫌疑主机流量、和/或封锁被攻破的登录账号等（）","options":["准备阶段","遏制阶段","根除阶段","检测阶段"],"correctIndex":1,"explanation":"拒绝来自发起攻击的嫌疑主机流量等做法属于遏制阶段的工作。","imageNames":[]},{"id":"wx2026-05-076","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"76","domain":"信息安全技术","stem":"在网络信息系统中对用户进行认证识别时,口令是一种传统但仍然使用广泛的方法,口令认证过程中常常使用静态口令和动态口令。下面找描述中错误的是（ ）","options":["所谓静态口令方案,是指用户登录验证身份的过程中,每次输入的口令都是固定、静止不变的","使用静态口令方案时,即使对口令进行简单加密或哈希后进行传输,攻击者依然可能通过重放攻击来欺骗信息系统的身份认证模块","动态口令方案中通常需要使用密码算法产生较长的口令序列,攻击者如果连续地收集到足够多的历史口令,则有可能预测出下次要使用的口令","通常,动态口令实现方式分为口令序列、时间同步以及挑战/应答等几种类型"],"correctIndex":2,"explanation":"动态口令方案要求其口令不能被收集和预测。","imageNames":[]},{"id":"wx2026-05-077","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"77","domain":"信息安全管理","stem":"“统一威胁管理”是将防病毒,入侵检测和防火墙等安全需求统一管理,目前市场上已经出现了多种此类安全设备,这里“统一威胁管理”常常被简称为（ ）","options":["UTM","FW","IDS","SOC"],"correctIndex":0,"explanation":"“统一威胁管理”简称为UTM,FW是防火墙,IDS是入侵检测系统,SOC是安全运营中心。","imageNames":[]},{"id":"wx2026-05-078","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"78","domain":"信息安全技术","stem":"某网络安全公司基于网络的实时入侵检测技术,动态监测来自于外部网络和内部网络的所有访问行为。当检测到来自内外网络针对或通过防火墙的攻击行为,会及时响应,并通知防火墙实时阻断攻击源,从而进一步提高了系统的抗攻击能力,更有效地保护了网络资源,提高了防御体系级别。但入侵检测技术不能实现以下哪种功能（ ）。","options":["检测并分析用户和系统的活动","核查系统的配置漏洞,评估系统关键资源和数据文件的完整性","防止IP地址欺骗","识别违反安全策略的用户活动"],"correctIndex":2,"explanation":"入侵检测技术是发现安全攻击,不能防止IP欺骗。","imageNames":[]},{"id":"wx2026-05-079","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"79","domain":"信息安全工程","stem":"Gary McGraw 博士及其合作者提出软件安全BSI模型应由三根支柱来支撑,这三个支柱是（ ）。","options":["源代码审核、风险分析和渗透测试","风险管理、安全接触点和安全知识","威胁建模、渗透测试和软件安全接触点","威胁建模、源代码审核和模糊测试"],"correctIndex":1,"explanation":"BSI的模型包括风险管理、安全接触点和安全知识。","imageNames":[]},{"id":"wx2026-05-080","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"80","domain":"信息安全管理","stem":"以下哪一项不是常见威胁对应的消减措施:","options":["假冒攻击可以采用身份认证机制来防范","为了防止传输的信息被篡改,收发双方可以使用单向Hash函数来验证数据的完整性","为了防止发送方否认曾经发送过的消息,收发双方可以使用消息验证码来防止抵赖","为了防止用户提升权限,可以采用访问控制表的方式来管理权限"],"correctIndex":2,"explanation":"消息验证码不能防止抵赖,而是提供消息鉴别、完整性校验和抗重放攻击。","imageNames":[]},{"id":"wx2026-05-081","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"81","domain":"信息安全工程","stem":"以下关于模糊测试过程的说法正确的是:","options":["模糊测试的效果与覆盖能力,与输入样本选择不相关","为保障安全测试的效果和自动化过程,关键是将发现异常进行现场保护记录,系统可能无法恢复异常状态进行后续的测试","通过异常样本重视异常,人工分析异常原因,判断是否为潜在的安全漏洞,如果是安全漏洞,就需要进一步分析其危害性、影响范围和修复建议","对于可能产生的大量异常报告,需要人工全部分析异常报告"],"correctIndex":2,"explanation":"模糊测试效果与输入样本选择相关,A选项错误；为保障测试效果和自动化,应能恢复系统异常状态,B选项错误；对于大量异常报告,可先进行筛选分析,再人工分析重点报告,D选项错误；通过异常样本重现异常,人工分析原因,判断是否为漏洞及分析危害等,C选项正确。","imageNames":[]},{"id":"wx2026-05-082","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"82","domain":"信息安全保障","stem":"国务院信息化工作办公室于2004年7月份下发了《关于做好重要信息系统灾难备份工作的通知》,该文件中指出了我国在灾备工作原则,下面哪项不属于该工作原则（ ）","options":["统筹规划","分组建设","资源共享","平战结合"],"correctIndex":1,"explanation":"灾备工作原则包括统筹规划、资源共享、平战结合。","imageNames":[]},{"id":"wx2026-05-083","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"83","domain":"信息安全法规标准","stem":"关于信息安全管理体系（Information Security Management Systems,ISMS）,描述错误的是（ ）。","options":["信息安全管理体系是组织在整体或特定范围内建立信息安全方针和目标,以及完成这些目标所用方法的体系,包括组织架构、方针、活动、职责及相关实践要素","管理体系（Management Systems）是为达到组织目标的策略、程序、指南和相关资源的框架,信息安全管理体系是管理体系思想和方法在信息安全领域的应用","概念上,信息安全管理体系有广义和狭义之分,狭义的信息安全管理体系是指按照ISO27001标准定义的管理体系,它是一个组织整体管理体系的组成部分","同其他管理体系一样,信息安全管理体系也要建立信息安全管理组织机构,健全信息安全管理制度、构建信息安全技术防护体系和加强人员的安全意识等内容"],"correctIndex":3,"explanation":"同其他管理体系不一样。","imageNames":[]},{"id":"wx2026-05-084","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"84","domain":"信息安全技术","stem":"二十世纪二十年代,德国发明家亚瑟 谢尔比乌斯发明了Engmia密码机,按照密码学发展历史阶段划分,这个阶段属于（）","options":["古典密码阶段。这一阶段的密码专家常常靠直觉和技术来设计密码,而不是凭借推理和证明,常用的密码运算方法包括替代方法和转换方法（）","近代密码发展阶段。这一阶段开始使用机械代替手工计算,形成了机械式密码设备和更进一步的机电密码设备","现代密码学的早起发展阶段。这一阶段以香农的论文“保密系统的通信理论”为理论基础,开始了对密码学的科学探索","现代密码学的近期发展阶段。这一阶段以公钥密码思想为标志,引发了密码学历"],"correctIndex":1,"explanation":"根据密码学发展阶段的知识点,Engmia密码机属于近代密码学发展阶段的产物。","imageNames":[]},{"id":"wx2026-05-085","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"85","domain":"信息安全管理","stem":"小王在学习定量风险评估方法后,决定试着为单位机房计算火灾的风险大小,假设单位机房的总价值为400万元人民币,暴露系数是25%,年度发生率为0.2,那么小王计算的年度预期损失应该是（）","options":["100万元人民币","400万元人民币","20万元人民币","180万元人民币"],"correctIndex":2,"explanation":"年度预期损失（ALE）= 单位机房总价值×暴露系数×年度发生率,即400万元×25%×0.2 = 20万元人民币。","imageNames":[]},{"id":"wx2026-05-086","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"86","domain":"信息安全管理","stem":"小牛在对某公司的信息系统进行风险评估后,因考虑到该业务系统中部分涉及金融交易的功能模块风险太高,他建议该公司以放弃这个功能模块的方式来处理风险,请问这种风险处置的方法是（）","options":["降低风险","规避风险","放弃风险","转移风险"],"correctIndex":1,"explanation":"风险处理方式包括降低、规避、接受和转移四种方式。","imageNames":[]},{"id":"wx2026-05-087","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"87","domain":"信息安全管理","stem":"关于信息安全事件和应急响应的描述不正确的是（）","options":["信息安全事件,是指由于自然或人为以及软、硬件本身缺陷或故障的原因,对信息系统造成危害,或在信息系统内发生对社会造成负面影响事件","至今已有一种信息安全策略或防护措施,能够对信息及信息系统提供绝对的保护,这就使得信息安全事件的发生是不可能的","应急响应是指组织为了应对突发/重大信息安全事件的发生所做的准备,以及在事件发生后所采取的措施","应急响应工作与其他信息安全管理工作将比有其鲜明的特点:具有高技术复杂性志专业性、强突发性、对知识经验的高依赖性,以及需要广泛的协调与合作"],"correctIndex":1,"explanation":"目前不存在一种信息安全策略或防护措施,能够对信息及信息系统提供绝对的保护。","imageNames":[]},{"id":"wx2026-05-088","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"88","domain":"信息安全管理","stem":"目前,很多行业用户在进行信息安全产品选项时,均要求产品需通过安全测评,关于信息安全产品测评的意义,下列说法中不正确的是（）","options":["有助于建立和实施信息安全产品的市场准入制度","对用户采购信息安全产品、设计、建设、使用和管理安全的信息系统提供科学公正的专业指导","对信息安全产品的研究、开发、生产以及信息安全服务的组织提供严格的规范引导和质量监督","打破市场垄断,为信息安全产品发展创造一个良好的竞争环境"],"correctIndex":3,"explanation":"题干中信息安全产品测评的主要目的是安全作用,不是经济作用。","imageNames":[]},{"id":"wx2026-05-089","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"89","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合ISO/TEC27001或GB22080标准要求,其信息安全控制措施通常在以下方面实施常规控制,不包括哪一项（）","options":["信息安全方针、信息安全组织、资产管理","人力资源安全、物理和环境安全、通信和操作管理","访问控制、信息系统获取、开发和维护、符合性","规划与建立ISMS"],"correctIndex":3,"explanation":"“规划与建立ISMS”属于ISMS的工作阶段,不属于措施。","imageNames":[]},{"id":"wx2026-05-090","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"90","domain":"信息安全法规标准","stem":"信息安全事件和分类方法有多种,依据GB/Z 20986-2007《信息安全技术自信安全事件分类分级指南》,信息安全事件分为7个基本类别,描述正确的是（）","options":["有害程序事件、网络攻击事件、信息破坏事件、信息内容安全事件、设备设施故障、灾害性事件和其他信息安全事件","网络贡献事件、拒绝服务攻击事件、信息破坏事件、信息内容安全事件、设备设施故障、灾害性事件和其他信息安全事件","网络攻击事件、网络钓鱼事件、信息破坏事件、信息内容安全事件、设备设施故障、灾害性事件和其他信息安全事件","网络攻击事件、网络扫描窃听事件、信息破坏事件、信息内容安全事件、设备设施故障、灾害性事件和其他信息安全事件"],"correctIndex":0,"explanation":"根据标准知识点,安全事件分为:有害程序事件、网络攻击事件、信息破坏事件、信息内容安全事件、设备设施故障、灾害性事件和其他信息安全事件。","imageNames":[]},{"id":"wx2026-05-091","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"91","domain":"信息安全管理","stem":"王工是某单位的系统管理员,他在某次参加了单位组织的风险管理工作时,根据任务安排,他使用了Nessus工具来扫描和发现数据库服务器的漏洞,根据风险管理的相关理论,他这个是扫描活动属于下面哪一个阶段的工作（）","options":["风险分析","风险要素识别","风险结果判定","风险处理"],"correctIndex":1,"explanation":"漏洞扫描属于风险要素的脆弱性要素识别,风险要素包括资产、威胁、脆弱性、安全措施。","imageNames":[]},{"id":"wx2026-05-092","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"92","domain":"信息安全法规标准","stem":"某集团公司信息安全管理员根据领导安排制定了一下年度的培训工作计划、提出了四大培训任务目标,关于这四个培训任务和目标,作为主管领导,以下选项中正确的是（）","options":["由于网络安全上升到国家安全的高度,因此网络安全必须得到足够的重视,因此安排了对集团公司下属公司的总经理(一把手)的网络安全法培训","对下级单位的网络安全管理人员实施全面安全培训,计划全员通过CISP持证培训以确保人员能力得到保障","对其他信息化相关人员(网络管理员、软件开发人员)也进行安全基础培训,使相关人员对网络安全有所了解","对全体员工安排信息安全意识及基础安全知识培训,安全全员信息安全意识教育"],"correctIndex":0,"explanation":"对主管领导来讲,主要是培训网络安全法。","imageNames":[]},{"id":"wx2026-05-093","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"93","domain":"信息安全管理","stem":"应急响应是信息安全事件管理的重要内容。基于应急响应工作的特点和事件的不规则性,事先创定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生成是在混乱状态中迅速恢复控制,将损失和负面影响降到最低。应急响应方法和过程并不是唯一的。一种被广为接受的应急响应方法是将应急响应管理过程分为6个阶段,为准备→检测→遏制-,根除→恢复→跟踪总结。请问下列说法有关于信息安全应急响应管理过程错误的是( ):","options":["确定重要资产和风险,实施针对风险的防护措施是信息安全应急响应规划过程中最关键的步骤","在检测阶段,首先要进行监测、报告及信息收集","遏制措施可能会因为事件的类别和级别不同而完全不同。常见的遏制措施有完全关闭所有系统、拔掉网线等","应按照应急响应计划中事先制定的业务恢复优先顺序和恢复步骤,顺次恢复相关的系统"],"correctIndex":2,"explanation":"不能完全关闭系统的操作。","imageNames":[]},{"id":"wx2026-05-094","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"94","domain":"信息安全管理","stem":"某市环卫局网络建设是当地政府投资的重点项目。总体目标就是用于交换式千兆以太网为主干,超五类双绞线作水平布线,由大型交换机和路由器连通几个主要的工作区域,在各区域建立一个闭路电视监控系统,再把信号通过网络传输到各监控中心,其中对交换机和路由器进行配置是网络安全中的一个不可缺少的步骤,下面对于交换机和路由器的安全配置,操作错误的是( )","options":["保持当前版本的操作系统,不定期更新交换机操作系统补丁","控制交换机的物理访问端口,关闭空闲的物理端口","带外管理交换机,如果不能实现的话,可以利用单独的VLAN号进行带内管理","安全配置必要的网络服务,关闭不必要的网络服务"],"correctIndex":0,"explanation":"交换机和路由器的管理包括了版本更新,也包括了补丁管理。","imageNames":[]},{"id":"wx2026-05-095","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"95","domain":"信息安全技术","stem":"在某信息系统的设计中,用户登陆过程是这样的:（1）用户通过HTTP协议访问信息系统；（2）用户在登陆页面输入用户名和口令；（3）信息系统在服务器端检查用户名和密码的正确性,如果正确,则鉴别完成。可以看出,这个鉴别过程属于（）。","options":["单向鉴别","双向鉴别","三向鉴别","第三方鉴别"],"correctIndex":0,"explanation":"用户输入用户名和口令,信息系统在服务器端检查,是单向鉴别,双向鉴别是双方互相鉴别,三向鉴别和第三方鉴别涉及更多方,A选项正确。","imageNames":[]},{"id":"wx2026-05-096","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"96","domain":"信息安全技术","stem":"PKI的主要理论基础是（）。","options":["对称密码算法","公钥密码算法","量子密码","摘要算法"],"correctIndex":1,"explanation":"PKI（公钥基础设施）的主要理论基础是公钥密码算法,利用公钥和私钥进行加密、解密和数字签名等操作,对称密码算法、量子密码、摘要算法不是PKI的主要理论基础,B选项正确。","imageNames":[]},{"id":"wx2026-05-097","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"97","domain":"信息安全管理","stem":"组织第一次建立业务连续性计划时,最为重要的活动是:","options":["制定业务连续性策略","进行业务影响分析","进行灾难恢复演练","构建灾备系统"],"correctIndex":0,"explanation":"策略是BCP的顶层设计,若无策略,后续活动可能缺乏方向。","imageNames":[]},{"id":"wx2026-05-098","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"98","domain":"信息安全管理","stem":"防止非法授权访问数据文件的控制措施,哪项是最佳的方式:","options":["自动文件条目","磁带库管理程序","访问控制软件","锁定库"],"correctIndex":2,"explanation":"访问控制软件可以根据用户的身份、权限等对数据文件进行访问控制,防止非法授权访问,是最佳方式。自动文件条目、磁带库管理程序、锁定库等都不能像访问控制软件那样灵活、有效地控制对数据文件的访问,C选项正确。","imageNames":[]},{"id":"wx2026-05-099","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"99","domain":"信息安全工程","stem":"白盒测试的具体优点是:","options":["其检查程序是否可与系统的其他部分一起正常运行","在不知程序内部结构下确保程序的功能性操作有效","其确定程序准确性成某程序的特定逻辑路径的状态","其通过严格限制访问主机系统的受控或虚拟环境中执行对程序功能的检查"],"correctIndex":2,"explanation":"白盒测试是基于程序的内部结构进行测试,其具体优点是可以确定程序准确性或某程序的特定逻辑路径的状态,A选项是系统测试的优点,B选项是黑盒测试的优点,D选项描述的是在受控或虚拟环境中执行测试的一种方式,不是白盒测试的优点,C选项正确。","imageNames":[]},{"id":"wx2026-05-100","setId":"wx2026-05","setName":"CISP 复习题（3）","sourceNumber":"100","domain":"信息安全管理","stem":"为某航空公司的订票系统设计业务连续性计划时,最适用于异地数据转移/备份的方法是:","options":["文件映像处理","电子链接","硬盘镜像","热备援中心配置"],"correctIndex":3,"explanation":"热备援中心配置是在异地建立一个与主中心相似的备份中心,实时同步数据,当主中心发生灾难时,可快速切换到备份中心,继续提供服务,适用于异地数据转移/备份,保证业务的连续性。文件映像处理、电子链接、硬盘镜像等方法在异地数据转移/备份和业务连续性保障方面不如热备援中心配置全面和可靠,D选项正确。","imageNames":[]}]},{"id":"wx2026-06","name":"CISP 复习题（4）","subtitle":"原卷顺序 · 有答案+解析","sourceFile":"CISP复习题（4）100题（有答案）-已审+解析.docx","questionCount":99,"questions":[{"id":"wx2026-06-001","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"1","domain":"信息安全法规标准","stem":"小陈学习了有关信息安全管理体系的内容后,认为组织建立信息安全管理体系并持续运行,比起简单地实施信息安全管理,有更大的作用,他总结了四个方面的作用,其中总结错误的是（ ）","options":["可以建立起文档化的信息安全管理规范,实现有“法”可依,有章可循,有据可查","可以强化员工的信息安全意识,建立良好的安全作业习惯,培育组织的信息安全企业文化","可以增强客户、业务伙伴、投资人对该组织保障其业务平台和数据信息的安全信心","可以深化信息安全管理,提高安全防护效果,使组织通过国际标准化组织的ISO 9001认证"],"correctIndex":3,"explanation":"ISO 9001是质量管理体系标准,与信息安全管理体系（ISMS）的ISO 27001无关。建立ISMS可通过ISO 27001认证,而非ISO 9001。","imageNames":[]},{"id":"wx2026-06-002","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"2","domain":"信息安全技术","stem":"随着“互联网”概念的普及,越来越多的新兴住宅小区引入了“智能楼宇”的理念,某物业为提供高档次的服务,防止网络主线路出现故障,保证小区内网络服务的可用,稳定、高效,计划通过网络冗余配置的是（）。","options":["接入互联网时,同时采用不同电信运营商线路,相互备份且互不影响。","核心层、汇聚层的设备和重要的接入层设备均应双机设备。","规划网络IP地址,制定网络IP地址分配策略","保证网络带宽和网络设备的业务处理能力具备冗余空间,满足业务高峰期和业务发展需求"],"correctIndex":0,"explanation":"选项A、B、D都与网络冗余相关,选项A为网络链路冗余；选项B为网络设备冗余,选选项D为网络性能冗余,针对网络的 “承载能力” 设计冗余,保障网络高效性（避免拥堵）和可扩展性。选项C是网络规划与管理,目的是便于管理、避免冲突。 如果题目为“不属于网络冗余的”则选C。但题目强调的是“防止网络主线路出现故障”,而主线路更多指对外连接的通信链路,最符合的题意的选项为A。","imageNames":[]},{"id":"wx2026-06-003","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"3","domain":"信息安全管理","stem":"小陈自学了风评的相关国家准则后,将风险的公式用图形来表示,下面F1,F2,F3,F4分别代表某种计算函数,四张图中,那个计算关系正确","options":["选项 A（见题图）","选项 B（见题图）","选项 C（见题图）","选项 D（见题图）"],"correctIndex":2,"explanation":"依据GB/T 20984-2007《信息安全风险评估规范》","imageNames":["wx2026-06-01.png"]},{"id":"wx2026-06-004","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"4","domain":"信息安全技术","stem":"在网络信息系统建设中部署防火墙,往往用于提高内部网络的安全防护能力。某公司准备部署一台防火墙来保护内网主机,下列选项中部署位置正确的是（）","options":["内网主机——交换机——防火墙——外网","防火墙——内网主机——交换机——外网","内网主机——防火墙——交换机——外网","防火墙——交换机——内网主机——外网"],"correctIndex":0,"explanation":"防火墙应部署在内网与外网之间,形成保护屏障。正确顺序为:内网主机→交换机→防火墙→外网。","imageNames":["wx2026-06-03.png"]},{"id":"wx2026-06-005","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"5","domain":"信息安全管理","stem":"访问控制是对用户或用户访问本地或网络上的域资源进行法令一种机制。在Windows2000以后的操作系统版本中,访问控制是一种双重机制,它对用户的授权基于用户权限和对象许可,通常使用ACL、访问令牌和授权管理器来实现访问控制功能。以下选项中,对windows操作系统访问控制实现方法的理解错误的是（）","options":["ACL只能由管理员进行管理","ACL是对象安全描述的基本组成部分,它包括有权访问对象的用户和级的SID","访问令牌存储着用户的SID,组信息和分配给用户的权限","通过授权管理器,可以实现基于角色的访问控制"],"correctIndex":0,"explanation":"ACL可由管理员或授权用户管理,非仅管理员,选项A错误。","imageNames":[]},{"id":"wx2026-06-006","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"6","domain":"信息安全技术","stem":"在现实的异构网络环境中,越来越多的信息需要实现安全的互操作。即进行跨域信息交换和处理。Kerberos协议不仅能在域内进行认证,也支持跨域认证,下图显示的是Kerberos协议实现跨域认证的7个步骤,其中有几个步骤出现错误,图中错误的描述正确的是:","options":["步骤1和步骤2发生错误,应该向本地AS请求并获得远程TGT","步骤3和步骤4发生错误,应该向本地TGS请求并获得远程TGT","步骤5和步骤6发生错误,应该向远程AS请求并获得远程TGT","步骤5和步骤6发生错误,应该向远程TGS请求并获得远程SGT"],"correctIndex":1,"explanation":"用本地的TGS做代理去获取远程的TGT","imageNames":["wx2026-06-04.png"]},{"id":"wx2026-06-007","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"7","domain":"信息安全工程","stem":"某黑客通过分析和整理某报社记者小张的博客,找到一些有用的信息,通过伪装的新闻线索,诱使其执行木马程序,从而控制了小张的电脑,并以她的电脑为攻击的端口,使报社的局域网全部感染木马病毒,为防范此类社会工程学攻击,报社不需要做的是（）","options":["加强信息安全意识培训,提高安全防范能力,了解各种社会工程学攻击方法,防止受到此类攻击","建立相应的安全相应应对措施,当员工受到社会工程学的攻击,应当及时报告","教育员工注重个人隐私保护","减少系统对外服务的端口数量,修改服务旗标"],"correctIndex":3,"explanation":"减少对外服务端口和修改服务旗标属于技术防护,与防范社会工程学攻击（如伪装诱导）无关","imageNames":[]},{"id":"wx2026-06-008","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"8","domain":"信息安全技术","stem":"2016年9月,一位安全研究人员在Google Cloud IP上通过扫描,发现了完整的美国路易斯安邦州290万选民数据库。这套数据库中囊括了诸如完整姓名、电子邮箱地址、性别与种族、选民状态、注册日期与编号、正党代名和密码,以防止攻击者利用以上信息进行（）攻击。","options":["默认口令","字典","暴力","XSS"],"correctIndex":1,"explanation":"数据库包含常用密码,攻击者可利用字典攻击尝试常见密码组合。","imageNames":[]},{"id":"wx2026-06-009","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"9","domain":"信息安全技术","stem":"下图中描述网络动态安全的P2DR模型,这个模型经常使用图形的形式来表达的下图空白处应填（）","options":["策略","方针","人员","项目"],"correctIndex":0,"explanation":"P2DR模型（策略、防护、检测、响应）中,策略是核心,指导其他环节。","imageNames":["wx2026-06-05.png"]},{"id":"wx2026-06-010","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"10","domain":"信息安全技术","stem":"如图所示,主机A向主机B发出的数据采用AH或者ESP的传输模式对流量进行保护时,主机A和主机B的IP地址在应该在下列哪个范围？","options":["10.0.0.0~10.255.255.255","172.16.0.0~172.31.255.255","192.168.0.0~192.168.255.255","不在上述范围内"],"correctIndex":3,"explanation":"AH或ESP传输模式用于公网IP,非私有地址范围（A、B、C为私有地址）。","imageNames":["wx2026-06-06.png"]},{"id":"wx2026-06-011","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"11","domain":"信息安全管理","stem":"小王是某大学计算机科学与技术专业的学生,最近因为生病缺席了几堂信息安全课程,这几次课的内容是自主访问控制与强制访问控制,为了赶上课程进度,他向同班的小李借来课堂笔记,进行自学。而小李在听课时由于经常走神,所以笔记中会出现一些错误。下列选项是小李笔记中关于强制访问控制模型的内容,其中出现错误的选项是（）","options":["强制访问控制是指主体和客体都有一个固定的安全属性,系统用该安全属性来决定一个主体是否可以访问某个客体","安全属性是强制性的规定,它由安全管理员或操作系统根据限定的规则确定,不能随意修改","系统通过比较客体和主体的安全属性来决定主体是否可以访问客体","它是一种对单个用户执行访问控制的过程控制措施"],"correctIndex":3,"explanation":"强制访问控制是系统级控制,非对单个用户的过程控制,选项D错误。","imageNames":[]},{"id":"wx2026-06-012","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"12","domain":"信息安全保障","stem":"下图排序你认为那个是正确的:","options":["1是主体,2是客体,3是实施,4是决策","1是客体,2是主体3是决策,4是实施","1实施,2是客体3是主题,4是决策","1是主体,2是实施3是客体,4是决策"],"correctIndex":3,"explanation":"公开题库未附解析。","imageNames":["wx2026-06-07.png"]},{"id":"wx2026-06-013","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"13","domain":"信息安全技术","stem":"某社交网站的用户点击了该网站上的一个广告。该广告含有一个跨站脚本,会将他的浏览器定向到旅游网站,旅游网站则获得了他的社交网络信息。虽然该用户没有主动访问该旅游网站,但旅游网站已经截获了他的社交网络信息（还有他的好友们的信息）,于是犯罪分子便可以躲藏在社交网站的广告后面,截获用户的个人信息了,这种向Web页面插入恶意html代码的攻击方式称为（）","options":["分布式拒绝服务攻击","跨站脚本攻击","SQL注入攻击","缓冲区溢出攻击"],"correctIndex":1,"explanation":"跨站脚本攻击（XSS）通过注入恶意HTML代码窃取用户信息。","imageNames":["wx2026-06-08.png"]},{"id":"wx2026-06-014","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"14","domain":"信息安全工程","stem":"模糊测试,也称Fuzz测试,是一种通过提供非预期的输入并监视异常结果来发现软件故障的方法。下面描述正确的是（）","options":["模糊测试本质上属于黑盒测试","模糊测试本质上属于白盒测试","模糊测试有时属于黑盒测试,有时属于白盒测试,取决于其使用的测试方法","模糊测试既不属于黑盒测试,也不属于白盒测试"],"correctIndex":0,"explanation":"模糊测试通过非预期输入发现故障,属于黑盒测试,无需了解内部代码。","imageNames":[]},{"id":"wx2026-06-015","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"15","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合ISO/IEC 27001或GB/T22080标准要求,其信息安全控制措施通常需要在人力资源安全方面实施常规控制,人力资源安全划分为3个控制阶段,不包括哪一项（）","options":["任用之前","任用中","任用终止或变化","任用后"],"correctIndex":3,"explanation":"人力资源安全分任用前、任用中、任用终止或变化三个阶段,无“任用后”。","imageNames":[]},{"id":"wx2026-06-016","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"16","domain":"信息安全工程","stem":"下图是安全测试人员连接某远程主机时的操作界面,请您仔细分析该图,下面分析推理正确的是（）","options":["安全测试人员链接了远程服务器的220端口","安全测试人员的本地操作系统是Linux","远程服务器开启了FTP服务,使用的服务器软件名FTP Sｅｒｖｅｒ","远程服务器的操作系统是ｗｉｎｄｏｗｓ系统"],"correctIndex":3,"explanation":"公开题库未附解析。","imageNames":["wx2026-06-09.png"]},{"id":"wx2026-06-017","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"17","domain":"信息安全技术","stem":"某信息安全公司的团队对某款名为“红包快抢”的外挂进行分析发现此外挂是一个典型的木马后门,使黑客能够获得受害者电脑的访问权,该后门程序为了达到长期驻留在受害者的计算机中,通过修改注册表启动项来达到后门程序随受害者计算机系统启动而启动为防范此类木马的攻击,以下做法无用的是（）","options":["不下载、不执行、不接收来历不明的软件和文件","不随意打开来历不明的邮件,不浏览不健康不正规的网站","使用共享文件夹","安装反病毒软件和防火墙,安装专门的木马防范软件"],"correctIndex":2,"explanation":"使用共享文件夹可能增加木马传播风险,与防范木马攻击无关。","imageNames":[]},{"id":"wx2026-06-018","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"18","domain":"信息安全管理","stem":"小华在某电子商务公司工作,某天他在查看信息系统设计文档时,发现其中标注该信息系统的RPO（恢复点目标）指标为3小时。请问这意味着（）","options":["该信息系统发生重大安全事件后,工作人员应在3小时内到位,完成问题定位和应急处理工作","该信息系统发生重大安全事件后,工作人员应在3小时内完整应急处理工作并恢复对外运行","该信息系统发生重大安全事件后,工作人员在完成处置和灾难恢复工作后,系统至少能提供3小时的紧急业务服务能力","该信息系统发生重大安全事件后,工作人员在完成处置和灾难恢复工作后,系统至多能丢失3小时的业务数据"],"correctIndex":3,"explanation":"RPO（恢复点目标）指灾难后最大可接受数据丢失时间,3小时即最多丢失3小时数据。","imageNames":[]},{"id":"wx2026-06-019","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"19","domain":"信息安全管理","stem":"陈工学习了信息安全风险的有关知识,了解到信息安全风险的构成过程,有五个方面:起源、方式、途径、受体和后果,他画了下面这张图来描述信息安全风险的构成过程,图中空白处应填写？","options":["信息载体","措施","脆弱性","风险评估"],"correctIndex":2,"explanation":"风险构成过程为:威胁利用脆弱性,通过途径影响受体,导致后果。空白处为“脆弱性”。","imageNames":["wx2026-06-10.png"]},{"id":"wx2026-06-020","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"20","domain":"信息安全技术","stem":"Kerberos协议是一种集中访问控制协议,他能在复杂的网络环境中,为用户提供安全的单点登录服务。单点登录是指用户在网络中进行一次身份认证,便可以访问其授权的所有网络资源,而不在需要其他的认证过程,实质是消息M在多个应用系统之间的传递或共享。其中消息M是指以下选项中的()","options":["安全凭证","用户名","加密密钥","会话密钥"],"correctIndex":0,"explanation":"Kerberos单点登录中,消息M为安全凭证（如票据）,用于多系统间传递认证信息。","imageNames":[]},{"id":"wx2026-06-021","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"21","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合ISO/IEC 27001或GB/T22080标准要求。其信息安全控制措施通常需要在物理和环境安全方面实施常规控制。物理和环境安全领域包括安全区域和设备安全两个控制目标。安全区域的控制目标是防止对组织场所和信息的未授权物理访问、损坏和干扰。关键或敏感的信息及信息处理设施应放在安全区域内并受到相应保护。该目标可以通过以下控制措施来实现,不包括哪一项","options":["物理安全边界、物理入口控制","办公室、房间和设施的安全保护。外部和环境威胁的安全防护","在安全区域工作。公共访问、交接区安全","人力资源安全"],"correctIndex":3,"explanation":"人力资源安全属组织安全领域,非物理和环境安全目标。","imageNames":[]},{"id":"wx2026-06-022","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"22","domain":"信息安全法规标准","stem":"风险分析师风险评估工作的一个重要内容,GB/T 20984-2007在资料性附录中给出了一种矩阵法来计算信息安全风险大小,如下图所示,图中括号应填那个？","options":["安全资产价值大小等级","脆弱性严重程度等级","安全风险隐患严重等级","安全事件造成损失大小"],"correctIndex":3,"explanation":"依据GB/T 20984-2007《信息安全风险评估规范》,选D","imageNames":["wx2026-06-11.png"]},{"id":"wx2026-06-023","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"23","domain":"信息安全管理","stem":"关于信息安全管理体系的作用,下面理解错误的是","options":["对内而言,有助于建立起文档化的信息安全管理规范,实现有“法”可依,有据可查","对内而言,是一个光花钱不挣钱的事情,需要组织通过其他方法收入来弥补投入","对外而言,有助于使各科室相关方对组织充满信心","对外而言,规范工作流程要求,帮助界定双方各自信息安全责任"],"correctIndex":1,"explanation":"ISMS可提升组织效率、降低风险,长期看非“光花钱不挣钱”,选项B错误。","imageNames":[]},{"id":"wx2026-06-024","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"24","domain":"信息安全法规标准","stem":"关于补丁安装时应注意的问题,以下说法正确的是","options":["在补丁安装部署之前不需要进行测试,因为补丁发布之前厂商已经经过了测试","补丁的获取有严格的标准,必须在厂商的官网上获取","信息系统打补丁时需要做好备份和相应的应急措施","补丁安装部署时关闭和重启系统不会产生影响"],"correctIndex":2,"explanation":"补丁安装前需测试,避免系统崩溃；获取应通过官方渠道；安装时需备份并准备应急措施。","imageNames":[]},{"id":"wx2026-06-025","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"25","domain":"信息安全管理","stem":"某电子商务网站架构设计时,为了避免数据误操作,在管理员进行订单删除时,需要由审核员进行审核后该删除操作才能生效,这种设计是遵循了发下哪个原则","options":["权限分离原则","最小的特权原则","保护最薄弱环节的原则","纵深防御的原则"],"correctIndex":0,"explanation":"权限分离原则要求操作需多人审核,避免单点风险。","imageNames":[]},{"id":"wx2026-06-026","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"26","domain":"信息安全保障","stem":"实体身份鉴别的方法多种多样,且随着技术的进步,鉴别方法的强度不断提高,常见的方法有指令鉴别、令牌鉴别、指纹鉴别等。如图,小王作为合法用户使用自己的账户进行支付、转账等操作。这说法属于下列选项中的（）","options":["实体所知的鉴别方法","实体所有的鉴别方法","实体特征的鉴别方法","实体所见的鉴别方法"],"correctIndex":2,"explanation":"使用支付方式属于“实体特征的鉴别方法”。","imageNames":["wx2026-06-12.png"]},{"id":"wx2026-06-027","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"27","domain":"信息安全管理","stem":"定量风险分析是从财务数字上对安全风险进行评估,得出可以量化的风险分析结果,准确度量风险的可以性和损失量。小王采用该方法来为单位机房计算火灾风险大小,假设单位机房的总价值为200万元人民币,暴露系数（ExposureFactor,EF）是x,年度发生率（Annual izod Eato of Occurrence,ARO）为0.1,而小王计算的年度预期损失（Annual izod Loss Erpectancy,ALE）值为5万元人民币,由此,x值应该是","options":["2.5%","25%","5%","50%"],"correctIndex":1,"explanation":"ALE = 资产价值 × EF × ARO → 5万 = 200万 × EF × 0.1 → EF = 25%。","imageNames":[]},{"id":"wx2026-06-028","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"28","domain":"信息安全管理","stem":"关于Kerberos认证协议,以下说法错误的是:","options":["只要用户拿到了认证服务器（AS）发送的票据许可票据（TGT）并且该TGT没有过期,就可以使用该TGT通过票据授权服务器（TGS）完成到任一个服务器的认证而不必重新输入密码","认证服务器（AS）和票据授权服务器（TGS）是集中式管理,容易形成瓶颈,系统的性能和安全也严重依赖于AS和TGS的性能和安全","该协议通过用户获得票据许可票据、用户获得服务许可票据、用户获得服务三个阶段,仅支持服务器对用户的单向认证","该协议是一种基于对称密码算法的网络认证协议,随用户数量增加,密钥管理较复杂"],"correctIndex":2,"explanation":"Kerberos支持双向认证（用户↔服务器）,非仅服务器对用户单向认证。","imageNames":[]},{"id":"wx2026-06-029","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"29","domain":"信息安全技术","stem":"kerberos协议是常用的集中访问控制协议,通过可信第三的认证服务,减轻应用Kerberos的运行环境由秘钥分发中心（KDC）、应用服务器和客户端三个部分组成,认证服务器AS和票据授权服务器","options":["1——2——3","3——2——1","2——1——3","3——1——2"],"correctIndex":3,"explanation":"首先Kerberos获得票据许可票据,用户向认证服务器AS申请票据许可票据；然后Kerberos获得服务许可票据,用户凭借票据许可票据向票据授权服务器TGS申请服务许可票据；最后Kerberos获得服务,用户凭借服务许可票据向应用服务器申请服务。所以顺序是(3)-(1)-(2)。","imageNames":["wx2026-06-13.png"]},{"id":"wx2026-06-030","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"30","domain":"信息安全管理","stem":"某单位系统管理员对组织内核心资源的访问制定访问策略,针对每个用户指明能够访问的资源,对于不在指定资源列表中的对象不允许访问。该访问控制策略属于以下哪一种:","options":["强制访问控制","基于角色的访问控制","自主访问控制","基于任务的访问控制"],"correctIndex":2,"explanation":"自主访问控制（DAC）允许用户指定访问权限,符合题干描述。","imageNames":[]},{"id":"wx2026-06-031","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"31","domain":"信息安全技术","stem":"由于Internet的安全问题日益突出,基于TCP/IP协议,相关组织和专家在协议的不同层次设计了相应的安全通信协议,用来保障网络各层次的安全。其中,属于或依附于传输层的安全协议是（）","options":["PP2P","L2TP","SSL","IPSec"],"correctIndex":2,"explanation":"SSL/TLS工作于传输层,提供端到端安全通信。","imageNames":[]},{"id":"wx2026-06-032","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"32","domain":"信息安全保障","stem":"根据Bell-LaPedula模型安全策略,下图中写和读操作正确的是（ ）","options":["可读可写","可读不可写","可写不可读","不可读不可写"],"correctIndex":1,"explanation":"左半部分密级相同,NUC范畴小,属于高级向低级别访问,依据“向下读,向上写”原则,因此不可写,右边部分:机密级高于密秘级,范畴相同,属于高级别向低级别访问,因此可以向下读。","imageNames":["wx2026-06-14.png"]},{"id":"wx2026-06-033","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"33","domain":"信息安全技术","stem":"防火墙是网络信息系统建设中常采用的一类产品,它在内外网隔离方面的作用是（）。","options":["既能物理隔离,又能逻辑隔离","能物理隔离,但不能逻辑隔离","不能物理隔离,但是能逻辑隔离","不能物理隔离,也不能逻辑隔离"],"correctIndex":2,"explanation":"防火墙通过逻辑隔离（如访问控制）保护内网,无法物理隔离。","imageNames":[]},{"id":"wx2026-06-034","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"34","domain":"信息安全管理","stem":"张主任的计算机使用Windows7操作系统,他常登陆的用户名为zhang,张主任给他个人文件夹设置了权限为只有zhang这个用户有权访问这个目录,管理员在某次维护中无意将zhang这个用户删除了,随后又重新建了一个用户名为zhang,张主任使用zhang这个用户登录系统后,发现无法访问他原来的个人文件夹,原因是:","options":["任何一个新建用户都需要经过授权才能访问系统中的文件","Windows7不认为新建立的用户zhang与原来用户zhang是同一个用户,因此无权访问","用户被删除后,该用户创建的文件夹也会自动删除,新建用户找不到原来用户的文件夹,因此无法访问","新建的用户zhang会继承原来用户的权限,之所以无权访问是因为文件夹经过了加密"],"correctIndex":1,"explanation":"Windows用户SID随删除重建变化,新用户与原用户不同,无法继承权限。","imageNames":[]},{"id":"wx2026-06-035","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"35","domain":"信息安全管理","stem":"以下关于Windows系统的账号存储管理机制（Security Accounts Manager）的说法哪个是正确的:","options":["存储在注册表中的账号数据是管理员组用户都可以访问,具有较高的安全性","存储在注册表中的账号数据只有administrator账户才有权访问,具有较高的安全性","存储在注册表中的账号数据任何用户都可以直接访问,灵活方便","存储在注册表中的账号数据有只有System账户才能访问,具有较高的安全性"],"correctIndex":3,"explanation":"Windows账号数据存储在注册表中,仅System账户可访问,安全性高。","imageNames":[]},{"id":"wx2026-06-036","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"36","domain":"信息安全法规标准","stem":"ISO9001-2000标准在制定、实施质量管理体系以及改进其有效性时采用过程方法,通过满足顾客要求增进顾客满意。下图是关于过程方法的示意图,图中括号空白处应填写（）","options":["策略","管理者","组织","活动"],"correctIndex":3,"explanation":"ISO9001过程方法中,括号内通常为“活动","imageNames":["wx2026-06-15.png"]},{"id":"wx2026-06-037","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"37","domain":"信息安全法规标准","stem":"设计信息系统安全保障方案时,以下哪个做法是错误的:","options":["要充分切合信息安全需求并且实际可行","要充分考虑成本效益,在满足合规性要求和风险处置要求的前提下,尽量控制成本","要充分采取新技术,在使用过程中不断完善成熟,精益求精,实现技术投入保值要求","要充分考虑用户管理和文化的可接受性,减少系统方案实施障碍"],"correctIndex":2,"explanation":"设计安全方案应优先采用成熟技术,避免过度依赖未经验证的新技术。","imageNames":[]},{"id":"wx2026-06-038","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"38","domain":"信息安全管理","stem":"Windows文件系统权限管理访问控制列表（Access Control List,ACL）机制,以下哪个说法是错误的:","options":["安装Windows系统时要确保文件格式使用的是NTFS,因为Windows的ACL机制需要NTFS文件格式的支持","由于Windows操作系统自身有大量的文件和目录,因此很难对每个文件和目录设置严格的访问权限,为了使用上的便利,Windows上的ACL存在默认设置安全性不高的问题","Windows的ACL机制中,文件和文件夹的权限是与主体进行关联的,即文件夹和文件的访问权限信息是写在用户数据库中","由于ACL具有很好的灵活性,在实际使用中可以为每一个文件设定独立用户的权限"],"correctIndex":2,"explanation":"Windows ACL中,文件权限与客体（文件）关联,存储在文件ACL中,非用户数据库。","imageNames":[]},{"id":"wx2026-06-039","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"39","domain":"信息安全法规标准","stem":"ISO27002（Information technology-Security techniques0Codeofpratice for inforeation security managcacnt）是重要的信息安全管理标准之一,下图是关于其演进变化示意图,图中括号空白处应填写（）","options":["BS 7799.1.3","ISO 17799","AS/NZS 4630","NIST SP 800-37"],"correctIndex":1,"explanation":"ISO27002前身为ISO17799,由BS7799-1演化而来。","imageNames":["wx2026-06-16.png"]},{"id":"wx2026-06-040","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"40","domain":"信息安全技术","stem":"自主访问控制模型（DAC）的访问控制关系可以用访问控制（ACL）来表示,该ACL利用在客体上附加一个主体明细表的方法来表示访问控制矩阵,通常使用由客体指向的链表来存储相关数据。下面选项中说法正确的是（）","options":["ACL是Bell-LaPadula模型的一种具体实现","ACL在删除用户时,去除该用户所有的访问权限比较方便","ACL对于统计某个主体能访问哪些客体比较方便","ACL在增加客体时,增加相关的访问控制权限较为简单"],"correctIndex":3,"explanation":"ACL增加客体时,只需在客体链表中添加主体权限,操作简单。","imageNames":[]},{"id":"wx2026-06-041","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"41","domain":"信息安全技术","stem":"数据库的安全很复杂,往往需要考虑多种安全策略,才可以更好地保护数据库的安全。以下关于数据库常用的安全策略理解不正确的是:","options":["最小特权原则,是让用户可以合法的存取或修改数据库的前提下,分配最小的特权,使得这些信息恰好能够完成用户的工作","最大共享策略,在保证数据库的完整性、保密性和可用性的前提下,最大程度也共享数据库中的信息","粒度最小策略,将数据库中的数据项进行划分,粒度越小,安全级别越高,在实际中需要选择最小粒度","按内容存取控制策略,不同权限的用户访问数据库的不同部分"],"correctIndex":2,"explanation":"粒度最小策略需平衡安全与效率,实际中需选择合适粒度,非最小粒度。","imageNames":[]},{"id":"wx2026-06-042","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"42","domain":"信息安全法规标准","stem":"我国标准《信息安全风险管理指南》（GB/Z24364）给出了信息安全风险管理的内容和过程,可以用下图来表示。图中空白处应该填写（）","options":["风险计算","风险评价","风险预测","风险处理"],"correctIndex":3,"explanation":"我国标准《信息安全风险管理指南》（GB/Z 24364）给出“信息安全风险管理包括背景建立、风险评估、风险处理、批准监督、监控审查和沟通咨询6个方面的内容。背景建立、风险评估、风险处理和批准监督是信息安全风险管理的4个基本步骤,监控审查和沟通咨询则贯穿于这4个步骤中”。","imageNames":["wx2026-06-17.png"]},{"id":"wx2026-06-043","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"43","domain":"信息安全工程","stem":"以下哪一项不是信息系统集成项目的特点:","options":["信息系统集成项目要以满足客户和用户的需求为根本出发点","系统集成就是选择最好的产品和技术,开发相应的软件和硬件,将其集成到信息系统的过程","信息系统集成项目的指导方法是“总体规划、分步实施”","信息系统集成包含技术,管理和商务等方面,是一项综合性的系统工程"],"correctIndex":1,"explanation":"系统集成需选择“合适”产品和技术,非“最好”,选项B片面。","imageNames":[]},{"id":"wx2026-06-044","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"44","domain":"信息安全法规标准","stem":"某单位的信息安全主管部门在学习我国有关信息安全的政策和文件后,认识到信息安全风险评估分为自评估和检查评估两种形式。该部门将有关检查评估的特点和要求整理成如下四条报告给单位领导,其中描述错误的是（）","options":["检查评估可依据相关标准的要求,实施完整的风险评估过程；也可在自评估的基础上,对关键环节或重点内容实施抽样评估","检查评估可以由上级管理部门组织,也可以由本级单位发起,其重点是针对存在的问题进行检查和评测","检查评估可以由上级管理部门组织,并委托有资质的第三方技术机构实施","检查评估是通过行政手段加强信息安全管理的重要措施,具有强制性的特点"],"correctIndex":1,"explanation":"检查评估可由上级组织或本级发起,但本级发起需上级批准,选项B描述不准确。","imageNames":[]},{"id":"wx2026-06-045","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"45","domain":"信息安全管理","stem":"为了能够合理、有序地处理安全事件,应事件制定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生或是在混乱状态中迅速恢复控制,将损失和负面影响降至最低。PDCERF方法论是一种防范使用的方法,其将应急响应分成六个阶段,如下图所示,请为图中括号空白处选择合适的内容（）","options":["培训阶段","文档阶段","报告阶段","检测阶段"],"correctIndex":3,"explanation":"PDCERF模型中,检测阶段是响应事件的第一步,用于确认事件发生。","imageNames":["wx2026-06-18.png"]},{"id":"wx2026-06-046","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"46","domain":"信息安全管理","stem":"关于信息安全管理,下面理解片面的是（）","options":["信息安全管理是组织整体管理的重要、固有组成部分,它是组织实现其业务目标的重要保障","信息安全管理是一个不断演进、循环发展的动态过程,不是一成不变的","在信息安全建设中,技术是基础,管理是拔高,有效的管理依赖于良好的技术基础","坚持管理与技术并重的原则,是我国加强信息安全保障工作的主要原则之一"],"correctIndex":2,"explanation":"技术与管理并重,管理依赖技术基础的说法片面,管理可独立提升安全水平。","imageNames":[]},{"id":"wx2026-06-047","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"47","domain":"信息安全管理","stem":"关于风险要素识别阶段工作内容叙述错误的是:","options":["资产识别是指对需要保护的资产和系统等进行识别和分类","威胁识别是指识别与每项资产相关的可能威胁和漏洞及其发生的可能性","脆弱性识别以资产为核心,针对每一项需要保护的资产,识别可能被威胁利用的弱点,并对脆弱性的严重程度进行评估","确认已有的安全措施仅属于技术层面的工作,牵涉到具体方面包括:物理平台、系统平台、网络平台和应用平台"],"correctIndex":3,"explanation":"确认安全措施需涵盖技术和管理层面,如政策、流程等,选项D片面。 某学员在学习国家标准《信息系统安全保障评估框架第一部分:简介和一般模型》（GB/T 20274.1-2006）后,绘制了一张简化的信息系统安全保障模型图,如下所示。请为图中括号空白处选择合适的选项（）","imageNames":[]},{"id":"wx2026-06-048","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"48","domain":"信息安全法规标准","stem":"某学员在学习国家标准《信息系统安全保障评估框架第一部分:简介和一般模型》（GB/T 20274.1-2006）后,绘制了一张简化的信息系统安全保障模型图,如下所示。请为图中括号空白处选择合适的选项（）","options":["安全保障（方针和组织）","安全防护（技术和管理）","深度防御（策略、防护、检测、响应）","保障要素（管理、工程、技术、人员）"],"correctIndex":3,"explanation":"信息系统安全保障模型中,保障要素包括管理、工程、技术、人员。","imageNames":["wx2026-06-19.png"]},{"id":"wx2026-06-049","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"49","domain":"信息安全法规标准","stem":"为了进一步提供信息安全的保障能力和防护水平,保障和促进信息化建设的健康发展,公安部等四部门联合发布《关于信息安全等级保护工作的实施意见》（公通字[2004]66号）,对等级保护工作的开展提供宏观指导和约束,明确了等级保护工作哟的基本内容、工作要求和实施计划,以及各部门工作职责分工等。关于该文件,下面理解正确的是（）","options":["该文件是一个由部委发布的政策性文件,不属于法律文件","该文件适用于2004年的等级保护工作,其内容不能约束到2005年及之后的工作","该文件是一个总体性指导文件,规定所有信息系统都要纳入等级保护定级范围","该文件适用范围为发文的这四个部门,不适用于其他部门和企业等单位"],"correctIndex":0,"explanation":"公通字[2004]66号是政策性文件,非法律文件,但长期有效且适用所有部门。","imageNames":[]},{"id":"wx2026-06-050","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"50","domain":"信息安全管理","stem":"在某次信息安全应急响应过程中,小王正在实施如下措施:消除或阻断攻击源、找到并消除系统的脆弱性/漏洞、修改安全策略、加强防范措施、格式化被感染恶意程序的介质等。请问,按照PDCERF应急响应方法,这些工作应处于以下哪个阶段（）","options":["准备阶段","检测阶段","遏制阶段","根除阶段"],"correctIndex":3,"explanation":"PDCERF应急响应方法中,根除阶段的任务是消除或阻断攻击源、找到并消除系统的脆弱性/漏洞、修改安全策略、加强防范措施、格式化被感染恶意程序的介质等,以彻底解决问题,防止再次发生类似事件。准备阶段主要是制定应急响应计划、准备资源等；检测阶段是发现信息安全事件；遏制阶段是采取措施限制事件扩散和影响范围。所以选D。","imageNames":[]},{"id":"wx2026-06-051","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"51","domain":"信息安全技术","stem":"Linux系统的安全设置中,对文件的权限操作是一项关键操作。通过对文件权限的设置,能够保障不同用户的个人隐私和系统安全。文件fib.c的文件属性信息如下图所示,小张想要修改其文件权限,为文件主增加执行权限,并删除组外其他用户的写权限,那么以下操作中正确的是（）","options":["#chmod u+x, a-w fib.c","#chmod ug+x, o-w fib.c","#chmod 764 fib.c","#chmod 467 fib.c"],"correctIndex":2,"explanation":"要为文件主增加执行权限,删除组外其他用户的写权限,-rwxrw-r--,二进制表示为111110100,转换成十进制为764。","imageNames":["wx2026-06-20.png"]},{"id":"wx2026-06-052","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"52","domain":"信息安全管理","stem":"关于信息安全事件管理和应急响应,以下说法错误的是:","options":["应急响应是指组织为了应对突发重大信息安全事件的所做的准备,以及在事件发生后所采取的措施","应急响应方法,将应急响应管理过程分为遏制、根除、处置、恢复、报告和跟踪6个阶段","对信息安全事件的分级主要参考信息系统的重要程度、系统损失和社会影响三方面因素","根据信息安全事件的分级参考要素,可将信息安全事件划分为4个级别:特别重大事件（I级）、重大事件（II级）、较大事件（III级）和一般事件（IV级）"],"correctIndex":1,"explanation":"应急响应方法将应急响应管理过程分为准备、检测、遏制、根除、恢复和跟踪6个阶段,B选项中“处置”表述错误。A选项对应急响应的定义正确；C选项对信息安全事件分级参考因素描述正确；D选项对信息安全事件级别的划分正确。所以选B。","imageNames":[]},{"id":"wx2026-06-053","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"53","domain":"信息安全管理","stem":"恢复时间目标（RTO）和恢复点目标（RPO）是信息系统灾难恢复中的重要概念,关于这两个值能否为零,正确的选项是（）","options":["RTO可以为0,RPO也可以为0","RTO可以为0,RPO不可以为0","RTO不可以为0,但RPO可以为0","RTO不可以为0,RPO也不可以为0"],"correctIndex":0,"explanation":"恢复时间目标（RTO）是指从灾难发生到业务恢复运行所允许的最大时间间隔,理论上可以为0,意味着立即恢复。恢复点目标（RPO）是指业务系统所允许的最大数据丢失量,在理想情况下,如果采用实时备份等技术,RPO也可以为0,即不丢失任何数据。所以选A。","imageNames":[]},{"id":"wx2026-06-054","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"54","domain":"信息安全技术","stem":"下面有关软件安全问题的描述中,哪项应是由于软件设计缺陷引起的（）","options":["设计了三层WEB架构,但是软件存在SQL注入漏洞,导致被黑客攻击后直接访问数据库","使用C语言开发时,采用了一些存在安全问题的字符串处理函数,导致存在缓冲区溢出漏洞","设计了缓存用户隐私数据机制以加快系统处理性能,导致软件在发布运行后,被黑客攻击获取到用户隐私数据","使用了符合要求的密码算法,但在使用算法接口时,没有按照要求生成密钥,导致黑客攻击后能破解并得到明文数据"],"correctIndex":2,"explanation":"A选项是软件存在SQL注入漏洞,属于编码实现问题；B选项是使用存在安全问题的字符串处理函数导致缓冲区溢出漏洞,属于编码实现问题；C选项是设计了缓存用户隐私数据机制,这是软件设计层面的缺陷,导致用户隐私数据泄露风险；D选项是没有按照要求生成密钥,属于使用接口不当问题。所以选C。","imageNames":[]},{"id":"wx2026-06-055","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"55","domain":"信息安全技术","stem":"通过对称密码算法进行安全消息传输的必要条件是:","options":["在安全的传输信道上进行通信","通讯双方通过某种方式,安全且秘密地共享密钥","通讯双方使用不公开的加密算法","通讯双方将传输的信息夹杂在无用信息中传输并提取"],"correctIndex":1,"explanation":"对称密码算法中,通讯双方必须安全且秘密地共享密钥,才能进行安全的消息传输。如果在不安全的传输信道上通信,密钥可能被窃取；加密算法可以是公开的；将传输信息夹杂在无用信息中传输并提取不是对称密码算法安全传输的必要条件。所以选B。","imageNames":[]},{"id":"wx2026-06-056","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"56","domain":"信息安全技术","stem":"某银行有5台交换机连接了大量交易机构的网路（如图所示）,在基于以太网的通信中,计算机A需要与计算机B通信,A必须先广播“ARP请求信息”,获取计算机B的物理地址。没到月底时用户发现该银行网络服务速度极其缓慢。银行经调查后发现为了当其中一台交换机收到ARP请求后,会转发给接收端口以外的其他所有端口,ARP请求会被转发到网络中的所有客户机上。为降低网络的带宽消耗,将广播流限制在固定区域内,可以采用的技术是（）","options":["VLAN划分","动态分配地址","设立入侵防御系统","为路由交换设备修改默认口令"],"correctIndex":0,"explanation":"VLAN（虚拟局域网）划分可以将网络划分为多个逻辑上的子网,限制广播流在固定区域内传播,从而降低网络的带宽消耗。动态分配地址不能解决广播流问题；设立入侵防御系统主要用于防御入侵行为；为路由交换设备修改默认口令是安全加固措施,但不能解决广播流问题。所以选A。","imageNames":["wx2026-06-21.png"]},{"id":"wx2026-06-057","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"57","domain":"信息安全管理","stem":"Windows系统下,哪项不是有效进行共享安全的防护措施？","options":["使用netshare\\\\127.0.0.1\\c$/delete命令,删除系统中的c$等管理共享,并重启系统","确保所有的共享都有高强度的密码防护","禁止通过“空会话”连接以匿名的方式列举用户、群组、系统配置和注册表键值","安装软件防火墙阻止外面对共享目录的连接"],"correctIndex":0,"explanation":"使用net share\\\\127.0.0.1\\c$/delete命令删除系统中的c$等管理共享并重启系统,在Windows系统重启后,这些管理共享通常会自动重新创建,这不是有效的共享安全防护措施。确保共享有高强度密码防护、禁止“空会话”连接、安装软件防火墙阻止外部对共享目录的连接都是有效的防护措施。所以选A。","imageNames":[]},{"id":"wx2026-06-058","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"58","domain":"信息安全技术","stem":"以下对Windows账号的描述,正确的是:","options":["Windows系统是采用SID（安全标识符）来标识用户对文件或文件夹的权限","Windows系统是采用用户名来标识用户对文件或文件夹的权限","Windows系统默认会生成administrator和guest两个账号,两个账号都不允许改名和删除","Windows系统默认生成administrator和guest两个账号,两个账号都可以改名和删除"],"correctIndex":0,"explanation":"Windows系统采用SID（安全标识符）来标识用户对文件或文件夹的权限,而不是用户名。Windows系统默认生成administrator和guest两个账号,administrator账号可以改名和删除（但不建议删除）,guest账号默认是禁用状态,可以启用、改名和删除相关设置受系统策略限制。所以选A。","imageNames":[]},{"id":"wx2026-06-059","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"59","domain":"信息安全技术","stem":"如图一所示:主机A和主机B需要通过IPSec隧道模式保护二者之间的通信流量,这种情况下IPSec的处理通常发生在哪二个设备中?","options":["主机A和安全网关1;","主机B和安全网关2;","主机A和主机B中;","安全网关1和安全网关2中;"],"correctIndex":3,"explanation":"隧道模式的IPSec处理通常由网络边界设备（如安全网关、路由器、防火墙）完成,而非终端主机。","imageNames":["wx2026-06-22.png"]},{"id":"wx2026-06-060","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"60","domain":"信息安全技术","stem":"以下关于代替密码的说法正确的是:","options":["明文根据密钥被不同的密文字母代替","明文字母不变,仅仅是位置根据密钥发生改变","明文和密钥的每个bit 异或","明文根据密钥作移位"],"correctIndex":0,"explanation":"代替密码是明文根据密钥被不同的密文字母代替。B选项是置换密码的特点；C选项是异或运算加密的特点；D选项是移位密码的特点。所以选A。","imageNames":[]},{"id":"wx2026-06-061","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"61","domain":"信息安全法规标准","stem":"AES在抵抗差分密码分析及线性密码分析的能力比DES更有效,已经替代DES成为新的据加密标准。其算法的信息块长度和加密密钥是可变的,以下哪一种不是其可能的密钥长度？","options":["64bit","128bit","192bit","256bit"],"correctIndex":0,"explanation":"AES算法的密钥长度可以是128bit、192bit、256bit,信息块长度固定为128bit,64bit不是其可能的密钥长度。所以选A。","imageNames":[]},{"id":"wx2026-06-062","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"62","domain":"信息安全技术","stem":"以下对Windows系统的服务描述,正确的是:","options":["Windows服务必须是一个独立的可执行程序","Windows服务的运行不需要用户的交互登陆","Windows服务都是随系统启动而启动,无需用户进行干预","Windows服务都需要用户进行登陆后,以登录用户的权限进行启动"],"correctIndex":1,"explanation":"Windows服务不一定是独立的可执行程序,也可以是动态链接库等形式；Windows服务的运行不需要用户的交互登陆,可以在后台自动运行；Windows服务可以设置启动类型,如自动、手动、禁用等,并非都是随系统启动而启动；Windows服务可以以系统权限运行,不一定需要用户登陆后以登录用户权限启动。所以选B。","imageNames":[]},{"id":"wx2026-06-063","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"63","domain":"信息安全管理","stem":"为了能够合理、有序地处理安全事件,应事件制定出事件应急响应方法和过程,有助于一个组织在事件发生时阻止混乱的发生或是在混乱状态中迅速恢复控制,将损失和负面影响降至最低。PDCERF方法论是一种防范使用的方法,其将应急响应分成六个阶段,如下图所示,请为图中括号空白处选择合适的内容（）","options":["培训阶段","文档阶段","报告阶段","检测阶段"],"correctIndex":3,"explanation":"PDCERF方法论将应急响应分成准备、检测、遏制、根除、恢复和跟踪六个阶段,图中空白处应为检测阶段,在检测阶段发现信息安全事件。所以选D。","imageNames":["wx2026-06-23.png"]},{"id":"wx2026-06-064","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"64","domain":"信息安全保障","stem":"Alice 有一个消息M通过密钥K2生成一个密文E（K2,M）然后用K1生成一个MAC为C（K1,E（K2,M））,Alice将密文和MAC发送给Bob,Bob用密钥K1和密文生成一个MAC并和Alice 的MAC比较,假如相同再用K2解密Alice发送的密文,这个过程可以提供什么安全服务？","options":["仅提供数字签名","仅提供保密性","仅提供不可否认性","保密性和消息完整性"],"correctIndex":3,"explanation":"Alice用密钥K2生成密文,保证了消息的保密性；用K1生成MAC并发送给Bob,Bob验证MAC,保证了消息的完整性。该过程没有提供数字签名（数字签名通常涉及私钥签名、公钥验证）和不可否认性（需要更复杂的机制如数字证书等）。所以选D。","imageNames":[]},{"id":"wx2026-06-065","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"65","domain":"信息安全管理","stem":"以下关于windowsSAM(安全账号管理器)的说法错误的是:","options":["安全账号管理器(SAM)具体表现就是%SystemRoot%\\system32\\config\\sam","安全账号管理器(SAM)存储的账号信息是存储在注册表中","安全账号管理器(SAM)存储的账号信息administrator和system是可读和可写的","安全账号管理器(SAM)是windows的用户数据库系统进程通过Security Accounts Manager服务进行访问和操作"],"correctIndex":2,"explanation":"安全账号管理器（SAM）存储的账号信息administrator和system是不可读和不可写的,这是为了保护系统核心账号的安全。A选项对SAM文件位置描述正确；B选项SAM存储账号信息在注册表中描述正确；D选项对SAM是用户数据库及访问方式描述正确。所以选C。","imageNames":[]},{"id":"wx2026-06-066","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"66","domain":"信息安全保障","stem":"公钥基础设施,引入数字证书的概念,用来表示用户的身份,下图简要的描述了终端实体（用户）,从认证权威机构CA申请、撤销和更新数字证书的流程,请为中间框空白处选择合适的选项（）","options":["证书库","RA","OCSP","CRL库"],"correctIndex":1,"explanation":"终端实体（用户）从认证权威机构CA申请、撤销和更新数字证书的流程中,中间框空白处应为RA（注册机构）,RA负责接收用户的证书申请、审核用户身份等信息,并将申请转发给CA。证书库是存储证书和CRL（证书撤销列表）的地方；OCSP（在线证书状态协议）用于实时查询证书的状态；CRL库是存储证书撤销列表的数据库。所以选B。","imageNames":["wx2026-06-24.png"]},{"id":"wx2026-06-067","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"67","domain":"信息安全技术","stem":"常见密码系统包含的元素是:","options":["明文,密文,信道,加密算法,解密算法","明文,摘要,信道,加密算法,解密算法","明文,密文,密钥,加密算法,解密算法","消息,密文,信道,加密算法,解密算法"],"correctIndex":2,"explanation":"常见密码系统包含明文（待加密的消息）、密文（加密后的消息）、密钥（加密和解密使用的参数）、加密算法（将明文转换为密文的规则）、解密算法（将密文转换为明文的规则）。信道是消息传输的通道,不属于密码系统基本元素；摘要是哈希函数的输出结果,不是密码系统基本元素。所以选C。","imageNames":[]},{"id":"wx2026-06-068","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"68","domain":"信息安全技术","stem":"如图所示,主体 S 对客体 01 有读（R）权限,对客体 02 有读（R） 、写（）权限。该 图所示的访问控制实现方法是:","options":["访问控制表（ACL）","访问控制矩阵","能力表（CL）","前缀表（Profiles）"],"correctIndex":2,"explanation":"能力表为每个用户维护一个表,表示主体可以访问的客体及权限。","imageNames":["wx2026-06-25.png"]},{"id":"wx2026-06-069","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"69","domain":"信息安全工程","stem":"社会工程学定位在计算机信息安全工作链的一个最脆弱的环节,即“人”这个环节上。这些社会工程黑客在某黑客大会上成功攻入世界五百强公司,其中一名自称是CSO杂志做安全调查,半小时内,攻击者选择了在公司工作两个月安全工程部门的合约雇员,在询问关于工作满意度以及食堂食物质量问题后,雇员开始透露其他信息,包括:操作系统、服务包、杀毒软件、电子邮件及浏览器。为对抗此类信息收集和分析,公司需要做的是（）","options":["通过信息安全培训,使相关信息发布人员了解信息收集风险,发布信息最小化原则","减少系统对外服务的端口数量,修改服务旗标","关闭不必要的服务,部署防火墙、IDS等措施","系统安全管理员使用漏洞扫描软件对系统进行安全审计"],"correctIndex":0,"explanation":"社会工程学攻击利用人的弱点获取信息,通过信息安全培训,使相关信息发布人员了解信息收集风险,遵循发布信息最小化原则,可以有效对抗此类信息收集和分析。减少系统对外服务端口数量、修改服务旗标,关闭不必要服务、部署防火墙、IDS等措施,系统安全管理员使用漏洞扫描软件对系统进行安全审计,这些措施主要针对技术层面的安全防护,对社会工程学攻击效果有限。所以选A。","imageNames":[]},{"id":"wx2026-06-070","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"70","domain":"信息安全技术","stem":"基于TCP的主机在进行一次TCP连接时简要进行三次握手,请求通信的主机A要与另一台主机B建立连接时,A需要先发一个SYN数据包向B主机提出连接请示,B收到后,回复一个ACK/SYN确认请示给A主机,然后A再次回应ACK数据包,确认连接请求。攻击通过伪造带有虚假源地址的SYN包给目标主机,使目标主机发送的ACK/SYN包得不到确认。一般情况下,目标主机会等一段时间后才会放弃这个连接等待。因此大量虚假SYN包同时发送到目标主机时,目标主机上就会有大量的连接请示等待确认,当这些未释放的连接请示数量超过目标主机的资源限制时。正常的连接请示就不能被目标主机接受,这种SYN Flood攻击属于（）","options":["拒绝服务攻击","分布式拒绝服务攻击","缓冲区溢出攻击","SQL注入攻击"],"correctIndex":0,"explanation":"SYN Flood攻击通过伪造大量虚假SYN包,使目标主机上有大量连接请求等待确认,占用目标主机资源,导致正常连接请求无法被接受,属于拒绝服务攻击。分布式拒绝服务攻击是多个攻击源同时发起攻击；缓冲区溢出攻击是利用程序缓冲区溢出漏洞进行攻击；SQL注入攻击是利用Web应用程序对SQL语句处理不当进行攻击。所以选A。","imageNames":[]},{"id":"wx2026-06-071","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"71","domain":"信息安全法规标准","stem":"信息安全是国家安全的重要组成部分,综合研究当前世界各国信息安全保障工作,总结错误的是（）","options":["各国普遍将与国家安全、社会稳定和民生密切相关的关键基础设施作为信息安全保障的重点","各国普遍重视战略规划工作,逐步发布网络安全战略、政策评估报告、推进计划等文件","各国普遍加强国际交流与对话,均同意建立一致的安全保障系统,强化各国安全系统互通","各国普遍积极推动信息安全立法和标准规范建设,重视应急响应、安全监管和安全测评"],"correctIndex":2,"explanation":"各国在信息安全保障方面,虽然加强国际交流与对话,但由于各国国情、安全需求等不同,不会建立一致的安全保障系统,C选项总结错误。A选项各国将关键基础设施作为保障重点正确；B选项各国重视战略规划工作正确；D选项各国推动信息安全立法和标准规范建设等正确。所以选C。","imageNames":[]},{"id":"wx2026-06-072","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"72","domain":"信息安全技术","stem":"公钥密码的应用不包括:","options":["数字签名","非安全信道的密钥交换","消息认证码","身份认证"],"correctIndex":2,"explanation":"公钥密码的应用包括数字签名（利用私钥签名、公钥验证）、非安全信道的密钥交换（如Diffie - Hellman密钥交换）、身份认证等。消息认证码（MAC）通常使用对称密钥,不属于公钥密码应用。所以选C。","imageNames":[]},{"id":"wx2026-06-073","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"73","domain":"信息安全保障","stem":"Hash 算法的碰撞是指:","options":["两个不同的消息,得到相同的消息摘要","两个相同的消息,得到不同的消息摘要","消息摘要和消息的长度相同","消息摘要比消息长度更长"],"correctIndex":0,"explanation":"Hash算法的碰撞是指两个不同的消息,经过Hash算法计算得到相同的消息摘要。两个相同消息得到相同消息摘要是正常情况；消息摘要长度通常固定且远小于消息长度。所以选A。","imageNames":[]},{"id":"wx2026-06-074","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"74","domain":"信息安全技术","stem":"Windows操作系统的注册表运行命令是:","options":["Regsvr32","Regedit","Regedit.msc","Regedit.mmc"],"correctIndex":1,"explanation":"Windows操作系统的注册表运行命令是Regedit。Regsvr32用于注册和注销DLL文件；Regedit.msc和Regedit.mmc不是正确的注册表运行命令。所以选B。","imageNames":[]},{"id":"wx2026-06-075","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"75","domain":"信息安全技术","stem":"视窗操作系统（Windows）从哪个版本开始引入安全中心的概念？","options":["WinNT SP6","Win2000 SP4","WinXP SP2","Win2003 SP1"],"correctIndex":2,"explanation":"视窗操作系统（Windows）从WinXP SP2开始引入安全中心的概念,提供系统安全状态监控和提示等功能。WinNT SP6、Win2000 SP4、Win2003 SP1均未引入安全中心。所以选C。","imageNames":[]},{"id":"wx2026-06-076","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"76","domain":"信息安全技术","stem":"DSA算法不提供以下哪种服务?","options":["数据完整性","加密","数字签名","认证"],"correctIndex":1,"explanation":"DSA算法主要用于数字签名和认证,可保证数据完整性和认证用户身份,但不提供加密服务。所以选B。","imageNames":[]},{"id":"wx2026-06-077","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"77","domain":"信息安全技术","stem":"在Windows文件系统中,_______支持文件加密。","options":["FAT16","NTFS","FAT32","EXT3"],"correctIndex":1,"explanation":"在Windows文件系统中,NTFS支持文件加密功能,可通过EFS（加密文件系统）对文件进行加密。FAT16、FAT32不支持文件加密；EXT3是Linux系统下的文件系统。所以选B。","imageNames":[]},{"id":"wx2026-06-078","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"78","domain":"信息安全技术","stem":"相比FAT文件系统,以下那个不是NTFS所具有的优势？","options":["NTFS使用事务日志自动记录所有文件和文件夹更新,当出现系统损坏引起操作失败后,系统能利用日志文件重做或恢复未成功的操作。","NTFS的分区上,可以为每个文件或文件夹设置单独的许可权限","对于大磁盘,NTFS文件系统比FAT有更高的磁盘利用率。","相比FAT文件系统,NTFS文件系统能有效的兼容linux下的EXT3文件格式。"],"correctIndex":3,"explanation":"NTFS使用事务日志自动记录所有文件和文件夹更新,能利用日志文件重做或恢复未成功操作；NTFS分区可为每个文件或文件夹设置单独许可权限；对于大磁盘,NTFS文件系统比FAT有更高磁盘利用率。而NTFS文件系统不能有效兼容linux下的EXT3文件格式,这是其不具备的优势。所以选D。","imageNames":[]},{"id":"wx2026-06-079","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"79","domain":"信息安全管理","stem":"风险要素识别是风险评估实施过程中的一个重要步骤,小李将风险要素识别的主要过程使用图形来表示,如下图所示,请为图中空白框处选择一个最合适的选项()。","options":["识别面临的风险并赋值","识别存在的脆弱性并赋值","制定安全措施实施计划","检查安全措施有效性"],"correctIndex":1,"explanation":"风险要素识别主要过程包括识别资产、识别面临的威胁、识别存在的脆弱性并赋值、识别已有安全措施等,图中空白框处应为识别存在的脆弱性并赋值,以进一步评估风险。识别面临的风险并赋值是在前面步骤基础上进行；制定安全措施实施计划和检查安全措施有效性是风险评估后续的风险处理和监控阶段工作。所以选B。","imageNames":["wx2026-06-26.png"]},{"id":"wx2026-06-080","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"80","domain":"信息安全技术","stem":"Windows NT提供的分布式安全环境又被称为:","options":["域（Domain）","工作组","对等网","安全网"],"correctIndex":0,"explanation":"Windows NT提供的分布式安全环境被称为域（Domain）,域是一种管理方式,可将网络中的计算机和用户组织起来,方便管理和控制。工作组是一种简单的网络组织形式；对等网强调网络中计算机地位平等；安全网不是Windows NT分布式安全环境的特定称呼。所以选A。","imageNames":[]},{"id":"wx2026-06-081","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"81","domain":"信息安全管理","stem":"在Windows系统中,管理权限最高的组是:","options":["everyone","administrators","powerusers","users"],"correctIndex":1,"explanation":"在Windows系统中,administrators组的管理权限最高,拥有对系统的完全控制权。everyone组包含所有用户,权限较低；powerusers组拥有较多权限,但不如administrators组；users组权限相对较低,主要用于普通用户操作。所以选B。","imageNames":[]},{"id":"wx2026-06-082","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"82","domain":"信息安全管理","stem":"小李去参加单位组织的信息安全培训后,他把自己对管理信息管理体系ISMS的理解画了一张图,但是他还存在一个空白处未填写,请帮他选择一个合适的选项（）","options":["监控和反馈ISMS","批准和监督ISMS","监视和评审ISMS","沟通和咨询ISMS"],"correctIndex":2,"explanation":"管理信息管理体系ISMS需要监视和评审ISMS,以持续改进其有效性和适应性。监控和反馈ISMS表述不准确；批准和监督ISMS不是主要环节；沟通和咨询ISMS是ISMS实施过程中的一部分,但不是图中空白处核心内容。所以选C。","imageNames":["wx2026-06-27.png"]},{"id":"wx2026-06-083","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"83","domain":"信息安全管理","stem":"Windows系统下,可通过运行_______命令打开Windows管理控制台。","options":["regedit","cmd","mmc","mfc"],"correctIndex":2,"explanation":"Windows系统下,可通过运行mmc命令打开Windows管理控制台,用于管理和配置系统各种组件和服务。regedit用于打开注册表编辑器；cmd用于打开命令提示符；mfc不是Windows系统命令。所以选C。","imageNames":[]},{"id":"wx2026-06-084","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"84","domain":"信息安全技术","stem":"下图是某单位对其主网站一天流量的监测图,如果该网站当天17:00到20:00之间受到攻击,则从图中数据分析,这种攻击可能属于下面什么攻击。","options":["跨站脚本攻击","TCP会话劫持","IP欺骗攻击","拒绝服务攻击"],"correctIndex":3,"explanation":"从图中数据看,17:00到20:00之间网站流量急剧增加,可能是遭受拒绝服务攻击,攻击者通过发送大量请求,使网站服务器资源耗尽,无法正常响应合法用户请求。跨站脚本攻击主要是利用网站漏洞注入恶意脚本；TCP会话劫持是劫持已建立的TCP连接；IP欺骗攻击是伪造IP地址进行攻击,这些攻击通常不会直接导致流量急剧增加。所以选D。","imageNames":["wx2026-06-28.png"]},{"id":"wx2026-06-085","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"85","domain":"信息安全技术","stem":"在window系统中用于显示本机各网络端口详细情况的命令是:","options":["netshow","netstat","ipconfig","Netview"],"correctIndex":1,"explanation":"在window系统中,netstat命令用于显示本机各网络端口详细情况,包括连接的协议、本地地址、外部地址、状态等信息。netshow不是Windows系统命令；ipconfig用于显示网络配置信息；Netview不是Windows系统命令。所以选B。","imageNames":[]},{"id":"wx2026-06-086","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"86","domain":"信息安全技术","stem":"以下哪些问题或概念不是公钥密码体制中经常使用到的困难问题?","options":["大整数分解","离散对数问题","背包问题","伪随机数发生器"],"correctIndex":3,"explanation":"公钥密码体制中经常使用到的困难问题包括大整数分解（如RSA算法基于该问题）、离散对数问题（如Diffie - Hellman密钥交换、DSA算法基于该问题）、背包问题等。伪随机数发生器不是公钥密码体制中经常使用的困难问题,它是用于生成随机数的工具。所以选D。","imageNames":[]},{"id":"wx2026-06-087","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"87","domain":"信息安全技术","stem":"如下图所示,Alice 用 Bob 的密钥加密明文,将密文发送给 Bob,Bob 再用自己的私钥解密,恢复出明文以下说法正确的是:","options":["此密码体制为对称密码体制","此密码体制为私钥密码体制","此密码体制为单钥密码体制","此密码体制为公钥密码体制"],"correctIndex":3,"explanation":"Alice用Bob的公钥加密明文,将密文发送给Bob,Bob再用自己的私钥解密,恢复出明文,这种密码体制为公钥密码体制,也称为非对称密码体制。对称密码体制、私钥密码体制、单钥密码体制都是指使用相同密钥进行加密和解密的密码体制。所以选D。","imageNames":["wx2026-06-29.png"]},{"id":"wx2026-06-088","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"88","domain":"信息安全技术","stem":"以下哪种公钥密码算法既可以用于数据加密又可以用于密钥交换?","options":["DSS","Diffie-Hellman","RSA","AES"],"correctIndex":2,"explanation":"RSA公钥密码算法既可以用于数据加密,也可以用于密钥交换。DSS（数字签名标准）主要用于数字签名；Diffie - Hellman主要用于密钥交换,不能直接用于数据加密；AES是对称密码算法,不属于公钥密码算法。所以选C。","imageNames":[]},{"id":"wx2026-06-089","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"89","domain":"信息安全技术","stem":"在密码学的Kerchhof假设中,密码系统的安全性仅依赖于_______。","options":["明文","密文","密钥","信道"],"correctIndex":2,"explanation":"在密码学的Kerchhof假设中,密码系统的安全性仅依赖于密钥的秘密性,即使密码算法公开,只要密钥保密,系统仍然是安全的。明文和密文本身不直接决定密码系统安全性；信道安全性与密码系统安全性核心假设无关。所以选C。","imageNames":[]},{"id":"wx2026-06-090","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"90","domain":"信息安全技术","stem":"在Windows XP中用事件查看器查看日志文件,可看到的日志包括？","options":["用户访问日志、安全性日志、系统日志和IE日志","应用程序日志、安全性日志、系统日志和IE日志","网络攻击日志、安全性日志、记账日志和IE日志","网络链接日志、安全性日志、服务日志和IE日志"],"correctIndex":1,"explanation":"在Windows XP中用事件查看器查看日志文件,可看到的日志包括应用程序日志、安全性日志、系统日志和IE日志。用户访问日志不是事件查看器直接分类查看的日志类型；网络攻击日志、网络链接日志、记账日志、服务日志等不是事件查看器标准日志分类。所以选B。","imageNames":[]},{"id":"wx2026-06-091","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"91","domain":"信息安全管理","stem":"操作系统安全的基础是建立在:","options":["安全安装","安全配置","安全管理","以上都对"],"correctIndex":3,"explanation":"操作系统安全的基础建立在安全安装、安全配置和安全管理等方面。安全安装确保系统初始状态安全；安全配置对系统各项参数进行合理设置；安全管理包括用户管理、权限管理、日志管理等持续的安全维护工作。所以选D。","imageNames":[]},{"id":"wx2026-06-092","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"92","domain":"信息安全技术","stem":"某用户通过账号,密码和验证码成功登陆某银行的个人网银系统,此过程属于以下哪一类:","options":["个人网银和用户之间的双向鉴别","由可信第三方完成的用户身份鉴别","个人网银系统对用户身份的单向鉴别","用户对个人网银系统 合法性 单向鉴别"],"correctIndex":2,"explanation":"用户通过账号、密码和验证码成功登陆银行个人网银系统,此过程是个人网银系统对用户身份的单向鉴别,即系统验证用户身份的合法性。不是双向鉴别（双向鉴别是双方互相验证身份）；也不是由可信第三方完成的用户身份鉴别；用户没有对个人网银系统合法性进行鉴别。所以选C。","imageNames":["wx2026-06-30.png"]},{"id":"wx2026-06-093","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"93","domain":"信息安全管理","stem":"windows文件系统权限管理作用访问控制列表（Access Control List.ACL）机制,以下哪个说法是错误的:","options":["安装Windows系统时要确保文件格式使用的是NTFS,因为Windows的ACL机制需要NTFS文件格式的支持","由于windows操作系统自身有大量的文件和目录,因此很难对每个文件和目录设置严格的访问权限,为了作用上的便利,Windows上的ACL存在默认设置安全性不高的问题","windows的ACL机制中,文件和文件夹的权限是与主体进行关联的,即文件夹和文件的访问权限信息是写在用户数据库中","由于ACL具有很好的灵活性,在实际使用中可以为每一个文件设定独立的用户的权限答案:C"],"correctIndex":2,"explanation":"Windows的ACL机制中,文件和文件夹的权限是与客体（文件和文件夹）进行关联的,即访问权限信息是写在文件和文件夹的属性中,而不是写在用户数据库中。A选项安装Windows系统用NTFS文件格式以支持ACL机制正确；B选项Windows有大量文件和目录,默认ACL设置安全性不高正确；D选项ACL灵活性好,可为每个文件设定独立用户权限正确。所以选C。","imageNames":[]},{"id":"wx2026-06-094","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"94","domain":"信息安全技术","stem":"下列关于kerckhof准则的说法正确的是:","options":["保持算法的秘密性比保持密钥的秘密性要困难的多","密钥一旦泄漏,也可以方便的更换","在一个密码系统中,密码算法是可以公开的,密钥应保证安全","公开的算法能够经过更严格的安全性分析"],"correctIndex":2,"explanation":"kerckhof准则认为在一个密码系统中,密码算法可以公开,密钥应保证安全。保持算法的秘密性比保持密钥的秘密性要困难得多,且密钥一旦泄漏,更换相对方便,公开的算法能够经过更严格的安全性分析。所以选C。","imageNames":[]},{"id":"wx2026-06-095","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"95","domain":"信息安全管理","stem":"小李是某公司系统规划师,某天他针对公司信息系统的现状,绘制了一张系统安全建设规划图,如下图所示。请问这个图形是依据下面哪个模型来绘制的（ ）","options":["PDR","PPDR","PDCA","IATF"],"correctIndex":1,"explanation":"IATF强调人、技术、操作三个核心要素。PDR（保护、检测、响应）、PPDR（策略、保护、检测、响应）、PDCA（计划、执行、检查、改进）。","imageNames":["wx2026-06-31.png"]},{"id":"wx2026-06-096","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"96","domain":"信息安全保障","stem":"信息发送者使用__________进行数字签名。","options":["己方的私钥","己方的公钥","对方的私钥","对方的公钥"],"correctIndex":0,"explanation":"信息发送者使用己方的私钥进行数字签名,接收者使用发送者的公钥验证签名,以确保消息的完整性和来源的真实性。使用己方公钥无法进行签名；使用对方的私钥和公钥不符合数字签名原理。所以选A。","imageNames":[]},{"id":"wx2026-06-097","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"97","domain":"信息安全保障","stem":"根据Bell-Lapadula模型安全策略,下图中写和读操作正确的是:","options":["可读可写","可读不可写","可写不可读","不可读不可写"],"correctIndex":3,"explanation":"根据Bell - Lapadula模型安全策略,下读上写原则,即主体可以读取低于自己安全级别的客体信息,但不能写入；可以向上写入高于自己安全级别的客体,但不能读取。图中主体安全级别高于左边客体,可读不可写,但图片问的是写这种情况,没问读,所以结论为不可写。主体与右边的客体,其密级高于客体,但范畴不同,范畴不同所以没法比,所以是不可读也不可写的。","imageNames":["wx2026-06-32.png"]},{"id":"wx2026-06-098","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"98","domain":"信息安全技术","stem":"以下列出了mac和散列函数的相似性,哪一项说法是错误的？","options":["MAC和散列函数都是用于提供消息认证","MAC的输出值不是固定长度的,而散列函数的输出值是固定长度的","MAC和散列函数都不需要密钥","MAC和散列函数都不属于非对称加密算法"],"correctIndex":2,"explanation":"MAC（消息认证码）需要密钥,用于提供消息认证、完整性校验和抗重放攻击；散列函数不需要密钥,用于消息验证和完整性校验。二者输出长度情况不同,都不属于非对称加密算法。所以选C。","imageNames":[]},{"id":"wx2026-06-099","setId":"wx2026-06","setName":"CISP 复习题（4）","sourceNumber":"99","domain":"信息安全技术","stem":"面哪种方法产生的密码是最难记忆的？","options":["将用户的生日倒转或是重排","将用户的年薪倒转或是重排","将用户配偶的名字倒转或是重排","用户随机给出的字母"],"correctIndex":3,"explanation":"用户随机给出的字母没有规律,最难记忆。将用户的生日、年薪、配偶名字倒转或重排,虽然有一定变化,但仍有一定逻辑关联,相对容易记忆一些。所以选D。","imageNames":[]}]},{"id":"wx2026-07","name":"CISP 复习题（5）","subtitle":"原卷顺序 · 有答案+解析","sourceFile":"CISP复习题（5）100题（有答案）-已审+解析.docx","questionCount":99,"questions":[{"id":"wx2026-07-001","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"1","domain":"信息安全工程","stem":"关于微软的SDL原则,弃用不安全的函数属于哪个价格段？（ ）","options":["规划","设计","实现","测试"],"correctIndex":2,"explanation":"微软的SDL（安全开发生命周期）原则中,弃用不安全的函数属于实现阶段。在实现阶段,开发人员需要按照安全编码规范进行代码编写,弃用不安全的函数是其中的重要内容,以避免潜在的安全漏洞。","imageNames":[]},{"id":"wx2026-07-002","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"2","domain":"信息安全工程","stem":"优秀源代码审核工具有哪些特点（ ） １安全性 ２多平台性 ３可扩民性 ４知识性 ５集成性","options":["１２３４５","２３４","１２３４","２３"],"correctIndex":0,"explanation":"优秀源代码审核工具应具备安全性,能保障审核过程及系统本身安全；多平台性,可在不同操作系统和开发环境下使用；可扩展性,方便根据需求添加新功能和规则；知识性,内置丰富的安全知识库辅助审核；集成性,能与开发流程中的其他工具集成,提高审核效率。","imageNames":[]},{"id":"wx2026-07-003","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"3","domain":"信息安全管理","stem":"信息安全风险管理过程的模型如图所示。按照流程,请问,信息安全风险管理包括（）六个方面的内容 。（ ） 是信息安全风险管理的四个基本步骤,（）则贯穿于这四个基本步骤中。（ ）","options":["背景建立、风险评估、风险外理、批准监督、监控审查和沟通咨询；背景建立、风险评估、风险处理和批准监督；监控审查和沟通咨询","背景建立、风险评估、风险外理、批准监督、监控审查和沟通咨询；背景建立、风险评估、风险处理和监控审查；批准监督和沟通咨询","背景建立、风险评估、风险外理、批准监督、监控审查和沟通咨询；背景建立、风险评估、风险处理和沟通咨询；监控审查和批准监督","背景建立、风险评估、风险外理、批准监督、监控审查和沟通咨询；背景建立、风险评估、监控审查和批准监督；风险处理和沟通咨询"],"correctIndex":0,"explanation":"信息安全风险管理包括背景建立、风险评估、风险处理、批准监督、监控审查和沟通咨询六个方面内容。背景建立、风险评估、风险处理和批准监督是四个基本步骤,监控审查和沟通咨询贯穿于这四个基本步骤中,对风险管理过程进行持续监督和沟通。","imageNames":["wx2026-07-01.png"]},{"id":"wx2026-07-004","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"4","domain":"信息安全保障","stem":"某公司在讨论如何确认已有的安全措施,对于确认已有这全措施,下列选项中近期内述不正确的是（ ）","options":["对有效的安全措施继续保持,以避免不必要的工作和费用,防止安全措施的重复实施","安全措施主要有预防性、检测性和纠正性三种","安全措施的确认应评估其有效性,即是否真正地降低了系统的脆弱性,抵御了威胁","对确认为不适当的安全措施可以置不顾"],"correctIndex":3,"explanation":"对确认为不适当的安全措施,应及时进行改进或替换,而不能置之不顾,否则会给系统带来安全风险。A选项对有效安全措施继续保持可避免不必要工作和费用；B选项安全措施分为预防性、检测性和纠正性三种是正确的分类；C选项确认安全措施有效性,评估其是否降低系统脆弱性、抵御威胁是必要的步骤。","imageNames":[]},{"id":"wx2026-07-005","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"5","domain":"信息安全技术","stem":"密码是一种用来混淆的技术,使用者希望正常的（可识别的）信息转变为无法识别的信息。但这种无法识别信息部分是可以再加工并恢复和破解的,小刚是某公司新进的员工,公司要求他注册一个公司网站的账号,小刚使用一个安全一点的密码,请问以下选项中哪个密码是最安全（ ）","options":["使用和与用户名相同的口令","选择可以在任何字典或语言中找到的口令","选择任何和个人信息有关的口令","采取数字,字母和特殊符号混合并且易于记忆"],"correctIndex":3,"explanation":"A选项使用和用户名相同的口令,容易被猜测和破解；B选项选择在字典或语言中能找到的口令,也容易被字典攻击破解；C选项选择和个人信息有关的口令,可能因个人信息泄露导致口令被猜出；D选项采取数字、字母和特殊符号混合并且易于记忆的密码,增加了密码的复杂度,提高了安全性。","imageNames":[]},{"id":"wx2026-07-006","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"6","domain":"信息安全工程","stem":"基于对（ ）的信任,当一个请求或命令来自一个“权威”人士时,这个请求就可能被毫不怀疑的（ ）。在（ ）中,攻击者伪装成“公安部门”人员要求受害者对权威的信任。在（ ）中,攻击者可能伪装成监管部门、信息系统管理人员等身份,去要求受害者执行操作,例如伪装成系统管理员,告诉用户请求配合进行一次系统测试,要求（ ）等 。","options":["权威；执行；电信诈骗；网络攻击；更改密码","权威；执行；网络攻击；电信诈骗；更改密码","执行；权威；电信诈骗；网络攻击；更改密码","执行；权威；网络攻击；电信诈骗；更改密码"],"correctIndex":0,"explanation":"基于对权威的信任,请求来自“权威”人士时可能被毫不怀疑地执行。在电信诈骗中,攻击者常伪装成“公安部门”人员利用这种信任；在网络攻击中,可能伪装成监管部门、信息系统管理人员等身份要求受害者执行操作,如伪装成系统管理员要求更改密码。","imageNames":[]},{"id":"wx2026-07-007","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"7","domain":"信息安全管理","stem":"在软件项目开发过程中,评估软件项目风险时,（）与风险无关。","options":["高级管理人员是否正式承诺支持该项目","开发人员和用户是否充分理解系统的需求","最终用户是否同意部署已开发的系统","开发需求的资金是否能按时到位"],"correctIndex":2,"explanation":"A选项高级管理人员正式承诺支持项目,能为项目提供资源和决策支持,与风险相关；B选项开发人员和用户充分理解系统需求,可减少需求不明确带来的风险；D选项开发需求资金按时到位,保证项目顺利进行,与风险相关；C选项最终用户同意部署已开发系统是在系统开发完成后的事,在评估项目风险时,它不是影响项目风险的关键因素。","imageNames":[]},{"id":"wx2026-07-008","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"8","domain":"信息安全技术","stem":"物理安全是一个非常关键的领域包括环境安全、设施安全与传输安全。其中,信息系统的设施作为直存储、处理数据的载体,其安全性对信息系统至关重要。下列选项中,对设施安全的保障的描述正确的是（）。","options":["安全区域不仅包含物理区域,还包含信息系统等软件区域","建立安全区域需要建立安全屏蔽及访问控制机制","由于传统门锁容易被破解,因此禁止采用门锁的方式进行边界防护","闭路电视监控系统的前端设备包括摄像机、数字式控制录像设备后端设备包括中央控制设备、监视器等"],"correctIndex":1,"explanation":"A选项安全区域主要指物理区域,不包括信息系统等软件区域；B选项建立安全区域需要建立安全屏蔽及访问控制机制,以限制对区域的访问,保障设施安全；C选项虽然传统门锁安全性较低,但在一些安全要求不高的场景仍可使用,并非禁止采用；D选项闭路电视监控系统前端设备包括摄像机等,后端设备包括中央控制设备、监视器等,数字式控制录像设备一般属于前端或中间处理设备。","imageNames":[]},{"id":"wx2026-07-009","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"9","domain":"信息安全管理","stem":"不同的信息安全风险评估方法可能得到不同的风险评估结果,所以组织机构应当根据各自的实际选择适当的风险评估方法。下面的描述中错误是（）","options":["定量风险分析试图从财务数字上对安全进行评估得出可以量化的风险分析结果,以度量风险的可能性和缺失量","定量风险分析相比定性风险分析能得到准确的数值,所以在实际工作中应使用定量风险分析,而不应选择定性风险分析","定性风险分析过程中往往需要凭借分析者的经验各直接进行,所以分析结果和风险评估团队的素质、经验和知识技能密切相关","定性风险分析更具主观性,面定量风险分析更具客观性"],"correctIndex":1,"explanation":"定量风险分析虽然能得到量化结果,但需要大量准确数据和复杂模型,实际工作中往往难以满足这些条件,且定性风险分析也有其优势,如能快速识别主要风险,考虑难以量化的因素等,所以应根据实际情况选择合适方法,不能只使用定量风险分析。A选项定量风险分析从财务数字上评估安全,度量风险可能性和损失量正确；C选项定性风险分析依赖分析者经验,结果与团队素质等密切相关正确；D选项定性主观性强,定量客观性强正确。","imageNames":[]},{"id":"wx2026-07-010","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"10","domain":"信息安全工程","stem":"与浏览器兼容性测试不需要考虑的问题是（）。","options":["软件是否可以在不同的J2EE中运行","不同的浏览器是否可以提供合适的安全设置","脚本和插是否适用于不同的浏览器","符合最新HTML版本的页面能否在浏览器中正确显示"],"correctIndex":0,"explanation":"浏览器兼容性测试主要关注浏览器相关方面,如不同浏览器能否提供合适安全设置、脚本和插件是否适用不同浏览器、符合最新HTML版本的页面能否正确显示等。而软件在不同J2EE中运行属于服务器端环境兼容性问题,与浏览器兼容性无关。","imageNames":[]},{"id":"wx2026-07-011","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"11","domain":"信息安全工程","stem":"下列关于测试方法的叙述中不正确的是（）","options":["从某种角度上讲,白盒测试与墨盒测试都属于动态测试","功能测试属于黑盒测试","结构测试属于白盒测试","对功能的测试通常是要考虑程序的内部结构的"],"correctIndex":3,"explanation":"A选项白盒测试通过程序内部逻辑结构测试,黑盒测试通过程序输入输出测试,二者都需运行程序,属于动态测试；B选项功能测试关注程序功能,不考虑内部结构,属于黑盒测试；C选项结构测试依据程序内部结构进行测试,属于白盒测试；D选项对功能测试通常不考虑程序内部结构,而是从用户角度测试功能是否正确实现。","imageNames":[]},{"id":"wx2026-07-012","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"12","domain":"信息安全保障","stem":"小王学习了灾难备份的相关知识,了解到常用的数据备份方式包括完全备份、增量备份、差量备份,为了巩固所学知识,小王对这种备份方式进行对比,其中在数据恢复速度方面三种备份方式由快到慢的顺序是（）","options":["完全备份、增量备份、差量备份","完全备份、差量备份、增量备份","增量备份、差量备份、完全备份","差量备份、增量备份、完全备份"],"correctIndex":1,"explanation":"完全备份是对所有数据进行备份,恢复时只需恢复一次完全备份的数据,速度最快；差量备份是备份与上一次完全备份的差异数据,恢复时先恢复完全备份,再恢复差量备份,速度次之；增量备份是备份上一次备份后的变化数据,恢复时需按顺序恢复完全备份和所有增量备份,速度最慢。","imageNames":[]},{"id":"wx2026-07-013","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"13","domain":"信息安全工程","stem":"以下哪一项不属于Web应用软件表示层测试关注的范畴（）。","options":["排版结构的测试","数据完整性测试","客户端兼容性的测试","链接结构的测试"],"correctIndex":1,"explanation":"Web应用软件表示层测试关注排版结构、客户端兼容性、链接结构等方面。数据完整性测试属于数据层或业务逻辑层测试范畴,主要验证数据的准确性和一致性等。","imageNames":[]},{"id":"wx2026-07-014","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"14","domain":"信息安全法规标准","stem":"在国家标准GB／T2024.1-2006《信息安全技术信息系统安全保障评估框架第一部分:简介和一般模型》中,信息系统安全保障模型包含哪几个方面( )","options":["保障要素、生命周期和运行维护","保障要素、生命周期和安全特征","规划组织、生命周期和安全特征","规划组织、生命周期和运行维护"],"correctIndex":1,"explanation":"信息系统安全保障模型包含保障要素、生命周期和安全特征三个方面。保障要素包括技术、管理、工程和人员等；生命周期涵盖信息系统从规划、设计、实施到运维等阶段；安全特征体现信息系统应具备的安全属性,如保密性、完整性和可用性等。","imageNames":[]},{"id":"wx2026-07-015","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"15","domain":"信息安全技术","stem":"以下哪些不是《国家网络空间安全战略》中阐述的我国网络空间当前任务？","options":["捍卫网络空间主权","保护关键信息基础设施","提升网络空间防护能力","阻断与国外网络连接"],"correctIndex":3,"explanation":"《国家网络空间安全战略》阐述了我国网络空间当前任务包括捍卫网络空间主权、保护关键信息基础设施、提升网络空间防护能力等。阻断与国外网络连接不符合我国对外开放和国际合作的原则,也不是我国网络空间的任务。","imageNames":[]},{"id":"wx2026-07-016","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"16","domain":"信息安全技术","stem":"在信息安全保障工作中人才是非常重要的因素,近年来,我国一直调试重视我国信自成安全人才队伍培养建设。在以下关于我国关于人才培养工作的描述中,错误的是（）。","options":["在《中胃信息化领导小组关于加强信息安全保障工作的中意见》（中办发[2003]27号）中,针对信息安全人才建设与培养工作提出了“加快网络空间安全人才培养增强全民信息安全意识”的指导精神","2015年,为加快网络安全高层次人才培养,经报国务院学位委员会 批准,国务院学位委员会、教育部决定“工学”门类下增设“网络空间安全“一级学科,这对于我国网络信息安全人才成体系化、规模化、系统培养到积极的推到作用","经过十余年的发展,我国信息安全人才培养已经成熟和体系化,每年培养的信息全从人员的数量较多 ,能同社会实际需求相匹配；同时,高效信息安全专业毕业人才的合能力要求高、知识更全面,因面社会化培养重点放在非安全专业人才培养上","除正规大学教育外,我国信息安全非学历教育已基本形成了以各种认证为核心,辅以各种职业技能培训的信息安全人才培训休系,包括“注册信息安全专业人员(CISP)”资质认证和一些大型企业的信息安全资质认证"],"correctIndex":2,"explanation":"虽然我国信息安全人才培养取得了一定成绩,但尚未完全成熟和体系化,每年培养的信息安全人员数量还不能完全满足社会实际需求,且高校信息安全专业毕业人才综合能力要求高、知识更全面,但社会化培养仍需加强,不能重点放在非安全专业人才培养上而忽视安全专业人才培养。A选项关于信息安全人才建设指导精神正确；B选项增设“网络空间安全”一级学科对人才培养有积极作用正确；D选项我国信息安全非学历教育体系基本形成正确。","imageNames":[]},{"id":"wx2026-07-017","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"17","domain":"信息安全保障","stem":"王明买了一个新的蓝牙耳机,但王明听说使用蓝牙设备有一定的安全威胁,于是王明找到对蓝牙技术有所了解的王红,希望王红能够给自己一点建议,以下哪一条建议不可取（）","options":["在选择使用蓝牙设备时,应考虑设备的技术实现及设置是否具备防止上述安全威胁的能力","选择使用工能合适的设备而不是功能尽可能多的设备、尽量关闭不使用的服务及功能","如果蓝牙设备丢失,最好不要做任何操作","在配对时使用随机生成的密钥、不使用时设置不可被其他蓝牙设备发现"],"correctIndex":2,"explanation":"A选项选择具备防止安全威胁能力的蓝牙设备可降低安全风险；B选项选择合适功能设备、关闭不使用服务和功能可减少攻击面；D选项配对时使用随机密钥、不使用时设置不可被发现可提高安全性；C选项如果蓝牙设备丢失,应及时采取措施如远程锁定、擦除数据等,不做任何操作会导致数据泄露等安全风险。","imageNames":[]},{"id":"wx2026-07-018","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"18","domain":"信息安全工程","stem":"某公司正在进行IT系统灾难恢复测试,下列问题中哪个最应该引起关注（）","options":["由于有限的测试时间窗,仅仅测试了最必的系统,其他系统在今年的剩余时间里陆续独测试","在测试的过程中,有些备份系统有缺陷或者不能正常工作,从面导致这些系统的测试失败","在开启备份站点之前关闭和保护原生产站点的过程比计划需要多得多的时间","每年都是同相同的员工执行此测试由于所有的参与者都很熟悉每一个恢复步骤,因而没有使用灾难殴打推荐计划（DRP）文档"],"correctIndex":1,"explanation":"在灾难恢复测试中,备份系统有缺陷或不能正常工作,导致测试失败是最应该引起关注的问题,因为这直接影响到在真正灾难发生时系统的恢复能力。A选项仅测试部分系统可在后续补充测试；C选项开启备份站点时间问题可通过优化流程解决；D选项不使用文档依赖人员记忆虽有问题,但不如备份系统缺陷影响大。","imageNames":[]},{"id":"wx2026-07-019","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"19","domain":"信息安全管理","stem":"Hadoop是目前广泛应用的大数据处理分析平台。在Hadoop1.0.0版本之前,Hadoop 并不存在安全认证一说。认集群内所有的节点都是可靠的,值得信赖的。用户与服务器进行交互时并不需要进行验证。导致在恶意用户装成真正的用户或者服务器入侵到Hadoop 集群上,恶意的提交作业篡改分布式存储的数据伪装成Name No 安康头发TaskTracker 接受任务等。在Hadoop2.0 中引入 Kerberos机制来解决用户到服务器认证问题,Kerberos 认证过程不包括（）","options":["获得票据许可票据","获得服务许可票据","获得密钥分配中心的管理权限","获得服务"],"correctIndex":2,"explanation":"Kerberos认证过程包括获得票据许可票据、获得服务许可票据和获得服务三个主要步骤。获得票据许可票据是用户向认证服务器申请票据；获得服务许可票据是用户凭票据许可票据向特定服务器申请服务许可票据；获得服务是用户使用服务许可票据获取服务。不包括获得密钥分配中心的管理权限。","imageNames":[]},{"id":"wx2026-07-020","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"20","domain":"信息安全工程","stem":"下面哪个阶段不属于软件的开发时期","options":["详细设计","总体设计","编码","需求分析"],"correctIndex":1,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-07-021","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"21","domain":"信息安全工程","stem":"下列关于软件需求管理与需求开发的论述正确的是（）","options":["所谓需求管理,是指对需求开发的管理","需求管理包括:需求获取、需求分析、需求定义各需求验证","需求开发是将用户需求转换为应用系统成果的过程","在需求管理中要求维持对原有需求和所有的产品需求的双向跟踪"],"correctIndex":3,"explanation":"A选项需求管理不仅是对需求开发的管理,还包括对需求变更、跟踪等方面的管理；B选项需求获取、需求分析、需求定义和需求验证属于需求开发过程；C选项需求开发是将用户需求转换为软件需求规格说明的过程；D选项在需求管理中要求维持对原有需求和所有产品需求的双向跟踪,以确保需求的完整性和一致性。","imageNames":[]},{"id":"wx2026-07-022","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"22","domain":"信息安全管理","stem":"信息安全是通过实施一组合适的（）而达到的,包括策略、过程、规程、（）以及软件和硬件功能。在必要时需建立、实施、监视、评审和改进包含这些控制措施的（）过程,以确保满足该组织的特定安全和（）。这个过程宜与其他业务（）联合进行。","options":["信息安全管理；控制措施；组织结构；业务目标；管理过程","组织结构；控制措施；信息安全管理；业务目标；管理过程","控制措施；组织结构；信息安全管理；业务目标；管理过程","控制措施；组织结构；业务目标；信息安全管理；管理过程"],"correctIndex":2,"explanation":"教材文章中的一段:“信息安全是通过实施一组合适的控制措施而达到的,包括策略、过程、规程、组织结构以及软件和硬件功能。在需要时需建立、实施、监视、评审和改进这些控制措施,以确保满足该组织的特定安全和业务目标。这个过程应与其他业务管理过程联合进行。”","imageNames":[]},{"id":"wx2026-07-023","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"23","domain":"信息安全工程","stem":"了解社会工程学攻击是应对和防御（）的关键,对于信息系统的管理人员和用户,都应该了解社会学的攻击的概念和攻击的（）。组织机构可采取对相关人员实施社会工程学培训来帮助员工了解什么是社会工程学攻击,如何判断是否存在社会工程学攻击,这样才能更好的保护信息系统和（）。因为如果对攻击方式有所了解那么用户识破攻击者的伪装就（）。因此组织机构应持续不断的向员工提供安全意识的培训和教育,向员工灌输（）,人机降低社会工程学攻击的风险。","options":["社会工程学攻击；越容易；原理；个人数据；安全意识","社会工程学攻击；原理；越容易；个人数据；安全意识","原理；社会工程学攻击；个人数据；越容易；安全意识","社会工程学攻击；原理；个人数据；越容易；安全意识"],"correctIndex":3,"explanation":"了解社会工程学攻击是应对和防御社会工程学攻击的关键,对于信息系统管理人员和用户,应了解攻击的概念和原理。通过培训帮助员工判断是否存在攻击,更好保护信息系统和个人数据。对攻击方式了解,用户识破攻击者伪装就越容易。组织应持续提供安全意识培训和教育,灌输安全意识,降低攻击风险。","imageNames":[]},{"id":"wx2026-07-024","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"24","domain":"信息安全法规标准","stem":"某IT公司针对信息安全事件已经建立了完善的预案,在年度企业信息安全总结会上,信息安全管理员对今年应急预案工作做出了四个总结,其中有一项总结工作是错误,作为企业的CSO,请你指出存在问题的是哪个总结？（）","options":["公司自身拥有优秀的技术人员,系统也是自己开发的,无需进行应急演练工作,因此今年的仅制定了应急演练相关流程及文档,为了不影响业务,应急演练工作不举行","公司制定的应急演练流程包括应急事件通报、确定应急事件优先级应急响应启动实施、应急响应时间后期运维、更新现在应急预案五个阶段,流程完善可用","公司应急预案包括了基本环境类、业务系统、安全事件类、安全事件类和其他类,基本覆盖了各类应急事件类型","公司应急预案对事件分类依据GB/Z 20986 – 2007《信息安全技术信息安全事件分类分级指南》,分为7个基本类别,预案符合国家相关标准"],"correctIndex":0,"explanation":"应急演练是检验和完善应急预案的重要手段,即使公司有优秀技术人员和自研系统,也应进行应急演练,以发现潜在问题,提高应急响应能力。B选项应急演练流程完善；C选项应急预案覆盖各类事件类型；D选项应急预案符合国家相关标准都是正确的做法。","imageNames":[]},{"id":"wx2026-07-025","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"25","domain":"信息安全技术","stem":"强制访问控制是指主体和客体都有一个固定的安全属性,系统用该安全属性决定一个主体是否可以访问某个客体,具有较高的安全性,适用于专用或对安全性要求较高的系统。强制访问控制模型有多种类型,如BLP、Biba、Clark-willson 和ChineseWall 等。小李自学了BLP模型,并对该模型的特点进行了总结。以下4种对BLP模型的描述中,正确的是（）。","options":["BLP模型用于保证系统信息的完整性","BLP模型的规则是“向下读,向上写”","BLP的自主安全策略中,系统通过比较主体与客体的访问类属性控制主体对客体的访问","BLP的强制安全策略使用一个访问控制矩阵表示"],"correctIndex":1,"explanation":"A选项BLP模型用于保证系统信息的保密性,而非完整性；B选项BLP模型规则是“向下读,向上写”,即主体只能读取安全级别低于或等于自身的客体信息,只能写入安全级别高于或等于自身的客体；C选项BLP的强制安全策略通过比较主体与客体的安全属性控制访问,自主安全策略是主体自主决定访问权限；D选项BLP的强制安全策略使用安全标签表示,而非访问控制矩阵。","imageNames":[]},{"id":"wx2026-07-026","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"26","domain":"信息安全工程","stem":"对操作系统软件安装方面应建立安装（）,运行系统要化安装经过批准的可执行代码,不安装开发代码和（）,应用和操作系统软件要在大范围的、成功的测试之后才能实施。而且要仅由受过培训的管理员,根据合适的（）,进行运行软件、应用和程序库的更新；必要时在管理者批准情况下,仅为了支持目的才授予供应商物理或逻辑访问权,并且要监督供应商的活动。对于用户能安装何种类型的软件,组织宜定义并强制执行严格的方针,宜使用（）。不受控制的计算机设备上的软件安装可能导致脆弱性。进行导致信息泄露；整体性损失或其他信息安全事件或违反（）。","options":["控制规程； 编译程序； 管理授权； 最小特权方针； 知识产权","编译程序； 控制规程； 管理授权； 最小特权方针； 知识产权","控制规程； 管理授权； 编译程序； 最小特权方针； 知识产权","控制规程； 最小特权方针；编译程序； 管理授权； 知识产权"],"correctIndex":0,"explanation":"对操作系统软件安装应建立安装控制规程,运行系统安装批准的可执行代码,不安装开发代码和编译程序。应用和操作系统软件经测试后由受过培训的管理员根据管理授权更新。应定义并强制执行用户安装软件方针,使用最小特权方针。不受控制的软件安装可能导致信息安全事件或违反知识产权。","imageNames":[]},{"id":"wx2026-07-027","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"27","domain":"信息安全管理","stem":"网络与信息安全应急预案是在分析网络与信息系统突发事件后果和应急能力的基础上,针对可能发生的重大网络与信息系统突发事件,预先制定的行动计划或应急对策。应急预案的实施需要各子系统相互与协调,下面应急响应工作流程图中,空白方框中从右到左依欠填入的是（）。","options":["应急响应专家小组、应急响应技术保障小组、应急响应实施小组、应急响应日常运行小组","应急响应专家小组、应急响应实施小组、应急响应技术保障小组、应急响应日常运行小组","应急响应技术保障小组、应急响应专家小组、应急响应实施小组、应急响应日常运行小组","应急响应技术保障小组、应急响应专家小组、应急响应日常运行小组、应急响应实施小组"],"correctIndex":0,"explanation":"公开题库未附解析。","imageNames":["wx2026-07-04.png"]},{"id":"wx2026-07-028","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"28","domain":"信息安全技术","stem":"SQL Server 支持两种身份验证模式,即Windows 身份验证模式和混合模式。SQL Server 的混全模式是指:当网络用户尝试接到SQL Server数据库时,（）","options":["Windows 获取用户输入的用户和密码,并提交给 SQL Serve 进行身份验证,并决定用户的数据库访权限","SQL Serve 根据用户输入的用户和密码,并提交给 Windows进行身份验证,并决定用户的数据库访权限","SQL Serve 根据已在Windows 网络中登录的用户的网络安全属性,对用户进行身份验证,并决定用户的数据库访权限","登录到本地 Windows的用户均可无限制访问 SQL Serve数据库"],"correctIndex":2,"explanation":"SQL Server混合模式下,Windows获取用户输入的用户名和密码,提交给SQL Server进行身份验证,并决定用户的数据库访问权限。B选项是SQL Server将用户信息提交给Windows验证错误；C选项是Windows身份验证模式特点；D选项登录本地Windows用户不能无限制访问SQL Server数据库,需经过身份验证和授权。","imageNames":["wx2026-07-05.png"]},{"id":"wx2026-07-029","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"29","domain":"信息安全法规标准","stem":"物联网将我们带入一个复杂多元、综合交互的新信息时代,物联网安全成为关系国计民生的大事,直接影响到个人生活的社会稳定。物联网安全问题必须引起高度重视,并从技术、标准和法律方面予以保障。物联网的感知由安全技术主要包括（）、（）等 实现RFID安全性机制所采用的方法主要有三类:（）、（）和（）。传感器网络认证技术主要包含（）、（）和（）","options":["RFID安全技术； 传感器网络安全技术；内部实体认证、网络与用户认证,以及广播认证；物理机制,密码机制,以及二者相结合的方法","RFID安全技术； 传感器技术；物理机制、密码机制,以及二者相结合的方法；实体认证、网络与用户认证,以及广播认证","RFID安全技术；传感器网络安全技术；物理机制、密码机制,以及二者相结合的方法； 内部实体认证、网络与用户认证,以及广播认证","RFID 技术； 传感器技术；物理机制、密码机制,以及二者相结合的方法；实体认证、网络与用户认证,以及广播认证"],"correctIndex":2,"explanation":"物联网感知层安全技术主要包括RFID安全技术和传感器网络安全技术。RFID安全性机制采用物理机制、密码机制及二者相结合的方法。传感器网络认证技术包含内部实体认证、网络与用户认证以及广播认证。","imageNames":[]},{"id":"wx2026-07-030","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"30","domain":"信息安全工程","stem":"建立并完善（）是有效应对社会工程攻击的方法,通过（）的建立,使得信息系统用户需要遵循（）来实施某些操作,从而在一定程度上降低社会工程学的影响。例如对于用户密码的修改,由于相应管理制度的要求,（）需要对用户身份进行电话回拨确认才能执行,那么来自外部的攻击就可能很难伪装成为内部工作人员进行（）,因为他还需要想办法拥有一个组织机构内部电话才能实施。","options":["信息安全管理体系；安全管理制度； 规范；网络管理员；社会工程学攻击","信息安全管理体系；安全管理制度； 网络管理员；规范；社会工程学攻击","安全管理制度；信息安全管理体系； 规范；网络管理员；社会工程学攻击","信息安全管理体系； 网络管理员；安全管理制度；规范；社会工程学攻击"],"correctIndex":0,"explanation":"建立并完善信息安全管理体系,通过安全管理制度的建立,使信息系统用户遵循规范操作,降低社会工程学影响。例如对于密码修改,网络管理员按管理制度要求进行电话回拨确认,可防止外部攻击伪装内部人员进行社会工程学攻击。","imageNames":[]},{"id":"wx2026-07-031","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"31","domain":"信息安全管理","stem":"管理,是指（）组织并利用其各个要素（人、财、物、信息和时空）,借助（）,完成该组织目标的过程。其中,（）就像其他重要业务资产各（）一样,也 对组织业务至关重要的一种资产,因此需要加以适当地保护。在业务环境互连日益增加的情况下这一点显得尤为重要。这种互连性的增加导致信息暴露于日益增多的、范围越来越广的威胁各（）当中。","options":["管理手段；管理主体；信息；管理要素；脆弱性","管理主体；管理手段；信息；管理要素；脆弱性","管理主体；信息；管理手段；管理要素；脆弱性","管理主体；管理要素；管理手段；信息；脆弱性"],"correctIndex":1,"explanation":"管理是指管理主体组织并利用人、财、物、信息和时空等要素,借助管理手段完成组织目标的过程。信息像其他重要业务资产和管理要素一样,对组织业务至关重要,需加以保护。业务环境互连增加使信息暴露于更多威胁和脆弱性中。","imageNames":[]},{"id":"wx2026-07-032","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"32","domain":"信息安全保障","stem":"如下图所示,两份文件包含了不同的内容,却拥有相同的SHA- 1 数字签名a,这违背了安全的哈希函数（）性质。","options":["单向性","弱抗碰撞性","强抗碰撞性","机密性"],"correctIndex":2,"explanation":"安全的哈希函数强抗碰撞性是指找到两个不同的输入,使其具有相同的哈希值在计算上是不可行的。两份文件内容不同却有相同SHA - 1数字签名,违背了强抗碰撞性。单向性是指从哈希值难以反推出原始输入；弱抗碰撞性是指对于给定输入,找到另一个不同输入具有相同哈希值在计算上不可行；机密性不是哈希函数性质。","imageNames":["wx2026-07-06.png"]},{"id":"wx2026-07-033","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"33","domain":"信息安全管理","stem":"信息安全管理体系也采用了（）模型可应用于所有的（）。ISMS把相关方的信息安全要求和期望作为输入,并通过必要的（）,产生满足这些要求和期望的（）。","options":["ISMS:PDCA过程；行动和过程；信息安全结果","PDCA；ISMS过程；行动和过程；信息安全结果","ISMS:PDCA过程；信息安全结果；行动和过程","PDCA；ISMS过程；信息安全结果；行动和过程"],"correctIndex":1,"explanation":"信息安全管理体系采用PDCA模型,可应用于所有ISMS过程。ISMS将相关方信息安全要求和期望作为输入,通过行动和过程,产生满足要求的信息安全结果。","imageNames":[]},{"id":"wx2026-07-034","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"34","domain":"信息安全保障","stem":"以下对Kerberos 协议过程说法正确的是:（）","options":["协议可以分为两个步骤:一是用户身份鉴别；二是获取请求服务","协议可以分为两个步骤:一是获得票据许可票据；二是获取请求服务","协议可以分为三个步骤:一是用户身份鉴别；二是获得票据许可票据；三是获得服务许可票据","协议可以分为三个步骤:一是获得票据许可票据 二是获得服务许可票据；三是获得服务"],"correctIndex":3,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-07-035","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"35","domain":"信息安全管理","stem":"下列选项中,对物理与环境安全的近期内述出现错误的是（）","options":["物理安全确保了系统在对信息进行采集、传输、处理等过程中的安全","物理安全面对是环境风险及不可预知的人类活动,是一个非常关键的领域","物理安全包括环境安全、系统安全、设施安全等","影响物理安全的因素不仅包含自然因素,还包含人为因素"],"correctIndex":2,"explanation":"A选项,《信息安全技术 信息系统物理安全技术要求》（GB/T 21052—2007）“信息系统物理安全（简称物理安全）是指为了保证信息系统安全可靠运行,确保信息系统在对信息进行采集、处理、传输、存储过程中,不致受到人为或自然因素的危害,而使信息丢失、泄露或破坏,对计算机设备、设施（包括机房建筑、供电、空调等）、环境人员、系统等采取适当的安全措施。”B选项物理安全面对环境风险和人类活动正确；C选项,《信息安全技术 信息系统物理安全技术要求》（GB/T 21052—2007）“物理安全包括设备安全、环境安全/设施安全以及介质安全。”不包括系统安全；D选项影响物理安全因素包括自然和人为因素正确。","imageNames":[]},{"id":"wx2026-07-036","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"36","domain":"信息安全管理","stem":"风险处理是依据（）,选择和实施合适的安全措施。风险处理的目的是为了将（）始终控制在可接爱的范围内。风险处理的方式主要有（）、（）、（）和（）四种方式。","options":["风险；风险评估的结果；降低；规避；转移；接受","风险评估的结果；风险；降低；规避；转移；接受","风险评估；风险；降低；规避；转移；接受","风险；风险评估；降低；规避；转移；接受"],"correctIndex":1,"explanation":"风险处理依据风险评估结果,选择和实施合适安全措施,目的是将风险控制在可接受范围内。风险处理方式主要有降低、规避、转移和接受四种。","imageNames":[]},{"id":"wx2026-07-037","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"37","domain":"信息安全工程","stem":"信息收集是（）攻击实施的基础,因此攻击者在实施前会对目标进行（）,了解目标所有相关的（）。这些资料和信息对很多组织机构来说都是公开或看无用的,然而对攻击者来说,这些信息都 是非常有价值的,这些信息收集得越多,离他们成功得实现（）就越近。如果为信息没有价值或价值的非常低,组织机构通常不会采取措施（）,这正是社会工程学攻击者所希望的。","options":["信息收集；社会工程学；资料和信息；身份伪装 ；进行保护","社会工程学；信息收集；资料和信息；身份伪装 ；进行保护","社会工程学；信息收集；身份伪装；资料和信息 ；进行保护","信息收集；资料和信息；社会工程学；身份伪装 ；进行保护"],"correctIndex":1,"explanation":"信息收集是社会工程学攻击实施基础,攻击者实施前会对目标进行信息收集,了解相关资料和信息,这些信息对攻击者有价值,收集越多离实现身份伪装越近。组织若不重视信息保护,正是攻击者所希望的。","imageNames":[]},{"id":"wx2026-07-038","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"38","domain":"信息安全管理","stem":"信息是流动的,在信息的流动过程中必须能够识别所有可能途径的（）与（）；而对于信息本身而言,信息的 敏感性的定义是对信息保护的（）和( ),信息在不同的环境存储和表现的形式也决定了（）的效果,不同的载体下,可能体现出信息的（）、临时性和信息的交互场景,这使得风险管理变得复杂和不可预测•","options":["基础；依据；载体；环境:永久性:风险管理","基础；依据；载体；环境；风险管理；永久性","载体；环境；风险管理；永久性；基础；依据；","载体；环境；基础；依据:风险管理；永久性"],"correctIndex":3,"explanation":"信息流动需识别途径的载体与环境,信息敏感性定义是信息保护的基础与依据,信息存储和表现形式决定风险管理效果,不同载体体现信息不同特性,使风险管理复杂。","imageNames":[]},{"id":"wx2026-07-039","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"39","domain":"信息安全法规标准","stem":"软件安全设计和开发中应考虑用户隐私保护,以下关于用户隐私保护的说法错误的是？","options":["告诉用户需要收集什么数据及搜集到的数据会如何被使用","当用户的数据由于某种原因要被使用时,给客户选择是否允许","用户提交的用户名和密码属于隐私数据,其他都不是","确保数据的使用符合国家、地方、行业的相关法律法规"],"correctIndex":2,"explanation":"用户隐私保护应告诉用户收集数据及使用方式,给用户选择是否允许使用数据的权利,确保数据使用符合法律法规。用户提交的用户名和密码属于隐私数据,但其他如用户行为数据、偏好数据等也可能属于隐私数据,C选项说法错误。","imageNames":[]},{"id":"wx2026-07-040","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"40","domain":"信息安全保障","stem":"随着时代的发展,有根多伟人都为通信亊业的发展贡献出自己力量,根据常识可知以下哪项是正确的？（）","options":["19世纪中叶以后,随着电磁技术的发展,诞生了笔记本电脑,通信领域产生了根本性的飞跃,开始了人类通信新时代","1837年,美国人费曼发明了电报机,可将信息转换成电脉冲传向目的地,再转换为原来的信息,从而实现了长途电报通信","1875年,贝尔（Bell) 发明了电话机• 1878年在相距300公里的波士顿和纽约之间进行了首次长途电话实验","1906年美国物理学家摩斯发明出无线电广播•法国人克拉维尔建立了英法第一条商用无线电线路,推动了无线电技术的进一步发展"],"correctIndex":2,"explanation":"A选项笔记本电脑不是19世纪中叶电磁技术发展诞生的成果；B选项1837年美国人莫尔斯发明电报机,不是费曼；C选项1875年贝尔发明电话机,1878年进行首次长途电话实验正确；D选项1906年美国物理学家费森登发明无线电广播,不是摩斯。","imageNames":[]},{"id":"wx2026-07-041","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"41","domain":"信息安全管理","stem":"随着人们信息安全意识的不断增强,版权保护也受到越来越多的关注。在版权保护方面国内外使用较为广泛的是数字对象标识符DOI (Digital Object Identifier)系统,它是由非贏利性组织国际DOI基金会IDF (International DOI Foundation)研究设计的,在数字环境下标识知识产权对象的一种开放性系统。DOI系统工 作流程如图所示,则下面对于DOI系统认识正确的是（）","options":["DOI是一个暂时性的标识号,由Intermational DOI Foundation管理","DOI的优点有唯一性、持久性、兼容性、或操作性、动态更新","DOI命名规则中前缀和后缀两部之间用“ ； ”分开","DOI的体现形式只有网络域名和字符码两种形式"],"correctIndex":1,"explanation":"A选项DOI是永久性标识号；B选项DOI具有唯一性、持久性、兼容性、互操作性、动态更新等优点正确；C选项DOI命名规则中前缀和后缀用“/”分开；D选项DOI体现形式有网络域名、字符码等多种形式。","imageNames":["wx2026-07-07.png"]},{"id":"wx2026-07-042","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"42","domain":"信息安全法规标准","stem":"关于我国信息安全保障的基本原则,下列说法中不正确的是:","options":["要与国际接轨,积极吸收国外先进经验并加强合作,遵循国际标准和通行做法,坚持管理与技术并重","信息化发展和信息安全不是矛盾的关系,不能牺牲—方以保证另一方","在信息安全保障建设的各项工作中,既要统筹规划,又要突出重点","在国家信息安全保障工作中,要充分发挥国家、企业和个人的积极性,不能忽视任何一方的作用"],"correctIndex":0,"explanation":"我国信息安全保障基本原则强调立足国情,以我为主,不能完全依赖国外经验,要在借鉴国外经验基础上,结合我国实际情况开展信息安全保障工作。B选项信息化发展和信息安全不矛盾正确；C选项统筹规划和突出重点正确；D选项发挥国家、企业和个人积极性正确。","imageNames":[]},{"id":"wx2026-07-043","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"43","domain":"信息安全技术","stem":"攻击者通过向网络或目标主机发送伪造的ARP应答报文,修改目标计算机上ARP缓存,形成一个错误的IP地址<->MAC地址映射,这个错误的映射在目标主机在需要发送数据时封装错误的MAC地址。欺骗攻击过程如下图所示,其属于欺骗攻击中的哪一种欺骗攻击的过程（）","options":["ARP","IP","DNS","SN"],"correctIndex":0,"explanation":"攻击者通过发送伪造ARP应答报文修改目标计算机ARP缓存,属于ARP欺骗攻击。IP欺骗是通过伪造IP地址进行攻击；DNS欺骗是篡改DNS解析结果进行攻击；SN不是常见欺骗攻击类型。","imageNames":["wx2026-07-08.png"]},{"id":"wx2026-07-044","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"44","domain":"信息安全管理","stem":"组织应依照已确定的访问控制策略限制对信息和( )功能的访间。对访间的限制要基于各个业务应用要求,访问控制策略还要与组织的访问策略一致。应建立安全登录规程控制实现对系统和应用的访问。宜选择合适的身份验证技术以验证用户身份。在需要强认证和()时,宜使用如加密、智能卡、令牌或生物手段等替代密码的身份验证方法。应建立交互式的口令管理系统,并确保使用优质的口令。对于可能覆盖系统和应用的控制措施的实用工具和程序的使用,应加以限制并()。对程序源代码和相关事项(例如设计、说明书、验证计划和确认计划 的访问宜严格控制,以防引入非授权功能、避免无意识的变更和维持有价值的知识产权的（）。对于程序源代码的保存,可以通过这种代码的中央存储控制来实现,更好的是放在( )中","options":["应用系统:身份验证:严格控制;保密性:源程序库","身份验证;应用系统;严格控制:保密性;源程序库","应用系统;严格控制:身份验证;保密性;源程序库","应用系统;保密性;身份验证;严格控制;源程序库"],"correctIndex":0,"explanation":"组织应限制对信息和应用系统功能的访问,访问控制策略与组织策略一致,建立安全登录规程,选择合适身份验证技术,强认证时使用替代密码方法,建立交互式口令管理系统,限制实用工具使用并严格控制,严格控制程序源代码访问以保护保密性和知识产权,可通过中央存储控制或源程序库保存源代码。","imageNames":[]},{"id":"wx2026-07-045","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"45","domain":"信息安全技术","stem":"OSI模型把网络通信工作分为七层,如图所示,0SI模型的每一层只与相邻的上下两层直接通信,当发送进程需要发送信息时,它把数据交给应用层。应用层对数据进行加工处理后,传给表示层。再经过一次加工后,数据被到会话层,这一过程一直继续到物理层接收数据后进行实际的传输,每一次的加工又称为数据封装。其中IP层对应OSI模型中的那一层()","options":["应用层","传输层","应用层","网络层"],"correctIndex":3,"explanation":"OSI模型中,网络层负责将数据包从源节点传输到目标节点,IP层对应OSI模型的网络层,主要功能是进行网络互联和路由选择。","imageNames":["wx2026-07-09.png"]},{"id":"wx2026-07-046","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"46","domain":"信息安全保障","stem":"以下关于软件安全问题对应关系错误的是?()","options":["缺点( Defect)软件实现和设计上的弱点","缺陷(Bug)-实现级上的软件问题","瑕疵(Flaw)-种更深层次、设计层面的问题","故障( Failure)-由于软件存在缺点造成的一种外部表现,是静态的、程序执行过程中出现的行为表现"],"correctIndex":2,"explanation":"非CISP来源,来源于CISSP的曾经的练习题,是翻译的,可参考百度文库2017年04月18日关于《软件安全错误区别》ISO/IEC/IEEE 24765-2010的翻译。Bug,defect,error,fault,failure,mistake等区别。","imageNames":[]},{"id":"wx2026-07-047","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"47","domain":"信息安全技术","stem":"自主访问控制(DAC)是应用很广泛的访问控制方法,常用于多种商业系统中。以下对DAC模型的理解中,存在错误的是（）","options":["在DAC模型中,资源的所有者可以规定谁有权访问它们的资源","DAC是一种对单个用户执行访问控制的过程和措施","DAC可为用户提供灵活调整的安全策略,具有较好的易用性可扩展性,可以抵御特洛伊木马的攻击","在DAC中,具有某种访问能力的主体能够自主地将访问权的某个子集授予其它主体"],"correctIndex":2,"explanation":"DAC模型不能抵御特洛伊木马攻击,因为特洛伊木马可以窃取用户权限,绕过DAC的安全策略。A选项DAC中资源所有者可规定谁有权访问资源正确；B选项DAC是对单个用户执行访问控制正确；D选项DAC中主体可自主授予其他主体访问权正确。","imageNames":[]},{"id":"wx2026-07-048","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"48","domain":"信息安全技术","stem":"恶意代码经过20多年的发展,破坏性、种类和感染性都得到增强。随着计算机的网络化程度逐步提高,网络播的恶意代码对人们日常生活影响越来越大。小李发现在自己的电脑查出病毒的过程中,防病毒软件通过对有毒件的检测,将软件行为与恶意代码行为模型进行匹配,判断出该软件存在恶意代码,这种方式属于( )","options":["简单运行","行为检测","特征数据匹配","特征码扫描"],"correctIndex":1,"explanation":"CISP知识点范围内,在知识点理解的基础上,进一步参考“防病毒软件通过对有毒软件的检测,将软件行为与恶意代码为模型进行匹配”参考教材第388页第三段的内容。","imageNames":[]},{"id":"wx2026-07-049","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"49","domain":"信息安全法规标准","stem":"信息安全风险值应该是以下哪些因素的函数?( )","options":["信息资产的价值、面临的威胁以及自身存在的脆弱性","病毒、黑客、漏洞等","保密信息如国家秘密、商业秘密等","网络、系统、应用的复杂程度"],"correctIndex":0,"explanation":"信息安全风险值是信息资产价值、面临的威胁以及自身存在的脆弱性的函数。通过评估资产价值、威胁可能性和脆弱性严重程度,计算风险值。B选项病毒、黑客、漏洞等是威胁的具体表现；C选项保密信息是信息资产类型；D选项网络、系统、应用复杂程度与风险值计算无关。","imageNames":[]},{"id":"wx2026-07-050","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"50","domain":"信息安全法规标准","stem":"管理层应该表现对 ( ),程序和控制措施的支持, 并以身作则。管理职责要确保雇员和承包方人员都了( )角色和职责,并遵守相应的条款和条件。组织要建立信息安全意识计划,并定期组织信息安全()。组织立正式的(),确保正确和公平的对待被怀疑安全违规的雇员。纪律处理过程要规定(),考虑例如违规的性质、重要性及对于业务的影响等因素,以及相关法律、业务合同和其他因素。","options":["信息安全:信息安全政策:教育和培训;纪律处理过程:分级的响应","信息安全政策:信息安全:教育和培训:纪律处理过程:分级的响应","信息安全政策:教育和培训:信息安全;纪律处理过程:分级的响应","信息安全政策:纪律处理过程信息安全;教育和培训:分级的响应"],"correctIndex":1,"explanation":"CISP知识点范围内,但内容需要理解或背诵,来源于教材第113页,第一段和第二段,请背诵下来,最好要理解。","imageNames":[]},{"id":"wx2026-07-051","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"51","domain":"信息安全技术","stem":"近几年,无线通信技术迅猛发展,广泛应用于各个领域。而无线信道是一个开放性信道,它在赋予无线用户通信自由的同时也给无线通信网络带来一些不安全因素,下列选项中,对无线通信技术的安全特点描述正确的是（）","options":["无线信道是一个开放信道,任何具有适当无线设备的人均可以通过搭线窃听而获得网络通信内容","通过传输流分析,攻击者可以掌握精确的通信内容","对于无线局域网络和无线个人区域网络来说,它们的通信内容更容易被窃听","群通信方式可以防止网络外部人员获取网络内部通信内容"],"correctIndex":2,"explanation":"无线信道开放,攻击者可通过适当设备搭线窃听通信内容,A选项表述不准确；传输流分析一般不能直接掌握精确通信内容；群通信方式不能防止外部人员获取内部通信内容；无线局域网络和无线个人区域网络通信内容更易被窃听,C选项正确。","imageNames":[]},{"id":"wx2026-07-052","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"52","domain":"信息安全工程","stem":"软件的可维护性可用七个质量特性来衡量,分别是:可理解性、可测试性、可修改性、可靠性、可移植性、可使用性和效率对于不同类型的维护,这些侧重点也是不同的,在可维护性的特性中相互促进的是（ ）","options":["可理解性和可测试性","效率和可移植性","效率和可修改性","效率和可理解性"],"correctIndex":0,"explanation":"可理解性和可测试性在可维护性特性中相互促进,可理解性好有助于测试,可测试性强能更好发现可理解方面的问题。效率和可移植性、效率和可修改性、效率和可理解性之间不存在明显相互促进关系。","imageNames":[]},{"id":"wx2026-07-053","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"53","domain":"信息安全法规标准","stem":"54下列选项中对信息系统审计概念的描述中不正确的是( )","options":["信息系统审计,也可称作IT审计或信息系统控制审计","信息系统审计是一个获取并评价证据的过程,审计对象是信息系统相关控制,审计目标则是判断信息系统是否能够保证其安全性、可靠性、经济性以及数据的真实性、完整性等相关属性","信息系统审计是单一的概念,是对会计信息系统的安全性、有效性进行检查","从信息系统审计内容上看,可以将信息系统审计分为不同专项审计,例如安全审计、项目合规审计、绩效审计等。"],"correctIndex":2,"explanation":"信息系统审计是对信息系统相关控制获取并评价证据,判断信息系统能否保证安全性等属性,不是单一对会计信息系统安全性、有效性检查,还包括其他方面,C选项错误。A、B、D选项对信息系统审计描述正确。","imageNames":[]},{"id":"wx2026-07-054","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"54","domain":"信息安全技术","stem":"随着互联网的迅猛发展、WEB信息的增加,用户要在信息海洋里查找自己所需的信息,就像大海捞针一样, 索引擎技术恰好解决了这一难题。以下关于搜索引擎技术特点的描述中错误的是( )","options":["搜索引擎以一定的策略在Web系统中搜索和发现信息","搜索引擎可以分为目录导航式与网页索引式","搜索器在 Internet上逐个访问Web站点,并建立一个网站的关键字列表","索引器功能是理解搜索器获取的信息, 向用户显示查询结果"],"correctIndex":3,"explanation":"索引器功能是理解搜索器获取信息并建立索引,向用户显示查询结果是检索器功能,。","imageNames":["wx2026-07-10.png"]},{"id":"wx2026-07-055","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"55","domain":"信息安全法规标准","stem":"“规划(Plan)-实施(Do)-检查( Check)-处置(Act)”(PDCA过程)又叫( ),是管理学中的一个通用模型,最早由( )于1930年构想,后来被美国质量管理专家( )博士在1950年再度挖掘出来,并加以广泛宣传和运用于持续改善产品质量的过程。PDCA循环就是按照“规划、实施、检查、处置”的顺序进行质量管理,并且循环不止地进行下去的( ),建立符合国际标准ISO 9001的质量管理体系即是一个典型的PDCA过程,建立IS0 14001环境管理体系、IS0 20000I服务 ( )也是一个类似的过程。","options":["质量环; 休哈特 ;戴明; 管理体系; 科学程序","质量环; 戴明; 休哈特; 管理体系; 科学程序","质量环: 戴明; 休哈特; 科学程序; 管理体系","质量环; 休哈特 ;戴明; 科学程序; 管理体系"],"correctIndex":3,"explanation":"PDCA过程又叫质量环,最早由休哈特于1930年构想,后被戴明博士挖掘并广泛宣传用于持续改善产品质量,是科学程序,建立符合国际标准的质量管理体系等都是类似管理体系。","imageNames":[]},{"id":"wx2026-07-056","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"56","domain":"信息安全技术","stem":"ZigBee主要的信息安全服务为( )、 ( )、( )、( )。访问控制使设备能够选择其愿意与之通信的其他设备。为了实现访问控制,设备必须在ACL中维护一个( ),表明它愿意接受来自这些设备的数据。数据加密使用的密钥可能是一组设备共享,或者两两共享。数据加密服务于 Beacon、 command以及数据载荷。数据()主要是利用消息完整性校验码保证没有密钥的节点不会修改传输中的消息,进一步确认消息来自一个知道( )的节点","options":["访问控制、数据加密、数据完整性、序列抗重播保护;设备列表;完整性:密钥","访问控制、加密、完整性、序列抗重播保护;设备列表;完整性;密钥","访问控制、加密、数据完整性、序列抗重播保护;列表;完整性;密钥","访问控制、数据加密、数据完整性、序列抗重播;列表;完整性;密钥"],"correctIndex":0,"explanation":"IEEE802.15.4规范是一种经济、高效、低数据速率(<250kbps)、工作在2.4GHz和868/915MHz的无线技术。ZigBee主要信息安全服务为访问控制、数据加密、数据完整性、序列抗重播保护；设备在ACL中维护设备列表；数据完整性利用消息完整性校验码保证,确认消息来自知道密钥节点。","imageNames":[]},{"id":"wx2026-07-057","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"57","domain":"信息安全技术","stem":"58在一个网络中,当拥有的网络地址容量不够多,或普通终端计算机没有必要分配静态IP地址时,可以采用通过在计算机连接到网络时,每次为其临时在IP地址池中选择一个IP地址并分配的方式为( )","options":["动态分配IP地址","静态分配IP地址","网络地址转换分配地址","手动分配"],"correctIndex":0,"explanation":"动态分配IP地址是在计算机连接到网络时,每次从IP地址池中临时选择一个IP地址分配,适用于网络地址容量不够或普通终端无需静态IP地址情况。","imageNames":[]},{"id":"wx2026-07-058","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"58","domain":"信息安全管理","stem":"信息安全风险管理是基于( )的信息安全管理,也就是,始终以( )为主线进行信息安全的管理。应根据实际( )的不同来理解信息安全风险管理的侧重点,即( )选择的范围和对象重点应有所不同。","options":["风险; 风险; 信息系统: 风险管理","风险; 风险; 风险管理; 信息系统","风险管理; 信息系统; 风险;风险","风险管理; 风险; 风险 ;信息系统"],"correctIndex":0,"explanation":"信息安全风险管理是基于风险的信息安全管理,以风险为主线,根据实际信息系统不同理解风险管理侧重点,即信息系统选择范围和对象重点不同。","imageNames":[]},{"id":"wx2026-07-059","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"59","domain":"信息安全法规标准","stem":"某商贸公司信息安全管理员考虑到信息系统对业务影响越来越重要,计划编制本单位信息安全应急响应预案,在向主管领导写报告时,他列举了编制信息安全应急响应预案的好处和重要性,在他罗列的四条理由中,其中不适合作为理由的一条是( )","options":["应急预案是明确关键业务系统信息安全应急响应指挥体系和工作机制的重要方式","应急预案是提高应对网络和信息系统突发事件能力,减少突发事件造成的损失和危害,保障信息系统运行平稳、安全、有序、高效的手段","编制应急预案是国家网络安全法对所有单位的强制要求,因此必须建设","应急预案是保障单位业务系统信息安全的重要措施"],"correctIndex":2,"explanation":"编制应急预案虽是国家网络安全法要求,但不能作为必须建设的唯一理由,应急预案能明确指挥体系和工作机制、提高应对能力、保障信息系统安全等,C选项不适合作为理由。","imageNames":[]},{"id":"wx2026-07-060","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"60","domain":"信息安全技术","stem":"数据链路层负责监督相邻网络节点的信息流动,用检错或纠错技术来确保正确的传输,确保解决该层的流量控制问题。数据链路层的数据单元是( )","options":["报文","比特流","帧","包"],"correctIndex":2,"explanation":"数据链路层负责相邻节点信息传输,数据单元是帧,报文是网络层数据单元,比特流是物理层数据单元,包是网络层及以上常用术语。","imageNames":[]},{"id":"wx2026-07-061","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"61","domain":"信息安全法规标准","stem":"以下对于标准化特点的描述哪项是错误的?","options":["标准化的对象是共同的、可重复的事物。不是孤立的一件事、一个事物","标准化必须是静态的,相对科技的进步和社会的发展不能发现变化","标准化的相对性,原有标准随着社会发展和环境变化,需要更新","标准化的效益,通过应用体现经济和社会效益,否则就没必要"],"correctIndex":1,"explanation":"标准化具有动态性,随着科技进步和社会发展需要不断更新,不是静态的,B选项错误。A、C、D选项对标准化特点描述正确。","imageNames":[]},{"id":"wx2026-07-062","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"62","domain":"信息安全法规标准","stem":"以下哪个是国际信息安全标准化组织的简称?","options":["ANSI","ISO","IEEE","NIST"],"correctIndex":1,"explanation":"ISO是国际信息安全标准化组织简称,ANSI是美国国家标准学会,IEEE是电气和电子工程师协会,NIST是美国国家标准与技术研究院。","imageNames":[]},{"id":"wx2026-07-063","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"63","domain":"信息安全管理","stem":"风险,在GB /T 22081中定义为事态的概率及其结果的组合。风险的目标可能有很多不同的方面,如财务目标、健康和人身安全目标、信息安全目标和环境目标等:目标也可能有不同的级别,如战略目标、组织目标、项目目标、产品目标和过程目标等, ISO / IEC 13335-1中揭示了风险各要素关系模型,如图所示。请结合此图,怎么才能降低风险对组织产生的影响?( )","options":["组织应该根据风险建立响应的保护要求,通过构架防护措施降低风险对组织产生的影响","加强防护措施,降低风险","减少威胁和脆弱点降低风险","减少资产降低风险"],"correctIndex":0,"explanation":"组织应根据风险建立响应保护要求,通过构架防护措施降低风险影响,B、C选项表述不全面,D选项减少资产不是降低风险合理方式,A选项正确。","imageNames":["wx2026-07-11.png"]},{"id":"wx2026-07-064","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"64","domain":"信息安全管理","stem":"某公司财务服务器受到攻击被攻击者删除了所有用户数据,包括系统日志,公司网络管理员在了解情况后,给出了一些解决措施建议,作为信息安全主管,你必须指出不恰当的操作并阻止此次操作（）","options":["由于单位并无专业网络安全应急人员,网络管理员希望出具授权书委托某网络安全公司技术人员对本次攻击进行取证","由于公司缺乏备用硬盘,因此计划将恢复服务器上被删除的日志文件进行本地恢复后再提取出来进行取证","由于公司缺乏备用硬盘,因此网络管理员申请采购与服务器硬盘同一型号的硬盘用于存储恢复出来的数据","由于公司并无专业网络安全应急人员,因此由网络管理员负责此次事件的应急协调相关工作"],"correctIndex":1,"explanation":"将恢复服务器上被删除日志文件本地恢复再提取取证,可能覆盖原有数据,导致证据丢失,不恰当。","imageNames":[]},{"id":"wx2026-07-065","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"65","domain":"信息安全技术","stem":"在你对远端计算机进行ping操作,不同操作系统回应的数据包中初始TTL值是不同的, TTL是IP协议包中的一个值,它告诉网络,数据包在网络中的时间是否太长而应被丢弃。(简而言之,你可以通过TTL值推算一下下列数据包已经通过了多少个路由器)根据回应的数据包中的TL值,可以大致判断( )","options":["内存容量","操作系统的类型","对方物理位置","对方的MAC地址"],"correctIndex":1,"explanation":"不同操作系统回应数据包初始TTL值不同,通过TTL值可大致判断操作系统类型,不能判断内存容量、对方物理位置和MAC地址。","imageNames":[]},{"id":"wx2026-07-066","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"66","domain":"信息安全工程","stem":"( )攻击是建立在人性“弱点”利用基础上的攻击,大部分的社会工程学攻击都是经过( )才能实施成功的。即使是最简单的“直接攻击”也需要进行 ( )。如果希望受害者接受攻击者所( ),攻击者就必须具备这个身份需要的 ( )","options":["社会工程学: 精心策划; 前期的准备; 伪装的身份; 一些特征","精心策划; 社会工程学; 前期的准备; 伪装的身份; 一些特征","精心策划; 社会工程学; 伪装的身份; 前期的准备: 一些特征","社会工程学; 伪装的身份; 精心策划; 前期的准备; 一些特征"],"correctIndex":0,"explanation":"书本的229页,右边最下面的一段话。","imageNames":[]},{"id":"wx2026-07-067","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"67","domain":"信息安全法规标准","stem":"68内容安全是我国信息安全保障工作中的一个重要环节,互联网所带来的数字资源大爆发是使得内容安全越 越受到重视,以下哪个描述不属于内容安全的范畴 ( )","options":["某杂志在线网站建立内容正版化审核团队,对向网站投稿的内容进行版权审核,确保无侵犯版权行为后才能在网站好进行发布","某网站采取了技术措施,限制对同一P地址对网站的并发连接,避免爬虫通过大量的访问采集网站发布数据","某论坛根据相关法律要求, 进行了大量的关键词过滤, 使用户无法发布包含被过滤关键词的相关内容","某论坛根据国家相关法律要求,为了保证用户信息泄露,对所有用户信息,包括用户名、密码、身份证号等都进行了加密的存储"],"correctIndex":3,"explanation":"内容安全主要关注信息内容合法性、版权等方面,D选项对用户信息加密存储属于数据安全范畴,不属于内容安全。","imageNames":[]},{"id":"wx2026-07-068","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"68","domain":"信息安全工程","stem":"恶意软件抗分析技术的发展,恶意软件广泛使用了加壳、加密、混淆等抗分析技术,对恶意软件的分析难度越来越大。对恶意代码分析的研究已经成为信息安全领域的一个研究热点。小赵通过查阅发现一些安全软件的沙箱功能 实际上是虚拟化技术的应用,是动态分析中广泛采用的一种技术。小赵列出了一些动态分析的知识,其中错误的是（ ）","options":["动态分析是指在虚拟运行环境中,使用测试及监控软件,检测恶意代码行为,分析其执行流程及处理数据的状态,从而判断恶意代码的性质,并掌握其行为特点","动态分析针对性强,并且具有较高的准确性,但由于其分析过程中覆盖的执行路径有限,分析的完整性难以保证","动态分析通过对其二进制文件的分析,获得恶意代码的基本结构和特征,了解其工作方式和机制","动态分析通过监控系统进程、文件和注册表等方面出现的非正常操作和变化,可以对恶意代码非法行为进行分析"],"correctIndex":2,"explanation":"动态分析是在虚拟运行环境中检测恶意代码行为,C选项是对静态分析描述,错误。","imageNames":[]},{"id":"wx2026-07-069","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"69","domain":"信息安全技术","stem":"安全评估技术采用()这一工具,它是一种能够自动检测远程或本地主机和网络安全性弱点的程序。","options":["安全扫描器","安全扫描仪","自动扫描器","自动扫描仪"],"correctIndex":0,"explanation":"来源CISSP的,参考百度问答库,某信息安全知识竞赛题目。解析:安全评估技术采用安全扫描器,它能自动检测远程或本地主机和网络安全性弱点。","imageNames":[]},{"id":"wx2026-07-070","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"70","domain":"信息安全技术","stem":"小张在一不知名的网站上下载了鲁大师并进行了安装,电脑安全软件提示该软件有恶意捆绑,小张惊出一身汗,因为他知道恶意代码将随之进入系统后会对他的系统信息安全造成极大的威胁,那么恶意代码的软件部署常的实现方式不包括（ ）","options":["攻击者在获得系统的上传权限后,将恶意代码部署到目标系统","恶意代码自身就是软件的一部分,随软件部署传播","内嵌在软件中,当文件被执行时进入目标系统","恶意代码通过网上激活"],"correctIndex":3,"explanation":"恶意代码软件部署常见方式有攻击者上传、随软件部署传播、内嵌在软件中,恶意代码通过网上激活不是常见实现方式。","imageNames":[]},{"id":"wx2026-07-071","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"71","domain":"信息安全管理","stem":"操作系统是作为一个支撑软件,使得你的程序或别的应用系统在上面正常运行的一个环境。操作系统提供了多的管理功能,主要是管理系统的软件资源和硬件资源。操作系统软件自身的不安全性,系统开发设计的不周而下的破绽,都给网络安全留下隐患。某公司的网络维护师为实现该公司操作系统的安全目标,按书中所学建立了 应的安全机制,这些机制不包括（）","options":["标识与鉴别","访问控制","权限管理","网络云盘存取保护"],"correctIndex":3,"explanation":"操作系统安全机制包括标识与鉴别、访问控制、权限管理等,网络云盘存取保护不属于操作系统安全机制。","imageNames":[]},{"id":"wx2026-07-072","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"72","domain":"信息安全管理","stem":"信息安全应急响应,是指一个组织为了应对各种安全意外事件的发生所采取的防范措施,既包括预防性措施也包括事件发生后的应对措施。应急响应方法和过程并不是唯一的,在下面的应急响应管理流程图中,空白方填写正确的选项是（ ）","options":["培训阶段","文档阶段","报告阶段","检测阶段"],"correctIndex":3,"explanation":"应急响应管理流程图中空白方应填检测阶段,先检测到安全事件才能进行后续处理。","imageNames":["wx2026-07-12.png"]},{"id":"wx2026-07-073","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"73","domain":"信息安全管理","stem":"即时通讯安全是移动互联网时代每个用户和组织机构都应该认真考虑的问题,特别对于使用即时通讯进行工作交流和协作的组织机构。安全使用即时通讯应考虑许多措施,下列措施中错误的是( )","options":["如果经费许可,可以使用自建服务器的即时通讯系统","在组织机构安全管理体系中制定相应安全要求,例如禁止在即时通讯中传输敏感及以上级别的文档;建立管理流程及时将离职员工移除等","选择在设计上已经为商业应用提供安全防护的即时通讯软件,例如提供传输安全性保护等即时通讯","涉及重要操作包括转账无需方式确认"],"correctIndex":3,"explanation":"涉及重要操作包括转账需通过多种方式确认,D选项措施错误。","imageNames":[]},{"id":"wx2026-07-074","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"74","domain":"信息安全技术","stem":"如果有一名攻击者在搜索引擎中搜索“.doc+ XXX. com”找到XXX.com 网站上所有的word文档。该攻击者通过搜索“mdb”、“.ini”+域名,找到该域名下的mdb库文件、ini配置文件等非公开信息,通过这 些敏感信息对该网站进行攻击,请问这属于( )","options":["定点挖掘","攻击定位","网络实施嗅探","溢出攻击"],"correctIndex":0,"explanation":"攻击者通过搜索特定文件找到网站非公开信息并进行攻击,属于定点挖掘。","imageNames":[]},{"id":"wx2026-07-075","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"75","domain":"信息安全工程","stem":"以下哪些因素属于信息安全特征?( )","options":["系统和网络的安全","系统和动态的安全","技术、管理、工程的安全","系统的安全;动态的安全;无边界的安全;非传统的安全"],"correctIndex":3,"explanation":"信息安全特征包括系统安全、动态安全、无边界安全、非传统安全等。","imageNames":[]},{"id":"wx2026-07-076","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"76","domain":"信息安全管理","stem":"以下对单点登录技术描述不正确的是:()。","options":["单点登录技术实质是安全凭证在多个用户之间的传递或共享","使用单点登录技术用户只需在登录时进行一次注册,就可以访问多个应用","单点登录不仅方便用户使用,而且也便于管理","使用单点登录技术能简化应用系统的开发"],"correctIndex":0,"explanation":"单点登录技术实质是安全凭证在用户和多个应用系统之间传递或共享,不是多个用户之间,A选项错误。","imageNames":[]},{"id":"wx2026-07-077","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"77","domain":"信息安全法规标准","stem":"某集团公司信息安全管理员根据领导安排制定了下一年度的培训工作计划,提出了四大培训任务和目标,关于这四个培训任务和目标,作为主管领导,以下选项中正确的是 ( )","options":["由于网络安全上升到国家安全的高度,因此网络安全必须得到足够的重视,因此安排了对集团公司下属公司的总经理(一把手)的网络安全法培训","对下级单位的网络安全管理岗人员实施全面安全培训,计划全员通过CISP持证培训以确保人员能力得到保障","对其他信息化相关人员(网络管理员、软件开发人员)也进行安全基础培训,使相关人员对网络安全有所了解","对全体员工安排信息安全意识及基础安全知识培训,实现全员信息安全意识教育"],"correctIndex":0,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-07-078","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"78","domain":"信息安全法规标准","stem":"信息应按照其法律要求、价值、对泄露或篡改的()和关键性予以分类。信息资产的所有者应对其分类负责。分类的结果表明了( ),该价值取决于其对组织的敏感性和关键性如保密性、完整性和有效性。信息要进行标记并体现其分类,标记的规程需要涵盖物理和电子格式的 ( )。分类信息的标记和安全处理是信息共享的一个关键要求。( )和元数据标签是常见的形式。标记应易于辨认,规程应对标记附着的位置和方式给出指导,并考虑到信息被访问的方式和介质类型的处理方式。组织要建立与信息分类一致的资产处理、加工、存储和( )","options":["敏感性; 物理标签; 资产的价值; 信息资产; 交换规程","敏感性; 信息资产; 资产的价值; 物理标签; 交换规程","资产的价值; 敏感性; 信息资产; 物理标签; 交换规程","敏感性；资产的价值 ；信息资产物理标签；交换规程"],"correctIndex":3,"explanation":"来源于27002标准的原文。信息应按敏感性分类,分类表明资产价值,信息要有标记并体现分类,物理标签和元数据标签是常见形式,组织要建立与信息分类一致的资产处理等交换规程。","imageNames":[]},{"id":"wx2026-07-079","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"79","domain":"信息安全技术","stem":"杀毒软件一般是通过对代码与特征库中的特征码进行比对,判断这个文件是否是为恶意代码,如果是则进 女联系到病毒库中对该病毒的描述,从而确认其行为,达到分析的目的。下列对恶意代码静态分析的说法中,错误的是( )","options":["静态分析不需要实际执行恶意代码,它通过对其二进制文件的分析,获得恶意代码的基本结构和特征,了解其工作方式和机制","静态分析通过查找恶意代码二进制程序中嵌入的可疑字符串,如:文件名称、URL地址、域名、调用函数等来进行分析判断","静态分析检测系统函数的运行状态,数据流转换过程,能判别出恶意代码行为和正常软件操作","静态分析方法可以分析恶意代码的所有执行路径,但是随着程序复杂度的提高,冗余路径增多,会出现分析效率很低的情况"],"correctIndex":2,"explanation":"检测系统函数运行状态等是动态分析内容,不是静态分析,C选项错误。","imageNames":[]},{"id":"wx2026-07-080","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"80","domain":"信息安全法规标准","stem":"数据库是一个单位或是一个应用领域的通用数据处理系统,它存储的是属于企业和事业部门、团体和个人的有关数据的集合。数据库中的数据是从全局观点出发建立的,按一定的数据模型进行组织、描述和存储。其结构基于数据间的自然联系,从而可提供一切必要的存取路径,且数据不再针对某一应用,而是面向全组织,具有整体的结构化特征。数据库作为应用系统数据存储的系统,毫无疑问会成为信息安全的重点防护对象。数据库安全涉及到数据资产的安全存储和安全访问,对数据库安全要求不包括下列( )","options":["向所有用户提供可靠的信息服务","拒绝执行不正确的数据操作","拒绝非法用户对数据库的访问","能跟踪记录,以便为合规性检查、安全责任审查等提供证据和迹象等"],"correctIndex":0,"explanation":"数据库安全要求拒绝非法用户访问、拒绝执行不正确数据操作、能跟踪记录等,不是向所有用户提供可靠信息服务,A选项错误。","imageNames":[]},{"id":"wx2026-07-081","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"81","domain":"信息安全管理","stem":"目前,很多行业用户在进行信息安全产品选项时,均要求产品需通过安全测评。关于信息安全产品测评的意义,下列说法中不正确的是:","options":["有助于建立和实施信息安全产品的市场准入制度","对用户采购信息安全产品,设计、建设、使用和管理安全的信息系统提供科学公正的专业指导","对信息安全产品的研究、开发、生产以及信息安全服务的组织提供严格的规范引导和质量监督","打破市场垄断,为信息安全产业发展创造一个良好的竞争环境"],"correctIndex":3,"explanation":"信息安全产品测评意义不包括打破市场垄断。","imageNames":[]},{"id":"wx2026-07-082","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"82","domain":"信息安全法规标准","stem":"下面关于信息系统安全保障模型的说法不正确的是:","options":["国家标准《信息系统安全保障评估框架第一部分:简介和一般模型》 GB / 202714.1-2006）中的信息系统安全保障模型将风险和策略作为基础和核心","模型中的信息系统生命周期模型是抽象的概念性说明模型,在信息系统安全保障具体操作时,可根据具体环境和要求进行改动和细化","信息系统安全保障强调的是动态持续性的长效安全,而不仅是某时间点下的安全","信息系统安全保障主要是确保信息系统的保密性、完整性和可用性,单位对信息系统运行维护和使用的人员在能力和培训方面不需要投入"],"correctIndex":3,"explanation":"信息系统安全保障需要确保信息系统保密性等,同时对信息系统运行维护和使用人员在能力和培训方面也要投入,D选项错误。","imageNames":[]},{"id":"wx2026-07-083","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"83","domain":"信息安全法规标准","stem":"风险评估相关政策,目前主要有( ) (国信办[2006]5号)。主要内容包括:分析信息系统资产的( ),评估信息系统面临的( )、存在的( )、已有的安全措施和残余风险的影响等、两类信息系统的( )、涉密信息系统参照“分级保护”、 非涉密信息系统参照“等级保护”。","options":["《关于开展信息安全风险评估工作的意见》；重要程度 ；安全威胁；脆弱性； 工作开展","《关于开展风险评估工作的意见》;安全威胁；重要程度；脆弱性；工作开展","《关于开展风险评估工作的意见》; 重要程度; 安全威胁; 脆弱性; 工作开展","《关于开展信息安全风险评估工作的意见》 脆弱性;重要程度; 安全威胁; 工作开展"],"correctIndex":0,"explanation":"相关政策是《关于开展信息安全风险评估工作的意见》,内容包括分析信息系统资产重要程度等,两类信息系统工作开展,涉密信息系统参照“分级保护”等。","imageNames":[]},{"id":"wx2026-07-084","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"84","domain":"信息安全管理","stem":"( )在实施攻击之前,需要尽量收集伪装身份(),这些信息是攻击者伪装成功的( )。例如攻击者要伪装成某个大型集团公司总部的( ),那么他需要了解这个大型集团公司所处行业的一些行规或者 ( )、公司规则制度、组织架构等信息,甚至包括集团公司中相关人员的绰号等等。","options":["攻击者;所需要的信息;系统管理员;基础;内部约定","所需要的信息;基础;攻击者;系统管理员;内部约定","攻击者;所需要的信息:基础;系统管理员;内部约定","所需要的信息;攻击者;基础;系统管理员;内部约定"],"correctIndex":2,"explanation":"攻击者实施攻击前需收集伪装身份所需信息,这些信息是伪装成功基础,如伪装成系统管理员需了解相关行业规则等信息。","imageNames":[]},{"id":"wx2026-07-085","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"85","domain":"信息安全管理","stem":"小红和小明在讨论有关于现在世界上的IP地址数量有限的问题,小红说他看到有新闻说在2011年2月3日,全球互联网IP地址相关管理组织宣布现有的互联网IP地址已于当天划分给所有的区域互联网注册管理机构,IP地址总库已经枯竭,小明吓了一跳觉得以后上网会成问题,小红安慰道,不用担心,现在IPv6已经被试用它有好多优点呢,以下小红说的优点中错误的是( )","options":["网络地址空间的得到极大扩展","IPv6对多播进行了改进,使得具有更大的多播地址空间","繁杂报头格式","良好的扩展性"],"correctIndex":2,"explanation":"IPv6优点包括网络地址空间极大扩展、对多播改进、良好扩展性等,繁杂报头格式不是优点,C选项错误。","imageNames":[]},{"id":"wx2026-07-086","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"86","domain":"信息安全法规标准","stem":"87方法指导类标准主要包括GB/T-T25058-2010-《信息安全技术信息系统安全等级保护实施指南》GB / T25070-2010《信息系统等级保护安全设计技术要求》等。其中《等级保护实施指南》原以()政策文件方式发布,后修改后以标准发布。这些标准主要对如何开展()做了详细规定。状况分析类标准主要包括GB/T28448-2012《信息安全技术信息系统安全等级保护测评要求》和GB/T 284492012《信息安全技术信息系统安全等级保护测评过程指南》等。其中在()工作期间还发布过《等级保护测评准则》等文件,后经过修改以《等级保护测评要求》发布。这些标准主要对如何开展( )工作做出了( )","options":["公安部；等级保护试点；等级保护工作；等级保护测评；详细规定.","公安部；等级保护工作；等级保护试点；等级保护测评；详细规定","公安部；等级保护工作；等级保护测评；等级保护试点；详细规定","公安部；等级保护工作；等级保护试点；详细规定；等级保护测评"],"correctIndex":1,"explanation":"《等级保护实施指南》原以公安部政策文件方式发布,后修改为标准发布,主要对如何开展等级保护工作做详细规定,在等级保护试点工作期间发布过相关文件,后修改为《等级保护测评要求》发布,主要对等级保护测评工作做详细规定。","imageNames":[]},{"id":"wx2026-07-087","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"87","domain":"信息安全管理","stem":"下列选项中,对风险评估文档的描述中正确的是( )","options":["评估结果文档包括描述资产识别和赋值的结果,形成重要资产列表","描述评估结果中不可接受的风险制定风险处理计划,选择适当的控制目标及安全措施,明确责任、进度、资源,并通过对残余风险的评价以确定所选择安全措施的有效性的《风险评估程序》","在文档分发过程中作废文档可以不用添加标识进行保留","对于风险评估过程中形成的相关文档行,还应规定其标识、储存、保护、检索、保存期限以及处置所需的控制"],"correctIndex":3,"explanation":"评估结果文档包括描述资产识别和赋值结果等；描述评估结果中不可接受风险制定风险处理计划等的是《风险处理计划》；文档分发中作废文档要添加标识保留；D选项对风险评估文档描述正确。","imageNames":[]},{"id":"wx2026-07-088","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"88","domain":"信息安全工程","stem":"下列软件开发模型中,支持需求不明确,特别是大型软件系统的开发,并支持多种软件开发方法的模型是（ ）","options":["原型模型","瀑布模型","喷泉模型","螺旋模型"],"correctIndex":3,"explanation":"螺旋模型支持需求不明确的大型软件系统开发,支持多种软件开发方法。原型模型主要用于需求不明确小型项目；瀑布模型需求明确且固定；喷泉模型以用户需求为动力,以对象为驱动。","imageNames":[]},{"id":"wx2026-07-089","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"89","domain":"信息安全保障","stem":"90供电安全是所有电子设备都需要考虑的问题,只有持续平稳的电力供应才能保障电子设备作稳定可靠因此电力供应需要解决问题包括两个,一是确保电力供应不中断、二是确保电力供应平稳。下列选项中,对电力供应的保障措施的描述正确的是（）","options":["可以采用双路供电来确保电力供应稳定性","UPS可提供持续、平稳的电力供应,不会受到电涌的影响","可以部署电涌保护器来确保电力供应稳定性","发动机供电是目前电力防护最主要的技术措施"],"correctIndex":2,"explanation":"该答案按照理论和实践的合理分析,答案为C。教材第337页。部署电涌保护器可确保电力供应稳定性,A选项双路供电是确保电力供应不中断措施；B选项UPS会受电涌影响；D选项发动机供电不是最主要技术措施。","imageNames":[]},{"id":"wx2026-07-090","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"90","domain":"信息安全法规标准","stem":"漏洞扫描是信息系统风险评估中的常用技术措施,定期的漏洞扫描有助于组织机构发现系统中存在的安全漏洞。漏洞扫描软件是实施漏洞扫描的工具,用于测试网络、操作系统、数据库及应用软件是否存在漏洞。某公司安全管理组成员小李对漏洞扫描技术和工具进行学习后有如下理解,其中错误的是（ ）","options":["主动扫描工作方式类似于IDS ( Intrusion Detection Systems)","CVE ( Common Vulnerabilities& Exposures) 为每个漏洞确定了唯一的名称和标准化的描述","X. Scanner采用多线程方式对指定IP地址段进行安全漏洞扫描","ISS 的 System Scanner通过依附于主机上的扫描器代理侦测主机内部的漏洞"],"correctIndex":0,"explanation":"主动扫描工作方式类似于网络扫描器,不是IDS,A选项错误。","imageNames":[]},{"id":"wx2026-07-091","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"91","domain":"信息安全工程","stem":"组织应开发和实施使用()来保护信息的策略,基于风险评估,宣确定需要的保护级别,并考虑需要的加密算法的类型、强度和质量。当实施组织的()时,宣考虑我国应用密码技术的规定和限制,以及( )跨越国界时的向题。组织应开发和实施在密钥生命周期中使用和保护密钥的方针。方针应包括密钥在其全部生命周期中的管理要求,包括密钥的生成、存储、归档、检索、分配、卸任和销毁。宜根据最好的实际效果选择加密算法、密钥长度和使用习惯。适合的( )要求密钥在生成、存储、归档、检索、分配、卸任和销毁过程中的安全。宜保护所有的密钥免遭修改和丢失。另外,秘密和私有密钥需要防范非授权的泄露。用来生成、存储和归档密钥的设备宜进行( )。","options":["加密控制措施; 加密信息; 密码策略; 密钥管理; 物理保护","加密控制措施; 密码策略; 密钥管理; 加密信息; 物理保护","加密控制措施; 密码策略; 加密信息; 密钥管理: 物理保护","加密控制措施; 物理保护; 密码策略; 加密信息; 密钥管理"],"correctIndex":2,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-07-092","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"92","domain":"信息安全技术","stem":"由于病毒攻击、非法入侵等原因,校园网整体瘫痪,或者校园网络中心全部DNS主WEB服务器不能正常工作;由于病毒攻击、非法入侵、人为破坏或不可抗力等原因,造成校园网出口中断,属于以下哪种级别事件( )","options":["特别重大事件","重大事件","较大事件","一般事件"],"correctIndex":3,"explanation":"按照《 信息安全技术 信息安全事件分类分级指南》（GB/Z 20986—2007）","imageNames":[]},{"id":"wx2026-07-093","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"93","domain":"信息安全管理","stem":"安全审计是事后认定违反安全规则行为的分析技术,在检测违反安全规则方面、准确发现系统发生的事件以对事件发生的事后分析方面,都发挥着巨大的作用。但安全审计也有无法实现的功能,以下哪个需求是网络安全审计无法实现的功能( )","options":["发现系统中存储的漏洞和缺陷","发现用户的非法操作行为","发现系统中存在后门及恶意代码","发现系统中感染的恶意代码类型及名称"],"correctIndex":3,"explanation":"要求识别恶意代码的具体类型和名称,这超出了审计的技术范围,需依赖专用恶意代码工具","imageNames":[]},{"id":"wx2026-07-094","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"94","domain":"信息安全保障","stem":"数位物件识别号 (Digital Object Identifier,简称DOI )是一套识别数位资源的机制,涵括的对象有视频报告或书籍等等。它既有一套为资源命名的机制,也有一套将识别号解析为具体位址的协定。DOI码由前缀和后两部分组成,之间用“/”分开,并且前缀以“.”再分为两部分。以下是一个典型的DOI识别号 10.1006/jmbi.1998.2354,下列选项错误的是( )","options":["“10.1006”是前缀,由国际数位物件识别号基金会确定","“10”为DOI目前唯一的特定代码,用以将DOI与其他采用同样技术的系统区分开","“1006”是注册代理机构的代码,或出版社代码,用于区分不同的注册机构","后缀部分为: jmbi.1998. 2354,由资源发行者自行指定,用于区分一个单独的数字资料,不具有唯一性"],"correctIndex":3,"explanation":"DOI后缀部分由资源发行者自行指定,用于区分单独数字资料,具有唯一性,D选项错误。","imageNames":[]},{"id":"wx2026-07-095","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"95","domain":"信息安全技术","stem":"某网盘被发现泄露了大量私人信息,通过第三方网盘搜索引擎可查询到该网盘用户的大量照片、通讯录。盘建议用户使用“加密分享”功能,以避免消息泄露,“加密分享”可以采用以下哪些算法（ ）。","options":["MD5 算法,SHA-1算法","DSA算法,RSA算法","SHA-1算法,SM2算法","RSA算法,SM2算法"],"correctIndex":3,"explanation":"RSA算法和SM2算法可用于加密分享,MD5算法和SHA - 1算法是哈希算法,DSA算法主要用于数字签名。","imageNames":[]},{"id":"wx2026-07-096","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"96","domain":"信息安全管理","stem":"作为单位新上任的CS0,你组织了一次本单位的安全评估工作以了解单位安全现状。在漏洞扫描报告发现了某部署在内网且仅对内部服务的业务系统存在一个漏洞,对比上一年度的漏洞扫描报告,发现这个 经报告出来,经询问安全管理员得知,这个业务系统开发商已经倒闭,因此无法修复。对于这个问题, 处理 ( )","options":["向公司管理层提出此问题,要求立即立项重新开发此业务系统,避免单位中存在这样的安全风险","既然此问题不是新发现的问题,之前已经存在,因此与自己无关,可以不予理会","让安全管理人员重新评估此漏洞存在的安全风险并给出进一步的防护措施后再考虑如何处理","让安全管理员找出验收材料看看有没有该业务系统源代码,自己修改解决这个漏洞"],"correctIndex":2,"explanation":"应让安全管理人员重新评估漏洞风险并给出防护措施后再处理,A选项重新开发成本高；B选项不理会不正确；D选项自己修改源代码不现实且可能引入新问题。","imageNames":[]},{"id":"wx2026-07-097","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"97","domain":"信息安全法规标准","stem":"98以下哪项网络攻击会对《网络安全法》定义的网络运行安全造成影响?","options":["DDOS攻击","网页篡改","个人信息泄露","发布谣言信息"],"correctIndex":0,"explanation":"DDOS攻击会影响网络运行安全,网页篡改主要影响信息完整性等,个人信息泄露涉及隐私,发布谣言信息涉及信息内容合法性。","imageNames":[]},{"id":"wx2026-07-098","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"98","domain":"信息安全工程","stem":"99软件工程方法提出起源于软件危机,而其目的应该是最终解决软件的问题的是（ ）","options":["质量保证","生产危机","生产工程化","开发效率"],"correctIndex":2,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-07-099","setId":"wx2026-07","setName":"CISP 复习题（5）","sourceNumber":"99","domain":"信息安全管理","stem":"风险评估的过程包括 ( )、( )、( )和( )四个阶段。在信息安全风险管理过程中,风险评估建立阶段的输出,形成本阶段的最终输出《风险评估报告》,此文档为风险处理活动提供输入。( )风险评估的四个阶段。","options":["风险评估准备; 风险要素识别; 风险分析; 监控审查; 风险结果判定; 沟通咨询","风险评估准备; 风险要素识别; 监控审查 ;风险分析; 风险结果判定; 沟通咨询","风险评估准备; 监控审查 ;风险要素识别; 风险分析 ;风险结果判定; 沟通咨询","风险评估准备; 风险要素识别: 风险分析: 风险结果判定 监控审查, 沟通咨询"],"correctIndex":3,"explanation":"风险评估过程包括风险评估准备、风险要素识别、风险分析、风险结果判定四个阶段,监控审查和沟通咨询贯穿其中。","imageNames":[]}]},{"id":"wx2026-08","name":"CISP 复习题（6）","subtitle":"100题 · 有答案+解析","sourceFile":"CISP复习题（6）100题（有答案）-已审+解析.docx","questionCount":100,"questions":[{"id":"wx2026-08-001","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"1","domain":"信息安全法规标准","stem":"CC标准是目前系统安全认证方面最权威的标准,以下哪一项没有体现CC标准的先进性:","options":["结构的开放性","表达方式的通用性","独立性","实用性"],"correctIndex":2,"explanation":"CC标准（信息技术安全评估准则）的先进性体现在结构开放性、表达通用性和实用性。","imageNames":[]},{"id":"wx2026-08-002","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"2","domain":"信息安全法规标准","stem":"根据《信息安全等级保护管理办法》、《关于开展信息安全等级保护测评体系建设试点工作的通知》（公信安[2009]812号）,关于推动信息安全等级保护（ ）建设和开展( )工作的通知（公信安[2010]303号）等文件,由公安部( )对等级保护测评机构管理,接受测评机构的申请、考核和定期（ ）,对不具备能力的测评机构则（ ）","options":["等级测评；测评体系；等级保护评估中心；能力验证；取消授权","测评体系；等级保护评估中心；等级测评；能力验证；取消授权","测评体系；等级测评；等级保护评估中心；能力验证；取消授权","测评体系；等级保护评估中心；能力验证；等级测评；取消授权"],"correctIndex":2,"explanation":"根据文件要求,公安部通过“测评体系”推动信息安全等级保护,开展“等级测评”工作,由“等级保护评估中心”管理测评机构,进行“能力验证”,对不合格机构“取消授权”。","imageNames":[]},{"id":"wx2026-08-003","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"3","domain":"信息安全管理","stem":"以下哪个现象较好的印证了信息安全特征中的动态性( )","options":["经过数十年的发展,互联网上已经接入了数亿台各种电子设备","刚刚经过风险评估并针对风险采取处理措施后仅一周,新的系统漏洞使得信息系统面临新的风险","某公司的信息系统面临了来自美国的“匿名者”黑客组织的攻击","某公司尽管部署了防火墙、防病毒等安全产品,但服务器中数据仍产生了泄露"],"correctIndex":1,"explanation":"动态性指信息安全风险随时间变化。新漏洞导致新风险,体现了风险的动态变化,符合信息安全特征的动态性。","imageNames":[]},{"id":"wx2026-08-004","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"4","domain":"信息安全技术","stem":"老王是某政府信息中心主任。以下哪项项目是符合《保守国家移密法》要求的( )","options":["老王安排下属小李将损害的涉密计算机某国外品牌硬盘送到该品牌中国区维修中心修理","老王要求下属小张把中心所有计算机贴上密级标志","老王每天晚上12点将涉密计算机连接上互联网更新杀毒软件病毒库","老王提出对加密机和红黑电源插座应该与涉密信息系统同步投入使用"],"correctIndex":3,"explanation":"根据《保守国家秘密法》,加密机和红黑电源插座应与涉密信息系统同步使用（“三同步”原则）,其他选项或违反保密规定,或操作不当。","imageNames":[]},{"id":"wx2026-08-005","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"5","domain":"信息安全法规标准","stem":"关于计算机取征描述不正确的是（）","options":["计算机取证是使用先进的技术和工具,按照标准规程全面的检查计算机系统以提取和保护有关计算机犯罪的相关证据的活动","取证的目的包括通过证据,查找肇事者,通过证据推断犯罪过程,通过证据判断受害者损失程度及涉及证据提供法律支持","电子证据是计算机系统运行过程中产生的各种信息记录及存储的电子化资料及物品,对于电子证据取证工作主要围绕两方面进行证据的获取和证据的保护","计算机取证的过程,可以分为准备,保护,提取,分析和提交五个步骤"],"correctIndex":2,"explanation":"电子证据取证包括获取和保护,但C项将“证据获取和保护”描述为“主要围绕两方面进行”不准确,取证还涉及分析、呈现等环节。","imageNames":[]},{"id":"wx2026-08-006","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"6","domain":"信息安全法规标准","stem":"（ ）第23条规定存储、处理国家机秘密的计算机信息系统（以下简称涉密信息系统）,按照（ ）实行分级保护,（ ）应当按照国家保密标准配备保密设施、设备。（ ）、设备应当与涉密信息系统同步规划、同步建设、同步运行（三同步）。涉密信息系统应当按照规定,经（ ）后方可投入使用。","options":["《保密法》；涉密程度；涉密信息系统；保密设施；检查合格","《国家保密法》；涉密程度；涉密系统；保密设施；检查合格","《网络保密法》；涉密程度；涉密系统；保密设施；检查合格","《安全保密法》；涉密程度,涉密信息系统；保密设施；检查合格"],"correctIndex":0,"explanation":"依据《保密法》,涉密信息系统按涉密程度分级保护,保密设施与系统同步规划,经检查合格后投入使用。","imageNames":[]},{"id":"wx2026-08-007","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"7","domain":"信息安全管理","stem":"Linux系统的安全设置主要从磁盘分区、账户安全设置、禁用危险服务、远程登录安全、用户鉴别安全、审计策略、保护root账户、使用网络防火墙和文件权限操作共10个方面来完成。小张在学习了Linux系统安全的相关知识后,尝试为自己计算机上的Linux系统进行安全配置。下列选项是他的部分操作,其中不合理的是（ ）。","options":["编辑文件/etc/passwd,检查文件中用户ID,禁用所有ID=0的用户","编辑文件/etc/ssh/sshd _config, 将Permit RootLogin设置为no","编辑文件/etc/pam.d/system~auth,设置auth required pam tally. so onerr=fail deny=6 unlock_time-300","编辑文件/etc/profile, 设置TMOUT=600"],"correctIndex":0,"explanation":"禁用ID=0的用户不合理,因root用户ID必须为0,禁用会导致系统无法管理。其他选项为合理安全配置。","imageNames":[]},{"id":"wx2026-08-008","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"8","domain":"信息安全管理","stem":"PDCA循环又叫戴明环,是管理学常用的一种模型。关于PDCA四个字母,下面理解错误的是（ ）","options":["P是Plan,指分析问题、发现问题、确定方针、目标和活动计划","D是Do,指实施、具体运作,实现计划中的内容","C是Check,指检查、总结执行计划的结果,明确效果,找出问题","A 是Aim,指瞄准问题,抓住安全事件的核心,确定责任"],"correctIndex":3,"explanation":"PDCA中A代表“Act”（处理）,指根据检查结果采取改进措施,而非“Aim”（瞄准问题）。","imageNames":[]},{"id":"wx2026-08-009","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"9","domain":"信息安全法规标准","stem":"在国家标准GB/T 20274. 1-2006《信息安全技术信息系统安全保障评估框架第一部分:简介和一般模型》中,信息系统安全保障模型包含哪几个方面? （ ）","options":["保障要素、生命周期和运行维护","保障要素、生命周期和安全特征","规划组织、生命周期和安全特征","规划组织、生命周期和运行维护"],"correctIndex":1,"explanation":"GB/T 20274.1-2006中,信息系统安全保障模型包含保障要素、生命周期和安全特征。","imageNames":[]},{"id":"wx2026-08-010","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"10","domain":"信息安全技术","stem":"目前,信息系统面临外部攻击者的恶意攻击威胁,从成胁能力和掌握资源分,这些威胁可以按照个人威胁、组织威胁和国家威胁三个层面划分,则下面选项中属于组织威胁的是（ ）","options":["喜欢恶作剧、实现自我挑战的娱乐型黑客","实施犯罪、获取非法经济利益网络犯罪团伙","搜集政治、军事、经济等情报信息的情报机构","巩固战略优势,执行军事任务、进行目标破坏的信息作战部队"],"correctIndex":1,"explanation":"组织威胁以经济利益为目标,如网络犯罪团伙；个人威胁多为娱乐型黑客；国家威胁涉及情报机构或军事部队。","imageNames":[]},{"id":"wx2026-08-011","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"11","domain":"信息安全法规标准","stem":"若一个组织声称自己的ISMS符合ISO/IEC 27001 或GB/T22080标准要求,其信息安全控制措施通常需要在资产管理方面安施常规控制,资产管理包含对资产负责和信息分类两个控制目标。信息分类控制的目标是为了确保信息受到适当级别的保护,通常采取以下哪项控制措施（ ）","options":["资产清单","资产责任人","资产的可接受使用","分类指南,信息的标记和处理"],"correctIndex":3,"explanation":"信息分类控制通过“分类指南、信息的标记和处理”确保信息受适当保护,其他选项为资产管理的一般控制。","imageNames":[]},{"id":"wx2026-08-012","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"12","domain":"信息安全法规标准","stem":"有关质量管理,错误的理解是（ ）。","options":["质量管理是与指挥和控制组织质量相关的一系列相互协调的活动,是为了实现质量目标,而进行的所有管理性质的活动","规范质量管理体系相关活动的标准是ISO 9000系列标准","C质量管理体系将资源与结果结合,以结果管理方法进行系统的管理","质量管理体系从机构,程序、过程和总结四个方面进行规范来提升质量"],"correctIndex":2,"explanation":"质量管理体系通过过程方法（PDCA）管理,而非结果管理方法。","imageNames":[]},{"id":"wx2026-08-013","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"13","domain":"信息安全技术","stem":"在某信息系统的设计中,用户登录过程是这样的: (1)用户通过HTTP协议访问信息系统; (2)用户在登录页面输入用户名和口令； (3)信息系统在服务器端检查用户名和密码的正确性, 如果正确,则鉴别完成。可以看出,这个鉴别过程属于（ ）","options":["单向鉴别","双向鉴别","三向鉴别","第三方鉴别"],"correctIndex":0,"explanation":"单向鉴别仅服务器验证用户身份,用户不验证服务器,如HTTP基本认证。","imageNames":[]},{"id":"wx2026-08-014","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"14","domain":"信息安全管理","stem":"随机进程名称是恶意代码迷惑管琊员和系统安全检查人员的技术手段之一,以下对于随机进程名技术。描述正确的是（ ）。","options":["随机进程名技术虽然每次进程名都是随机的,但是只要找到了进程名称,就找到了恶意代码程序本身","恶意代码生成随机进程名称的目的是使过程名称不固定,因为杀毒软件是按照进程名称进行病毒进程查杀","恶意代码使用随机进程名是通过生成特定格式的进程名称,使进程管理器中看不到恶意代码的进程","D随机进程名技术每次启动时随机生成恶意代码进程名称,通过不固定的进程名称使自己不容易被发现真实的恶意代码程序名称"],"correctIndex":3,"explanation":"随机进程名通过动态变化隐藏恶意代码,避免被检测,但进程名随机生成仍可能被逆向分析找到真实程序。","imageNames":[]},{"id":"wx2026-08-015","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"15","domain":"信息安全技术","stem":"随着即时通讯软件的普及使用,即时通讯软件也被恶意代码利用进行传播,以下哪项功能不是恶意代码利用即时通讯进行传播的方式","options":["利用即时通讯软件的文件传送功能发送带恶意代码的可执行文件","利用即时通讯软件发送指向恶意网页的URL","利用即时通讯软件发送指向恶意地址的二维码","利用即时通讯发送携带恶意代码的JPG图片"],"correctIndex":2,"explanation":"选项A即时通讯软件的文件传送功能允许用户发送任意文件类型,包括可执行文件（如.exe、.bat）。选项B攻击者可发送短链接或伪装成正常网站的URL,用户点击后跳转到恶意网页（如钓鱼网站、漏洞利用页面）。选项C的二维码需用户主动扫描,且即时通讯软件不直接解析二维码内容,传播依赖用户行为,非软件功能本身。选项D的恶意图片可通过软件漏洞或社会工程学直接传播,属于对软件功能的利用。","imageNames":[]},{"id":"wx2026-08-016","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"16","domain":"信息安全法规标准","stem":"GB/T 22080-2008 《信息技术 安全技术 信息安全管理体系 要求》指出,建立信息安全管理体系应参照PDCA模型进行,即信息安全管理体系应包括建立ISMS、 实施和运行ISMS、监视和评审ISMS、 保持和改进ISMS等过程,并在这些过程中应实施若干活动。请选出以下描述错误的选项（ ）。","options":["“制定ISMS方针”是建立ISMS阶段工作内容","“安施培训和意识教育计划”是实施和运行ISMS阶段工作内容","“进行有效性测量”是监视和评审ISMS阶段工作内容","“实施内部审核”是保持和改进ISMS阶段工作内容"],"correctIndex":3,"explanation":"“实施内部审核”是监视和评审ISMS阶段的内容,非保持和改进阶段。","imageNames":[]},{"id":"wx2026-08-017","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"17","domain":"信息安全工程","stem":"某单位需要开发一个网站,为了确保开发出安全的软件。软件开发商进行了OA系统的威胁建模,根据威胁建模,SQL注入是网站系统面临的攻击威胁之一, 根据威胁建模的消减威胁的做法。以下哪个属于修改设计消除威胁的做法（ ）","options":["在编码阶段程序员进行培训,避免程序员写出存在漏洞的代码","对代码进行严格检查,避免存在SQL注入漏洞的脚本被发布","使用静态发布,所有面向用户发布的数据都使用静态页面","在网站中部署防SQL注入脚本,对所有用户提交数据进行过滤"],"correctIndex":2,"explanation":"静态发布通过消除动态交互（如用户输入）彻底避免SQL注入,其他选项为减轻威胁而非消除。","imageNames":[]},{"id":"wx2026-08-018","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"18","domain":"信息安全工程","stem":"信息系统安全保障评估概念和关系如图所示。信息系统安全保障评估,就是在信息系统所处的运行环境中对信息系统安全保障的具体工作和活动进行客观的评估。通过信息系统安全保障评估所搜集的（ ）,向信息系统的所有相关方提供信息系统的（ ）能够实现其安全保障策略,能够将其所面临的风险降低到其可接受的程度的主观信心。信息系统安全保障评估的评估对象是（ ）,信息系统不仅包含了仅讨论技术的信息技术系统,还包括同信息系统所处的运行环境相关的人和管理等领域。信息系统安全保障是一个动态持续的过程,涉及信息系统整个（ ）,因此信息系统安全保障的评估也应该提供一种（ ）的信心。","options":["安全保障工作；客观证据；信息系统；生命周期；动态持续","客观证据；安全保障工作；信息系统；生命周期；动态持续","客观证据；安全保障工作；生命周期；信息系统；动态持续","客观证据；安全保障工作；动态持续；信息系统；生命周期"],"correctIndex":1,"explanation":"评估通过搜集客观证据,证明安全保障工作有效性,评估对象为信息系统,覆盖生命周期,提供动态持续信心。","imageNames":["wx2026-08-01.png"]},{"id":"wx2026-08-019","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"19","domain":"信息安全保障","stem":"某企业内网中感染了一种依靠移动存储进行传播的特洛伊木马病毒,由于企业部署的杀毒软件,为了解决该病毒在企业内部传播,作为信息化负责人,你应采取以下哪项策略()","options":["更换企业内部杀毒软件,选择一个可以查杀到该病毒的软件进行重新部署","向企业内部的计算机下发策略,关闭系统默认开启的自动播放功能","禁止在企业内部使用如U盘、移动硬盘这类的移动存储介质","在互联网出口部署防病毒网关,防止来自互联网的病毒进入企业内部"],"correctIndex":1,"explanation":"关闭自动播放可防止U盘等移动存储介质自动执行恶意代码,其他选项或治标不治本,或影响业务。","imageNames":[]},{"id":"wx2026-08-020","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"20","domain":"信息安全技术","stem":"分布式拒绝服务（Distributed Denial of Service, DDos）攻击指借助于客户/服务器技术,将多个计算机联合起来作为攻击平台。对一个或多个目标发动DDoS攻击,从而成倍地提高拒绝服务攻击的威力。一般来说,DDoS攻击的主要目的是破坏目标系统的（）","options":["保密性","完整性","可用性","真实性"],"correctIndex":2,"explanation":"DDoS攻击通过大量请求耗尽目标资源,破坏可用性。","imageNames":[]},{"id":"wx2026-08-021","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"21","domain":"信息安全技术","stem":"作为信息安全从业人员,以下哪种行为违反了CISP职业道德准侧（）","options":["抵制通过网络系统侵犯公众合法权益","通过公众网络传播非法软件","不在计算机网络系统中进行造谣、欺诈、诽谤等活动","帮助和指导信息安全同行提升信息安全保障知识和能力。"],"correctIndex":1,"explanation":"传播非法软件违反CISP职业道德准则,其他选项为合规行为。","imageNames":[]},{"id":"wx2026-08-022","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"22","domain":"信息安全技术","stem":"Apache HTTP Server（简称Apache）是个开放源码的Web服务运行平台,在使用过程中,该软件默认会将自己的软件名和版本号发送给客户端。从安全角度出发,为隐藏这些信息,应当采取以下哪种措施()","options":["不选择Windons平台,应选择在Linux平台下安装使用","安装后。修改配置文件httpd.conf中的有关参数","安装后。删除Apache HTTP Server源码","从正确的官方网站下载Apache HTTP Server. 并安装使用"],"correctIndex":1,"explanation":"修改httpd.conf中的ServerTokens和ServerSignature参数可隐藏Apache版本信息。","imageNames":[]},{"id":"wx2026-08-023","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"23","domain":"信息安全技术","stem":"安全漏洞产生的原因不包括以下哪一点()","options":["软件系统代码的复杂性","软件系统市场出现信息不对称现象","复杂异构的网络环境","攻击者的恶意利用"],"correctIndex":3,"explanation":"选项A复杂代码易引入未处理的边界条件、逻辑错误或未授权访问路径,是漏洞的直接成因。选项B信息不对称指开发者与用户之间对软件安全性认知的差异（如开发者隐瞒漏洞,用户不知情）。选项C异构网络（如不同协议、设备、操作系统）可能因兼容性问题或配置错误引入漏洞（如未加密通信、默认密码）。选项D攻击者利用漏洞是漏洞的后果或威胁行为,而非漏洞产生的原因。漏洞的存在是独立于攻击者的,即使无攻击者,漏洞仍可能存在。","imageNames":[]},{"id":"wx2026-08-024","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"24","domain":"信息安全法规标准","stem":"某IT 公司针对信息安全事件已经建立了完善的预案,在年度企业信息安全总结会上,信息安全管理员对今年应急预案工作做出了四个总结,其中有一项总结工作是错误,作为企业的CSO,请你指出存在问题的是哪个总结？（）","options":["公司自身拥有优秀的技术人员,系统也是自己开发的,无需进行应急演练工作,因此今年的仅制定了应急演练相关流程及文档,为了不影响业务,应急演练工作不举行","公司制定的应急演练流程包括应急事件通报、确定应急事件优先级应急响应启动实施、应急响应时间后期运维、更新现在应急预案五个阶段,流程完善可用","公司应急预案包括了基本环境类、业务系统、安全事件类、安全事件类和其他类,基本覆盖了各类应急事件类型","公司应急预案对事件分类依据GB/Z 20986-2007《信息安全技术信息安全事件分类分级指南》,分为7个基本类别,预案符合国家相关标准"],"correctIndex":0,"explanation":"应急演练必须定期进行,仅制定流程不执行无法验证预案有效性。","imageNames":[]},{"id":"wx2026-08-025","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"25","domain":"信息安全管理","stem":"某软件在设计时,有三种用户访问模式,分别是仅管理员可访问、所有合法用户可访问和允许匿名访问)采用这三种访问模式时,攻击面最高的是()。","options":["仅管理员可访问","所有合法用户可访问","允许匿名","三种方式一样"],"correctIndex":2,"explanation":"匿名访问无需认证,攻击者可自由访问,攻击面最大。","imageNames":[]},{"id":"wx2026-08-026","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"26","domain":"信息安全管理","stem":"王工是某单位的系统管理员,他在某次参加了单位组织的风险管理工作时,发现当前案例中共有两个重要资产:资产A1和资产A2,其中资产A1面临两个主要威胁: 威胁T1和威胁T2: 而资产A2面临一个主要威胁: 威胁T3；威胁T1可以利用的资产A1存在的两个脆性: 脆弱性V1和脆弱性V2； 威胁T2可以利用的资产A1存在的三个脆弱性:脆弱性V3、脆弱性V4和脆弱性V5; 威胁T3可以利用的资产A2存在的两个脆弱性: 脆弱性V6和脆弱性V7; 根据上述条件,请问:使用相乘法时,应该为资产A1计算几个风险值( )","options":["2","3","5","6"],"correctIndex":2,"explanation":"A1风险值是由两个值来决定,一个是安全事件的可能性,一个是安全事件造成的损失,先算第一个安全事件的可能性,就是它的发生的这个频率,它是由这个威胁去乘以这个脆弱性的,A1资产有2个威胁,T1是利用的是2个脆弱性,就是1个威胁*2脆弱性,1*2=2,T2是3个脆弱性,就是1个威胁*3脆弱性,1*3=3,两者比较,取值选大的,最后它发生的这个频率是3,算出安全事件的可能性是3,然后再算第二个安全事件造成的损失。就是资产受到破坏的程度,它是由资产去乘以这个脆弱性,一个资产,正好是5个脆弱性,1*5=5。安全事件可能性是3,安全事件造成的损失是5,两者比较,一个是3,一个是5,取值选大的,得到5,选C。","imageNames":[]},{"id":"wx2026-08-027","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"27","domain":"信息安全工程","stem":"某政府机构委托开发商开发了一个 OA系统。其中公交分发功能使用了FTP协议,该系统运行过程中被攻击者通过FTP对OA系统中的脚本文件进行了篡改,安全专家提出使用Http下载代替FTP功能以解决以上问题,该安全问题的产生主要是在哪个阶段产生的()","options":["程序员在进行安全需求分析时,没有分析出OA系统开发的安全需求","程序员在软件设计时,没遵循降低攻击面的原则,设计了不安全的功能","程序员在软件编码时,缺乏足够的经验,编写了不安全的代码","程序员在进行软件测试时,没有针对软件安全需求进行安全测试"],"correctIndex":1,"explanation":"FTP协议明文传输,设计时未遵循最小攻击面原则,应改用HTTPS。","imageNames":[]},{"id":"wx2026-08-028","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"28","domain":"信息安全工程","stem":"从SABSA的发展过程,可以看出整个SABSA在安全架构中的生命周期（如下图所示）,在此SABSA生命周期中,前两个阶段的过程被归类为所谓的（ ）,其次是（ ）,它包含了建筑设计中的（ ）、物理设计、组件设计和服务管理设计,再者就是（ ）,紧随其后的则是（ ）","options":["设计；战略与规划；逻辑设计；实施；管理与衡量","战略与规划；逻辑设计；设计；实施；管理与衡量","战略与规划；实施；设计；逻辑设计；管理与衡量","战略与规划；设计；逻辑设计；实施；管理与衡量"],"correctIndex":3,"explanation":"SABSA生命周期依次为战略与规划、设计、逻辑设计、实施、管理与衡量。","imageNames":[]},{"id":"wx2026-08-029","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"29","domain":"信息安全管理","stem":"随着信息安全涉及的范围越来越广,各个组织对信息安全管理的需求越来越迫切。越来越多的组织开始尝试使用参考ISO27001介绍的ISMS来实施信息安全管理体系,提高组织的信息安全管理能力。关于ISMS。下面描述错误的是（ ）。","options":["在组织中,应由信息技术责任部门(如信息中心)制定井颁布信息安全方针,为组织的ISMS建设指明方向并提供总体纲领,明确总体要求","组织的管理层应确保ISMS目标和相应的计划得以制定,信息安全管理目标应明确、可度量,风险管理计划应具体,具备可行性","组织的信息安全目标、信息安全方针和要求应传达到全组织范围内。应包括全体员工,同时,也应传达到客户、合作伙伴和供应商等外部各方","组织的管理层应全面了解组织所面临的信息安全风险,决定风险可接受级别和风险可接受准则,并确认接受相关残余风险"],"correctIndex":0,"explanation":"信息安全方针应由管理层制定,而非仅信息技术部门。","imageNames":[]},{"id":"wx2026-08-030","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"30","domain":"信息安全管理","stem":"小王在学习定量风险评估方法后,决定试着为单位机房计算火灾的风险大小。假设单位机房的总价值为400万元人民币,暴露系数(Exposure Factor,EF)是25%,年度发生率(Annualized Rate of Occurrence, ARO)是0.2,那么小王计算的年度预期损失（Annualized Loss Expectancy, ALE) 应该是( )。","options":["100万元人民币","400万元人民币","20万元人民币","180万元人民币"],"correctIndex":2,"explanation":"ALE = 资产价值 × 暴露系数 × 年发生率 = 400万 × 25% × 0.2 = 20万。","imageNames":[]},{"id":"wx2026-08-031","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"31","domain":"信息安全管理","stem":"随着信息技术的不断发展,信息系统的重要性也越来越突出,而与此同时,发生的信息安全事件也越来 ,综合分析信息安全问题产生的根源,下面描述正确的是（ ）","options":["信息系统自身存在脆弱性是根本原因。信息系统越来越重要,同时自身在开发、部署和使用过程中存在的脆弱性,导致了诸多的信息安全事件发生。因此,杜绝脆弱性的存在是解决信息安全问题的根本所在","信息系统面临诸多黑客的威胁,包括恶意攻击者和恶作剧攻击者。信息系统应用越来越广泛,接触信息系统的人越多,信息系统越可能遭受攻击,因此避免有恶意攻击可能的人接触信息系统就可以解决信息安全问题","信息安全问题,产生的根源要从内因和外因两个方面分析,因为信息系统自身存在脆弱性同时外部又有威胁源,从而导致信息系统可能发生安全事件,因此要防范安全风险,需从内外因同时着手","信息安全问题的根本原因是内因、外因和人三个因素的综合作用,内因和外因都可能导致安全事件的发生,但最重要的还是人的因素,外部攻击者和内部工作人员通过远程攻击,本地破坏和内外勾结等手段导致安全事件发生,因此对人这个因素的防范应是安全工作重点"],"correctIndex":2,"explanation":"信息安全问题由内因（脆弱性）和外因（威胁）共同导致,需内外兼防。","imageNames":[]},{"id":"wx2026-08-032","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"32","domain":"信息安全技术","stem":"在Linux系统中,下列哪项内容不包含在/etc/passwd文件中（）","options":["用户名","用户口令明文","用户主目录","用户登录后使用的 SHELL"],"correctIndex":1,"explanation":"/etc/passwd存储加密口令（如x）,明文口令通常在/etc/shadow中。 即使最好用的安全产品也存在（）。结果,在任何的系统中敌手最终都能够找出一个被开发出的漏洞。一种有效的对策时在敌手和它的目标之间配备多种（）。每一种机制都应包括（）两种手段。 A.安全机制；安全缺陷；保护和检测 B.安全缺陷；安全机制；保护和检测 C.安全缺陷；保护和检测；安全机制； D.安全缺陷；安全机制；保护和监测 答案:B 安全产品存在缺陷,需通过多种安全机制（保护和检测）降低风险。","imageNames":[]},{"id":"wx2026-08-033","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"33","domain":"信息安全技术","stem":"即使最好用的安全产品也存在（）。结果,在任何的系统中敌手最终都能够找出一个被开发出的漏洞。一种有效的对策时在敌手和它的目标之间配备多种（）。每一种机制都应包括（）两种手段。","options":["安全机制；安全缺陷；保护和检测","安全缺陷；安全机制；保护和检测","安全缺陷；保护和检测；安全机制；","安全缺陷；安全机制；保护和监测"],"correctIndex":1,"explanation":"安全产品存在缺陷,需通过多种安全机制（保护和检测）降低风险。","imageNames":[]},{"id":"wx2026-08-034","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"34","domain":"信息安全管理","stem":"某攻击者想通过远程控制软件潜伏在某监控方的UNIX系统的计算机中,如果攻击者打算长时间地远程监控某服务器上的存储的敏感数据,必须要能够清除在监控方计算机中存在的系统日志。否则当监控方查看自己的系统日志的时候,就会发现被监控以及访向的痕迹。不属于清除痕迹的方法是()。","options":["窃取root权限修改wtmp/wtmpx、utmp/utmpx和lastlog三个主要日志文件","采用干扰手段影响系统防火墙的审计功能","保留攻击时产生的临时文件","修改登录日志,伪造成功的登录日志,增加审计难度"],"correctIndex":2,"explanation":"保留临时文件会暴露攻击痕迹,其他选项为清除痕迹的方法。","imageNames":[]},{"id":"wx2026-08-035","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"35","domain":"信息安全管理","stem":"信息安全组织的管理涉及内部组织和外部各方两个控制目标。为了实现对组织内部信息安全的有效管理,实施常规的控制措施,不包括哪些选项()","options":["信息安全的管理承诺、信息安全协调、信息安全职责的分配","信息处理设施的授权过程、保密性协议、与政府部门的联系.","与特定利益集团的联系。信息安全的独立评审","与外部各方相关风险的识别、处理外部各方协议中的安全问题"],"correctIndex":3,"explanation":"D项属于外部组织管理,非内部控制目标。","imageNames":[]},{"id":"wx2026-08-036","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"36","domain":"信息安全法规标准","stem":"按照我国信息安全等级保护的有关政策和标准。有些信息系统只需要自主定级、自主保护,按照要求向公安机关备案即可,可以不需要上级或主管都门来测评和检查。此类信息系统应属于:","options":["零级系统","一级系统","二级系统","三级系统"],"correctIndex":2,"explanation":"选二级,按标准和政策来,国家政策66号文,等保分为5个等级,每个级别都叫自主定级,自主保护。明确三级及以上需测评。","imageNames":[]},{"id":"wx2026-08-037","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"37","domain":"信息安全技术","stem":"小李在检查公司对外服务网站的源代码时,发现程序在发生诸如没有找到资源、数据库连接错误、写临时文件错误等问题时,会将详细的错误原因在结果页面上显示出来。从安全角度考虑,小李决定修改代码。将详细的错误原因都隐藏起来,在页面上仅仅告知用户“抱歉。发生内部错误!”.请问,这种处理方法的主要目的是()。","options":["A避免缓冲区溢出","安全处理系统异常","C安全使用临时文件","最小化反馈信息"],"correctIndex":3,"explanation":"隐藏错误信息可减少攻击者获取系统内部信息的途径。","imageNames":[]},{"id":"wx2026-08-038","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"38","domain":"信息安全技术","stem":"关于ARP欺骗原理和防范措施,下面理解错误的是( )","options":["ARP欺骗是指攻击者直接向受害者主机发送错误的ARP应答报文。使得受害者主机将错误的硬件地址映射关系存到ARP缓存中,从而起到冒充主机的目的","单纯利用ARP欺骗攻击时,ARP欺骗通常影响的是内部子网,不能跨越路由实施攻击","解决ARP欺骗的一个有效方法是采用“静态”的APP缓存,如果发生硬件地址的更改,则需要人工更新缓存","彻底解决ARP欺骗的方法是避免使用ARP协议和ARP缓存。直接采用IP地址和其地主机进行连接"],"correctIndex":3,"explanation":"ARP协议是网络层基础协议,无法彻底避免使用。","imageNames":[]},{"id":"wx2026-08-039","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"39","domain":"信息安全管理","stem":"组织内人力资源部门开发了一套系统,用于管理所有员工的各种工资、绩效、考核、奖励等事宜。所有员工都可以登录系统完成相关需要员工配合的工作,以下哪项技术可以保证数据的保密性:","options":["SSL加密","双因子认证","加密会话cookie","IP地址校验"],"correctIndex":0,"explanation":"SSL加密传输数据,确保保密性；双因子认证用于身份验证；加密会话cookie防止篡改；IP校验易伪造。","imageNames":[]},{"id":"wx2026-08-040","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"40","domain":"信息安全技术","stem":"强制访问控制是指主体和客体都有一个固定的安全属性,系统用该安全属性来决定一个主体是否可以访问某个客体,具有较高的安全性,适用于专用或对安全性较高的系统。强制访问控制模型有多种类型,如BLP、Biba、Clark-Willson和ChineseWall等。小李自学了BLP模型,并对该模型的特点进行了总结。以下4钟对BLP模型的描述中,正确的是（ ）:","options":["BLP模型用于保证系统信息的机密性,规则是“向上读,向下写”","BLP模型用于保证系统信息的机密性,规则是“向下读,向上写”","BLP模型用于保证系统信息的完整性,规则是“向上读,向下写”","BLP模型用于保证系统信息的完整性,规则是“向下读,向上写”"],"correctIndex":1,"explanation":"BLP模型保证机密性,规则为“向下读,向上写”。","imageNames":[]},{"id":"wx2026-08-041","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"41","domain":"信息安全管理","stem":"一个信息管理系统通常会对用户进行分组并实施访问控制。例如,在一个学校的教务系统中,教师能够录入学生的考试成绩,学生只能查看自己的分数,而学校教务部门的管理人员能够对课程信息、学生的选课信息等内容进行修改。下列选项中,对访问控制的作用的理解错误的是:","options":["对经过身份鉴别后的合法用户提供所有服务","拒绝非法用户的非授权访问请求","在用户对系统资源提供最大限度共享的基础上,对用户的访问权进行管理","防止对信息的非授权篡改和滥用"],"correctIndex":0,"explanation":"访问控制需限制用户权限,而非提供所有服务。","imageNames":[]},{"id":"wx2026-08-042","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"42","domain":"信息安全管理","stem":"信息安全风险等级的最终因素是:","options":["威胁和脆弱性","影响和可能性","资产重要性","以上都不对"],"correctIndex":1,"explanation":"风险等级由影响和可能性共同决定。","imageNames":[]},{"id":"wx2026-08-043","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"43","domain":"信息安全管理","stem":"实施灾难恢复计划之后,组织的灾难前和灾难后运营成本将:","options":["降低","不变（保持相同）","提高","提高或降低（取决于业务的性质）"],"correctIndex":2,"explanation":"灾难恢复需冗余资源,成本通常提高。","imageNames":[]},{"id":"wx2026-08-044","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"44","domain":"信息安全技术","stem":"自主访问控制模型（DAC）的访问控制关系可以用访问控制表（ACL）来表示,该ACL利用在客体上附加一个主体明细表的方法来表示访问控制矩阵,通常使用由客体指向的链表来存储相关数据。下面选项中说法正确的是（ ）。","options":["ACL是Bell-LaPadula模型的一种具体实现","ACL在删除用户时,去除该用户所有的访问权限比较方便","ACL对于统计某个主体能访问哪些客体比较方便","ACL在增加和修改哪些客体被主体访问比较方便"],"correctIndex":3,"explanation":"ACL便于修改客体访问权限,统计主体权限需遍历链表,效率较低。","imageNames":[]},{"id":"wx2026-08-045","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"45","domain":"信息安全法规标准","stem":"二十世纪二十年代,德国发明家亚瑟.谢尔比乌斯（Arthur Scherbius）发明了Engmia密码机。按照密码学发展历史阶段划分,这个阶段属于（ ）","options":["古典密码阶段。这一阶段的密码专家常常靠直觉和技巧来设计密码,而不是凭借推理和证明,常用的密码运算方法包括替代方法和置换方法","近代密码发展阶段。这一阶段开始使用机械代替手工计算,形成了机械式密码设备和更进一步的机电密码设备。","现代密码学的早期发展阶段。这一阶段以香农的论文“保密系统的通信理论”（“The Communication Theory of Secret Systems”）为理论基础,开始了对密码学的科学探索。","现代密码学的近代发展阶段。这一阶段以公钥密码思想为标准,引发了密码学历史上的革命性的变革,同时,众多的密码算法开始应用于非机密单位和商业场合。"],"correctIndex":1,"explanation":"Enigma密码机属于近代密码阶段（机械密码设备）。","imageNames":[]},{"id":"wx2026-08-046","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"46","domain":"信息安全技术","stem":"主体和客体是访问控制模型中常用的概念。下面描述中错误的是（ ）","options":["主体是访问的发起者,是一个主动的实体,可以操作被动实体的相关信息或数据","客体也是一个实体,是操作的对象,是被规定需要保护的资源","主体是动作的实施者,比如人、进程或设备等均是主体,这些对象不能被当作客体使用","一个主体为了完成任务,可以创建另外的主体,这些主体可以独立运行"],"correctIndex":2,"explanation":"主体可同时作为客体（如进程访问文件时为主体,被其他进程访问时为客体）。","imageNames":[]},{"id":"wx2026-08-047","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"47","domain":"信息安全保障","stem":"数字签名不能实现的安全特性为（ ）","options":["防抵赖","防伪造","防冒充","保密通信"],"correctIndex":3,"explanation":"数字签名用于防抵赖、防伪造,保密通信需加密技术。","imageNames":[]},{"id":"wx2026-08-048","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"48","domain":"信息安全技术","stem":"在入侵检测（IDS）的运行中,最常见的问题是:（）","options":["误报检测","接收陷阱消息","误拒绝率","拒绝服务攻击"],"correctIndex":0,"explanation":"误报是IDS最常见问题,需平衡检测率和误报率。","imageNames":[]},{"id":"wx2026-08-049","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"49","domain":"信息安全工程","stem":"什么是系统变更控制中最重要的内容？","options":["所有的变更都必须文字化,并被批准","变更应通过自动化工具来实施","应维护系统的备份","通过测试和批准来确保质量"],"correctIndex":0,"explanation":"变更必须文档化并批准,确保可追溯性和合规性","imageNames":[]},{"id":"wx2026-08-050","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"50","domain":"信息安全法规标准","stem":"IPv4 协议在设计之初并没有过多地考虑安全问题,为了能够使网络方便地进行互联、互通,仅仅依靠IP头部的校验和字段来保证IP包的安全,因此IP包很容易被篡改,并重新计算校验和。IETF于1994年开始制定IPSec协议标准,其设计目标是在IPv4和IPv6环境中为网络层流量提供灵活、透明的安全服务,保护TCP/IP通信免遭窃听和篡改,保证数据的完整性和机密性,有效抵御网络攻击,同时保持易用性。下列选项中说法错误的是（ ）","options":["对于IPv4, IPSec是可选的,对于IPv6,IPSec是强制实施的。","IPSec协议提供对IP及其上层协议的保护。","IPSec是一个单独的协议","IPSec安全协议给出了封装安全载荷和鉴别头两种通信保护机制。"],"correctIndex":2,"explanation":"IPSec是协议族（包含AH、ESP等）,非单一协议。","imageNames":[]},{"id":"wx2026-08-051","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"51","domain":"信息安全技术","stem":"小赵是某大学计算机科学与技术专业的毕业生,在前往一家大型企业应聘时,面试经理要求他给出该企业信息系统访问控制模型的设计思路。如果想要为一个存在大量用户的信息系统实现自主访问控制功能,在以下选项中,从时间和资源消耗的角度,下列选项中他应该采取的最合适的模型或方法是（ ）。","options":["访问控制列表（ACL）","能力表（CL）","BLP模型","Biba模型"],"correctIndex":0,"explanation":"访问控制列表（ACL）通过直接关联用户和权限,实现灵活且高效的自主访问控制,适合大量用户场景。能力表（CL）需系统维护用户能力,资源消耗大；BLP和Biba为强制访问控制模型,不适用于自主控制需求。","imageNames":[]},{"id":"wx2026-08-052","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"52","domain":"信息安全工程","stem":"在软件开发过程中,常用图作为描述攻击,如DFD就是面向（）分析方法的描述工具,在一套分层DFD中,如果某一张图中有N个加工（Process）则这张图允许有（）张子图,在一张DFD中任意两个加工之间（）。在画分层DFD时,应注意保持（）之间的平衡。DFD中从系统的输入流到系统的输出流的一连串交换形式一种信息流,这种信息流可分为交换流和事物流两类。","options":["数据流；0^N；有0条或多条名字互不相同的数据流；父图与其子图","数据流；I^N；有0条或多条名字互不相同的数据流；父图与其子图","字节流；0^N；有0条或多条名字互不相同的数据流；父图与其子图","数据流；0^N；有0条或多条名字互不相同的数据流；子图之间"],"correctIndex":0,"explanation":"DFD（数据流图）面向数据流分析,分层DFD中父图子图平衡,子图数量为0到N,加工间数据流可多条且名称唯一。","imageNames":[]},{"id":"wx2026-08-053","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"53","domain":"信息安全工程","stem":"社会工程学本质上是一种（），（）通过种种方式来引导受攻击者的（）向攻击者期望的方向发展。罗 伯特·B·西奥迪尼（Robert B Cialdini）在科学美国人（2001 年 2 月）杂志中总结对（）的研究，介绍了 6 种“人类天性基本倾向”，这些基本倾向都是（）工程师在攻击中所依赖的（有意思或者无意识的）。","options":["攻击者；心理操纵；思维；心理操纵；社会工程学","攻击者；心理操纵；心理操纵；社会工程学","心理操纵；攻击者；思维；心理操纵；社会工程学","心理操纵；思维；心理操纵；攻击者；社会工程学"],"correctIndex":2,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-08-054","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"54","domain":"信息安全工程","stem":"ITIL它包含5个生命周期,分别是（）、（）、（）、（）、（）.","options":["战略阶段；设计阶段；转换阶段；运营阶段；改进阶段","设计阶段；战略阶段；转换阶段；运营阶段；改进阶段","战略阶段；设计阶段；运营阶段；转换阶段；改进阶段","转换阶段；战略阶段；设计阶段；运营阶段；改进阶段"],"correctIndex":0,"explanation":"ITIL的5个生命周期阶段依次为战略、设计、转换、运营、改进。","imageNames":[]},{"id":"wx2026-08-055","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"55","domain":"信息安全工程","stem":"某公司正在进行IT系统灾难恢复测试,下列问题中哪个最应该引起关注()","options":["由于有限的测试时间窗,仅仅测试了最必须的系统,其他系统在今年的剩余时间里陆续单独测试","在测试的过程中,有些备份系统有缺陷或者不能正常工作,从而导致这些系统的测试失败","在开启备份站点之前关闭和保护原生产站点的过程比计划需要多得多的时间","每年都是由相同的员工执行此测试,由于所有的参与者都很熟悉每一个恢复步骤,因而没有使用灾难恢复计划（DRP）文档"],"correctIndex":1,"explanation":"备份系统缺陷导致测试失败是关键问题,直接影响灾难恢复能力。其他选项虽需关注,但非最严重风险。","imageNames":[]},{"id":"wx2026-08-056","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"56","domain":"信息安全管理","stem":"COBIT（信息和相关技术的控制目标）是国际专业协会ISACA为信息技术（IT）管理和IT治理创建的良好实践框架。COBIT提供了一套可实施的“信息技术控制”并围绕IT相关流程和推动因素的逻辑框架进行组织。COBIT模型按照流程,请问,COBIT组件包括（）、()、（）、（）、（）等部分。","options":["流程描述、框架、控制目标、管理指南、成熟度模型","框架、流程描述、管理目标、控制目标、成熟度模型","框架、流程描述、控制目标、管理指南、成熟度模型","框架、管理指南、流程描述、控制目标、成熟度模型"],"correctIndex":2,"explanation":"COBIT组件包括框架、流程描述、控制目标、管理指南、成熟度模型,覆盖IT治理全流程。","imageNames":[]},{"id":"wx2026-08-057","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"57","domain":"信息安全工程","stem":"关于软件安全问题,下面描述错误的是（）","options":["软件的安全问题可以造成软件运行不稳定,得不到正确结果甚至崩溃","软件的安全问题应该依赖于软件开发的设计、编程、测试以及部署等各个阶段措施解决","软件的安全问题可能被攻击者利用后影响人身健康安全","软件的安全问题是由程序开发者遗留的,和软件部署运行环境无关"],"correctIndex":3,"explanation":"软件安全问题与部署环境密切相关,如配置错误、依赖库漏洞等均可能引入风险,非仅由开发者遗留。","imageNames":[]},{"id":"wx2026-08-058","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"58","domain":"信息安全技术","stem":"以下哪项是《国家信息化领导小组关于加强信息安全保障工作的意见》的总体方针和要求？","options":["坚持积极攻击、综合防范的方针","全面提高信息安全防护能力","重点保障电信基础信息网络和重要信息系统安全","创建安全健康的网络环境,保障和促进工业化发展,保护公众利益,维护国家安全"],"correctIndex":1,"explanation":"文件核心要求为全面提高信息安全防护能力,其他选项为具体措施或目标。","imageNames":[]},{"id":"wx2026-08-059","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"59","domain":"信息安全管理","stem":"随着计算机和网络技术的迅速发展,人们对网络的依赖性达到了前所未有的程度,网络安全也面临着越来越严峻的考验。如何保障网络安全就显得非常重要,而网络安全评估是保证网络安全的重要环节。以下不属于网络安全评估内容的是（）","options":["数据加密","漏洞检测","风险评估","安全审计"],"correctIndex":0,"explanation":"网络安全评估包括漏洞检测、风险评估、安全审计,数据加密为防护手段,非评估内容。","imageNames":[]},{"id":"wx2026-08-060","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"60","domain":"信息安全法规标准","stem":"2006年5月8日电,中共中央办公厅、国务院办公厅印发了《2006-2020年国家信息化发展战略》。全文分（）部分共计约15000余字。对国内外的信息化发展做了宏观分析,对我国信息化发展指导思想和战略目标标准要阐述,对我国（）发展的重点、行动计划和保障措施做了详尽描述。该战略指出了我国信息化发展的（）,当前我国信息安全保障工作逐步加强。制定并实施了（）,初步建立了信息安全管理体制和（）。基础信息网络和重要信息系统的安全防护水平明显提高,互联网信息安全管理进一步加强。","options":["5个；信息化；基本形势；国家安全战略；工作机制","6个；信息化；基本形势；国家信息安全战略；工作机制","7个；信息化；基本形势；国家安全战略；工作机制","8个；信息化；基本形势；国家信息安全战略；工作机制"],"correctIndex":1,"explanation":"全文分6部分,如果题目问战略分则为8部分,强调国家信息安全战略,建立工作机制,提升防护水平。","imageNames":[]},{"id":"wx2026-08-061","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"61","domain":"信息安全管理","stem":"张主任的计算机使用Windows7操作系统,他常登陆的用户名为zhang,张主任给他个人文件夹设置了权限为只有zhang这个用户有权访问这个目录,管理员在某次维护中无意将zhang这个用户删除了,随后又重新建了一个用户名为zhang,张主任使用zhang这个用户登陆系统后,发现无法访问他原来的个人文件夹,原因是（）","options":["任何一个新建用户都需要经过授权才能访问系统中的文件","windows不认为新建立用户zhang与原来的用户zhang同一个用户,因此无权访问","用户被删除后,该用户创建的文件夹也会自动删除,新建用户找不到原来用户的文件夹,因此无法访问","新建的用户zhang会继承原来用户的权限,之所以无权访问时因为文件夹经过了加密"],"correctIndex":1,"explanation":"Windows用户SID随删除重建变化,新用户与原用户不同,无法继承权限。","imageNames":[]},{"id":"wx2026-08-062","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"62","domain":"信息安全法规标准","stem":"ISO2007:2013《信息技术-安全技术-信息安全管理体系-要求》为在组织内为建立、实施、保持和不断改进（）制定了要求。ISO27001标准的前身为（）的BS7799标准,该标准于1993年由（）立项,于1995年英国首次出版BS7799-1:1995《信息安全管理实施细则》,它提供了一套综合的、由信息安全最佳惯例组成的（）,其目的是作为确定工商业信息系统在大多数情况所需控制范围的唯一（）,并且适用大、中、小组织。","options":["ISMS；德国；德国贸易工业部；实施规则；参考基准","ISMS；法国；法国贸易工业部；实施规则；参考基准","ISMS；英国；英国贸易工业部；实施规则；参考基准","ISMS；德国；德国贸易工业部；参考基准；实施规则"],"correctIndex":2,"explanation":"ISO27001前身为英国BS7799,由英国贸易工业部立项,提供实施规则,作为参考基准。","imageNames":[]},{"id":"wx2026-08-063","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"63","domain":"信息安全法规标准","stem":"终端访问控制器访问控制系统（Terminal Access Controller Access-Control System,TACACS）由RFC1492定义,标准的TACACS协议只认证用户是否可以登录系统,目前已经很少使用,TACACS+协议由Cisco公司提出,主要应用于Ciso公司的产品中,运行与TCP协议之上。TACACS+协议分为（）两个不同的过程","options":["认证和授权","加密和认证","数字签名和认证","访问控制和加密"],"correctIndex":0,"explanation":"TACACS+协议分为认证和授权两个独立过程,增强安全性与灵活性。","imageNames":[]},{"id":"wx2026-08-064","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"64","domain":"信息安全管理","stem":"网络与信息安全应急预案是在分析网络与信息系统突发事件后果和应急能力的基础上,针对可能发生的重大网络与信息系统突发事件,预先制定的行动计划或应急对策。应急预案的实施需要各子系统的相互配合与协调,下面应急响应工作流程图中,空白方框中从右到左依次填入的是（）。","options":["应急响应专家小组、应急响应技术保障小组、应急响应实施小组、应急响应日常运行小组","应急响应专家小组、应急响应实施小组、应急响应技术保障小组、应急响应日常运行小组","应急响应技术保障小组、应急响应专家小组、应急响应实施小组、应急响应日常运行小组","应急响应技术保障小组、应急响应专家小组、应急响应日常运行小组、应急响应实施小组"],"correctIndex":0,"explanation":"应急响应流程从右至左依次为专家小组、技术保障、实施小组、日常运行小组,确保协调配合。","imageNames":["wx2026-08-02.png"]},{"id":"wx2026-08-065","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"65","domain":"信息安全技术","stem":"随着计算机在商业和民用领域的应用,安全需求变得越来越多样化,自主访问控制和强制访问控制难以适应需求,基于角色的访问控制（RBAC）逐渐成为安全领域的一个研究热点。RBAC模型可以分为RBAC0、RBAC1、RBAC2和RBAC3四种类型,它们之间存在相互包含关系。下列选项中,对它们关系描述错误的是（）。","options":["RBACO是基于模型,RBAC1、RBAC2和RBAC3都包含RBAC0","RBAC1在RBAC0的基础上,加入了角色等级的概念","RBAC2在RBAC1的基础上,加入了约束的概念","RBAC3结合RBAC1和RBAC2,同时具备角色等级和约束"],"correctIndex":2,"explanation":"RBAC2在RBAC0基础上加入约束,非RBAC1。RBAC1引入角色层次,RBAC3结合RBAC1和RBAC2。","imageNames":[]},{"id":"wx2026-08-066","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"66","domain":"信息安全技术","stem":"安全漏洞扫描技术是一类重要的网络安全技术。当前,网络安全漏洞扫描技术的两大核心技术是（）。","options":["PING扫描技术和端口扫描技术","端口扫描技术和漏洞扫描技术","操作系统探测和漏洞扫描技术","PING扫描技术和操作系统探测"],"correctIndex":1,"explanation":"漏洞扫描核心为端口扫描（识别服务）和漏洞检测（匹配已知漏洞）。","imageNames":[]},{"id":"wx2026-08-067","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"67","domain":"信息安全法规标准","stem":"下列选项中对信息系统审计概念的描述中不正确的是（）","options":["信息系统审计,也可称作IT审计或信息系统控制审计","信息系统审计是一个获取并评价证据的过程,审计对象是信息系统相关控制,审计目标则是判断信息系统是否能够保证其安全性、可靠性、经济性以及数据的真实性、完整性等相关属性","信息系统审计师单一的概念,是对会计信息系统的安全性、有效性进行检查","从信息系统审计内容上看,可以将信息系统审计分为不同专项审计,例如安全审计、项目合规审计、绩效审计等"],"correctIndex":2,"explanation":"信息系统审计涵盖多领域,非仅会计系统,包括安全、合规、绩效等专项审计。","imageNames":[]},{"id":"wx2026-08-068","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"68","domain":"信息安全技术","stem":"甲公司打算制作网络连续时所需要的插件的规格尺寸、引脚数量和线序情况,甲公司将这个任务委托了乙公司,那么乙公司的设计员应该了解OSI参考模型中的哪一层（）","options":["数据链路层","会话层","物理层","传输层"],"correctIndex":2,"explanation":"物理层定义插头、引脚、线序等硬件特性,设计插件需了解该层规范。","imageNames":[]},{"id":"wx2026-08-069","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"69","domain":"信息安全管理","stem":"信息安全应急响应,是指一个组织为了应对各种安全意外事件的发生所采取的防范措施,既包括预防性措施,也包括事件发生后的应对措施。应急响应方法和过程并不偶是唯一的,在下面的应急响应管理流程中,空白方框处填写正确的是选项是（）","options":["培训阶段","文档阶段","报告阶段","检测阶段"],"correctIndex":3,"explanation":"应急响应流程中检测阶段为关键,确定事件后触发后续响应措施。","imageNames":["wx2026-08-03.png"]},{"id":"wx2026-08-070","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"70","domain":"信息安全技术","stem":"下面哪一项情景属于身份鉴别（Authentication）过程？（）","options":["用户依照系统提示输入用户名和口令","用户在网络上共享了自己编写的一份Office文档进行加密,以阻止其他人得到这份拷贝后到文档中的内容","用户使用加密软件对自己家编写的Office文档进行加密,以阻止其他人得到这份拷贝后到文档中的内容","某个人尝试登陆到你的计算机中,但是口令输入的不对,系统提示口令错误,并将这次失败的登陆过程记录在系统日志中"],"correctIndex":0,"explanation":"输入用户名和口令为典型身份鉴别过程,验证用户身份合法性。","imageNames":[]},{"id":"wx2026-08-071","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"71","domain":"信息安全技术","stem":"终端访问控制器访问控制系统（TERMINAL Access Controller Access-Control System,TACACS）,在认证过程中,客户机发送一个START包给服务器,包的内容包括执行的认证类型、用户名等信息。START包只在一个认证会话开始时使用一个,序列号永远为（）.服务器收到START包以后,回送一个REPLY包,表示认证继续还是结束。","options":["0","1","2","4"],"correctIndex":1,"explanation":"TACACS START包序列号固定为1,用于初始化认证会话。","imageNames":[]},{"id":"wx2026-08-072","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"72","domain":"信息安全工程","stem":"为了开发高质量的软件,软件效率成为最受关注的话题。那么开发效率主要取决于以下两点:开发新功能是否迅速以及修复缺陷是否及时。为了提高软件测试的效率,应（）。","options":["随机地选取测试数据","取一切可能的输入数据为测试数据","在完成编码以后制定软件的测试计划","选择发现错误可能性最大的数据作为测试用例"],"correctIndex":3,"explanation":"选择高概率发现错误的数据作为测试用例,可显著提升测试效率。","imageNames":[]},{"id":"wx2026-08-073","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"73","domain":"信息安全保障","stem":"以下哪个组织所属的行业的信息系统不属于关键信息基础设施？","options":["人民解放军战略支援部队","中国移动吉林公司","重庆市公安局消防总队","上海市卫生与计划生育委员会"],"correctIndex":3,"explanation":"卫生系统不直接涉及国计民生关键领域,不属于关键信息基础设施。","imageNames":[]},{"id":"wx2026-08-074","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"74","domain":"信息安全技术","stem":"目前应用面临的威胁越来越多,越来越难发现。对应用系统潜在的威胁目前还没有统一的分类,但小赵认为同事小李从对应用系统的攻击手段角度出发所列出的四项例子中有一项不对,请问是下面哪一项（）","options":["数据访问权限","伪造身份","钓鱼攻击","远程渗透"],"correctIndex":0,"explanation":"数据访问权限为防御措施,非攻击手段,其余选项均为典型攻击方式。","imageNames":[]},{"id":"wx2026-08-075","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"75","domain":"信息安全技术","stem":"与PDR模型相比,P2DR模型则更强调（）,即强调系统安全的（）,并且以安全检测、（）和自适应填充“安全间隙“为循环来提高（）。","options":["漏洞监测；控制和对抗；动态性；网络安全","动态性；控制和对抗；漏洞监测；网络安全","控制和对抗；漏洞监测；动态性；网络安全","控制和对抗；动态性；漏洞监测；网络安全"],"correctIndex":3,"explanation":"P2DR强调动态性,通过检测和漏洞监测循环提升网络安全。","imageNames":[]},{"id":"wx2026-08-076","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"76","domain":"信息安全管理","stem":"某单位在进行内部安全评估时,安全员小张使用了单位采购的漏洞扫描软件进行单位内的信息系统漏洞扫描。漏洞扫描报告的结论为信息系统基本不存在明显的安全漏洞,然而此报告在内部审计时被质疑,原因在于小张使用的漏洞扫描软件采购于三年前,服务已经过期,漏洞库是半年前最后一次更新的。关于内部审计人员对这份报告的说法正确的是（）","options":["内部审计人员的质疑是对的,由于没有更新漏洞库,因此这份漏洞扫描报告准确性无法保证","内部审计人员质疑是错的,漏洞扫描软件是正版采购,因此扫描结果是准确的","内部审计人员的质疑是正确的,因为漏洞扫描报告是软件提供,没有经过人为分析,因此结论不会准确","内部审计人员的质疑是错误的,漏洞软件是由专业的安全人员操作的,因此扫描结果是准确的"],"correctIndex":0,"explanation":"漏洞库未更新导致扫描结果不可靠,内部审计质疑合理。","imageNames":[]},{"id":"wx2026-08-077","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"77","domain":"信息安全工程","stem":"信息系统安全保障评估概念和关系如图所示。信息系统安全保障评估,就是在信息系统所处的运行环境中对信息系统安全保障的具体工作和活动进行客观的评估。通过信息系统安全保障评估所搜集的（）,向信息系统的所有相关方提供信息系统的（）能够实现其安全保障策略,能够将将其所面临的风险降低到其可接受的程度的主观信心。信息系统安全保障评估的评估对象是（）, 信息系统安全保障是一个动态持续的过程,涉及信息系统整个（）,因此信息系统安全保障的评估也应该提供一种（）的信心。","options":["安全保障工作；客观证据；信息系统；生命周期；动态持续","客观证据；安全保障工作；信息系统；生命周期；动态持续","客观证据；安全保障工作；生命周期；信息系统；动态持续","客观证据；安全保障工作；动态持续；信息系统；生命周期"],"correctIndex":1,"explanation":"评估基于客观证据,证明安全保障工作有效性,覆盖信息系统全生命周期,提供动态信心。","imageNames":["wx2026-08-04.png"]},{"id":"wx2026-08-078","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"78","domain":"信息安全保障","stem":"为了防止授权用户不会对数据进行未经授权的修改,需要实施对数据的完整性保护,下列哪一项最好地描述了星或（·-）完整性原则？（）","options":["Bell-LaPadula模型中的不允许向下写","Bell-LaPadula模型中的不允许向上读","Biba模型中的不允许向上写","Biba模型中的不允许向下读"],"correctIndex":2,"explanation":"Biba模型“不允许向上写”防止低完整性数据污染高完整性数据。","imageNames":[]},{"id":"wx2026-08-079","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"79","domain":"信息安全管理","stem":"组织应定期监控、审查、审计（）服务,确保协议中的信息安全条款和条件被遵守,信息安全事件和问题得到妥善管理。应将管理供应商关系的责任分配给指定的个人或（）团队。另外,组织应确保落实供应商符合性审查和相关协议要求强制执行的责任。应保存足够的技术技能和资源的可用性以监视协议要求尤其是（）要求的实现。当发现服务交付的不足时,宜采取（）.当供应商提供的服务,包括对（）方针、规程和控制措施的维持和改进等发生变更时,应在考虑到其对业务信息、系统、过程的重要性和重新评估风险的基础上管理。","options":["供应商；服务管理；信息安全；合适的措施；信息安全","服务管理；供应商；信息安全；合适的措施；信息安全","供应商；信息安全；服务管理；合适的措施；信息安全","供应商；合适的措施；服务管理；信息安全；信息安全"],"correctIndex":0,"explanation":"定期审计供应商服务,分配责任给团队,确保信息安全条款执行,采取纠正措施。","imageNames":[]},{"id":"wx2026-08-080","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"80","domain":"信息安全工程","stem":"下列关于面向对象测试问题的说法中,不正确的是（）","options":["在面向对象软件测试时,设计每个类的测试用例时,不仅仅要考虑用各个成员方法的输入参数,还需要考虑如何设计调用的序列","构造抽象类的驱动程序会比构造其他类的驱动程序复杂","类B继承自类A,如对B进行了严格的测试,就意味着不需再对类A进行测试","在存在多态的情况下,为了达到较高的测试充分性,应对所有可能的绑定都进行测试"],"correctIndex":2,"explanation":"继承类测试不能替代基类测试,基类可能被其他类调用,需单独验证。","imageNames":[]},{"id":"wx2026-08-081","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"81","domain":"信息安全保障","stem":"火灾是机房日常运营中面临最多的安全威胁之一,火灾防护的工作是通过构建火灾预防、检测和响应系统,保护信息化相关人员和信息系统,将火灾导致的影响降低到可接受的程度。下列选项中,对火灾的预防、检测和抑制的措施描述错误的选项是（）。","options":["将机房单独设置防火区,选址时远离易燃易爆物品存放区域,机房外墙使用非燃烧材料,进出机房区域的门采用防火门或防火卷帘,机房通风管设防火栓","火灾探测器的具体实现方式包括；烟雾检测、温度检测、火焰检测、可燃气体检测及多种检测复合等","自动响应的火灾抑制系统应考虑同时设立两组独立的火灾探测器,只要有一个探测器报警,就立即启动灭火工作","前在机房中使用较多的气体灭火剂有二氧化碳、七氟丙烷、三氟甲烷等"],"correctIndex":2,"explanation":"火灾抑制系统需两组探测器均报警后启动,避免误动作。","imageNames":[]},{"id":"wx2026-08-082","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"82","domain":"信息安全管理","stem":"信息安全管理体系也采用了（） 模型,该模型可应用于所有的（）。ISMS把相关方的信息安全要求和期望作为输入,并通过必要的(),产生满足这些要求和期望的（）。","options":["ISMS；PDCA过程；行动和过程；信息安全结果","PDCA;ISMS过程；行动和过程；信息安全结果","ISMS;PDCA过程；信息安全结果；行动和过程","PDCA;ISMS过程；信息安全结果；行动和过程"],"correctIndex":1,"explanation":"ISMS采用PDCA模型,输入需求,通过行动和过程输出信息安全结果。","imageNames":[]},{"id":"wx2026-08-083","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"83","domain":"信息安全工程","stem":"你是单位安全主管,由于微软刚发布了数个系统漏洞补丁,安全运维人员给出了针对此漏洞修补的四个建议方案,请选择其中一个最优方案执行（）","options":["由于本次发布的数个漏洞都属于高危漏洞,为了避免安全风险,应对单位所有的服务器和客户端尽快安装补丁","本次发布的漏洞目前尚未出现利用工具,因此不会对系统产生实质性危害,所以可以先不做处理","对于重要的服务,应在测试环境中安装并确认补丁兼容性问题后再在正式生产环境中部署","对于服务器等重要设备,立即使用系统更新功能安装这批补丁,用户终端计算机由于没有重要数据,由终端自行升级"],"correctIndex":2,"explanation":"重要服务需先测试补丁兼容性,避免生产环境故障。","imageNames":[]},{"id":"wx2026-08-084","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"84","domain":"信息安全保障","stem":"小王学习了灾备备份的有关知识,了解到常用的数据备份方式包括完全 备份、增量备份、差量备份,为了巩固所学知识,小王对这三种备份方式进行对比,其中在数据恢复速度方面三种备份方式由快到慢的顺序是（）","options":["完全备份、增量备份、差量备份","完全备份、差量备份、增量备份","增量备份、差量备份、完全备份","差量备份、增量备份、完全备份"],"correctIndex":1,"explanation":"恢复速度:完全备份最快,差量备份次之（仅恢复最后一次备份）,增量备份最慢（需恢复所有增量）。","imageNames":[]},{"id":"wx2026-08-085","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"85","domain":"信息安全技术","stem":"在网络交易发达的今天,贸易双方可以通过签署电子合同来保障自己的合法权益。某中心推出电子签名服务,按照如图方式提供电子签名,不属于电子签名的基本特性的是（）。","options":["不可伪造性","不可否认性","保证消息完整性","机密性"],"correctIndex":3,"explanation":"电子签名需不可伪造、不可否认、保证完整性,机密性非基本特性。","imageNames":["wx2026-08-05.png"]},{"id":"wx2026-08-086","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"86","domain":"信息安全管理","stem":"风险评估文档是指在整个风险评估过程中产生的评估过程文档和评估结果文档，其中，明确评估的目的、 职责、过程、相关的文档要求，以及实施本次评估所需要的各种资产、威胁、脆弱性识别和判断依据的文档 是（）","options":["《风险评估方案》","《风险评估程序》","《资产识别清单》","《风险评估报告》"],"correctIndex":0,"explanation":"公开题库未附解析。","imageNames":[]},{"id":"wx2026-08-087","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"87","domain":"信息安全法规标准","stem":"等级保护实施根据GB/T 25058-2010 《信息安全技术 信息系统安全等级保护实施指南》分为五大阶段；（）、总体规划、设计实施、（）和系统终止。但由于在开展等级保护试点工作时,大量信息系统已经建设完成,因此根据实际情况逐步形成了（）、备案、差距分析（也叫差距测评）、建设整改、验收测评、定期复查为流程的（）工作流程。和《等级保护实施指南》中规定的针对（）的五大阶段略有差异。","options":["运行维护；定级；定级；等级保护；信息系统生命周期","定级；运行维护；定级；等级保护；信息系统生命周期","定级运行维护；等级保护；定级；信息系统生命周期","定级；信息系统生命周期；运行维护；定级；等级保护"],"correctIndex":1,"explanation":"等级保护实施分定级、运行维护两大阶段,实际流程为定级、备案、差距分析等。","imageNames":[]},{"id":"wx2026-08-088","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"88","domain":"信息安全技术","stem":"保护-检测-响应（Protection-Detection-Response,PDR）模型是（）工作中常用的模型,七思想是承认（）中漏洞的存在,正视系统面临的（）,通过采取适度防护、加强（）、落实对安全事件的响应、建立对威胁的防护来保障系统的安全。","options":["信息系统；信息安全保障；威胁；检测工作","信息安全保障；信息系统；检测工作；威胁；检测工作","信息安全保障；信息系统；威胁；检测工作","信息安全保障；威胁；信息系统；检测工作"],"correctIndex":2,"explanation":"PDR模型承认漏洞存在,通过防护、检测、响应保障安全。","imageNames":[]},{"id":"wx2026-08-089","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"89","domain":"信息安全工程","stem":"在极限测试过程中,贯穿始终的是()","options":["单元测试和集成测试","单元测试和系统测试","集成测试和验收测试","集成测试和系统测试"],"correctIndex":2,"explanation":"极限测试中,集成测试和验收测试贯穿开发全程,确保需求满足。","imageNames":[]},{"id":"wx2026-08-090","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"90","domain":"信息安全工程","stem":"美国系统工程专家霍尔（A.D.Hall）在1969年利用机构分析法提出著名的霍尔三维结构,使系统工程的工作阶段和步骤更为清晰明了,如图所示,霍尔三维结构是将系统工程整个活动过程分为前后紧密衔接的（）阶段和（）步骤,同时还考虑了为完全这些阶段和步骤所需要的各种（）。这样,就形成了由（）、（）、和知识维所组成的三维空间结构。","options":["五个；七个；专业知识和技能；时间维；逻辑维","七个；七个；专业知识和技能；时间维；逻辑维","七个；六个；专业知识和技能；时间维；逻辑维","七个；六个；专业知识和技能；时间维；空间维"],"correctIndex":1,"explanation":"霍尔三维结构分7个阶段、7个步骤,依赖专业知识和技能,由时间、逻辑、知识维构成。","imageNames":["wx2026-08-06.png"]},{"id":"wx2026-08-091","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"91","domain":"信息安全工程","stem":"社会工程学是（）与（）结合的学科,准确来说,它不是一门科学,因为它不能总是重复合成功,并且在信息充分多的情况下它会失效。基于系统、体系、协议等技术体系缺陷的（）,随着时间流逝最终都会失效,因为系统的漏洞可以弥补,体系的缺陷可能随着技术的发展完善或替代,社会工程学利用的是人性的“弱点”,而人性是（）,这使得它几乎是永远有效的（）。","options":["网络安全；心理学；攻击方式；永恒存在的；攻击方式","网络安全；攻击方式；心理学；永恒存在的；攻击方式","网络安全；心理学；永恒存在的；攻击方式","网络安全；攻击方式；心理学；攻击方式；永恒存在的"],"correctIndex":0,"explanation":"社会工程学结合网络安全与心理学,利用人性弱点,几乎永远有效。","imageNames":[]},{"id":"wx2026-08-092","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"92","domain":"信息安全工程","stem":"系统安全工程能力成熟度模型评估方法（SSAM, SSE-CMM Appraisal Method）是专门基于SSE-CMM的评估方法。它包含对系统安全工程-能力成熟度模型中定义的组织的（）流程能力和成熟度进行评估所需的（）。SSAM评估过程分为四个阶段,（）、（）、（）、（）。","options":["信息和方向；系统安全工程；规划；准备；现场；报告","信息和方向；系统工程；规划；准备；现场；报告","系统安全工程；信息；规划；准备；现场；报告","系统安全工程；信息和方向；规划；准备；现场；报告"],"correctIndex":3,"explanation":"SSAM评估系统安全工程流程,分规划、准备、现场、报告四阶段。","imageNames":[]},{"id":"wx2026-08-093","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"93","domain":"信息安全法规标准","stem":"当使用移动设备时,应特别注意确保()不外泄。移动设备方针应考虑与非保护环境移动设备同时工作时的风险。当在公共场所、会议室和其他不受保护的区域使用移动计算设施时,要加以小心。应采取保护措施以避免通过这些设备存储和处理的信息未授权的访问或泄露,如使用()、强制使用秘钥身份验证信息。要对移动计算设施进行物理保护,以防被偷窃,例如,特别是遗留在汽车和其他形式的交通工具上、旅馆房间、会议中心和会议室。要为移动计算机设施的被窃或丢失等情况建立一个符号法律、保险和组织的其他安全要求的（）。携带重要、敏感和或关键业务信息的设备不宜无人值守,若有可能,要以物理的方式锁起来,或使用（）来保护设备。对于使用移动计算设施的人员要安排培训,以提高他们对这种工作方式导致的附加风险的意识,并且要实施控制措施。","options":["加密技术；业务信息；特定规程；专用锁","业务信息；特定规程；加密技术；专用锁","业务信息；加密技术；特定规程；专用锁","业务信息；专用锁；加密技术；特定规程"],"correctIndex":2,"explanation":"移动设备需保护业务信息,采用加密技术和特定规程,使用专用锁防止盗窃。","imageNames":[]},{"id":"wx2026-08-094","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"94","domain":"信息安全法规标准","stem":"在规定的时间间隔或重大变化发生时,组织的额（）和实施方法（如信息安全的控制目标、控制措施、方针、过程和规程）应（）。独立评审宜由管理者启动,由独立被评审范围的人员执行,例如内部审核部、独立的管理人员或专门进行这种评审的第三方组织。从事这些评审的人员宜具备适当的（）。管理人员宜对自己职责范围内的信息处理是否符合合适的安全策略、标准和任何其他安全要求进行（）。为了日常功评审的效率,可以考虑使用自动测量和（）。评审结果和管理人员采取的纠正措施宜被记录,且这些记录宜予以维护。","options":["信息安全管理；独立审查；报告工具；技能和经验；定期评审","信息安全管理；技能和经验；独立审查；定期评审；报告工具","独立审查；信息安全管理；技能和经验；定期评审；报告工具","信息安全管理；独立审查；技能和经验；定期评审；报告工具"],"correctIndex":3,"explanation":"信息安全管理需独立审查,由具备技能人员定期评审,使用报告工具提升效率。","imageNames":[]},{"id":"wx2026-08-095","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"95","domain":"信息安全管理","stem":"选择信息系统部署的场地应考虑组织机构对信息安全的需求并将安全性防在重要的位置,信息资产的保护很大程度上取决与场地的安全性,一个部署在高风险场所的额信息系统是很难有效的保障信息资产安全性的。为了保护环境安全,在下列选项中,公司在选址时最不应该选址的场地是().","options":["自然灾害较少的城市","部署严格监控的独立园区","大型医院旁的建筑","加油站旁的建筑"],"correctIndex":3,"explanation":"加油站旁存在爆炸风险,严重威胁信息系统安全。","imageNames":[]},{"id":"wx2026-08-096","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"96","domain":"信息安全法规标准","stem":"1998年英国公布标准的第二部分《信安全管理体系规范》,规定（）管理体系要求与（）要求,它是一个组织的全面或部分信息安全管理体系评估的（）,它可以作为一个正式认证方案的（）。BS 7799-1与BS7799-2经过修订于1999年重新予以发布,1999版考虑了信息处理技术,尤其是在网络和通信领域应用的近期发展,同时还非常强调了商务涉及的信息安全及（）的责任。","options":["信息安全；信息安全控制；根据；基础；信息安全","信息安全控制；信息安全；根据；基础；信息安全","信息安全控制；信息安全；基础；根据；信息安全","信息安全；信息安全控制；基础；根据；信息安全"],"correctIndex":3,"explanation":"1998年英国公布标准的第二部分《信息安全管理体系规范》,它规定信息安全管理体系要求与信息安全控制要求,它是一个组织的全面或部分信息安全管理体系评估的基础,它可以作为一个正式认证方案的根据。BS7799-1与BS7799-2经过修订于1999年重新予以发布,1999版考虑了信息处理技术,尤其是在网络和通信领域应用的近期发展,同时还非常强调了商务涉及的信息安全及信息安全的责任。","imageNames":[]},{"id":"wx2026-08-097","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"97","domain":"信息安全管理","stem":"某计算机机房由于人员疏忽或设备老化可能会有发生火灾的风险。该计算机机房的资产价值为200万元；如果发生火灾,资产总值将损失至资产值的25%；这种火灾发生的可能性为25年发生一次。则这种威胁的年度损失预期值为().","options":["10,000元","15,000元","20,000元","25,000元"],"correctIndex":2,"explanation":"年度损失预期值=资产价值×暴露因子×年发生率=200万×25%×(1/25)=20,000元。","imageNames":[]},{"id":"wx2026-08-098","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"98","domain":"信息安全管理","stem":"安全审计师一种很常见的安全控制措施,它在信息全保障系统中,属于（）措施。","options":["保护","检测","响应","恢复"],"correctIndex":1,"explanation":"安全审计通过检测异常行为,发现潜在威胁,属于检测措施。","imageNames":[]},{"id":"wx2026-08-099","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"99","domain":"信息安全管理","stem":"下列选项分别是四种常用的资产评估方法,哪个是目前采用最为广泛的资产评估方法（）。","options":["基于知识的分析方法","基于模型的分析方法","定量分析","定性分析"],"correctIndex":3,"explanation":"定性分析为主观评估,灵活适应不同场景,应用最为广泛。","imageNames":[]},{"id":"wx2026-08-100","setId":"wx2026-08","setName":"CISP 复习题（6）","sourceNumber":"100","domain":"信息安全技术","stem":"访问控制方法可分为自主访问控制、强制访问控制和基于角色访问控制,它们具有不同的特点和应用场景。如果需要选择一个访问控制模型,要求能够支持最小特权原则和职责分离原则,而且在不同的系统配置下可以具有不同的安全控制,那么在（1）自主访问控制,（2）强制访问控制,（3）基于角色的访问控制（4）基于规则的访问控制中,能够满足以上要求的选项有（）","options":["只有（1）（2）","只有（2）（3）","只有（3）（4）","只有（4）"],"correctIndex":2,"explanation":"基于角色（RBAC）和基于规则的访问控制支持最小特权和职责分离,适应不同系统配置。","imageNames":[]}]}]};
